window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["2KI"]={"book":"2KI","editions":{"hbo-source":[[1,1,"וַ⁠יִּפְשַׁ֤ע מוֹאָב֙ בְּ⁠יִשְׂרָאֵ֔ל אַחֲרֵ֖י מ֥וֹת אַחְאָֽב׃","wa⁠yi̇pĕşǎ֤ʻ mwòʼáb֙ bĕ̇⁠yişĕ̂ráʼé֔l ʼaẖàré֖y m֥wòţ ʼaẖĕʼáֽb׃"],[1,2,"וַ⁠יִּפֹּ֨ל אֲחַזְיָ֜ה בְּעַ֣ד הַ⁠שְּׂבָכָ֗ה בַּ⁠עֲלִיָּת֛⁠וֹ אֲשֶׁ֥ר בְּ⁠שֹׁמְר֖וֹן וַ⁠יָּ֑חַל וַ⁠יִּשְׁלַ֣ח מַלְאָכִ֔ים וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ לְכ֣וּ דִרְשׁ֗וּ בְּ⁠בַ֤עַל זְבוּב֙ אֱלֹהֵ֣י עֶקְר֔וֹן אִם־אֶחְיֶ֖ה מֵ⁠חֳלִ֥י זֶֽה׃ס","wa⁠yi̇pò̇֨l ʼàẖazĕyá֜h bĕ̇ʻa֣d ha⁠şĕ̇̂báká֗h bȧ⁠ʻàliyá̇ţ֛⁠wò ʼàşě֥r bĕ̇⁠şò̌mĕr֖wòn wa⁠yá֑̇ẖal wa⁠yi̇şĕ̌la֣ẖ malĕʼáki֔ym wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ lĕk֣ẇ dirĕş̌֗ẇ bĕ̇⁠ba֤ʻal zĕbẇb֙ ʼèlòhé֣y ʻeqĕr֔wòn ʼim-ʼeẖĕye֖h mé⁠ẖoli֥y zeֽh׃s"],[1,3,"וּ⁠מַלְאַ֣ךְ יְהוָ֗ה דִּבֶּר֙ אֶל־אֵלִיָּ֣ה הַ⁠תִּשְׁבִּ֔י ק֣וּם עֲלֵ֔ה לִ⁠קְרַ֖את מַלְאֲכֵ֣י מֶֽלֶךְ־שֹׁמְר֑וֹן וְ⁠דַבֵּ֣ר אֲלֵ⁠הֶ֔ם הַֽ⁠מִ⁠בְּלִ֤י אֵין־אֱלֹהִים֙ בְּ⁠יִשְׂרָאֵ֔ל אַתֶּם֙ הֹֽלְכִ֔ים לִ⁠דְרֹ֕שׁ בְּ⁠בַ֥עַל זְב֖וּב אֱלֹהֵ֥י עֶקְרֽוֹן׃","ẇ⁠malĕʼa֣kĕ yĕhwá֗h di̇bėr֙ ʼel-ʼéliyá֣̇h ha⁠ţi̇şĕ̌bi̇֔y q֣ẇm ʻàlé֔h li⁠qĕra֖ʼţ malĕʼàké֣y meֽlekĕ-şò̌mĕr֑wòn wĕ⁠dabé֣̇r ʼàlé⁠he֔m haֽ⁠mi⁠bĕ̇li֤y ʼéyn-ʼèlòhiym֙ bĕ̇⁠yişĕ̂ráʼé֔l ʼaţėm֙ hòֽlĕki֔ym li⁠dĕrò֕ş̌ bĕ̇⁠ba֥ʻal zĕb֖ẇb ʼèlòhé֥y ʻeqĕrֽwòn׃"],[1,4,"וְ⁠לָ⁠כֵן֙ כֹּֽה־אָמַ֣ר יְהוָ֔ה הַ⁠מִּטָּ֞ה אֲשֶׁר־עָלִ֥יתָ שָּׁ֛ם לֹֽא־תֵרֵ֥ד מִמֶּ֖⁠נָּה כִּ֣י מ֣וֹת תָּמ֑וּת וַ⁠יֵּ֖לֶךְ אֵלִיָּֽה׃","wĕ⁠lá⁠kén֙ kòֽ̇h-ʼáma֣r yĕhwá֔h ha⁠mi̇tá̇֞h ʼàşěr-ʻáli֥yţá şá֛̇̌m lòֽʼ-ţéré֥d mimė֖⁠ná̇h ki֣̇y m֣wòţ ţá̇m֑ẇţ wa⁠yé֖̇lekĕ ʼéliyáֽ̇h׃"],[1,5,"וַ⁠יָּשׁ֥וּבוּ הַ⁠מַּלְאָכִ֖ים אֵלָ֑י⁠ו וַ⁠יֹּ֥אמֶר אֲלֵי⁠הֶ֖ם מַה־זֶּ֥ה שַׁבְתֶּֽם׃","wa⁠yá̇ş֥̌ẇbẇ ha⁠mȧlĕʼáki֖ym ʼélá֑y⁠w wa⁠yò֥̇ʼmer ʼàléy⁠he֖m mah-zė֥h şǎbĕţėֽm׃"],[1,6,"וַ⁠יֹּאמְר֨וּ אֵלָ֜י⁠ו אִ֣ישׁ ׀ עָלָ֣ה לִ⁠קְרָאתֵ֗⁠נוּ וַ⁠יֹּ֣אמֶר אֵלֵי⁠נוּ֮ לְכ֣וּ שׁוּבוּ֮ אֶל־הַ⁠מֶּ֣לֶךְ אֲשֶׁר־שָׁלַ֣ח אֶתְ⁠כֶם֒ וְ⁠דִבַּרְתֶּ֣ם אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה הַֽ⁠מִ⁠בְּלִ֤י אֵין־אֱלֹהִים֙ בְּ⁠יִשְׂרָאֵ֔ל אַתָּ֣ה שֹׁלֵ֔חַ לִ⁠דְרֹ֕שׁ בְּ⁠בַ֥עַל זְב֖וּב אֱלֹהֵ֣י עֶקְר֑וֹן לָ֠⁠כֵן הַ⁠מִּטָּ֞ה אֲשֶׁר־עָלִ֥יתָ שָּׁ֛ם לֹֽא־תֵרֵ֥ד מִמֶּ֖⁠נָּה כִּֽי־מ֥וֹת תָּמֽוּת׃","wa⁠yò̇ʼmĕr֨ẇ ʼélá֜y⁠w ʼi֣yş̌ ׀ ʻálá֣h li⁠qĕráʼţé֗⁠nẇ wa⁠yò֣̇ʼmer ʼéléy⁠nẇ֮ lĕk֣ẇ ş̌ẇbẇ֮ ʼel-ha⁠mė֣lekĕ ʼàşěr-şá̌la֣ẖ ʼeţĕ⁠kem֒ wĕ⁠dibȧrĕţė֣m ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h haֽ⁠mi⁠bĕ̇li֤y ʼéyn-ʼèlòhiym֙ bĕ̇⁠yişĕ̂ráʼé֔l ʼaţá֣̇h şò̌lé֔ẖa li⁠dĕrò֕ş̌ bĕ̇⁠ba֥ʻal zĕb֖ẇb ʼèlòhé֣y ʻeqĕr֑wòn lá֠⁠kén ha⁠mi̇tá̇֞h ʼàşěr-ʻáli֥yţá şá֛̇̌m lòֽʼ-ţéré֥d mimė֖⁠ná̇h kiֽ̇y-m֥wòţ ţá̇mֽẇţ׃"],[1,7,"וַ⁠יְדַבֵּ֣ר אֲלֵ⁠הֶ֔ם מֶ֚ה מִשְׁפַּ֣ט הָ⁠אִ֔ישׁ אֲשֶׁ֥ר עָלָ֖ה לִ⁠קְרַאתְ⁠כֶ֑ם וַ⁠יְדַבֵּ֣ר אֲלֵי⁠כֶ֔ם אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yĕdabé֣̇r ʼàlé⁠he֔m me֚h mişĕ̌pȧ֣t há⁠ʼi֔yş̌ ʼàşě֥r ʻálá֖h li⁠qĕraʼţĕ⁠ke֑m wa⁠yĕdabé֣̇r ʼàléy⁠ke֔m ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[1,8,"וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו אִ֚ישׁ בַּ֣עַל שֵׂעָ֔ר וְ⁠אֵז֥וֹר ע֖וֹר אָז֣וּר בְּ⁠מָתְנָ֑י⁠ו וַ⁠יֹּאמַ֕ר אֵלִיָּ֥ה הַ⁠תִּשְׁבִּ֖י הֽוּא׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w ʼi֚yş̌ bȧ֣ʻal şé̂ʻá֔r wĕ⁠ʼéz֥wòr ʻ֖wòr ʼáz֣ẇr bĕ̇⁠máţĕná֑y⁠w wa⁠yò̇ʼma֕r ʼéliyá֥̇h ha⁠ţi̇şĕ̌bi֖̇y hֽẇʼ׃"],[1,9,"וַ⁠יִּשְׁלַ֥ח אֵלָ֛י⁠ו שַׂר־חֲמִשִּׁ֖ים וַ⁠חֲמִשָּׁ֑י⁠ו וַ⁠יַּ֣עַל אֵלָ֗י⁠ו וְ⁠הִנֵּה֙ יֹשֵׁב֙ עַל־רֹ֣אשׁ הָ⁠הָ֔ר וַ⁠יְדַבֵּ֣ר אֵלָ֔י⁠ו אִ֚ישׁ הָֽ⁠אֱלֹהִ֔ים הַ⁠מֶּ֥לֶךְ דִּבֶּ֖ר רֵֽדָ⁠ה׃","wa⁠yi̇şĕ̌la֥ẖ ʼélá֛y⁠w şâr-ẖàmişi֖̇̌ym wa⁠ẖàmişá֑̇̌y⁠w wa⁠yȧ֣ʻal ʼélá֗y⁠w wĕ⁠hiné̇h֙ yòşé̌b֙ ʻal-rò֣ʼş̌ há⁠há֔r wa⁠yĕdabé֣̇r ʼélá֔y⁠w ʼi֚yş̌ háֽ⁠ʼèlòhi֔ym ha⁠mė֥lekĕ di̇bė֖r réֽdá⁠h׃"],[1,10,"וַ⁠יַּעֲנֶ֣ה אֵלִיָּ֗הוּ וַ⁠יְדַבֵּר֮ אֶל־שַׂ֣ר הַ⁠חֲמִשִּׁים֒ וְ⁠אִם־אִ֤ישׁ אֱלֹהִים֙ אָ֔נִי תֵּ֤רֶד אֵשׁ֙ מִן־הַ⁠שָּׁמַ֔יִם וְ⁠תֹאכַ֥ל אֹתְ⁠ךָ֖ וְ⁠אֶת־חֲמִשֶּׁ֑י⁠ךָ וַ⁠תֵּ֤רֶד אֵשׁ֙ מִן־הַ⁠שָּׁמַ֔יִם וַ⁠תֹּ֥אכַל אֹת֖⁠וֹ וְ⁠אֶת־חֲמִשָּֽׁי⁠ו׃","wa⁠yȧʻàne֣h ʼéliyá̇֗hẇ wa⁠yĕdabé̇r֮ ʼel-şâ֣r ha⁠ẖàmişi̇̌ym֒ wĕ⁠ʼim-ʼi֤yş̌ ʼèlòhiym֙ ʼá֔niy ţé֤̇red ʼéş̌֙ min-ha⁠şá̇̌ma֔yim wĕ⁠ţòʼka֥l ʼòţĕ⁠ká֖ wĕ⁠ʼeţ-ẖàmişė֑̌y⁠ká wa⁠ţé֤̇red ʼéş̌֙ min-ha⁠şá̇̌ma֔yim wa⁠ţò֥̇ʼkal ʼòţ֖⁠wò wĕ⁠ʼeţ-ẖàmişáֽ̇̌y⁠w׃"],[1,11,"וַ⁠יָּ֜שָׁב וַ⁠יִּשְׁלַ֥ח אֵלָ֛י⁠ו שַׂר־חֲמִשִּׁ֥ים אַחֵ֖ר וַ⁠חֲמִשָּׁ֑י⁠ו וַ⁠יַּ֨עַן֙ וַ⁠יְדַבֵּ֣ר אֵלָ֔י⁠ו אִ֚ישׁ הָ⁠אֱלֹהִ֔ים כֹּֽה־אָמַ֥ר הַ⁠מֶּ֖לֶךְ מְהֵרָ֥ה רֵֽדָ⁠ה׃","wa⁠yá̇֜şá̌b wa⁠yi̇şĕ̌la֥ẖ ʼélá֛y⁠w şâr-ẖàmişi֥̇̌ym ʼaẖé֖r wa⁠ẖàmişá֑̇̌y⁠w wa⁠yȧ֨ʻan֙ wa⁠yĕdabé֣̇r ʼélá֔y⁠w ʼi֚yş̌ há⁠ʼèlòhi֔ym kòֽ̇h-ʼáma֥r ha⁠mė֖lekĕ mĕhérá֥h réֽdá⁠h׃"],[1,12,"וַ⁠יַּ֣עַן אֵלִיָּה֮ וַ⁠יְדַבֵּ֣ר אֲלֵי⁠הֶם֒ אִם־אִ֤ישׁ הָֽ⁠אֱלֹהִים֙ אָ֔נִי תֵּ֤רֶד אֵשׁ֙ מִן־הַ⁠שָּׁמַ֔יִם וְ⁠תֹאכַ֥ל אֹתְ⁠ךָ֖ וְ⁠אֶת־חֲמִשֶּׁ֑י⁠ךָ וַ⁠תֵּ֤רֶד אֵשׁ־אֱלֹהִים֙ מִן־הַ⁠שָּׁמַ֔יִם וַ⁠תֹּ֥אכַל אֹת֖⁠וֹ וְ⁠אֶת־חֲמִשָּֽׁי⁠ו׃","wa⁠yȧ֣ʻan ʼéliyá̇h֮ wa⁠yĕdabé֣̇r ʼàléy⁠hem֒ ʼim-ʼi֤yş̌ hֽá⁠ʼèlòhiym֙ ʼá֔niy ţé֤̇red ʼéş̌֙ min-ha⁠şá̇̌ma֔yim wĕ⁠ţòʼka֥l ʼòţĕ⁠ká֖ wĕ⁠ʼeţ-ẖàmişė֑̌y⁠ká wa⁠ţé֤̇red ʼéş̌-ʼèlòhiym֙ min-ha⁠şá̇̌ma֔yim wa⁠ţò֥̇ʼkal ʼòţ֖⁠wò wĕ⁠ʼeţ-ẖàmişáֽ̇̌y⁠w׃"],[1,13,"וַ⁠יָּ֗שָׁב וַ⁠יִּשְׁלַ֛ח שַׂר־חֲמִשִּׁ֥ים שְׁלִשִׁ֖ים וַ⁠חֲמִשָּׁ֑י⁠ו וַ⁠יַּ֡עַל וַ⁠יָּבֹא֩ שַׂר־הַ⁠חֲמִשִּׁ֨ים הַ⁠שְּׁלִישִׁ֜י וַ⁠יִּכְרַ֥ע עַל־בִּרְכָּ֣י⁠ו ׀ לְ⁠נֶ֣גֶד אֵלִיָּ֗הוּ וַ⁠יִּתְחַנֵּ֤ן אֵלָי⁠ו֙ וַ⁠יְדַבֵּ֣ר אֵלָ֔י⁠ו אִ֚ישׁ הָֽ⁠אֱלֹהִ֔ים תִּֽיקַר־נָ֣א נַפְשִׁ֗⁠י וְ⁠נֶ֨פֶשׁ עֲבָדֶ֥י⁠ךָֽ אֵ֛לֶּה חֲמִשִּׁ֖ים בְּ⁠עֵינֶֽי⁠ךָ׃","wa⁠yá̇֗şá̌b wa⁠yi̇şĕ̌la֛ẖ şâr-ẖàmişi֥̇̌ym şĕ̌lişǐ֖ym wa⁠ẖàmişá֑̇̌y⁠w wa⁠yȧ֡ʻal wa⁠yá̇bòʼ֩ şâr-ha⁠ẖàmişi̇̌֨ym ha⁠şĕ̇̌liyşǐ֜y wa⁠yi̇kĕra֥ʻ ʻal-bi̇rĕká֣̇y⁠w ׀ lĕ⁠ne֣ged ʼéliyá̇֗hẇ wa⁠yi̇ţĕẖané֤̇n ʼéláy⁠w֙ wa⁠yĕdabé֣̇r ʼélá֔y⁠w ʼi֚yş̌ háֽ⁠ʼèlòhi֔ym ţiֽ̇yqar-ná֣ʼ napĕşǐ֗⁠y wĕ⁠ne֨peş̌ ʻàbáde֥y⁠káֽ ʼé֛lėh ẖàmişi֖̇̌ym bĕ̇⁠ʻéyneֽy⁠ká׃"],[1,14,"הִ֠נֵּה יָ֤רְדָה אֵשׁ֙ מִן־הַ⁠שָּׁמַ֔יִם וַ֠⁠תֹּאכַל אֶת־שְׁנֵ֞י שָׂרֵ֧י הַ⁠חֲמִשִּׁ֛ים הָ⁠רִאשֹׁנִ֖ים וְ⁠אֶת־חֲמִשֵּׁי⁠הֶ֑ם וְ⁠עַתָּ֕ה תִּיקַ֥ר נַפְשִׁ֖⁠י בְּ⁠עֵינֶֽי⁠ךָ׃ס","hi֠né̇h yá֤rĕdáh ʼéş̌֙ min-ha⁠şá̇̌ma֔yim wa֠⁠ţò̇ʼkal ʼeţ-şĕ̌né֞y şá̂ré֧y ha⁠ẖàmişi֛̇̌ym há⁠riʼşò̌ni֖ym wĕ⁠ʼeţ-ẖàmişé̇̌y⁠he֑m wĕ⁠ʻaţá̇֕h ţi̇yqa֥r napĕşǐ֖⁠y bĕ̇⁠ʻéyneֽy⁠ká׃s"],[1,15,"וַ⁠יְדַבֵּ֞ר מַלְאַ֤ךְ יְהוָה֙ אֶל־אֵ֣לִיָּ֔הוּ רֵ֣ד אוֹת֔⁠וֹ אַל־תִּירָ֖א מִ⁠פָּנָ֑י⁠ו וַ⁠יָּ֛קָם וַ⁠יֵּ֥רֶד אוֹת֖⁠וֹ אֶל־הַ⁠מֶּֽלֶךְ׃","wa⁠yĕdabé̇֞r malĕʼa֤kĕ yĕhwáh֙ ʼel-ʼé֣liyá̇֔hẇ ré֣d ʼwòţ֔⁠wò ʼal-ţi̇yrá֖ʼ mi⁠pá̇ná֑y⁠w wa⁠yá֛̇qám wa⁠yé֥̇red ʼwòţ֖⁠wò ʼel-ha⁠mėֽlekĕ׃"],[1,16,"וַ⁠יְדַבֵּ֨ר אֵלָ֜י⁠ו כֹּֽה־אָמַ֣ר יְהוָ֗ה יַ֜עַן אֲשֶׁר־שָׁלַ֣חְתָּ מַלְאָכִים֮ לִ⁠דְרֹשׁ֮ בְּ⁠בַ֣עַל זְבוּב֮ אֱלֹהֵ֣י עֶקְרוֹן֒ הַֽ⁠מִ⁠בְּלִ֤י אֵין־אֱלֹהִים֙ בְּ⁠יִשְׂרָאֵ֔ל לִ⁠דְרֹ֖שׁ בִּ⁠דְבָר֑⁠וֹ לָ֠⁠כֵן הַ⁠מִּטָּ֞ה אֲשֶׁר־עָלִ֥יתָ שָּׁ֛ם לֹֽא־תֵרֵ֥ד מִמֶּ֖⁠נָּה כִּֽי־מ֥וֹת תָּמֽוּת׃","wa⁠yĕdabé̇֨r ʼélá֜y⁠w kòֽ̇h-ʼáma֣r yĕhwá֗h ya֜ʻan ʼàşěr-şá̌la֣ẖĕţá̇ malĕʼákiym֮ li⁠dĕròş֮̌ bĕ̇⁠ba֣ʻal zĕbẇb֮ ʼèlòhé֣y ʻeqĕrwòn֒ haֽ⁠mi⁠bĕ̇li֤y ʼéyn-ʼèlòhiym֙ bĕ̇⁠yişĕ̂ráʼé֔l li⁠dĕrò֖ş̌ bi̇⁠dĕbár֑⁠wò lá֠⁠kén ha⁠mi̇tá̇֞h ʼàşěr-ʻáli֥yţá şá֛̇̌m lòֽʼ-ţéré֥d mimė֖⁠ná̇h kiֽ̇y-m֥wòţ ţá̇mֽẇţ׃"],[1,17,"וַ⁠יָּ֜מָת כִּ⁠דְבַ֥ר יְהוָ֣ה ׀ אֲשֶׁר־דִּבֶּ֣ר אֵלִיָּ֗הוּ וַ⁠יִּמְלֹ֤ךְ יְהוֹרָם֙ תַּחְתָּ֔י⁠ו פ בִּ⁠שְׁנַ֣ת שְׁתַּ֔יִם לִ⁠יהוֹרָ֥ם בֶּן־יְהוֹשָׁפָ֖ט מֶ֣לֶךְ יְהוּדָ֑ה כִּ֛י לֹֽא־הָ֥יָה ל֖⁠וֹ בֵּֽן׃","wa⁠yá̇֜máţ ki̇⁠dĕba֥r yĕhwá֣h ׀ ʼàşěr-di̇bė֣r ʼéliyá̇֗hẇ wa⁠yi̇mĕlò֤kĕ yĕhwòrám֙ ţȧẖĕţá̇֔y⁠w p bi̇⁠şĕ̌na֣ţ şĕ̌ţȧ֔yim li⁠yhwòrá֥m bėn-yĕhwòşá̌pá֖t me֣lekĕ yĕhẇdá֑h ki֛̇y lòֽʼ-há֥yáh l֖⁠wò béֽ̇n׃"],[1,18,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י אֲחַזְיָ֖הוּ אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֽוֹא־הֵ֣מָּה כְתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠ye֛ţer di̇bĕré֥y ʼàẖazĕyá֖hẇ ʼàşě֣r ʻáşá֑̂h hà⁠lֽwòʼ-hé֣má̇h kĕţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃p"],[2,1,"וַ⁠יְהִ֗י בְּ⁠הַעֲל֤וֹת יְהוָה֙ אֶת־אֵ֣לִיָּ֔הוּ בַּֽ⁠סְעָרָ֖ה הַ⁠שָּׁמָ֑יִם וַ⁠יֵּ֧לֶךְ אֵלִיָּ֛הוּ וֶ⁠אֱלִישָׁ֖ע מִן־הַ⁠גִּלְגָּֽל׃","wa⁠yĕhi֗y bĕ̇⁠haʻàl֤wòţ yĕhwáh֙ ʼeţ-ʼé֣liyá̇֔hẇ bȧֽ⁠sĕʻárá֖h ha⁠şá̇̌má֑yim wa⁠yé֧̇lekĕ ʼéliyá֛̇hẇ we⁠ʼèliyşá֖̌ʻ min-ha⁠gi̇lĕgáֽ̇l׃"],[2,2,"וַ⁠יֹּאמֶר֩ אֵלִיָּ֨הוּ אֶל־אֱלִישָׁ֜ע שֵֽׁב־נָ֣א פֹ֗ה כִּ֤י יְהוָה֙ שְׁלָחַ֣⁠נִי עַד־בֵּֽית־אֵ֔ל וַ⁠יֹּ֣אמֶר אֱלִישָׁ֔ע חַי־יְהוָ֥ה וְ⁠חֵֽי־נַפְשְׁ⁠ךָ֖ אִם־אֶעֶזְבֶ֑⁠ךָּ וַ⁠יֵּרְד֖וּ בֵּֽית־אֵֽל׃","wa⁠yò̇ʼmer֩ ʼéliyá̇֨hẇ ʼel-ʼèliyşá̌֜ʻ şéֽ̌b-ná֣ʼ pò֗h ki֤̇y yĕhwáh֙ şĕ̌láẖa֣⁠niy ʻad-béֽ̇yţ-ʼé֔l wa⁠yò֣̇ʼmer ʼèliyşá̌֔ʻ ẖay-yĕhwá֥h wĕ⁠ẖéֽy-napĕşĕ̌⁠ká֖ ʼim-ʼeʻezĕbe֑⁠ká̇ wa⁠yé̇rĕd֖ẇ béֽ̇yţ-ʼéֽl׃"],[2,3,"וַ⁠יֵּצְא֨וּ בְנֵֽי־הַ⁠נְּבִיאִ֥ים אֲשֶׁר־בֵּֽית־אֵל֮ אֶל־אֱלִישָׁע֒ וַ⁠יֹּאמְר֣וּ אֵלָ֔י⁠ו הֲ⁠יָדַ֕עְתָּ כִּ֣י הַ⁠יּ֗וֹם יְהוָ֛ה לֹקֵ֥חַ אֶת־אֲדֹנֶ֖י⁠ךָ מֵ⁠עַ֣ל רֹאשֶׁ֑⁠ךָ וַ⁠יֹּ֛אמֶר גַּם־אֲנִ֥י יָדַ֖עְתִּי הֶחֱשֽׁוּ׃","wa⁠yé̇ẕĕʼ֨ẇ bĕnéֽy-ha⁠nĕ̇biyʼi֥ym ʼàşěr-béֽ̇yţ-ʼél֮ ʼel-ʼèliyşá̌ʻ֒ wa⁠yò̇ʼmĕr֣ẇ ʼélá֔y⁠w hà⁠yáda֕ʻĕţá̇ ki֣̇y ha⁠ẏ֗wòm yĕhwá֛h lòqé֥ẖa ʼeţ-ʼàdòne֖y⁠ká mé⁠ʻa֣l ròʼşě֑⁠ká wa⁠yò֛̇ʼmer gȧm-ʼàni֥y yáda֖ʻĕţi̇y heẖèşֽ̌ẇ׃"],[2,4,"וַ⁠יֹּאמֶר֩ ל֨⁠וֹ אֵלִיָּ֜הוּ אֱלִישָׁ֣ע ׀ שֵֽׁב־נָ֣א פֹ֗ה כִּ֤י יְהוָה֙ שְׁלָחַ֣⁠נִי יְרִיח֔וֹ וַ⁠יֹּ֕אמֶר חַי־יְהוָ֥ה וְ⁠חֵֽי־נַפְשְׁ⁠ךָ֖ אִם־אֶעֶזְבֶ֑⁠ךָּ וַ⁠יָּבֹ֖אוּ יְרִיחֽוֹ׃","wa⁠yò̇ʼmer֩ l֨⁠wò ʼéliyá̇֜hẇ ʼèliyşá֣̌ʻ ׀ şéֽ̌b-ná֣ʼ pò֗h ki֤̇y yĕhwáh֙ şĕ̌láẖa֣⁠niy yĕriyẖ֔wò wa⁠yò̇֕ʼmer ẖay-yĕhwá֥h wĕ⁠ẖéֽy-napĕşĕ̌⁠ká֖ ʼim-ʼeʻezĕbe֑⁠ká̇ wa⁠yá̇bò֖ʼẇ yĕriyẖֽwò׃"],[2,5,"וַ⁠יִּגְּשׁ֨וּ בְנֵֽי־הַ⁠נְּבִיאִ֥ים אֲשֶׁר־בִּֽ⁠ירִיחוֹ֮ אֶל־אֱלִישָׁע֒ וַ⁠יֹּאמְר֣וּ אֵלָ֔י⁠ו הֲ⁠יָדַ֕עְתָּ כִּ֣י הַ⁠יּ֗וֹם יְהוָ֛ה לֹקֵ֥חַ אֶת־אֲדֹנֶ֖י⁠ךָ מֵ⁠עַ֣ל רֹאשֶׁ֑⁠ךָ וַ⁠יֹּ֛אמֶר גַּם־אֲנִ֥י יָדַ֖עְתִּי הֶחֱשֽׁוּ׃","wa⁠yi̇gĕ̇ş̌֨ẇ bĕnéֽy-ha⁠nĕ̇biyʼi֥ym ʼàşěr-biֽ̇⁠yriyẖwò֮ ʼel-ʼèliyşá̌ʻ֒ wa⁠yò̇ʼmĕr֣ẇ ʼélá֔y⁠w hà⁠yáda֕ʻĕţá̇ ki֣̇y ha⁠ẏ֗wòm yĕhwá֛h lòqé֥ẖa ʼeţ-ʼàdòne֖y⁠ká mé⁠ʻa֣l ròʼşě֑⁠ká wa⁠yò֛̇ʼmer gȧm-ʼàni֥y yáda֖ʻĕţi̇y heẖèşֽ̌ẇ׃"],[2,6,"וַ⁠יֹּאמֶר֩ ל֨⁠וֹ אֵלִיָּ֜הוּ שֵֽׁב־נָ֣א פֹ֗ה כִּ֤י יְהוָה֙ שְׁלָחַ֣⁠נִי הַ⁠יַּרְדֵּ֔נָ⁠ה וַ⁠יֹּ֕אמֶר חַי־יְהוָ֥ה וְ⁠חֵֽי־נַפְשְׁ⁠ךָ֖ אִם־אֶעֶזְבֶ֑⁠ךָּ וַ⁠יֵּלְכ֖וּ שְׁנֵי⁠הֶֽם׃","wa⁠yò̇ʼmer֩ l֨⁠wò ʼéliyá̇֜hẇ şéֽ̌b-ná֣ʼ pò֗h ki֤̇y yĕhwáh֙ şĕ̌láẖa֣⁠niy ha⁠yȧrĕdé̇֔ná⁠h wa⁠yò̇֕ʼmer ẖay-yĕhwá֥h wĕ⁠ẖéֽy-napĕşĕ̌⁠ká֖ ʼim-ʼeʻezĕbe֑⁠ká̇ wa⁠yé̇lĕk֖ẇ şĕ̌néy⁠heֽm׃"],[2,7,"וַ⁠חֲמִשִּׁ֨ים אִ֜ישׁ מִ⁠בְּנֵ֤י הַ⁠נְּבִיאִים֙ הָֽלְכ֔וּ וַ⁠יַּעַמְד֥וּ מִ⁠נֶּ֖גֶד מֵ⁠רָח֑וֹק וּ⁠שְׁנֵי⁠הֶ֖ם עָמְד֥וּ עַל־הַ⁠יַּרְדֵּֽן׃","wa⁠ẖàmişi̇̌֨ym ʼi֜yş̌ mi⁠bĕ̇né֤y ha⁠nĕ̇biyʼiym֙ háֽlĕk֔ẇ wa⁠yȧʻamĕd֥ẇ mi⁠nė֖ged mé⁠ráẖ֑wòq ẇ⁠şĕ̌néy⁠he֖m ʻámĕd֥ẇ ʻal-ha⁠yȧrĕdéֽ̇n׃"],[2,8,"וַ⁠יִּקַּח֩ אֵלִיָּ֨הוּ אֶת־אַדַּרְתּ֤⁠וֹ וַ⁠יִּגְלֹם֙ וַ⁠יַּכֶּ֣ה אֶת־הַ⁠מַּ֔יִם וַ⁠יֵּחָצ֖וּ הֵ֣נָּה וָ⁠הֵ֑נָּה וַ⁠יַּעַבְר֥וּ שְׁנֵי⁠הֶ֖ם בֶּ⁠חָרָבָֽה׃","wa⁠yi̇qȧẖ֩ ʼéliyá̇֨hẇ ʼeţ-ʼadȧrĕţ֤̇⁠wò wa⁠yi̇gĕlòm֙ wa⁠yȧkė֣h ʼeţ-ha⁠mȧ֔yim wa⁠yé̇ẖáẕ֖ẇ hé֣ná̇h wá⁠hé֑ná̇h wa⁠yȧʻabĕr֥ẇ şĕ̌néy⁠he֖m bė⁠ẖárábáֽh׃"],[2,9,"וַ⁠יְהִ֣י כְ⁠עָבְרָ֗⁠ם וְ⁠אֵ֨לִיָּ֜הוּ אָמַ֤ר אֶל־אֱלִישָׁע֙ שְׁאַל֙ מָ֣ה אֶֽעֱשֶׂה־לָּ֔⁠ךְ בְּ⁠טֶ֖רֶם אֶלָּקַ֣ח מֵ⁠עִמָּ֑⁠ךְ וַ⁠יֹּ֣אמֶר אֱלִישָׁ֔ע וִֽ⁠יהִי־נָ֛א פִּֽי־שְׁנַ֥יִם בְּ⁠רוּחֲ⁠ךָ֖ אֵלָֽ⁠י׃","wa⁠yĕhi֣y kĕ⁠ʻábĕrá֗⁠m wĕ⁠ʼé֨liyá̇֜hẇ ʼáma֤r ʼel-ʼèliyşá̌ʻ֙ şĕ̌ʼal֙ má֣h ʼeֽʻèşêh-lá̇֔⁠kĕ bĕ̇⁠te֖rem ʼelá̇qa֣ẖ mé⁠ʻimá֑̇⁠kĕ wa⁠yò֣̇ʼmer ʼèliyşá̌֔ʻ wiֽ⁠yhiy-ná֛ʼ piֽ̇y-şĕ̌na֥yim bĕ̇⁠rẇẖà⁠ká֖ ʼéláֽ⁠y׃"],[2,10,"וַ⁠יֹּ֖אמֶר הִקְשִׁ֣יתָ לִ⁠שְׁא֑וֹל אִם־תִּרְאֶ֨ה אֹתִ֜⁠י לֻקָּ֤ח מֵֽ⁠אִתָּ⁠ךְ֙ יְהִֽי־לְ⁠ךָ֣ כֵ֔ן וְ⁠אִם־אַ֖יִן לֹ֥א יִהְיֶֽה׃","wa⁠yò֖̇ʼmer hiqĕşǐ֣yţá li⁠şĕ̌ʼ֑wòl ʼim-ţi̇rĕʼe֨h ʼòţi֜⁠y luqá֤̇ẖ méֽ⁠ʼiţá̇⁠kĕ֙ yĕhiֽy-lĕ⁠ká֣ ké֔n wĕ⁠ʼim-ʼa֖yin lò֥ʼ yihĕyeֽh׃"],[2,11,"וַ⁠יְהִ֗י הֵ֣מָּה הֹלְכִ֤ים הָלוֹךְ֙ וְ⁠דַבֵּ֔ר וְ⁠הִנֵּ֤ה רֶֽכֶב־אֵשׁ֙ וְ⁠ס֣וּסֵי אֵ֔שׁ וַ⁠יַּפְרִ֖דוּ בֵּ֣ין שְׁנֵי⁠הֶ֑ם וַ⁠יַּ֨עַל֙ אֵ֣לִיָּ֔הוּ בַּֽ⁠סְעָרָ֖ה הַ⁠שָּׁמָֽיִם׃","wa⁠yĕhi֗y hé֣má̇h hòlĕki֤ym hálwòkĕ֙ wĕ⁠dabé̇֔r wĕ⁠hiné֤̇h reֽkeb-ʼéş̌֙ wĕ⁠s֣ẇséy ʼé֔ş̌ wa⁠yȧpĕri֖dẇ bé֣̇yn şĕ̌néy⁠he֑m wa⁠yȧ֨ʻal֙ ʼé֣liyá̇֔hẇ bȧֽ⁠sĕʻárá֖h ha⁠şá̇̌máֽyim׃"],[2,12,"וֶ⁠אֱלִישָׁ֣ע רֹאֶ֗ה וְ⁠ה֤וּא מְצַעֵק֙ אָבִ֣⁠י ׀ אָבִ֗⁠י רֶ֤כֶב יִשְׂרָאֵל֙ וּ⁠פָ֣רָשָׁ֔י⁠ו וְ⁠לֹ֥א רָאָ֖⁠הוּ ע֑וֹד וַֽ⁠יַּחֲזֵק֙ בִּ⁠בְגָדָ֔י⁠ו וַ⁠יִּקְרָעֵ֖⁠ם לִ⁠שְׁנַ֥יִם קְרָעִֽים׃","we⁠ʼèliyşá֣̌ʻ ròʼe֗h wĕ⁠h֤ẇʼ mĕẕaʻéq֙ ʼábi֣⁠y ׀ ʼábi֗⁠y re֤keb yişĕ̂ráʼél֙ ẇ⁠pá֣ráşá̌֔y⁠w wĕ⁠lò֥ʼ ráʼá֖⁠hẇ ʻ֑wòd wֽa⁠yȧẖàzéq֙ bi̇⁠bĕgádá֔y⁠w wa⁠yi̇qĕráʻé֖⁠m li⁠şĕ̌na֥yim qĕráʻiֽym׃"],[2,13,"וַ⁠יָּ֨רֶם֙ אֶת־אַדֶּ֣רֶת אֵלִיָּ֔הוּ אֲשֶׁ֥ר נָפְלָ֖ה מֵ⁠עָלָ֑י⁠ו וַ⁠יָּ֥שָׁב וַֽ⁠יַּעֲמֹ֖ד עַל־שְׂפַ֥ת הַ⁠יַּרְדֵּֽן׃","wa⁠yá̇֨rem֙ ʼeţ-ʼadė֣reţ ʼéliyá̇֔hẇ ʼàşě֥r nápĕlá֖h mé⁠ʻálá֑y⁠w wa⁠yá֥̇şá̌b waֽ⁠yȧʻàmò֖d ʻal-şĕ̂pa֥ţ ha⁠yȧrĕdéֽ̇n׃"],[2,14,"וַ⁠יִּקַּח֩ אֶת־אַדֶּ֨רֶת אֵלִיָּ֜הוּ אֲשֶׁר־נָפְלָ֤ה מֵֽ⁠עָלָי⁠ו֙ וַ⁠יַּכֶּ֣ה אֶת־הַ⁠מַּ֔יִם וַ⁠יֹּאמַ֕ר אַיֵּ֕ה יְהוָ֖ה אֱלֹהֵ֣י אֵלִיָּ֑הוּ אַף־ה֣וּא ׀ וַ⁠יַּכֶּ֣ה אֶת־הַ⁠מַּ֗יִם וַ⁠יֵּֽחָצוּ֙ הֵ֣נָּה וָ⁠הֵ֔נָּה וַֽ⁠יַּעֲבֹ֖ר אֱלִישָֽׁע׃","wa⁠yi̇qȧẖ֩ ʼeţ-ʼadė֨reţ ʼéliyá̇֜hẇ ʼàşěr-nápĕlá֤h méֽ⁠ʻáláy⁠w֙ wa⁠yȧkė֣h ʼeţ-ha⁠mȧ֔yim wa⁠yò̇ʼma֕r ʼayé̇֕h yĕhwá֖h ʼèlòhé֣y ʼéliyá֑̇hẇ ʼap-h֣ẇʼ ׀ wa⁠yȧkė֣h ʼeţ-ha⁠mȧ֗yim wa⁠yéֽ̇ẖáẕẇ֙ hé֣ná̇h wá⁠hé֔ná̇h waֽ⁠yȧʻàbò֖r ʼèliyşáֽ̌ʻ׃"],[2,15,"וַ⁠יִּרְאֻ֨⁠הוּ בְנֵֽי־הַ⁠נְּבִיאִ֤ים אֲשֶׁר־בִּֽ⁠ירִיחוֹ֙ מִ⁠נֶּ֔גֶד וַ⁠יֹּ֣אמְר֔וּ נָ֛חָה ר֥וּחַ אֵלִיָּ֖הוּ עַל־אֱלִישָׁ֑ע וַ⁠יָּבֹ֨אוּ֙ לִ⁠קְרָאת֔⁠וֹ וַ⁠יִּשְׁתַּחֲווּ־ל֖⁠וֹ אָֽרְצָ⁠ה׃","wa⁠yi̇rĕʼu֨⁠hẇ bĕnéֽy-ha⁠nĕ̇biyʼi֤ym ʼàşěr-biֽ̇⁠yriyẖwò֙ mi⁠nė֔ged wa⁠yò֣̇ʼmĕr֔ẇ ná֛ẖáh r֥ẇẖa ʼéliyá֖̇hẇ ʻal-ʼèliyşá֑̌ʻ wa⁠yá̇bò֨ʼẇ֙ li⁠qĕráʼţ֔⁠wò wa⁠yi̇şĕ̌ţȧẖàwẇ-l֖⁠wò ʼáֽrĕẕá⁠h׃"],[2,16,"וַ⁠יֹּאמְר֣וּ אֵלָ֡י⁠ו הִנֵּה־נָ֣א יֵֽשׁ־אֶת־עֲבָדֶי⁠ךָ֩ חֲמִשִּׁ֨ים אֲנָשִׁ֜ים בְּנֵֽי־חַ֗יִל יֵ֣לְכוּ נָא֮ וִ⁠יבַקְשׁ֣וּ אֶת־אֲדֹנֶי⁠ךָ֒ פֶּן־נְשָׂא⁠וֹ֙ ר֣וּחַ יְהוָ֔ה וַ⁠יַּשְׁלִכֵ֨⁠הוּ֙ בְּ⁠אַחַ֣ד הֶ⁠הָרִ֔ים א֖וֹ בְּ⁠אַחַ֣ת ה⁠גיאות וַ⁠יֹּ֖אמֶר לֹ֥א תִשְׁלָֽחוּ׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֡y⁠w hiné̇h-ná֣ʼ yéֽş̌-ʼeţ-ʻàbádey⁠ká֩ ẖàmişi̇̌֨ym ʼànáşǐ֜ym bĕ̇néֽy-ẖa֗yil yé֣lĕkẇ náʼ֮ wi⁠ybaqĕş֣̌ẇ ʼeţ-ʼàdòney⁠ká֒ pėn-nĕşá̂ʼ⁠wò֙ r֣ẇẖa yĕhwá֔h wa⁠yȧşĕ̌liké֨⁠hẇ֙ bĕ̇⁠ʼaẖa֣d he⁠hári֔ym ʼ֖wò bĕ̇⁠ʼaẖa֣ţ h⁠gyʼwţ wa⁠yò֖̇ʼmer lò֥ʼ ţişĕ̌láֽẖẇ׃"],[2,17,"וַ⁠יִּפְצְרוּ־ב֥⁠וֹ עַד־בֹּ֖שׁ וַ⁠יֹּ֣אמֶר שְׁלָ֑חוּ וַֽ⁠יִּשְׁלְחוּ֙ חֲמִשִּׁ֣ים אִ֔ישׁ וַ⁠יְבַקְשׁ֥וּ שְׁלֹשָֽׁה־יָמִ֖ים וְ⁠לֹ֥א מְצָאֻֽ⁠הוּ׃","wa⁠yi̇pĕẕĕrẇ-b֥⁠wò ʻad-bò֖̇ş̌ wa⁠yò֣̇ʼmer şĕ̌lá֑ẖẇ waֽ⁠yi̇şĕ̌lĕẖẇ֙ ẖàmişi֣̇̌ym ʼi֔yş̌ wa⁠yĕbaqĕş֥̌ẇ şĕ̌lòşáֽ̌h-yámi֖ym wĕ⁠lò֥ʼ mĕẕáʼuֽ⁠hẇ׃"],[2,18,"וַ⁠יָּשֻׁ֣בוּ אֵלָ֔י⁠ו וְ⁠ה֖וּא יֹשֵׁ֣ב בִּ⁠ירִיח֑וֹ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם הֲ⁠לֽוֹא־אָמַ֥רְתִּי אֲלֵי⁠כֶ֖ם אַל־תֵּלֵֽכוּ׃","wa⁠yá̇şǔ֣bẇ ʼélá֔y⁠w wĕ⁠h֖ẇʼ yòşé֣̌b bi̇⁠yriyẖ֑wò wa⁠yò֣̇ʼmer ʼàlé⁠he֔m hà⁠lֽwòʼ-ʼáma֥rĕţi̇y ʼàléy⁠ke֖m ʼal-ţé̇léֽkẇ׃"],[2,19,"וַ⁠יֹּ֨אמְר֜וּ אַנְשֵׁ֤י הָ⁠עִיר֙ אֶל־אֱלִישָׁ֔ע הִנֵּה־נָ֞א מוֹשַׁ֤ב הָ⁠עִיר֙ ט֔וֹב כַּ⁠אֲשֶׁ֥ר אֲדֹנִ֖⁠י רֹאֶ֑ה וְ⁠הַ⁠מַּ֥יִם רָעִ֖ים וְ⁠הָ⁠אָ֥רֶץ מְשַׁכָּֽלֶת׃","wa⁠yò̇֨ʼmĕr֜ẇ ʼanĕşé֤̌y há⁠ʻiyr֙ ʼel-ʼèliyşá̌֔ʻ hiné̇h-ná֞ʼ mwòşǎ֤b há⁠ʻiyr֙ t֔wòb kȧ⁠ʼàşě֥r ʼàdòni֖⁠y ròʼe֑h wĕ⁠ha⁠mȧ֥yim ráʻi֖ym wĕ⁠há⁠ʼá֥reẕ mĕşǎkáֽ̇leţ׃"],[2,20,"וַ⁠יֹּ֗אמֶר קְחוּ־לִ⁠י֙ צְלֹחִ֣ית חֲדָשָׁ֔ה וְ⁠שִׂ֥ימוּ שָׁ֖ם מֶ֑לַח וַ⁠יִּקְח֖וּ אֵלָֽי⁠ו׃","wa⁠yò̇֗ʼmer qĕẖẇ-li⁠y֙ ẕĕlòẖi֣yţ ẖàdáşá̌֔h wĕ⁠şî֥ymẇ şá֖̌m me֑laẖ wa⁠yi̇qĕẖ֖ẇ ʼéláֽy⁠w׃"],[2,21,"וַ⁠יֵּצֵא֙ אֶל־מוֹצָ֣א הַ⁠מַּ֔יִם וַ⁠יַּשְׁלֶךְ־שָׁ֖ם מֶ֑לַח וַ⁠יֹּ֜אמֶר כֹּֽה־אָמַ֣ר יְהוָ֗ה רִפִּ֨אתִי֙ לַ⁠מַּ֣יִם הָ⁠אֵ֔לֶּה לֹֽא־יִהְיֶ֥ה מִ⁠שָּׁ֛ם ע֖וֹד מָ֥וֶת וּ⁠מְשַׁכָּֽלֶת׃","wa⁠yé̇ẕéʼ֙ ʼel-mwòẕá֣ʼ ha⁠mȧ֔yim wa⁠yȧşĕ̌lekĕ-şá֖̌m me֑laẖ wa⁠yò̇֜ʼmer kòֽ̇h-ʼáma֣r yĕhwá֗h ripi̇֨ʼţiy֙ la⁠mȧ֣yim há⁠ʼé֔lėh lòֽʼ-yihĕye֥h mi⁠şá֛̇̌m ʻ֖wòd má֥weţ ẇ⁠mĕşǎkáֽ̇leţ׃"],[2,22,"וַ⁠יֵּרָפ֣וּ הַ⁠מַּ֔יִם עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ⁠דְבַ֥ר אֱלִישָׁ֖ע אֲשֶׁ֥ר דִּבֵּֽר׃פ","wa⁠yé̇ráp֣ẇ ha⁠mȧ֔yim ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ki̇⁠dĕba֥r ʼèliyşá֖̌ʻ ʼàşě֥r di̇béֽ̇r׃p"],[2,23,"וַ⁠יַּ֥עַל מִ⁠שָּׁ֖ם בֵּֽית־אֵ֑ל וְ⁠ה֣וּא ׀ עֹלֶ֣ה בַ⁠דֶּ֗רֶךְ וּ⁠נְעָרִ֤ים קְטַנִּים֙ יָצְא֣וּ מִן־הָ⁠עִ֔יר וַ⁠יִּתְקַלְּסוּ־ב⁠וֹ֙ וַ⁠יֹּ֣אמְרוּ ל֔⁠וֹ עֲלֵ֥ה קֵרֵ֖חַ עֲלֵ֥ה קֵרֵֽחַ׃","wa⁠yȧ֥ʻal mi⁠şá֖̇̌m béֽ̇yţ-ʼé֑l wĕ⁠h֣ẇʼ ׀ ʻòle֣h ba⁠dė֗rekĕ ẇ⁠nĕʻári֤ym qĕtani̇ym֙ yáẕĕʼ֣ẇ min-há⁠ʻi֔yr wa⁠yi̇ţĕqalĕ̇sẇ-b⁠wò֙ wa⁠yò֣̇ʼmĕrẇ l֔⁠wò ʻàlé֥h qéré֖ẖa ʻàlé֥h qéréֽẖa׃"],[2,24,"וַ⁠יִּ֤פֶן אַֽחֲרָי⁠ו֙ וַ⁠יִּרְאֵ֔⁠ם וַֽ⁠יְקַלְלֵ֖⁠ם בְּ⁠שֵׁ֣ם יְהוָ֑ה וַ⁠תֵּצֶ֨אנָה שְׁתַּ֤יִם דֻּבִּים֙ מִן־הַ⁠יַּ֔עַר וַ⁠תְּבַקַּ֣עְנָה מֵ⁠הֶ֔ם אַרְבָּעִ֥ים וּ⁠שְׁנֵ֖י יְלָדִֽים׃","wa⁠yi֤̇pen ʼaֽẖàráy⁠w֙ wa⁠yi̇rĕʼé֔⁠m waֽ⁠yĕqalĕlé֖⁠m bĕ̇⁠şé֣̌m yĕhwá֑h wa⁠ţé̇ẕe֨ʼnáh şĕ̌ţȧ֤yim du̇bi̇ym֙ min-ha⁠yȧ֔ʻar wa⁠ţĕ̇baqȧ֣ʻĕnáh mé⁠he֔m ʼarĕbá̇ʻi֥ym ẇ⁠şĕ̌né֖y yĕládiֽym׃"],[2,25,"וַ⁠יֵּ֥לֶךְ מִ⁠שָּׁ֖ם אֶל־הַ֣ר הַ⁠כַּרְמֶ֑ל וּ⁠מִ⁠שָּׁ֖ם שָׁ֥ב שֹׁמְרֽוֹן׃פ","wa⁠yé֥̇lekĕ mi⁠şá֖̇̌m ʼel-ha֣r ha⁠kȧrĕme֑l ẇ⁠mi⁠şá֖̇̌m şá֥̌b şò̌mĕrֽwòn׃p"],[3,1,"וִ⁠יהוֹרָ֣ם בֶּן־אַחְאָ֗ב מָלַ֤ךְ עַל־יִשְׂרָאֵל֙ בְּ⁠שֹׁ֣מְר֔וֹן בִּ⁠שְׁנַת֙ שְׁמֹנֶ֣ה עֶשְׂרֵ֔ה לִ⁠יהוֹשָׁפָ֖ט מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּמְלֹ֖ךְ שְׁתֵּים־עֶשְׂרֵ֥ה שָׁנָֽה׃","wi⁠yhwòrá֣m bėn-ʼaẖĕʼá֗b mála֤kĕ ʻal-yişĕ̂ráʼél֙ bĕ̇⁠şò֣̌mĕr֔wòn bi̇⁠şĕ̌naţ֙ şĕ̌mòne֣h ʻeşĕ̂ré֔h li⁠yhwòşá̌pá֖t me֣lekĕ yĕhẇdá֑h wa⁠yi̇mĕlò֖kĕ şĕ̌ţé̇ym-ʻeşĕ̂ré֥h şá̌náֽh׃"],[3,2,"וַ⁠יַּעֲשֶׂ֤ה הָ⁠רַע֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה רַ֕ק לֹ֥א כְ⁠אָבִ֖י⁠ו וּ⁠כְ⁠אִמּ֑⁠וֹ וַ⁠יָּ֨סַר֙ אֶת־מַצְּבַ֣ת הַ⁠בַּ֔עַל אֲשֶׁ֥ר עָשָׂ֖ה אָבִֽי⁠ו׃","wa⁠yȧʻàşê֤h há⁠raʻ֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h ra֕q lò֥ʼ kĕ⁠ʼábi֖y⁠w ẇ⁠kĕ⁠ʼiṁ֑⁠wò wa⁠yá̇֨sar֙ ʼeţ-maẕĕ̇ba֣ţ ha⁠bȧ֔ʻal ʼàşě֥r ʻáşá֖̂h ʼábiֽy⁠w׃"],[3,3,"רַ֠ק בְּ⁠חַטֹּ֞אות יָרָבְעָ֧ם בֶּֽן־נְבָ֛ט אֲשֶׁר־הֶחֱטִ֥יא אֶת־יִשְׂרָאֵ֖ל דָּבֵ֑ק לֹא־סָ֖ר מִמֶּֽ⁠נָּה׃ס","ra֠q bĕ̇⁠ẖatò̇֞ʼwţ yárábĕʻá֧m bėֽn-nĕbá֛t ʼàşěr-heẖèti֥yʼ ʼeţ-yişĕ̂ráʼé֖l dá̇bé֑q lòʼ-sá֖r mimėֽ⁠ná̇h׃s"],[3,4,"וּ⁠מֵישַׁ֥ע מֶֽלֶךְ־מוֹאָ֖ב הָיָ֣ה נֹקֵ֑ד וְ⁠הֵשִׁ֤יב לְ⁠מֶֽלֶךְ־יִשְׂרָאֵל֙ מֵאָה־אֶ֣לֶף כָּרִ֔ים וּ⁠מֵ֥אָה אֶ֖לֶף אֵילִ֥ים צָֽמֶר׃","ẇ⁠méyşǎ֥ʻ meֽlekĕ-mwòʼá֖b háyá֣h nòqé֑d wĕ⁠héşǐ֤yb lĕ⁠meֽlekĕ-yişĕ̂ráʼél֙ méʼáh-ʼe֣lep ká̇ri֔ym ẇ⁠mé֥ʼáh ʼe֖lep ʼéyli֥ym ẕáֽmer׃"],[3,5,"וַ⁠יְהִ֖י כְּ⁠מ֣וֹת אַחְאָ֑ב וַ⁠יִּפְשַׁ֥ע מֶֽלֶךְ־מוֹאָ֖ב בְּ⁠מֶ֥לֶךְ יִשְׂרָאֵֽל׃","wa⁠yĕhi֖y kĕ̇⁠m֣wòţ ʼaẖĕʼá֑b wa⁠yi̇pĕşǎ֥ʻ meֽlekĕ-mwòʼá֖b bĕ̇⁠me֥lekĕ yişĕ̂ráʼéֽl׃"],[3,6,"וַ⁠יֵּצֵ֞א הַ⁠מֶּ֧לֶךְ יְהוֹרָ֛ם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא מִ⁠שֹּׁמְר֑וֹן וַ⁠יִּפְקֹ֖ד אֶת־כָּל־יִשְׂרָאֵֽל׃","wa⁠yé̇ẕé֞ʼ ha⁠mė֧lekĕ yĕhwòrá֛m bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ mi⁠şò̇̌mĕr֑wòn wa⁠yi̇pĕqò֖d ʼeţ-ká̇l-yişĕ̂ráʼéֽl׃"],[3,7,"וַ⁠יֵּ֡לֶךְ וַ⁠יִּשְׁלַח֩ אֶל־יְהוֹשָׁפָ֨ט מֶֽלֶךְ־יְהוּדָ֜ה לֵ⁠אמֹ֗ר מֶ֤לֶךְ מוֹאָב֙ פָּשַׁ֣ע בִּ֔⁠י הֲ⁠תֵלֵ֥ךְ אִתִּ֛⁠י אֶל־מוֹאָ֖ב לַ⁠מִּלְחָמָ֑ה וַ⁠יֹּ֣אמֶר אֶעֱלֶ֔ה כָּמ֧וֹ⁠נִי כָמ֛וֹ⁠ךָ כְּ⁠עַמִּ֥⁠י כְ⁠עַמֶּ֖⁠ךָ כְּ⁠סוּסַ֥⁠י כְּ⁠סוּסֶֽי⁠ךָ׃","wa⁠yé̇֡lekĕ wa⁠yi̇şĕ̌laẖ֩ ʼel-yĕhwòşá̌pá֨t meֽlekĕ-yĕhẇdá֜h lé⁠ʼmò֗r me֤lekĕ mwòʼáb֙ pá̇şǎ֣ʻ bi̇֔⁠y hà⁠ţélé֥kĕ ʼiţi֛̇⁠y ʼel-mwòʼá֖b la⁠mi̇lĕẖámá֑h wa⁠yò֣̇ʼmer ʼeʻèle֔h ká̇m֧wò⁠niy kám֛wò⁠ká kĕ̇⁠ʻami֥̇⁠y kĕ⁠ʻamė֖⁠ká kĕ̇⁠sẇsa֥⁠y kĕ̇⁠sẇseֽy⁠ká׃"],[3,8,"וַ⁠יֹּ֕אמֶר אֵי־זֶ֥ה הַ⁠דֶּ֖רֶךְ נַעֲלֶ֑ה וַ⁠יֹּ֕אמֶר דֶּ֖רֶךְ מִדְבַּ֥ר אֱדֽוֹם׃","wa⁠yò̇֕ʼmer ʼéy-ze֥h ha⁠dė֖rekĕ naʻàle֑h wa⁠yò̇֕ʼmer dė֖rekĕ midĕbȧ֥r ʼèdֽwòm׃"],[3,9,"וַ⁠יֵּלֶךְ֩ מֶ֨לֶךְ יִשְׂרָאֵ֤ל וּ⁠מֶֽלֶך־יְהוּדָה֙ וּ⁠מֶ֣לֶךְ אֱד֔וֹם וַ⁠יָּסֹ֕בּוּ דֶּ֖רֶךְ שִׁבְעַ֣ת יָמִ֑ים וְ⁠לֹא־הָיָ֨ה מַ֧יִם לַֽ⁠מַּחֲנֶ֛ה וְ⁠לַ⁠בְּהֵמָ֖ה אֲשֶׁ֥ר בְּ⁠רַגְלֵי⁠הֶֽם׃","wa⁠yé̇lekĕ֩ me֨lekĕ yişĕ̂ráʼé֤l ẇ⁠meֽlek-yĕhẇdáh֙ ẇ⁠me֣lekĕ ʼèd֔wòm wa⁠yá̇sò֕ḃẇ dė֖rekĕ şǐbĕʻa֣ţ yámi֑ym wĕ⁠lòʼ-háyá֨h ma֧yim laֽ⁠mȧẖàne֛h wĕ⁠la⁠bĕ̇hémá֖h ʼàşě֥r bĕ̇⁠ragĕléy⁠heֽm׃"],[3,10,"וַ⁠יֹּ֖אמֶר מֶ֣לֶךְ יִשְׂרָאֵ֑ל אֲהָ֕הּ כִּֽי־קָרָ֣א יְהוָ֗ה לִ⁠שְׁלֹ֨שֶׁת֙ הַ⁠מְּלָכִ֣ים הָ⁠אֵ֔לֶּה לָ⁠תֵ֥ת אוֹתָ֖⁠ם בְּ⁠יַד־מוֹאָֽב׃","wa⁠yò֖̇ʼmer me֣lekĕ yişĕ̂ráʼé֑l ʼàhá֕ḣ kiֽ̇y-qárá֣ʼ yĕhwá֗h li⁠şĕ̌lò֨şěţ֙ ha⁠mĕ̇láki֣ym há⁠ʼé֔lėh lá⁠ţé֥ţ ʼwòţá֖⁠m bĕ̇⁠yad-mwòʼáֽb׃"],[3,11,"וַ⁠יֹּ֣אמֶר יְהוֹשָׁפָ֗ט הַ⁠אֵ֨ין פֹּ֤ה נָבִיא֙ לַֽ⁠יהוָ֔ה וְ⁠נִדְרְשָׁ֥ה אֶת־יְהוָ֖ה מֵ⁠אוֹת֑⁠וֹ וַ֠⁠יַּעַן אֶחָ֞ד מֵ⁠עַבְדֵ֤י מֶֽלֶךְ־יִשְׂרָאֵל֙ וַ⁠יֹּ֔אמֶר פֹּ֚ה אֱלִישָׁ֣ע בֶּן־שָׁפָ֔ט אֲשֶׁר־יָ֥צַק מַ֖יִם עַל־יְדֵ֥י אֵלִיָּֽהוּ׃","wa⁠yò֣̇ʼmer yĕhwòşá̌pá֗t ha⁠ʼé֨yn pò֤̇h nábiyʼ֙ laֽ⁠yhwá֔h wĕ⁠nidĕrĕşá֥̌h ʼeţ-yĕhwá֖h mé⁠ʼwòţ֑⁠wò wa֠⁠yȧʻan ʼeẖá֞d mé⁠ʻabĕdé֤y meֽlekĕ-yişĕ̂ráʼél֙ wa⁠yò̇֔ʼmer pò֚̇h ʼèliyşá֣̌ʻ bėn-şá̌pá֔t ʼàşěr-yá֥ẕaq ma֖yim ʻal-yĕdé֥y ʼéliyáֽ̇hẇ׃"],[3,12,"וַ⁠יֹּ֨אמֶר֙ יְה֣וֹשָׁפָ֔ט יֵ֥שׁ אוֹת֖⁠וֹ דְּבַר־יְהוָ֑ה וַ⁠יֵּרְד֣וּ אֵלָ֗י⁠ו מֶ֧לֶךְ יִשְׂרָאֵ֛ל וִ⁠יהוֹשָׁפָ֖ט וּ⁠מֶ֥לֶךְ אֱדֽוֹם׃","wa⁠yò̇֨ʼmer֙ yĕh֣wòşá̌pá֔t yé֥ş̌ ʼwòţ֖⁠wò dĕ̇bar-yĕhwá֑h wa⁠yé̇rĕd֣ẇ ʼélá֗y⁠w me֧lekĕ yişĕ̂ráʼé֛l wi⁠yhwòşá̌pá֖t ẇ⁠me֥lekĕ ʼèdֽwòm׃"],[3,13,"וַ⁠יֹּ֨אמֶר אֱלִישָׁ֜ע אֶל־מֶ֤לֶךְ יִשְׂרָאֵל֙ מַה־לִּ֣⁠י וָ⁠לָ֔⁠ךְ לֵ֚ךְ אֶל־נְבִיאֵ֣י אָבִ֔י⁠ךָ וְ⁠אֶל־נְבִיאֵ֖י אִמֶּ֑⁠ךָ וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל אַ֗ל כִּֽי־קָרָ֤א יְהוָה֙ לִ⁠שְׁלֹ֨שֶׁת֙ הַ⁠מְּלָכִ֣ים הָ⁠אֵ֔לֶּה לָ⁠תֵ֥ת אוֹתָ֖⁠ם בְּ⁠יַד־מוֹאָֽב׃","wa⁠yò̇֨ʼmer ʼèliyşá̌֜ʻ ʼel-me֤lekĕ yişĕ̂ráʼél֙ mah-li֣̇⁠y wá⁠lá֔⁠kĕ lé֚kĕ ʼel-nĕbiyʼé֣y ʼábi֔y⁠ká wĕ⁠ʼel-nĕbiyʼé֖y ʼimė֑⁠ká wa⁠yò֤̇ʼmer l⁠wò֙ me֣lekĕ yişĕ̂ráʼé֔l ʼa֗l kiֽ̇y-qárá֤ʼ yĕhwáh֙ li⁠şĕ̌lò֨şěţ֙ ha⁠mĕ̇láki֣ym há⁠ʼé֔lėh lá⁠ţé֥ţ ʼwòţá֖⁠m bĕ̇⁠yad-mwòʼáֽb׃"],[3,14,"וַ⁠יֹּ֣אמֶר אֱלִישָׁ֗ע חַי־יְהוָ֤ה צְבָאוֹת֙ אֲשֶׁ֣ר עָמַ֣דְתִּי לְ⁠פָנָ֔י⁠ו כִּ֗י לוּלֵ֛י פְּנֵ֛י יְהוֹשָׁפָ֥ט מֶֽלֶךְ־יְהוּדָ֖ה אֲנִ֣י נֹשֵׂ֑א אִם־אַבִּ֥יט אֵלֶ֖י⁠ךָ וְ⁠אִם־אֶרְאֶֽ⁠ךָּ׃","wa⁠yò֣̇ʼmer ʼèliyşá̌֗ʻ ẖay-yĕhwá֤h ẕĕbáʼwòţ֙ ʼàşě֣r ʻáma֣dĕţi̇y lĕ⁠páná֔y⁠w ki̇֗y lẇlé֛y pĕ̇né֛y yĕhwòşá̌pá֥t meֽlekĕ-yĕhẇdá֖h ʼàni֣y nòşé֑̂ʼ ʼim-ʼabi֥̇yt ʼéle֖y⁠ká wĕ⁠ʼim-ʼerĕʼeֽ⁠ká̇׃"],[3,15,"וְ⁠עַתָּ֖ה קְחוּ־לִ֣⁠י מְנַגֵּ֑ן וְ⁠הָיָה֙ כְּ⁠נַגֵּ֣ן הַֽ⁠מְנַגֵּ֔ן וַ⁠תְּהִ֥י עָלָ֖י⁠ו יַד־יְהוָֽה׃","wĕ⁠ʻaţá֖̇h qĕẖẇ-li֣⁠y mĕnagé֑̇n wĕ⁠háyáh֙ kĕ̇⁠nagé֣̇n haֽ⁠mĕnagé̇֔n wa⁠ţĕ̇hi֥y ʻálá֖y⁠w yad-yĕhwáֽh׃"],[3,16,"וַ⁠יֹּ֕אמֶר כֹּ֖ה אָמַ֣ר יְהוָ֑ה עָשֹׂ֛ה הַ⁠נַּ֥חַל הַ⁠זֶּ֖ה גֵּבִ֥ים ׀ גֵּבִֽים׃","wa⁠yò̇֕ʼmer kò֖̇h ʼáma֣r yĕhwá֑h ʻáşò֛̂h ha⁠nȧ֥ẖal ha⁠zė֖h gé̇bi֥ym ׀ gé̇biֽym׃"],[3,17,"כִּֽי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה לֹֽא־תִרְא֥וּ ר֨וּחַ֙ וְ⁠לֹֽא־תִרְא֣וּ גֶ֔שֶׁם וְ⁠הַ⁠נַּ֥חַל הַ⁠ה֖וּא יִמָּ֣לֵא מָ֑יִם וּ⁠שְׁתִיתֶ֛ם אַתֶּ֥ם וּ⁠מִקְנֵי⁠כֶ֖ם וּֽ⁠בְהֶמְתְּ⁠כֶֽם׃","kiֽ̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h lòֽʼ-ţirĕʼ֥ẇ r֨ẇẖa֙ wĕ⁠lòֽʼ-ţirĕʼ֣ẇ ge֔şěm wĕ⁠ha⁠nȧ֥ẖal ha⁠h֖ẇʼ yimá֣̇léʼ má֑yim ẇ⁠şĕ̌ţiyţe֛m ʼaţė֥m ẇ⁠miqĕnéy⁠ke֖m ẇֽ⁠bĕhemĕţĕ̇⁠keֽm׃"],[3,18,"וְ⁠נָקַ֥ל זֹ֖את בְּ⁠עֵינֵ֣י יְהוָ֑ה וְ⁠נָתַ֥ן אֶת־מוֹאָ֖ב בְּ⁠יֶדְ⁠כֶֽם׃","wĕ⁠náqa֥l zò֖ʼţ bĕ̇⁠ʻéyné֣y yĕhwá֑h wĕ⁠náţa֥n ʼeţ-mwòʼá֖b bĕ̇⁠yedĕ⁠keֽm׃"],[3,19,"וְ⁠הִכִּיתֶ֞ם כָּל־עִ֤יר מִבְצָר֙ וְ⁠כָל־עִ֣יר מִבְח֔וֹר וְ⁠כָל־עֵ֥ץ טוֹב֙ תַּפִּ֔ילוּ וְ⁠כָל־מַעְיְנֵי־מַ֖יִם תִּסְתֹּ֑מוּ וְ⁠כֹל֙ הַ⁠חֶלְקָ֣ה הַ⁠טּוֹבָ֔ה תַּכְאִ֖בוּ בָּ⁠אֲבָנִֽים׃","wĕ⁠hiki̇yţe֞m ká̇l-ʻi֤yr mibĕẕár֙ wĕ⁠kál-ʻi֣yr mibĕẖ֔wòr wĕ⁠kál-ʻé֥ẕ twòb֙ ţȧpi̇֔ylẇ wĕ⁠kál-maʻĕyĕnéy-ma֖yim ţi̇sĕţò֑̇mẇ wĕ⁠kòl֙ ha⁠ẖelĕqá֣h ha⁠ṫwòbá֔h ţȧkĕʼi֖bẇ bá̇⁠ʼàbániֽym׃"],[3,20,"וַ⁠יְהִ֤י בַ⁠בֹּ֨קֶר֙ כַּ⁠עֲל֣וֹת הַ⁠מִּנְחָ֔ה וְ⁠הִנֵּה־מַ֥יִם בָּאִ֖ים מִ⁠דֶּ֣רֶךְ אֱד֑וֹם וַ⁠תִּמָּלֵ֥א הָ⁠אָ֖רֶץ אֶת־הַ⁠מָּֽיִם׃","wa⁠yĕhi֤y ba⁠bò̇֨qer֙ kȧ⁠ʻàl֣wòţ ha⁠mi̇nĕẖá֔h wĕ⁠hiné̇h-ma֥yim bá̇ʼi֖ym mi⁠dė֣rekĕ ʼèd֑wòm wa⁠ţi̇má̇lé֥ʼ há⁠ʼá֖reẕ ʼeţ-ha⁠máֽ̇yim׃"],[3,21,"וְ⁠כָל־מוֹאָב֙ שָֽׁמְע֔וּ כִּֽי־עָל֥וּ הַ⁠מְּלָכִ֖ים לְ⁠הִלָּ֣חֶם בָּ֑⁠ם וַ⁠יִּצָּעֲק֗וּ מִ⁠כֹּ֨ל חֹגֵ֤ר חֲגֹרָה֙ וָ⁠מַ֔עְלָ⁠ה וַ⁠יַּעַמְד֖וּ עַֽל־הַ⁠גְּבֽוּל׃","wĕ⁠kál-mwòʼáb֙ şáֽ̌mĕʻ֔ẇ kiֽ̇y-ʻál֥ẇ ha⁠mĕ̇láki֖ym lĕ⁠hilá֣̇ẖem bá֑̇⁠m wa⁠yi̇ẕá̇ʻàq֗ẇ mi⁠kò̇֨l ẖògé֤r ẖàgòráh֙ wá⁠ma֔ʻĕlá⁠h wa⁠yȧʻamĕd֖ẇ ʻaֽl-ha⁠gĕ̇bֽẇl׃"],[3,22,"וַ⁠יַּשְׁכִּ֣ימוּ בַ⁠בֹּ֔קֶר וְ⁠הַ⁠שֶּׁ֖מֶשׁ זָרְחָ֣ה עַל־הַ⁠מָּ֑יִם וַ⁠יִּרְא֨וּ מוֹאָ֥ב מִ⁠נֶּ֛גֶד אֶת־הַ⁠מַּ֖יִם אֲדֻמִּ֥ים כַּ⁠דָּֽם׃","wa⁠yȧşĕ̌ki֣̇ymẇ ba⁠bò̇֔qer wĕ⁠ha⁠şė֖̌meş̌ zárĕẖá֣h ʻal-ha⁠má֑̇yim wa⁠yi̇rĕʼ֨ẇ mwòʼá֥b mi⁠nė֛ged ʼeţ-ha⁠mȧ֖yim ʼàdumi֥̇ym kȧ⁠dáֽ̇m׃"],[3,23,"וַ⁠יֹּֽאמְרוּ֙ דָּ֣ם זֶ֔ה הָחֳרֵ֤ב נֶֽחֶרְבוּ֙ הַ⁠מְּלָכִ֔ים וַ⁠יַּכּ֖וּ אִ֣ישׁ אֶת־רֵעֵ֑⁠הוּ וְ⁠עַתָּ֥ה לַ⁠שָּׁלָ֖ל מוֹאָֽב׃","wa⁠yòֽ̇ʼmĕrẇ֙ dá֣̇m ze֔h háẖoré֤b neֽẖerĕbẇ֙ ha⁠mĕ̇láki֔ym wa⁠yȧk֖̇ẇ ʼi֣yş̌ ʼeţ-réʻé֑⁠hẇ wĕ⁠ʻaţá֥̇h la⁠şá̇̌lá֖l mwòʼáֽb׃"],[3,24,"וַ⁠יָּבֹאוּ֮ אֶל־מַחֲנֵ֣ה יִשְׂרָאֵל֒ וַ⁠יָּקֻ֤מוּ יִשְׂרָאֵל֙ וַ⁠יַּכּ֣וּ אֶת־מוֹאָ֔ב וַ⁠יָּנֻ֖סוּ מִ⁠פְּנֵי⁠הֶ֑ם ו⁠יבו־בָ֔⁠הּ וְ⁠הַכּ֖וֹת אֶת־מוֹאָֽב׃","wa⁠yá̇bòʼẇ֮ ʼel-maẖàné֣h yişĕ̂ráʼél֒ wa⁠yá̇qu֤mẇ yişĕ̂ráʼél֙ wa⁠yȧk֣̇ẇ ʼeţ-mwòʼá֔b wa⁠yá̇nu֖sẇ mi⁠pĕ̇néy⁠he֑m w⁠ybw-bá֔⁠ḣ wĕ⁠hak֖̇wòţ ʼeţ-mwòʼáֽb׃"],[3,25,"וְ⁠הֶ⁠עָרִ֣ים יַהֲרֹ֡סוּ וְ⁠כָל־חֶלְקָ֣ה ט֠וֹבָה יַשְׁלִ֨יכוּ אִישׁ־אַבְנ֜⁠וֹ וּ⁠מִלְא֗וּ⁠הָ וְ⁠כָל־מַעְיַן־מַ֤יִם יִסְתֹּ֨מוּ֙ וְ⁠כָל־עֵֽץ־ט֣וֹב יַפִּ֔ילוּ עַד־הִשְׁאִ֧יר אֲבָנֶ֛י⁠הָ בַּ⁠קִּ֖יר חֲרָ֑שֶׂת וַ⁠יָּסֹ֥בּוּ הַ⁠קַּלָּעִ֖ים וַ⁠יַּכּֽוּ⁠הָ׃","wĕ⁠he⁠ʻári֣ym yahàrò֡sẇ wĕ⁠kál-ẖelĕqá֣h t֠wòbáh yaşĕ̌li֨ykẇ ʼiyş̌-ʼabĕn֜⁠wò ẇ⁠milĕʼ֗ẇ⁠há wĕ⁠kál-maʻĕyan-ma֤yim yisĕţò̇֨mẇ֙ wĕ⁠kál-ʻéֽẕ-t֣wòb yapi̇֔ylẇ ʻad-hişĕ̌ʼi֧yr ʼàbáne֛y⁠há bȧ⁠qi֖̇yr ẖàrá֑şêţ wa⁠yá̇sò֥ḃẇ ha⁠qȧlá̇ʻi֖ym wa⁠yȧkֽ̇ẇ⁠há׃"],[3,26,"וַ⁠יַּרְא֙ מֶ֣לֶךְ מוֹאָ֔ב כִּֽי־חָזַ֥ק מִמֶּ֖⁠נּוּ הַ⁠מִּלְחָמָ֑ה וַ⁠יִּקַּ֣ח א֠וֹת⁠וֹ שְׁבַע־מֵא֨וֹת אִ֜ישׁ שֹׁ֣לֵֽף חֶ֗רֶב לְ⁠הַבְקִ֛יעַ אֶל־מֶ֥לֶךְ אֱד֖וֹם וְ⁠לֹ֥א יָכֹֽלוּ׃","wa⁠yȧrĕʼ֙ me֣lekĕ mwòʼá֔b kiֽ̇y-ẖáza֥q mimė֖⁠ṅẇ ha⁠mi̇lĕẖámá֑h wa⁠yi̇qȧ֣ẖ ʼ֠wòţ⁠wò şĕ̌baʻ-méʼ֨wòţ ʼi֜yş̌ şò֣̌léֽp ẖe֗reb lĕ⁠habĕqi֛yʻa ʼel-me֥lekĕ ʼèd֖wòm wĕ⁠lò֥ʼ yákòֽlẇ׃"],[3,27,"וַ⁠יִּקַּח֩ אֶת־בְּנ֨⁠וֹ הַ⁠בְּכ֜וֹר אֲשֶׁר־יִמְלֹ֣ךְ תַּחְתָּ֗י⁠ו וַ⁠יַּעֲלֵ֤⁠הוּ עֹלָה֙ עַל־הַ֣⁠חֹמָ֔ה וַ⁠יְהִ֥י קֶצֶף־גָּד֖וֹל עַל־יִשְׂרָאֵ֑ל וַ⁠יִּסְעוּ֙ מֵֽ⁠עָלָ֔י⁠ו וַ⁠יָּשֻׁ֖בוּ לָ⁠אָֽרֶץ׃פ","wa⁠yi̇qȧẖ֩ ʼeţ-bĕ̇n֨⁠wò ha⁠bĕ̇k֜wòr ʼàşěr-yimĕlò֣kĕ ţȧẖĕţá̇֗y⁠w wa⁠yȧʻàlé֤⁠hẇ ʻòláh֙ ʻal-ha֣⁠ẖòmá֔h wa⁠yĕhi֥y qeẕep-gá̇d֖wòl ʻal-yişĕ̂ráʼé֑l wa⁠yi̇sĕʻẇ֙ méֽ⁠ʻálá֔y⁠w wa⁠yá̇şǔ֖bẇ lá⁠ʼáֽreẕ׃p"],[4,1,"וְ⁠אִשָּׁ֣ה אַחַ֣ת מִ⁠נְּשֵׁ֣י בְנֵֽי־הַ֠⁠נְּבִיאִים צָעֲקָ֨ה אֶל־אֱלִישָׁ֜ע לֵ⁠אמֹ֗ר עַבְדְּ⁠ךָ֤ אִישִׁ⁠י֙ מֵ֔ת וְ⁠אַתָּ֣ה יָדַ֔עְתָּ כִּ֣י עַבְדְּ⁠ךָ֔ הָיָ֥ה יָרֵ֖א אֶת־יְהוָ֑ה וְ⁠הַ֨⁠נֹּשֶׁ֔ה בָּ֗א לָ⁠קַ֜חַת אֶת־שְׁנֵ֧י יְלָדַ֛⁠י ל֖⁠וֹ לַ⁠עֲבָדִֽים׃","wĕ⁠ʼişá֣̇̌h ʼaẖa֣ţ mi⁠nĕ̇şé֣̌y bĕnéֽy-ha֠⁠nĕ̇biyʼiym ẕáʻàqá֨h ʼel-ʼèliyşá̌֜ʻ lé⁠ʼmò֗r ʻabĕdĕ̇⁠ká֤ ʼiyşǐ⁠y֙ mé֔ţ wĕ⁠ʼaţá֣̇h yáda֔ʻĕţá̇ ki֣̇y ʻabĕdĕ̇⁠ká֔ háyá֥h yáré֖ʼ ʼeţ-yĕhwá֑h wĕ⁠ha֨⁠nò̇şě֔h bá̇֗ʼ lá⁠qa֜ẖaţ ʼeţ-şĕ̌né֧y yĕláda֛⁠y l֖⁠wò la⁠ʻàbádiֽym׃"],[4,2,"וַ⁠יֹּ֨אמֶר אֵלֶ֤י⁠הָ אֱלִישָׁע֙ מָ֣ה אֶֽעֱשֶׂה־לָּ֔⁠ךְ הַגִּ֣ידִי לִ֔⁠י מַה־יֶּשׁ־ל⁠כי בַּ⁠בָּ֑יִת וַ⁠תֹּ֗אמֶר אֵ֣ין לְ⁠שִׁפְחָתְ⁠ךָ֥ כֹל֙ בַּ⁠בַּ֔יִת כִּ֖י אִם־אָס֥וּךְ שָֽׁמֶן׃","wa⁠yò̇֨ʼmer ʼéle֤y⁠há ʼèliyşá̌ʻ֙ má֣h ʼֽeʻèşêh-lá̇֔⁠kĕ hagi֣̇ydiy li֔⁠y mah-yėş̌-l⁠ky bȧ⁠bá֑̇yiţ wa⁠ţò̇֗ʼmer ʼé֣yn lĕ⁠şǐpĕẖáţĕ⁠ká֥ kòl֙ bȧ⁠bȧ֔yiţ ki֖̇y ʼim-ʼás֥ẇkĕ şáֽ̌men׃"],[4,3,"וַ⁠יֹּ֗אמֶר לְכִ֨י שַׁאֲלִי־לָ֤⁠ךְ כֵּלִים֙ מִן־הַ⁠ח֔וּץ מֵ⁠אֵ֖ת כָּל־שכנ⁠כי כֵּלִ֥ים רֵקִ֖ים אַל־תַּמְעִֽיטִי׃","wa⁠yò̇֗ʼmer lĕki֨y şǎʼàliy-lá֤⁠kĕ ké̇liym֙ min-ha⁠ẖ֔ẇẕ mé⁠ʼé֖ţ ká̇l-şkn⁠ky ké̇li֥ym réqi֖ym ʼal-ţȧmĕʻiֽytiy׃"],[4,4,"וּ⁠בָ֗את וְ⁠סָגַ֤רְתְּ הַ⁠דֶּ֨לֶת֙ בַּעֲדֵ֣⁠ךְ וּ⁠בְעַד־בָּנַ֔יִ⁠ךְ וְ⁠יָצַ֕קְתְּ עַ֥ל כָּל־הַ⁠כֵּלִ֖ים הָ⁠אֵ֑לֶּה וְ⁠הַ⁠מָּלֵ֖א תַּסִּֽיעִי׃","ẇ⁠bá֗ʼţ wĕ⁠sága֤rĕţĕ̇ ha⁠dė֨leţ֙ bȧʻàdé֣⁠kĕ ẇ⁠bĕʻad-bá̇na֔yi⁠kĕ wĕ⁠yáẕa֕qĕţĕ̇ ʻa֥l ká̇l-ha⁠ké̇li֖ym há⁠ʼé֑lėh wĕ⁠ha⁠má̇lé֖ʼ ţȧsiֽ̇yʻiy׃"],[4,5,"וַ⁠תֵּ֨לֶךְ֙ מֵֽ⁠אִתּ֔⁠וֹ וַ⁠תִּסְגֹּ֣ר הַ⁠דֶּ֔לֶת בַּעֲדָ֖⁠הּ וּ⁠בְעַ֣ד בָּנֶ֑י⁠הָ הֵ֛ם מַגִּשִׁ֥ים אֵלֶ֖י⁠הָ וְ⁠הִ֥יא מיצקת׃","wa⁠ţé̇֨lekĕ֙ méֽ⁠ʼiţ̇֔⁠wò wa⁠ţi̇sĕgò֣̇r ha⁠dė֔leţ bȧʻàdá֖⁠ḣ ẇ⁠bĕʻa֣d bá̇ne֑y⁠há hé֛m magi̇şǐ֥ym ʼéle֖y⁠há wĕ⁠hi֥yʼ myẕqţ׃"],[4,6,"וַ⁠יְהִ֣י ׀ כִּ⁠מְלֹ֣את הַ⁠כֵּלִ֗ים וַ⁠תֹּ֤אמֶר אֶל־בְּנָ⁠הּ֙ הַגִּ֨ישָׁ⁠ה אֵלַ֥⁠י עוֹד֙ כֶּ֔לִי וַ⁠יֹּ֣אמֶר אֵלֶ֔י⁠הָ אֵ֥ין ע֖וֹד כֶּ֑לִי וַֽ⁠יַּעֲמֹ֖ד הַ⁠שָּֽׁמֶן׃","wa⁠yĕhi֣y ׀ ki̇⁠mĕlò֣ʼţ ha⁠ké̇li֗ym wa⁠ţò֤̇ʼmer ʼel-bĕ̇ná⁠ḣ֙ hagi̇֨yşá̌⁠h ʼéla֥⁠y ʻwòd֙ kė֔liy wa⁠yò֣̇ʼmer ʼéle֔y⁠há ʼé֥yn ʻ֖wòd kė֑liy waֽ⁠yȧʻàmò֖d ha⁠şáֽ̇̌men׃"],[4,7,"וַ⁠תָּבֹ֗א וַ⁠תַּגֵּד֙ לְ⁠אִ֣ישׁ הָ⁠אֱלֹהִ֔ים וַ⁠יֹּ֗אמֶר לְכִי֙ מִכְרִ֣י אֶת־הַ⁠שֶּׁ֔מֶן וְ⁠שַׁלְּמִ֖י אֶת־נשי⁠כי וְ⁠אַ֣תְּ בני⁠כי תִֽחְיִ֖י בַּ⁠נּוֹתָֽר׃פ","wa⁠ţá̇bò֗ʼ wa⁠ţȧgé̇d֙ lĕ⁠ʼi֣yş̌ há⁠ʼèlòhi֔ym wa⁠yò̇֗ʼmer lĕkiy֙ mikĕri֣y ʼeţ-ha⁠şė̌֔men wĕ⁠şǎlĕ̇mi֖y ʼeţ-nşy⁠ky wĕ⁠ʼa֣ţĕ̇ bny⁠ky ţiֽẖĕyi֖y bȧ⁠ṅwòţáֽr׃p"],[4,8,"וַ⁠יְהִ֨י הַ⁠יּ֜וֹם וַ⁠יַּעֲבֹ֧ר אֱלִישָׁ֣ע אֶל־שׁוּנֵ֗ם וְ⁠שָׁם֙ אִשָּׁ֣ה גְדוֹלָ֔ה וַ⁠תַּחֲזֶק־בּ֖⁠וֹ לֶ⁠אֱכָל־לָ֑חֶם וַֽ⁠יְהִי֙ מִ⁠דֵּ֣י עָבְר֔⁠וֹ יָסֻ֥ר שָׁ֖מָּ⁠ה לֶ⁠אֱכָל־לָֽחֶם׃","wa⁠yĕhi֨y ha⁠ẏ֜wòm wa⁠yȧʻàbò֧r ʼèliyşá֣̌ʻ ʼel-ş̌ẇné֗m wĕ⁠şá̌m֙ ʼişá֣̇̌h gĕdwòlá֔h wa⁠ţȧẖàzeq-ḃ֖⁠wò le⁠ʼèkál-lá֑ẖem waֽ⁠yĕhiy֙ mi⁠dé֣̇y ʻábĕr֔⁠wò yásu֥r şá֖̌má̇⁠h le⁠ʼèkál-láֽẖem׃"],[4,9,"וַ⁠תֹּ֨אמֶר֙ אֶל־אִישָׁ֔⁠הּ הִנֵּה־נָ֣א יָדַ֔עְתִּי כִּ֛י אִ֥ישׁ אֱלֹהִ֖ים קָד֣וֹשׁ ה֑וּא עֹבֵ֥ר עָלֵ֖י⁠נוּ תָּמִֽיד׃","wa⁠ţò̇֨ʼmer֙ ʼel-ʼiyşá̌֔⁠ḣ hiné̇h-ná֣ʼ yáda֔ʻĕţi̇y ki֛̇y ʼi֥yş̌ ʼèlòhi֖ym qád֣wòş̌ h֑ẇʼ ʻòbé֥r ʻálé֖y⁠nẇ ţá̇miֽyd׃"],[4,10,"נַֽעֲשֶׂה־נָּ֤א עֲלִיַּת־קִיר֙ קְטַנָּ֔ה וְ⁠נָשִׂ֨ים ל֥⁠וֹ שָׁ֛ם מִטָּ֥ה וְ⁠שֻׁלְחָ֖ן וְ⁠כִסֵּ֣א וּ⁠מְנוֹרָ֑ה וְ⁠הָיָ֛ה בְּ⁠בֹא֥⁠וֹ אֵלֵ֖י⁠נוּ יָס֥וּר שָֽׁמָּ⁠ה׃","naֽʻàşêh-ná֤̇ʼ ʻàliyȧţ-qiyr֙ qĕtaná̇֔h wĕ⁠náşî֨ym l֥⁠wò şá֛̌m mitá֥̇h wĕ⁠şǔlĕẖá֖n wĕ⁠kisé֣̇ʼ ẇ⁠mĕnwòrá֑h wĕ⁠háyá֛h bĕ̇⁠bòʼ֥⁠wò ʼélé֖y⁠nẇ yás֥ẇr şáֽ̌má̇⁠h׃"],[4,11,"וַ⁠יְהִ֥י הַ⁠יּ֖וֹם וַ⁠יָּ֣בֹא שָׁ֑מָּ⁠ה וַ⁠יָּ֥סַר אֶל־הָ⁠עֲלִיָּ֖ה וַ⁠יִּשְׁכַּב־שָֽׁמָּ⁠ה׃","wa⁠yĕhi֥y ha⁠ẏ֖wòm wa⁠yá֣̇bòʼ şá֑̌má̇⁠h wa⁠yá֥̇sar ʼel-há⁠ʻàliyá֖̇h wa⁠yi̇şĕ̌kȧb-şáֽ̌má̇⁠h׃"],[4,12,"וַ⁠יֹּ֨אמֶר֙ אֶל־גֵּחֲזִ֣י נַעֲר֔⁠וֹ קְרָ֖א לַ⁠שּׁוּנַמִּ֣ית הַ⁠זֹּ֑את וַ⁠יִּקְרָא־לָ֔⁠הּ וַֽ⁠תַּעֲמֹ֖ד לְ⁠פָנָֽי⁠ו׃","wa⁠yò̇֨ʼmer֙ ʼel-gé̇ẖàzi֣y naʻàr֔⁠wò qĕrá֖ʼ la⁠ş̇̌ẇnami֣̇yţ ha⁠zò֑̇ʼţ wa⁠yi̇qĕráʼ-lá֔⁠ḣ waֽ⁠ţȧʻàmò֖d lĕ⁠pánáֽy⁠w׃"],[4,13,"וַ⁠יֹּ֣אמֶר ל֗⁠וֹ אֱמָר־נָ֣א אֵלֶי⁠הָ֮ הִנֵּ֣ה חָרַ֣דְתְּ ׀ אֵלֵי⁠נוּ֮ אֶת־כָּל־הַ⁠חֲרָדָ֣ה הַ⁠זֹּאת֒ מֶ֚ה לַ⁠עֲשׂ֣וֹת לָ֔⁠ךְ הֲ⁠יֵ֤שׁ לְ⁠דַבֶּר־לָ⁠ךְ֙ אֶל־הַ⁠מֶּ֔לֶךְ א֖וֹ אֶל־שַׂ֣ר הַ⁠צָּבָ֑א וַ⁠תֹּ֕אמֶר בְּ⁠ת֥וֹךְ עַמִּ֖⁠י אָנֹכִ֥י יֹשָֽׁבֶת׃","wa⁠yò֣̇ʼmer l֗⁠wò ʼèmár-ná֣ʼ ʼéley⁠há֮ hiné֣̇h ẖára֣dĕţĕ̇ ׀ ʼéléy⁠nẇ֮ ʼeţ-ká̇l-ha⁠ẖàrádá֣h ha⁠zò̇ʼţ֒ me֚h la⁠ʻàş֣̂wòţ lá֔⁠kĕ hà⁠yé֤ş̌ lĕ⁠dabėr-lá⁠kĕ֙ ʼel-ha⁠mė֔lekĕ ʼ֖wò ʼel-şâ֣r ha⁠ẕá̇bá֑ʼ wa⁠ţò̇֕ʼmer bĕ̇⁠ţ֥wòkĕ ʻami֖̇⁠y ʼánòki֥y yòşáֽ̌beţ׃"],[4,14,"וַ⁠יֹּ֕אמֶר וּ⁠מֶ֖ה לַ⁠עֲשׂ֣וֹת לָ֑⁠הּ וַ⁠יֹּ֣אמֶר גֵּיחֲזִ֗י אֲבָ֛ל בֵּ֥ן אֵֽין־לָ֖⁠הּ וְ⁠אִישָׁ֥⁠הּ זָקֵֽן׃","wa⁠yò̇֕ʼmer ẇ⁠me֖h la⁠ʻàş֣̂wòţ lá֑⁠ḣ wa⁠yò֣̇ʼmer gé̇yẖàzi֗y ʼàbá֛l bé֥̇n ʼéֽyn-lá֖⁠ḣ wĕ⁠ʼiyşá֥̌⁠ḣ záqéֽn׃"],[4,15,"וַ⁠יֹּ֖אמֶר קְרָא־לָ֑⁠הּ וַ⁠יִּקְרָא־לָ֔⁠הּ וַֽ⁠תַּעֲמֹ֖ד בַּ⁠פָּֽתַח׃","wa⁠yò֖̇ʼmer qĕráʼ-lá֑⁠ḣ wa⁠yi̇qĕráʼ-lá֔⁠ḣ waֽ⁠ţȧʻàmò֖d bȧ⁠páֽ̇ţaẖ׃"],[4,16,"וַ⁠יֹּ֗אמֶר לַ⁠מּוֹעֵ֤ד הַ⁠זֶּה֙ כָּ⁠עֵ֣ת חַיָּ֔ה אתי חֹבֶ֣קֶת בֵּ֑ן וַ⁠תֹּ֗אמֶר אַל־אֲדֹנִ⁠י֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים אַל־תְּכַזֵּ֖ב בְּ⁠שִׁפְחָתֶֽ⁠ךָ׃","wa⁠yò̇֗ʼmer la⁠ṁwòʻé֤d ha⁠zėh֙ ká̇⁠ʻé֣ţ ẖayá̇֔h ʼţy ẖòbe֣qeţ bé֑̇n wa⁠ţò̇֗ʼmer ʼal-ʼàdòni⁠y֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym ʼal-ţĕ̇kazé֖̇b bĕ̇⁠şǐpĕẖáţeֽ⁠ká׃"],[4,17,"וַ⁠תַּ֥הַר הָ⁠אִשָּׁ֖ה וַ⁠תֵּ֣לֶד בֵּ֑ן לַ⁠מּוֹעֵ֤ד הַ⁠זֶּה֙ כָּ⁠עֵ֣ת חַיָּ֔ה אֲשֶׁר־דִּבֶּ֥ר אֵלֶ֖י⁠הָ אֱלִישָֽׁע׃","wa⁠ţȧ֥har há⁠ʼişá֖̇̌h wa⁠ţé֣̇led bé֑̇n la⁠ṁwòʻé֤d ha⁠zėh֙ ká̇⁠ʻé֣ţ ẖayá̇֔h ʼàşěr-di̇bė֥r ʼéle֖y⁠há ʼèliyşáֽ̌ʻ׃"],[4,18,"וַ⁠יִּגְדַּ֖ל הַ⁠יָּ֑לֶד וַ⁠יְהִ֣י הַ⁠יּ֔וֹם וַ⁠יֵּצֵ֥א אֶל־אָבִ֖י⁠ו אֶל־הַ⁠קֹּצְרִֽים׃","wa⁠yi̇gĕdȧ֖l ha⁠yá֑̇led wa⁠yĕhi֣y ha⁠ẏ֔wòm wa⁠yé̇ẕé֥ʼ ʼel-ʼábi֖y⁠w ʼel-ha⁠qò̇ẕĕriֽym׃"],[4,19,"וַ⁠יֹּ֥אמֶר אֶל־אָבִ֖י⁠ו רֹאשִׁ֣⁠י ׀ רֹאשִׁ֑⁠י וַ⁠יֹּ֨אמֶר֙ אֶל־הַ⁠נַּ֔עַר שָׂאֵ֖⁠הוּ אֶל־אִמּֽ⁠וֹ׃","wa⁠yò֥̇ʼmer ʼel-ʼábi֖y⁠w ròʼşǐ֣⁠y ׀ ròʼşǐ֑⁠y wa⁠yò̇֨ʼmer֙ ʼel-ha⁠nȧ֔ʻar şá̂ʼé֖⁠hẇ ʼel-ʼiṁֽ⁠wò׃"],[4,20,"וַ⁠יִּשָּׂאֵ֔⁠הוּ וַ⁠יְבִיאֵ֖⁠הוּ אֶל־אִמּ֑⁠וֹ וַ⁠יֵּ֧שֶׁב עַל־בִּרְכֶּ֛י⁠הָ עַד־הַֽ⁠צָּהֳרַ֖יִם וַ⁠יָּמֹֽת׃","wa⁠yi̇şá̇̂ʼé֔⁠hẇ wa⁠yĕbiyʼé֖⁠hẇ ʼel-ʼiṁ֑⁠wò wa⁠yé֧̇şěb ʻal-bi̇rĕkė֛y⁠há ʻad-haֽ⁠ẕá̇hora֖yim wa⁠yá̇mòֽţ׃"],[4,21,"וַ⁠תַּ֨עַל֙ וַ⁠תַּשְׁכִּבֵ֔⁠הוּ עַל־מִטַּ֖ת אִ֣ישׁ הָ⁠אֱלֹהִ֑ים וַ⁠תִּסְגֹּ֥ר בַּעֲד֖⁠וֹ וַ⁠תֵּצֵֽא׃","wa⁠ţȧ֨ʻal֙ wa⁠ţȧşĕ̌ki̇bé֔⁠hẇ ʻal-mitȧ֖ţ ʼi֣yş̌ há⁠ʼèlòhi֑ym wa⁠ţi̇sĕgò֥̇r bȧʻàd֖⁠wò wa⁠ţé̇ẕéֽʼ׃"],[4,22,"וַ⁠תִּקְרָא֮ אֶל־אִישָׁ⁠הּ֒ וַ⁠תֹּ֗אמֶר שִׁלְחָ֨⁠ה נָ֥א לִ⁠י֙ אֶחָ֣ד מִן־הַ⁠נְּעָרִ֔ים וְ⁠אַחַ֖ת הָ⁠אֲתֹנ֑וֹת וְ⁠אָר֛וּצָה עַד־אִ֥ישׁ הָ⁠אֱלֹהִ֖ים וְ⁠אָשֽׁוּבָה׃","wa⁠ţi̇qĕráʼ֮ ʼel-ʼiyşá̌⁠ḣ֒ wa⁠ţò̇֗ʼmer şǐlĕẖá֨⁠h ná֥ʼ li⁠y֙ ʼeẖá֣d min-ha⁠nĕ̇ʻári֔ym wĕ⁠ʼaẖa֖ţ há⁠ʼàţòn֑wòţ wĕ⁠ʼár֛ẇẕáh ʻad-ʼi֥yş̌ há⁠ʼèlòhi֖ym wĕ⁠ʼáşֽ̌ẇbáh׃"],[4,23,"וַ⁠יֹּ֗אמֶר מַ֠דּוּעַ אתי הלכתי אֵלָי⁠ו֙ הַ⁠יּ֔וֹם לֹֽא־חֹ֖דֶשׁ וְ⁠לֹ֣א שַׁבָּ֑ת וַ⁠תֹּ֖אמֶר שָׁלֽוֹם׃","wa⁠yò̇֗ʼmer ma֠ḋẇʻa ʼţy hlkţy ʼéláy⁠w֙ ha⁠ẏ֔wòm lòֽʼ-ẖò֖deş̌ wĕ⁠lò֣ʼ şǎbá֑̇ţ wa⁠ţò֖̇ʼmer şá̌lֽwòm׃"],[4,24,"וַֽ⁠תַּחֲבֹשׁ֙ הָֽ⁠אָת֔וֹן וַ⁠תֹּ֥אמֶר אֶֽל־נַעֲרָ֖⁠הּ נְהַ֣ג וָ⁠לֵ֑ךְ אַל־תַּעֲצָר־לִ֣⁠י לִ⁠רְכֹּ֔ב כִּ֖י אִם־אָמַ֥רְתִּי לָֽ⁠ךְ׃","waֽ⁠ţȧẖàbòş̌֙ háֽ⁠ʼáţ֔wòn wa⁠ţò֥̇ʼmer ʼeֽl-naʻàrá֖⁠ḣ nĕha֣g wá⁠lé֑kĕ ʼal-ţȧʻàẕár-li֣⁠y li⁠rĕkò̇֔b ki֖̇y ʼim-ʼáma֥rĕţi̇y láֽ⁠kĕ׃"],[4,25,"וַ⁠תֵּ֗לֶךְ וַ⁠תָּב֛וֹא אֶל־אִ֥ישׁ הָ⁠אֱלֹהִ֖ים אֶל־הַ֣ר הַ⁠כַּרְמֶ֑ל וַ֠⁠יְהִי כִּ⁠רְא֨וֹת אִישׁ־הָ⁠אֱלֹהִ֤ים אֹתָ⁠הּ֙ מִ⁠נֶּ֔גֶד וַ⁠יֹּ֨אמֶר֙ אֶל־גֵּיחֲזִ֣י נַעֲר֔⁠וֹ הִנֵּ֖ה הַ⁠שּׁוּנַמִּ֥ית הַלָּֽז׃","wa⁠ţé̇֗lekĕ wa⁠ţá̇b֛wòʼ ʼel-ʼi֥yş̌ há⁠ʼèlòhi֖ym ʼel-ha֣r ha⁠kȧrĕme֑l wa֠⁠yĕhiy ki̇⁠rĕʼ֨wòţ ʼiyş̌-há⁠ʼèlòhi֤ym ʼòţá⁠ḣ֙ mi⁠nė֔ged wa⁠yò̇֨ʼmer֙ ʼel-gé̇yẖàzi֣y naʻàr֔⁠wò hiné֖̇h ha⁠ş̇̌ẇnami֥̇yţ haláֽ̇z׃"],[4,26,"עַתָּה֮ רֽוּץ־נָ֣א לִ⁠קְרָאתָ⁠הּ֒ וֶ⁠אֱמָר־לָ֗⁠הּ הֲ⁠שָׁל֥וֹם לָ֛⁠ךְ הֲ⁠שָׁל֥וֹם לְ⁠אִישֵׁ֖⁠ךְ הֲ⁠שָׁל֣וֹם לַ⁠יָּ֑לֶד וַ⁠תֹּ֖אמֶר שָׁלֽוֹם׃","ʻaţá̇h֮ rֽẇẕ-ná֣ʼ li⁠qĕráʼţá⁠ḣ֒ we⁠ʼèmár-lá֗⁠ḣ hà⁠şá̌l֥wòm lá֛⁠kĕ hà⁠şá̌l֥wòm lĕ⁠ʼiyşé֖̌⁠kĕ hà⁠şá̌l֣wòm la⁠yá֑̇led wa⁠ţò֖̇ʼmer şá̌lֽwòm׃"],[4,27,"וַ⁠תָּבֹ֞א אֶל־אִ֤ישׁ הָֽ⁠אֱלֹהִים֙ אֶל־הָ⁠הָ֔ר וַֽ⁠תַּחֲזֵ֖ק בְּ⁠רַגְלָ֑י⁠ו וַ⁠יִּגַּ֨שׁ גֵּֽיחֲזִ֜י לְ⁠הָדְפָ֗⁠הּ וַ⁠יֹּאמֶר֩ אִ֨ישׁ הָ⁠אֱלֹהִ֤ים הַרְפֵּֽה־לָ⁠הּ֙ כִּֽי־נַפְשָׁ֣⁠הּ מָֽרָה־לָ֔⁠הּ וַֽ⁠יהוָה֙ הֶעְלִ֣ים מִמֶּ֔⁠נִּי וְ⁠לֹ֥א הִגִּ֖יד לִֽ⁠י׃","wa⁠ţá̇bò֞ʼ ʼel-ʼi֤yş̌ háֽ⁠ʼèlòhiym֙ ʼel-há⁠há֔r waֽ⁠ţȧẖàzé֖q bĕ̇⁠ragĕlá֑y⁠w wa⁠yi̇gȧ֨ş̌ géֽ̇yẖàzi֜y lĕ⁠hádĕpá֗⁠ḣ wa⁠yò̇ʼmer֩ ʼi֨yş̌ há⁠ʼèlòhi֤ym harĕpéֽ̇h-lá⁠ḣ֙ kiֽ̇y-napĕşá֣̌⁠ḣ máֽráh-lá֔⁠ḣ waֽ⁠yhwáh֙ heʻĕli֣ym mimė֔⁠ni̇y wĕ⁠lò֥ʼ higi֖̇yd liֽ⁠y׃"],[4,28,"וַ⁠תֹּ֕אמֶר הֲ⁠שָׁאַ֥לְתִּי בֵ֖ן מֵ⁠אֵ֣ת אֲדֹנִ֑⁠י הֲ⁠לֹ֣א אָמַ֔רְתִּי לֹ֥א תַשְׁלֶ֖ה אֹתִֽ⁠י׃","wa⁠ţò̇֕ʼmer hà⁠şá̌ʼa֥lĕţi̇y bé֖n mé⁠ʼé֣ţ ʼàdòni֑⁠y hà⁠lò֣ʼ ʼáma֔rĕţi̇y lò֥ʼ ţaşĕ̌le֖h ʼòţiֽ⁠y׃"],[4,29,"וַ⁠יֹּ֨אמֶר לְ⁠גֵיחֲזִ֜י חֲגֹ֣ר מָתְנֶ֗י⁠ךָ וְ⁠קַ֨ח מִשְׁעַנְתִּ֣⁠י בְ⁠יָדְ⁠ךָ֮ וָ⁠לֵךְ֒ כִּֽי־תִמְצָ֥א אִישׁ֙ לֹ֣א תְבָרְכֶ֔⁠נּוּ וְ⁠כִֽי־יְבָרֶכְ⁠ךָ֥ אִ֖ישׁ לֹ֣א תַעֲנֶ⁠נּ֑וּ וְ⁠שַׂמְתָּ֥ מִשְׁעַנְתִּ֖⁠י עַל־פְּנֵ֥י הַ⁠נָּֽעַר׃","wa⁠yò̇֨ʼmer lĕ⁠géyẖàzi֜y ẖàgò֣r máţĕne֗y⁠ká wĕ⁠qa֨ẖ mişĕ̌ʻanĕţi֣̇⁠y bĕ⁠yádĕ⁠ká֮ wá⁠lékĕ֒ kiֽ̇y-ţimĕẕá֥ʼ ʼiyş̌֙ lò֣ʼ ţĕbárĕke֔⁠ṅẇ wĕ⁠kiֽy-yĕbárekĕ⁠ká֥ ʼi֖yş̌ lò֣ʼ ţaʻàne⁠ṅ֑ẇ wĕ⁠şâmĕţá֥̇ mişĕ̌ʻanĕţi֖̇⁠y ʻal-pĕ̇né֥y ha⁠náֽ̇ʻar׃"],[4,30,"וַ⁠תֹּ֨אמֶר֙ אֵ֣ם הַ⁠נַּ֔עַר חַי־יְהוָ֥ה וְ⁠חֵֽי־נַפְשְׁ⁠ךָ֖ אִם־אֶעֶזְבֶ֑⁠ךָּ וַ⁠יָּ֖קָם וַ⁠יֵּ֥לֶךְ אַחֲרֶֽי⁠הָ׃","wa⁠ţò̇֨ʼmer֙ ʼé֣m ha⁠nȧ֔ʻar ẖay-yĕhwá֥h wĕ⁠ẖéֽy-napĕşĕ̌⁠ká֖ ʼim-ʼeʻezĕbe֑⁠ká̇ wa⁠yá֖̇qám wa⁠yé֥̇lekĕ ʼaẖàreֽy⁠há׃"],[4,31,"וְ⁠גֵחֲזִ֞י עָבַ֣ר לִ⁠פְנֵי⁠הֶ֗ם וַ⁠יָּ֤שֶׂם אֶת־הַ⁠מִּשְׁעֶ֨נֶת֙ עַל־פְּנֵ֣י הַ⁠נַּ֔עַר וְ⁠אֵ֥ין ק֖וֹל וְ⁠אֵ֣ין קָ֑שֶׁב וַ⁠יָּ֤שָׁב לִ⁠קְרָאת⁠וֹ֙ וַ⁠יַּגֶּד־ל֣⁠וֹ לֵ⁠אמֹ֔ר לֹ֥א הֵקִ֖יץ הַ⁠נָּֽעַר׃","wĕ⁠géẖàzi֞y ʻába֣r li⁠pĕnéy⁠he֗m wa⁠yá֤̇şêm ʼeţ-ha⁠mi̇şĕ̌ʻe֨neţ֙ ʻal-pĕ̇né֣y ha⁠nȧ֔ʻar wĕ⁠ʼé֥yn q֖wòl wĕ⁠ʼé֣yn qá֑şěb wa⁠yá֤̇şá̌b li⁠qĕráʼţ⁠wò֙ wa⁠yȧgėd-l֣⁠wò lé⁠ʼmò֔r lò֥ʼ héqi֖yẕ ha⁠náֽ̇ʻar׃"],[4,32,"וַ⁠יָּבֹ֥א אֱלִישָׁ֖ע הַ⁠בָּ֑יְתָ⁠ה וְ⁠הִנֵּ֤ה הַ⁠נַּ֨עַר֙ מֵ֔ת מֻשְׁכָּ֖ב עַל־מִטָּתֽ⁠וֹ׃","wa⁠yá̇bò֥ʼ ʼèliyşá֖̌ʻ ha⁠bá֑̇yĕţá⁠h wĕ⁠hiné֤̇h ha⁠nȧ֨ʻar֙ mé֔ţ muşĕ̌ká֖̇b ʻal-mitá̇ţֽ⁠wò׃"],[4,33,"וַ⁠יָּבֹ֕א וַ⁠יִּסְגֹּ֥ר הַ⁠דֶּ֖לֶת בְּעַ֣ד שְׁנֵי⁠הֶ֑ם וַ⁠יִּתְפַּלֵּ֖ל אֶל־יְהוָֽה׃","wa⁠yá̇bò֕ʼ wa⁠yi̇sĕgò֥̇r ha⁠dė֖leţ bĕ̇ʻa֣d şĕ̌néy⁠he֑m wa⁠yi̇ţĕpȧlé֖̇l ʼel-yĕhwáֽh׃"],[4,34,"וַ⁠יַּ֜עַל וַ⁠יִּשְׁכַּ֣ב עַל־הַ⁠יֶּ֗לֶד וַ⁠יָּשֶׂם֩ פִּ֨י⁠ו עַל־פִּ֜י⁠ו וְ⁠עֵינָ֤י⁠ו עַל־עֵינָי⁠ו֙ וְ⁠כַפָּ֣י⁠ו עַל־כפ⁠ו וַ⁠יִּגְהַ֖ר עָלָ֑י⁠ו וַ⁠יָּ֖חָם בְּשַׂ֥ר הַ⁠יָּֽלֶד׃","wa⁠yȧ֜ʻal wa⁠yi̇şĕ̌kȧ֣b ʻal-ha⁠yė֗led wa⁠yá̇şêm֩ pi̇֨y⁠w ʻal-pi̇֜y⁠w wĕ⁠ʻéyná֤y⁠w ʻal-ʻéynáy⁠w֙ wĕ⁠kapá֣̇y⁠w ʻal-kp⁠w wa⁠yi̇gĕha֖r ʻálá֑y⁠w wa⁠yá֖̇ẖám bĕ̇şâ֥r ha⁠yáֽ̇led׃"],[4,35,"וַ⁠יָּ֜שָׁב וַ⁠יֵּ֣לֶךְ בַּ⁠בַּ֗יִת אַחַ֥ת הֵ֨נָּה֙ וְ⁠אַחַ֣ת הֵ֔נָּה וַ⁠יַּ֖עַל וַ⁠יִּגְהַ֣ר עָלָ֑י⁠ו וַ⁠יְזוֹרֵ֤ר הַ⁠נַּ֨עַר֙ עַד־שֶׁ֣בַע פְּעָמִ֔ים וַ⁠יִּפְקַ֥ח הַ⁠נַּ֖עַר אֶת־עֵינָֽי⁠ו׃","wa⁠yá̇֜şá̌b wa⁠yé֣̇lekĕ bȧ⁠bȧ֗yiţ ʼaẖa֥ţ hé֨ná̇h֙ wĕ⁠ʼaẖa֣ţ hé֔ná̇h wa⁠yȧ֖ʻal wa⁠yi̇gĕha֣r ʻálá֑y⁠w wa⁠yĕzwòré֤r ha⁠nȧ֨ʻar֙ ʻad-şě֣baʻ pĕ̇ʻámi֔ym wa⁠yi̇pĕqa֥ẖ ha⁠nȧ֖ʻar ʼeţ-ʻéynáֽy⁠w׃"],[4,36,"וַ⁠יִּקְרָ֣א אֶל־גֵּיחֲזִ֗י וַ⁠יֹּ֨אמֶר֙ קְרָא֙ אֶל־הַ⁠שֻּׁנַמִּ֣ית הַ⁠זֹּ֔את וַ⁠יִּקְרָאֶ֖⁠הָ וַ⁠תָּב֣וֹא אֵלָ֑י⁠ו וַ⁠יֹּ֖אמֶר שְׂאִ֥י בְנֵֽ⁠ךְ׃","wa⁠yi̇qĕrá֣ʼ ʼel-gé̇yẖàzi֗y wa⁠yò̇֨ʼmer֙ qĕráʼ֙ ʼel-ha⁠şu̇̌nami֣̇yţ ha⁠zò̇֔ʼţ wa⁠yi̇qĕráʼe֖⁠há wa⁠ţá̇b֣wòʼ ʼélá֑y⁠w wa⁠yò֖̇ʼmer şĕ̂ʼi֥y bĕnéֽ⁠kĕ׃"],[4,37,"וַ⁠תָּבֹא֙ וַ⁠תִּפֹּ֣ל עַל־רַגְלָ֔י⁠ו וַ⁠תִּשְׁתַּ֖חוּ אָ֑רְצָ⁠ה וַ⁠תִּשָּׂ֥א אֶת־בְּנָ֖⁠הּ וַ⁠תֵּצֵֽא׃פ","wa⁠ţá̇bòʼ֙ wa⁠ţi̇pò֣̇l ʻal-ragĕlá֔y⁠w wa⁠ţi̇şĕ̌ţȧ֖ẖẇ ʼá֑rĕẕá⁠h wa⁠ţi̇şá֥̇̂ʼ ʼeţ-bĕ̇ná֖⁠ḣ wa⁠ţé̇ẕéֽʼ׃p"],[4,38,"וֶ⁠אֱלִישָׁ֞ע שָׁ֤ב הַ⁠גִּלְגָּ֨לָ⁠ה֙ וְ⁠הָ⁠רָעָ֣ב בָּ⁠אָ֔רֶץ וּ⁠בְנֵי֙ הַ⁠נְּבִיאִ֔ים יֹשְׁבִ֖ים לְ⁠פָנָ֑י⁠ו וַ⁠יֹּ֣אמֶר לְ⁠נַעֲר֗⁠וֹ שְׁפֹת֙ הַ⁠סִּ֣יר הַ⁠גְּדוֹלָ֔ה וּ⁠בַשֵּׁ֥ל נָזִ֖יד לִ⁠בְנֵ֥י הַ⁠נְּבִיאִֽים׃","we⁠ʼèliyşá̌֞ʻ şá֤̌b ha⁠gi̇lĕgá̇֨lá⁠h֙ wĕ⁠há⁠ráʻá֣b bá̇⁠ʼá֔reẕ ẇ⁠bĕnéy֙ ha⁠nĕ̇biyʼi֔ym yòşĕ̌bi֖ym lĕ⁠páná֑y⁠w wa⁠yò֣̇ʼmer lĕ⁠naʻàr֗⁠wò şĕ̌pòţ֙ ha⁠si֣̇yr ha⁠gĕ̇dwòlá֔h ẇ⁠başé֥̇̌l názi֖yd li⁠bĕné֥y ha⁠nĕ̇biyʼiֽym׃"],[4,39,"וַ⁠יֵּצֵ֨א אֶחָ֣ד אֶל־הַ⁠שָּׂדֶה֮ לְ⁠לַקֵּ֣ט אֹרֹת֒ וַ⁠יִּמְצָא֙ גֶּ֣פֶן שָׂדֶ֔ה וַ⁠יְלַקֵּ֥ט מִמֶּ֛⁠נּוּ פַּקֻּעֹ֥ת שָׂדֶ֖ה מְלֹ֣א בִגְד֑⁠וֹ וַ⁠יָּבֹ֗א וַ⁠יְפַלַּ֛ח אֶל־סִ֥יר הַ⁠נָּזִ֖יד כִּֽי־לֹ֥א יָדָֽעוּ׃","wa⁠yé̇ẕé֨ʼ ʼeẖá֣d ʼel-ha⁠şá̇̂deh֮ lĕ⁠laqé֣̇t ʼòròţ֒ wa⁠yi̇mĕẕáʼ֙ gė֣pen şá̂de֔h wa⁠yĕlaqé֥̇t mimė֛⁠ṅẇ pȧqu̇ʻò֥ţ şá̂de֖h mĕlò֣ʼ bigĕd֑⁠wò wa⁠yá̇bò֗ʼ wa⁠yĕpalȧ֛ẖ ʼel-si֥yr ha⁠ná̇zi֖yd kiֽ̇y-lò֥ʼ yádáֽʻẇ׃"],[4,40,"וַ⁠יִּֽצְק֥וּ לַ⁠אֲנָשִׁ֖ים לֶ⁠אֱכ֑וֹל וַ֠⁠יְהִי כְּ⁠אָכְלָ֨⁠ם מֵ⁠הַ⁠נָּזִ֜יד וְ⁠הֵ֣מָּה צָעָ֗קוּ וַ⁠יֹּֽאמְרוּ֙ מָ֤וֶת בַּ⁠סִּיר֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים וְ⁠לֹ֥א יָכְל֖וּ לֶ⁠אֱכֹֽל׃","wa⁠yiֽ̇ẕĕq֥ẇ la⁠ʼànáşǐ֖ym le⁠ʼèk֑wòl wa֠⁠yĕhiy kĕ̇⁠ʼákĕlá֨⁠m mé⁠ha⁠ná̇zi֜yd wĕ⁠hé֣má̇h ẕáʻá֗qẇ wa⁠yòֽ̇ʼmĕrẇ֙ má֤weţ bȧ⁠si̇yr֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym wĕ⁠lò֥ʼ yákĕl֖ẇ le⁠ʼèkòֽl׃"],[4,41,"וַ⁠יֹּ֨אמֶר֙ וּ⁠קְחוּ־קֶ֔מַח וַ⁠יַּשְׁלֵ֖ךְ אֶל־הַ⁠סִּ֑יר וַ⁠יֹּ֗אמֶר צַ֤ק לָ⁠עָם֙ וְ⁠יֹאכֵ֔לוּ וְ⁠לֹ֥א הָיָ֛ה דָּבָ֥ר רָ֖ע בַּ⁠סִּֽיר׃ס","wa⁠yò̇֨ʼmer֙ ẇ⁠qĕẖẇ-qe֔maẖ wa⁠yȧşĕ̌lé֖kĕ ʼel-ha⁠si֑̇yr wa⁠yò̇֗ʼmer ẕa֤q lá⁠ʻám֙ wĕ⁠yòʼké֔lẇ wĕ⁠lò֥ʼ háyá֛h dá̇bá֥r rá֖ʻ bȧ⁠siֽ̇yr׃s"],[4,42,"וְ⁠אִ֨ישׁ בָּ֜א מִ⁠בַּ֣עַל שָׁלִ֗שָׁה וַ⁠יָּבֵא֩ לְ⁠אִ֨ישׁ הָ⁠אֱלֹהִ֜ים לֶ֤חֶם בִּכּוּרִים֙ עֶשְׂרִֽים־לֶ֣חֶם שְׂעֹרִ֔ים וְ⁠כַרְמֶ֖ל בְּ⁠צִקְלֹנ֑⁠וֹ וַ⁠יֹּ֕אמֶר תֵּ֥ן לָ⁠עָ֖ם וְ⁠יֹאכֵֽלוּ׃","wĕ⁠ʼi֨yş̌ bá̇֜ʼ mi⁠bȧ֣ʻal şá̌li֗şá̌h wa⁠yá̇béʼ֩ lĕ⁠ʼi֨yş̌ há⁠ʼèlòhi֜ym le֤ẖem bi̇k̇ẇriym֙ ʻeşĕ̂riֽym-le֣ẖem şĕ̂ʻòri֔ym wĕ⁠karĕme֖l bĕ̇⁠ẕiqĕlòn֑⁠wò wa⁠yò̇֕ʼmer ţé֥̇n lá⁠ʻá֖m wĕ⁠yòʼkéֽlẇ׃"],[4,43,"וַ⁠יֹּ֨אמֶר֙ מְשָׁ֣רְת֔⁠וֹ מָ֚ה אֶתֵּ֣ן זֶ֔ה לִ⁠פְנֵ֖י מֵ֣אָה אִ֑ישׁ וַ⁠יֹּ֗אמֶר תֵּ֤ן לָ⁠עָם֙ וְ⁠יֹאכֵ֔לוּ כִּ֣י כֹ֥ה אָמַ֛ר יְהוָ֖ה אָכֹ֥ל וְ⁠הוֹתֵֽר׃","wa⁠yò̇֨ʼmer֙ mĕşá֣̌rĕţ֔⁠wò má֚h ʼeţé֣̇n ze֔h li⁠pĕné֖y mé֣ʼáh ʼi֑yş̌ wa⁠yò̇֗ʼmer ţé֤̇n lá⁠ʻám֙ wĕ⁠yòʼké֔lẇ ki֣̇y kò֥h ʼáma֛r yĕhwá֖h ʼákò֥l wĕ⁠hwòţéֽr׃"],[4,44,"וַ⁠יִּתֵּ֧ן לִ⁠פְנֵי⁠הֶ֛ם וַ⁠יֹּאכְל֥וּ וַ⁠יּוֹתִ֖רוּ כִּ⁠דְבַ֥ר יְהוָֽה׃פ","wa⁠yi̇ţé֧̇n li⁠pĕnéy⁠he֛m wa⁠yò̇ʼkĕl֥ẇ wa⁠ẏwòţi֖rẇ ki̇⁠dĕba֥r yĕhwáֽh׃p"],[5,1,"וְ֠⁠נַעֲמָן שַׂר־צְבָ֨א מֶֽלֶךְ־אֲרָ֜ם הָיָ֣ה אִישׁ֩ גָּד֨וֹל לִ⁠פְנֵ֤י אֲדֹנָי⁠ו֙ וּ⁠נְשֻׂ֣א פָנִ֔ים כִּֽי־ב֛⁠וֹ נָֽתַן־יְהוָ֥ה תְּשׁוּעָ֖ה לַ⁠אֲרָ֑ם וְ⁠הָ⁠אִ֗ישׁ הָיָ֛ה גִּבּ֥וֹר חַ֖יִל מְצֹרָֽע׃","wĕ֠⁠naʻàmán şâr-ẕĕbá֨ʼ meֽlekĕ-ʼàrá֜m háyá֣h ʼiyş̌֩ gá̇d֨wòl li⁠pĕné֤y ʼàdònáy⁠w֙ ẇ⁠nĕşû֣ʼ páni֔ym kiֽ̇y-b֛⁠wò náֽţan-yĕhwá֥h ţĕ̇ş̌ẇʻá֖h la⁠ʼàrá֑m wĕ⁠há⁠ʼi֗yş̌ háyá֛h gi̇ḃ֥wòr ẖa֖yil mĕẕòráֽʻ׃"],[5,2,"וַ⁠אֲרָם֙ יָצְא֣וּ גְדוּדִ֔ים וַ⁠יִּשְׁבּ֛וּ מֵ⁠אֶ֥רֶץ יִשְׂרָאֵ֖ל נַעֲרָ֣ה קְטַנָּ֑ה וַ⁠תְּהִ֕י לִ⁠פְנֵ֖י אֵ֥שֶׁת נַעֲמָֽן׃","wa⁠ʼàrám֙ yáẕĕʼ֣ẇ gĕdẇdi֔ym wa⁠yi̇şĕ̌ḃ֛ẇ mé⁠ʼe֥reẕ yişĕ̂ráʼé֖l naʻàrá֣h qĕtaná֑̇h wa⁠ţĕ̇hi֕y li⁠pĕné֖y ʼé֥şěţ naʻàmáֽn׃"],[5,3,"וַ⁠תֹּ֨אמֶר֙ אֶל־גְּבִרְתָּ֔⁠הּ אַחֲלֵ֣י אֲדֹנִ֔⁠י לִ⁠פְנֵ֥י הַ⁠נָּבִ֖יא אֲשֶׁ֣ר בְּ⁠שֹׁמְר֑וֹן אָ֛ז יֶאֱסֹ֥ף אֹת֖⁠וֹ מִ⁠צָּרַעְתּֽ⁠וֹ׃","wa⁠ţò̇֨ʼmer֙ ʼel-gĕ̇birĕţá̇֔⁠ḣ ʼaẖàlé֣y ʼàdòni֔⁠y li⁠pĕné֥y ha⁠ná̇bi֖yʼ ʼàşě֣r bĕ̇⁠şò̌mĕr֑wòn ʼá֛z yeʼèsò֥p ʼòţ֖⁠wò mi⁠ẕá̇raʻĕţֽ̇⁠wò׃"],[5,4,"וַ⁠יָּבֹ֕א וַ⁠יַּגֵּ֥ד לַ⁠אדֹנָ֖י⁠ו לֵ⁠אמֹ֑ר כָּ⁠זֹ֤את וְ⁠כָ⁠זֹאת֙ דִּבְּרָ֣ה הַֽ⁠נַּעֲרָ֔ה אֲשֶׁ֖ר מֵ⁠אֶ֥רֶץ יִשְׂרָאֵֽל׃","wa⁠yá̇bò֕ʼ wa⁠yȧgé֥̇d la⁠ʼdòná֖y⁠w lé⁠ʼmò֑r ká̇⁠zò֤ʼţ wĕ⁠ká⁠zòʼţ֙ di̇bĕ̇rá֣h haֽ⁠nȧʻàrá֔h ʼàşě֖r mé⁠ʼe֥reẕ yişĕ̂ráʼéֽl׃"],[5,5,"וַ⁠יֹּ֤אמֶר מֶֽלֶךְ־אֲרָם֙ לֶךְ־בֹּ֔א וְ⁠אֶשְׁלְחָ֥ה סֵ֖פֶר אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֑ל וַ⁠יֵּלֶךְ֩ וַ⁠יִּקַּ֨ח בְּ⁠יָד֜⁠וֹ עֶ֣שֶׂר כִּכְּרֵי־כֶ֗סֶף וְ⁠שֵׁ֤שֶׁת אֲלָפִים֙ זָהָ֔ב וְ⁠עֶ֖שֶׂר חֲלִיפ֥וֹת בְּגָדִֽים׃","wa⁠yò֤̇ʼmer meֽlekĕ-ʼàrám֙ lekĕ-bò̇֔ʼ wĕ⁠ʼeşĕ̌lĕẖá֥h sé֖per ʼel-me֣lekĕ yişĕ̂ráʼé֑l wa⁠yé̇lekĕ֩ wa⁠yi̇qȧ֨ẖ bĕ̇⁠yád֜⁠wò ʻe֣şêr ki̇kĕ̇réy-ke֗sep wĕ⁠şé֤̌şěţ ʼàlápiym֙ záhá֔b wĕ⁠ʻe֖şêr ẖàliyp֥wòţ bĕ̇gádiֽym׃"],[5,6,"וַ⁠יָּבֵ֣א הַ⁠סֵּ֔פֶר אֶל־מֶ֥לֶךְ יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר וְ⁠עַתָּ֗ה כְּ⁠ב֨וֹא הַ⁠סֵּ֤פֶר הַ⁠זֶּה֙ אֵלֶ֔י⁠ךָ הִנֵּ֨ה שָׁלַ֤חְתִּי אֵלֶ֨י⁠ךָ֙ אֶת־נַעֲמָ֣ן עַבְדִּ֔⁠י וַ⁠אֲסַפְתּ֖⁠וֹ מִ⁠צָּרַעְתּֽ⁠וֹ׃","wa⁠yá̇bé֣ʼ ha⁠sé̇֔per ʼel-me֥lekĕ yişĕ̂ráʼé֖l lé⁠ʼmò֑r wĕ⁠ʻaţá̇֗h kĕ̇⁠b֨wòʼ ha⁠sé֤̇per ha⁠zėh֙ ʼéle֔y⁠ká hiné̇֨h şá̌la֤ẖĕţi̇y ʼéle֨y⁠ká֙ ʼeţ-naʻàmá֣n ʻabĕdi̇֔⁠y wa⁠ʼàsapĕţ֖̇⁠wò mi⁠ẕá̇raʻĕţֽ̇⁠wò׃"],[5,7,"וַ⁠יְהִ֡י כִּ⁠קְרֹא֩ מֶֽלֶךְ־יִשְׂרָאֵ֨ל אֶת־הַ⁠סֵּ֜פֶר וַ⁠יִּקְרַ֣ע בְּגָדָ֗י⁠ו וַ⁠יֹּ֨אמֶר֙ הַ⁠אֱלֹהִ֥ים אָ֨נִי֙ לְ⁠הָמִ֣ית וּֽ⁠לְ⁠הַחֲי֔וֹת כִּֽי־זֶה֙ שֹׁלֵ֣חַ אֵלַ֔⁠י לֶ⁠אֱסֹ֥ף אִ֖ישׁ מִ⁠צָּֽרַעְתּ֑⁠וֹ כִּ֤י אַךְ־דְּעֽוּ־נָא֙ וּ⁠רְא֔וּ כִּֽי־מִתְאַנֶּ֥ה ה֖וּא לִֽ⁠י׃","wa⁠yĕhi֡y ki̇⁠qĕròʼ֩ meֽlekĕ-yişĕ̂ráʼé֨l ʼeţ-ha⁠sé̇֜per wa⁠yi̇qĕra֣ʻ bĕ̇gádá֗y⁠w wa⁠yò̇֨ʼmer֙ ha⁠ʼèlòhi֥ym ʼá֨niy֙ lĕ⁠hámi֣yţ ẇֽ⁠lĕ⁠haẖày֔wòţ kiֽ̇y-zeh֙ şò̌lé֣ẖa ʼéla֔⁠y le⁠ʼèsò֥p ʼi֖yş̌ mi⁠ẕáֽ̇raʻĕţ֑̇⁠wò ki֤̇y ʼakĕ-dĕ̇ʻֽẇ-náʼ֙ ẇ⁠rĕʼ֔ẇ kiֽ̇y-miţĕʼanė֥h h֖ẇʼ liֽ⁠y׃"],[5,8,"וַ⁠יְהִ֞י כִּ⁠שְׁמֹ֣עַ ׀ אֱלִישָׁ֣ע אִישׁ־הָ⁠אֱלֹהִ֗ים כִּֽי־קָרַ֤ע מֶֽלֶךְ־יִשְׂרָאֵל֙ אֶת־בְּגָדָ֔י⁠ו וַ⁠יִּשְׁלַח֙ אֶל־הַ⁠מֶּ֣לֶךְ לֵ⁠אמֹ֔ר לָ֥⁠מָּה קָרַ֖עְתָּ בְּגָדֶ֑י⁠ךָ יָבֹֽא־נָ֣א אֵלַ֔⁠י וְ⁠יֵדַ֕ע כִּ֛י יֵ֥שׁ נָבִ֖יא בְּ⁠יִשְׂרָאֵֽל׃","wa⁠yĕhi֞y ki̇⁠şĕ̌mò֣ʻa ׀ ʼèliyşá֣̌ʻ ʼiyş̌-há⁠ʼèlòhi֗ym kiֽ̇y-qára֤ʻ meֽlekĕ-yişĕ̂ráʼél֙ ʼeţ-bĕ̇gádá֔y⁠w wa⁠yi̇şĕ̌laẖ֙ ʼel-ha⁠mė֣lekĕ lé⁠ʼmò֔r lá֥⁠má̇h qára֖ʻĕţá̇ bĕ̇gáde֑y⁠ká yábòֽʼ-ná֣ʼ ʼéla֔⁠y wĕ⁠yéda֕ʻ ki֛̇y yé֥ş̌ nábi֖yʼ bĕ̇⁠yişĕ̂ráʼéֽl׃"],[5,9,"וַ⁠יָּבֹ֥א נַעֲמָ֖ן ב⁠סוס⁠ו וּ⁠בְ⁠רִכְבּ֑⁠וֹ וַ⁠יַּעֲמֹ֥ד פֶּֽתַח־הַ⁠בַּ֖יִת לֶ⁠אֱלִישָֽׁע׃","wa⁠yá̇bò֥ʼ naʻàmá֖n b⁠sws⁠w ẇ⁠bĕ⁠rikĕḃ֑⁠wò wa⁠yȧʻàmò֥d pėֽţaẖ-ha⁠bȧ֖yiţ le⁠ʼèliyşáֽ̌ʻ׃"],[5,10,"וַ⁠יִּשְׁלַ֥ח אֵלָ֛י⁠ו אֱלִישָׁ֖ע מַלְאָ֣ךְ לֵ⁠אמֹ֑ר הָל֗וֹךְ וְ⁠רָחַצְתָּ֤ שֶֽׁבַע־פְּעָמִים֙ בַּ⁠יַּרְדֵּ֔ן וְ⁠יָשֹׁ֧ב בְּשָׂרְ⁠ךָ֛ לְ⁠ךָ֖ וּ⁠טְהָֽר׃","wa⁠yi̇şĕ̌la֥ẖ ʼélá֛y⁠w ʼèliyşá֖̌ʻ malĕʼá֣kĕ lé⁠ʼmò֑r hál֗wòkĕ wĕ⁠ráẖaẕĕţá֤̇ şěֽbaʻ-pĕ̇ʻámiym֙ bȧ⁠yȧrĕdé̇֔n wĕ⁠yáşò֧̌b bĕ̇şá̂rĕ⁠ká֛ lĕ⁠ká֖ ẇ⁠tĕháֽr׃"],[5,11,"וַ⁠יִּקְצֹ֥ף נַעֲמָ֖ן וַ⁠יֵּלַ֑ךְ וַ⁠יֹּאמֶר֩ הִנֵּ֨ה אָמַ֜רְתִּי אֵלַ֣⁠י ׀ יֵצֵ֣א יָצ֗וֹא וְ⁠עָמַד֙ וְ⁠קָרָא֙ בְּ⁠שֵׁם־יְהוָ֣ה אֱלֹהָ֔י⁠ו וְ⁠הֵנִ֥יף יָד֛⁠וֹ אֶל־הַ⁠מָּק֖וֹם וְ⁠אָסַ֥ף הַ⁠מְּצֹרָֽע׃","wa⁠yi̇qĕẕò֥p naʻàmá֖n wa⁠yé̇la֑kĕ wa⁠yò̇ʼmer֩ hiné̇֨h ʼáma֜rĕţi̇y ʼéla֣⁠y ׀ yéẕé֣ʼ yáẕ֗wòʼ wĕ⁠ʻámad֙ wĕ⁠qáráʼ֙ bĕ̇⁠şé̌m-yĕhwá֣h ʼèlòhá֔y⁠w wĕ⁠héni֥yp yád֛⁠wò ʼel-ha⁠má̇q֖wòm wĕ⁠ʼása֥p ha⁠mĕ̇ẕòráֽʻ׃"],[5,12,"הֲ⁠לֹ֡א טוֹב֩ אבנה וּ⁠פַרְפַּ֜ר נַהֲר֣וֹת דַּמֶּ֗שֶׂק מִ⁠כֹּל֙ מֵימֵ֣י יִשְׂרָאֵ֔ל הֲ⁠לֹֽא־אֶרְחַ֥ץ בָּ⁠הֶ֖ם וְ⁠טָהָ֑רְתִּי וַ⁠יִּ֖פֶן וַ⁠יֵּ֥לֶךְ בְּ⁠חֵמָֽה׃","hà⁠lò֡ʼ twòb֩ ʼbnh ẇ⁠parĕpȧ֜r nahàr֣wòţ dȧmė֗şêq mi⁠kò̇l֙ méymé֣y yişĕ̂ráʼé֔l hà⁠lòֽʼ-ʼerĕẖa֥ẕ bá̇⁠he֖m wĕ⁠táhá֑rĕţi̇y wa⁠yi֖̇pen wa⁠yé֥̇lekĕ bĕ̇⁠ẖémáֽh׃"],[5,13,"וַ⁠יִּגְּשׁ֣וּ עֲבָדָי⁠ו֮ וַ⁠יְדַבְּר֣וּ אֵלָי⁠ו֒ וַ⁠יֹּאמְר֗וּ אָבִי֙ דָּבָ֣ר גָּד֗וֹל הַ⁠נָּבִ֛יא דִּבֶּ֥ר אֵלֶ֖י⁠ךָ הֲ⁠ל֣וֹא תַעֲשֶׂ֑ה וְ⁠אַ֛ף כִּֽי־אָמַ֥ר אֵלֶ֖י⁠ךָ רְחַ֥ץ וּ⁠טְהָֽר׃","wa⁠yi̇gĕ̇ş֣̌ẇ ʻàbádáy⁠w֮ wa⁠yĕdabĕ̇r֣ẇ ʼéláy⁠w֒ wa⁠yò̇ʼmĕr֗ẇ ʼábiy֙ dá̇bá֣r gá̇d֗wòl ha⁠ná̇bi֛yʼ di̇bė֥r ʼéle֖y⁠ká hà⁠l֣wòʼ ţaʻàşê֑h wĕ⁠ʼa֛p kiֽ̇y-ʼáma֥r ʼéle֖y⁠ká rĕẖa֥ẕ ẇ⁠tĕháֽr׃"],[5,14,"וַ⁠יֵּ֗רֶד וַ⁠יִּטְבֹּ֤ל בַּ⁠יַּרְדֵּן֙ שֶׁ֣בַע פְּעָמִ֔ים כִּ⁠דְבַ֖ר אִ֣ישׁ הָ⁠אֱלֹהִ֑ים וַ⁠יָּ֣שָׁב בְּשָׂר֗⁠וֹ כִּ⁠בְשַׂ֛ר נַ֥עַר קָטֹ֖ן וַ⁠יִּטְהָֽר׃","wa⁠yé̇֗red wa⁠yi̇tĕbò֤̇l bȧ⁠yȧrĕdé̇n֙ şě֣baʻ pĕ̇ʻámi֔ym ki̇⁠dĕba֖r ʼi֣yş̌ há⁠ʼèlòhi֑ym wa⁠yá֣̇şá̌b bĕ̇şá̂r֗⁠wò ki̇⁠bĕşâ֛r na֥ʻar qátò֖n wa⁠yi̇tĕháֽr׃"],[5,15,"וַ⁠יָּשָׁב֩ אֶל־אִ֨ישׁ הָ⁠אֱלֹהִ֜ים ה֣וּא וְ⁠כָֽל־מַחֲנֵ֗⁠הוּ וַ⁠יָּבֹא֮ וַ⁠יַּעֲמֹ֣ד לְ⁠פָנָי⁠ו֒ וַ⁠יֹּ֗אמֶר הִנֵּה־נָ֤א יָדַ֨עְתִּי֙ כִּ֣י אֵ֤ין אֱלֹהִים֙ בְּ⁠כָל־הָ⁠אָ֔רֶץ כִּ֖י אִם־בְּ⁠יִשְׂרָאֵ֑ל וְ⁠עַתָּ֛ה קַח־נָ֥א בְרָכָ֖ה מֵ⁠אֵ֥ת עַבְדֶּֽ⁠ךָ׃","wa⁠yá̇şá̌b֩ ʼel-ʼi֨yş̌ há⁠ʼèlòhi֜ym h֣ẇʼ wĕ⁠káֽl-maẖàné֗⁠hẇ wa⁠yá̇bòʼ֮ wa⁠yȧʻàmò֣d lĕ⁠pánáy⁠w֒ wa⁠yò̇֗ʼmer hiné̇h-ná֤ʼ yáda֨ʻĕţi̇y֙ ki֣̇y ʼé֤yn ʼèlòhiym֙ bĕ̇⁠kál-há⁠ʼá֔reẕ ki֖̇y ʼim-bĕ̇⁠yişĕ̂ráʼé֑l wĕ⁠ʻaţá֛̇h qaẖ-ná֥ʼ bĕráká֖h mé⁠ʼé֥ţ ʻabĕdėֽ⁠ká׃"],[5,16,"וַ⁠יֹּ֕אמֶר חַי־יְהוָ֛ה אֲשֶׁר־עָמַ֥דְתִּי לְ⁠פָנָ֖י⁠ו אִם־אֶקָּ֑ח וַ⁠יִּפְצַר־בּ֥⁠וֹ לָ⁠קַ֖חַת וַ⁠יְמָאֵֽן׃","wa⁠yò̇֕ʼmer ẖay-yĕhwá֛h ʼàşěr-ʻáma֥dĕţi̇y lĕ⁠páná֖y⁠w ʼim-ʼeqá֑̇ẖ wa⁠yi̇pĕẕar-ḃ֥⁠wò lá⁠qa֖ẖaţ wa⁠yĕmáʼéֽn׃"],[5,17,"וַ⁠יֹּאמֶר֮ נַעֲמָן֒ וָ⁠לֹ֕א יֻתַּן־נָ֣א לְ⁠עַבְדְּ⁠ךָ֔ מַשָּׂ֥א צֶֽמֶד־פְּרָדִ֖ים אֲדָמָ֑ה כִּ֡י לֽוֹא־יַעֲשֶׂה֩ ע֨וֹד עַבְדְּ⁠ךָ֜ עֹלָ֤ה וָ⁠זֶ֨בַח֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים כִּ֖י אִם־לַ⁠יהוָֽה׃","wa⁠yò̇ʼmer֮ naʻàmán֒ wá⁠lò֕ʼ yuţȧn-ná֣ʼ lĕ⁠ʻabĕdĕ̇⁠ká֔ maşá֥̇̂ʼ ẕeֽmed-pĕ̇rádi֖ym ʼàdámá֑h ki̇֡y lֽwòʼ-yaʻàşêh֩ ʻ֨wòd ʻabĕdĕ̇⁠ká֜ ʻòlá֤h wá⁠ze֨baẖ֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym ki֖̇y ʼim-la⁠yhwáֽh׃"],[5,18,"לַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה יִסְלַ֥ח יְהוָ֖ה לְ⁠עַבְדֶּ֑⁠ךָ בְּ⁠ב֣וֹא אֲדֹנִ֣⁠י בֵית־רִמּוֹן֩ לְ⁠הִשְׁתַּחֲוֺ֨ת שָׁ֜מָּ⁠ה וְ⁠ה֣וּא ׀ נִשְׁעָ֣ן עַל־יָדִ֗⁠י וְ⁠הִֽשְׁתַּחֲוֵ֨יתִי֙ בֵּ֣ית רִמֹּ֔ן בְּ⁠הִשְׁתַּחֲוָיָ֨תִ⁠י֙ בֵּ֣ית רִמֹּ֔ן יִסְלַח־נא יְהוָ֥ה לְ⁠עַבְדְּ⁠ךָ֖ בַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","la⁠dá̇bá֣r ha⁠zė֔h yisĕla֥ẖ yĕhwá֖h lĕ⁠ʻabĕdė֑⁠ká bĕ̇⁠b֣wòʼ ʼàdòni֣⁠y béyţ-riṁwòn֩ lĕ⁠hişĕ̌ţȧẖàwֺ֨ţ şá̌֜má̇⁠h wĕ⁠h֣ẇʼ ׀ nişĕ̌ʻá֣n ʻal-yádi֗⁠y wĕ⁠hiֽşĕ̌ţȧẖàwé֨yţiy֙ bé֣̇yţ rimò̇֔n bĕ̇⁠hişĕ̌ţȧẖàwáyá֨ţi⁠y֙ bé֣̇yţ rimò̇֔n yisĕlaẖ-nʼ yĕhwá֥h lĕ⁠ʻabĕdĕ̇⁠ká֖ bȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[5,19,"וַ⁠יֹּ֥אמֶר ל֖⁠וֹ לֵ֣ךְ לְ⁠שָׁל֑וֹם וַ⁠יֵּ֥לֶךְ מֵ⁠אִתּ֖⁠וֹ כִּבְרַת־אָֽרֶץ׃ס","wa⁠yò֥̇ʼmer l֖⁠wò lé֣kĕ lĕ⁠şá̌l֑wòm wa⁠yé֥̇lekĕ mé⁠ʼiţ֖̇⁠wò ki̇bĕraţ-ʼáֽreẕ׃s"],[5,20,"וַ⁠יֹּ֣אמֶר גֵּיחֲזִ֗י נַעַר֮ אֱלִישָׁ֣ע אִישׁ־הָ⁠אֱלֹהִים֒ הִנֵּ֣ה ׀ חָשַׂ֣ךְ אֲדֹנִ֗⁠י אֶֽת־נַעֲמָ֤ן הָֽ⁠אֲרַמִּי֙ הַ⁠זֶּ֔ה מִ⁠קַּ֥חַת מִ⁠יָּד֖⁠וֹ אֵ֣ת אֲשֶׁר־הֵבִ֑יא חַי־יְהוָה֙ כִּֽי־אִם־רַ֣צְתִּי אַחֲרָ֔י⁠ו וְ⁠לָקַחְתִּ֥י מֵ⁠אִתּ֖⁠וֹ מְאֽוּמָה׃","wa⁠yò֣̇ʼmer gé̇yẖàzi֗y naʻar֮ ʼèliyşá֣̌ʻ ʼiyş̌-há⁠ʼèlòhiym֒ hiné֣̇h ׀ ẖáşâ֣kĕ ʼàdòni֗⁠y ʼeֽţ-naʻàmá֤n háֽ⁠ʼàrami̇y֙ ha⁠zė֔h mi⁠qȧ֥ẖaţ mi⁠yá̇d֖⁠wò ʼé֣ţ ʼàşěr-hébi֑yʼ ẖay-yĕhwáh֙ kiֽ̇y-ʼim-ra֣ẕĕţi̇y ʼaẖàrá֔y⁠w wĕ⁠láqaẖĕţi֥̇y mé⁠ʼiţ֖̇⁠wò mĕʼֽẇmáh׃"],[5,21,"וַ⁠יִּרְדֹּ֥ף גֵּיחֲזִ֖י אַחֲרֵ֣י נַֽעֲמָ֑ן וַ⁠יִּרְאֶ֤ה נַֽעֲמָן֙ רָ֣ץ אַחֲרָ֔י⁠ו וַ⁠יִּפֹּ֞ל מֵ⁠עַ֧ל הַ⁠מֶּרְכָּבָ֛ה לִ⁠קְרָאת֖⁠וֹ וַ⁠יֹּ֥אמֶר הֲ⁠שָׁלֽוֹם׃","wa⁠yi̇rĕdò֥̇p gé̇yẖàzi֖y ʼaẖàré֣y naֽʻàmá֑n wa⁠yi̇rĕʼe֤h naֽʻàmán֙ rá֣ẕ ʼaẖàrá֔y⁠w wa⁠yi̇pò̇֞l mé⁠ʻa֧l ha⁠mėrĕká̇bá֛h li⁠qĕráʼţ֖⁠wò wa⁠yò֥̇ʼmer hà⁠şá̌lֽwòm׃"],[5,22,"וַ⁠יֹּ֣אמֶר ׀ שָׁל֗וֹם אֲדֹנִ⁠י֮ שְׁלָחַ֣⁠נִי לֵ⁠אמֹר֒ הִנֵּ֣ה עַתָּ֡ה זֶ֠ה בָּ֣אוּ אֵלַ֧⁠י שְׁנֵֽי־נְעָרִ֛ים מֵ⁠הַ֥ר אֶפְרַ֖יִם מִ⁠בְּנֵ֣י הַ⁠נְּבִיאִ֑ים תְּנָ⁠ה־נָּ֤א לָ⁠הֶם֙ כִּכַּר־כֶּ֔סֶף וּ⁠שְׁתֵּ֖י חֲלִפ֥וֹת בְּגָדִֽים׃","wa⁠yò֣̇ʼmer ׀ şá̌l֗wòm ʼàdòni⁠y֮ şĕ̌láẖa֣⁠niy lé⁠ʼmòr֒ hiné֣̇h ʻaţá̇֡h ze֠h bá֣̇ʼẇ ʼéla֧⁠y şĕ̌néֽy-nĕʻári֛ym mé⁠ha֥r ʼepĕra֖yim mi⁠bĕ̇né֣y ha⁠nĕ̇biyʼi֑ym ţĕ̇ná⁠h-ná֤̇ʼ lá⁠hem֙ ki̇kȧr-kė֔sep ẇ⁠şĕ̌ţé֖̇y ẖàlip֥wòţ bĕ̇gádiֽym׃"],[5,23,"וַ⁠יֹּ֣אמֶר נַעֲמָ֔ן הוֹאֵ֖ל קַ֣ח כִּכָּרָ֑יִם וַ⁠יִּפְרָץ־בּ֗⁠וֹ וַ⁠יָּצַר֩ כִּכְּרַ֨יִם כֶּ֜סֶף בִּ⁠שְׁנֵ֣י חֲרִטִ֗ים וּ⁠שְׁתֵּי֙ חֲלִפ֣וֹת בְּגָדִ֔ים וַ⁠יִּתֵּן֙ אֶל־שְׁנֵ֣י נְעָרָ֔י⁠ו וַ⁠יִּשְׂא֖וּ לְ⁠פָנָֽי⁠ו׃","wa⁠yò֣̇ʼmer naʻàmá֔n hwòʼé֖l qa֣ẖ ki̇ká̇rá֑yim wa⁠yi̇pĕráẕ-ḃ֗⁠wò wa⁠yá̇ẕar֩ ki̇kĕ̇ra֨yim kė֜sep bi̇⁠şĕ̌né֣y ẖàriti֗ym ẇ⁠şĕ̌ţé̇y֙ ẖàlip֣wòţ bĕ̇gádi֔ym wa⁠yi̇ţé̇n֙ ʼel-şĕ̌né֣y nĕʻárá֔y⁠w wa⁠yi̇şĕ̂ʼ֖ẇ lĕ⁠pánáֽy⁠w׃"],[5,24,"וַ⁠יָּבֹא֙ אֶל־הָ⁠עֹ֔פֶל וַ⁠יִּקַּ֥ח מִ⁠יָּדָ֖⁠ם וַ⁠יִּפְקֹ֣ד בַּ⁠בָּ֑יִת וַ⁠יְשַׁלַּ֥ח אֶת־הָ⁠אֲנָשִׁ֖ים וַ⁠יֵּלֵֽכוּ׃","wa⁠yá̇bòʼ֙ ʼel-há⁠ʻò֔pel wa⁠yi̇qȧ֥ẖ mi⁠yá̇dá֖⁠m wa⁠yi̇pĕqò֣d bȧ⁠bá֑̇yiţ wa⁠yĕşǎlȧ֥ẖ ʼeţ-há⁠ʼànáşǐ֖ym wa⁠yé̇léֽkẇ׃"],[5,25,"וְ⁠הוּא־בָא֙ וַ⁠יַּעֲמֹ֣ד אֶל־אֲדֹנָ֔י⁠ו וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ אֱלִישָׁ֔ע מ⁠אן גֵּחֲזִ֑י וַ⁠יֹּ֕אמֶר לֹֽא־הָלַ֥ךְ עַבְדְּ⁠ךָ֖ אָ֥נֶה וָ⁠אָֽנָה׃","wĕ⁠hẇʼ-báʼ֙ wa⁠yȧʻàmò֣d ʼel-ʼàdòná֔y⁠w wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ʼèliyşá̌֔ʻ m⁠ʼn gé̇ẖàzi֑y wa⁠yò̇֕ʼmer lòֽʼ-hála֥kĕ ʻabĕdĕ̇⁠ká֖ ʼá֥neh wá⁠ʼáֽnáh׃"],[5,26,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ לֹא־לִבִּ֣⁠י הָלַ֔ךְ כַּ⁠אֲשֶׁ֧ר הָֽפַךְ־אִ֛ישׁ מֵ⁠עַ֥ל מֶרְכַּבְתּ֖⁠וֹ לִ⁠קְרָאתֶ֑⁠ךָ הַ⁠עֵ֞ת לָ⁠קַ֤חַת אֶת־הַ⁠כֶּ֨סֶף֙ וְ⁠לָ⁠קַ֣חַת בְּגָדִ֔ים וְ⁠זֵיתִ֤ים וּ⁠כְרָמִים֙ וְ⁠צֹ֣אן וּ⁠בָקָ֔ר וַ⁠עֲבָדִ֖ים וּ⁠שְׁפָחֽוֹת׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ lòʼ-libi֣̇⁠y hála֔kĕ kȧ⁠ʼàşě֧r háֽpakĕ-ʼi֛yş̌ mé⁠ʻa֥l merĕkȧbĕţ֖̇⁠wò li⁠qĕráʼţe֑⁠ká ha⁠ʻé֞ţ lá⁠qa֤ẖaţ ʼeţ-ha⁠kė֨sep֙ wĕ⁠lá⁠qa֣ẖaţ bĕ̇gádi֔ym wĕ⁠zéyţi֤ym ẇ⁠kĕrámiym֙ wĕ⁠ẕò֣ʼn ẇ⁠báqá֔r wa⁠ʻàbádi֖ym ẇ⁠şĕ̌páẖֽwòţ׃"],[5,27,"וְ⁠צָרַ֤עַת נַֽעֲמָן֙ תִּֽדְבַּק־בְּ⁠ךָ֔ וּֽ⁠בְ⁠זַרְעֲ⁠ךָ לְ⁠עוֹלָ֑ם וַ⁠יֵּצֵ֥א מִ⁠לְּ⁠פָנָ֖י⁠ו מְצֹרָ֥ע כַּ⁠שָּֽׁלֶג׃ס","wĕ⁠ẕára֤ʻaţ naֽʻàmán֙ ţiֽ̇dĕbȧq-bĕ̇⁠ká֔ ẇֽ⁠bĕ⁠zarĕʻà⁠ká lĕ⁠ʻwòlá֑m wa⁠yé̇ẕé֥ʼ mi⁠lĕ̇⁠páná֖y⁠w mĕẕòrá֥ʻ kȧ⁠şáֽ̇̌leg׃s"],[6,1,"וַ⁠יֹּאמְר֥וּ בְנֵֽי־הַ⁠נְּבִיאִ֖ים אֶל־אֱלִישָׁ֑ע הִנֵּֽה־נָ֣א הַ⁠מָּק֗וֹם אֲשֶׁ֨ר אֲנַ֜חְנוּ יֹשְׁבִ֥ים שָׁ֛ם לְ⁠פָנֶ֖י⁠ךָ צַ֥ר מִמֶּֽ⁠נּוּ׃","wa⁠yò̇ʼmĕr֥ẇ bĕnéֽy-ha⁠nĕ̇biyʼi֖ym ʼel-ʼèliyşá֑̌ʻ hinéֽ̇h-ná֣ʼ ha⁠má̇q֗wòm ʼàşě֨r ʼàna֜ẖĕnẇ yòşĕ̌bi֥ym şá֛̌m lĕ⁠páne֖y⁠ká ẕa֥r mimėֽ⁠ṅẇ׃"],[6,2,"נֵֽלְכָה־נָּ֣א עַד־הַ⁠יַּרְדֵּ֗ן וְ⁠נִקְחָ֤ה מִ⁠שָּׁם֙ אִ֚ישׁ קוֹרָ֣ה אֶחָ֔ת וְ⁠נַעֲשֶׂה־לָּ֥⁠נוּ שָׁ֛ם מָק֖וֹם לָ⁠שֶׁ֣בֶת שָׁ֑ם וַ⁠יֹּ֖אמֶר לֵֽכוּ׃","néֽlĕkáh-ná֣̇ʼ ʻad-ha⁠yȧrĕdé̇֗n wĕ⁠niqĕẖá֤h mi⁠şá̇̌m֙ ʼi֚yş̌ qwòrá֣h ʼeẖá֔ţ wĕ⁠naʻàşêh-lá֥̇⁠nẇ şá֛̌m máq֖wòm lá⁠şě֣beţ şá֑̌m wa⁠yò֖̇ʼmer léֽkẇ׃"],[6,3,"וַ⁠יֹּ֨אמֶר֙ הָֽ⁠אֶחָ֔ד ה֥וֹאֶל נָ֖א וְ⁠לֵ֣ךְ אֶת־עֲבָדֶ֑י⁠ךָ וַ⁠יֹּ֖אמֶר אֲנִ֥י אֵלֵֽךְ׃","wa⁠yò̇֨ʼmer֙ háֽ⁠ʼeẖá֔d h֥wòʼel ná֖ʼ wĕ⁠lé֣kĕ ʼeţ-ʻàbáde֑y⁠ká wa⁠yò֖̇ʼmer ʼàni֥y ʼéléֽkĕ׃"],[6,4,"וַ⁠יֵּ֖לֶךְ אִתָּ֑⁠ם וַ⁠יָּבֹ֨אוּ֙ הַ⁠יַּרְדֵּ֔נָ⁠ה וַֽ⁠יִּגְזְר֖וּ הָ⁠עֵצִֽים׃","wa⁠yé֖̇lekĕ ʼiţá֑̇⁠m wa⁠yá̇bò֨ʼẇ֙ ha⁠yȧrĕdé̇֔ná⁠h waֽ⁠yi̇gĕzĕr֖ẇ há⁠ʻéẕiֽym׃"],[6,5,"וַ⁠יְהִ֤י הָֽ⁠אֶחָד֙ מַפִּ֣יל הַ⁠קּוֹרָ֔ה וְ⁠אֶת־הַ⁠בַּרְזֶ֖ל נָפַ֣ל אֶל־הַ⁠מָּ֑יִם וַ⁠יִּצְעַ֥ק וַ⁠יֹּ֛אמֶר אֲהָ֥הּ אֲדֹנִ֖⁠י וְ⁠ה֥וּא שָׁאֽוּל׃","wa⁠yĕhi֤y háֽ⁠ʼeẖád֙ mapi֣̇yl ha⁠q̇wòrá֔h wĕ⁠ʼeţ-ha⁠bȧrĕze֖l nápa֣l ʼel-ha⁠má֑̇yim wa⁠yi̇ẕĕʻa֥q wa⁠yò֛̇ʼmer ʼàhá֥ḣ ʼàdòni֖⁠y wĕ⁠h֥ẇʼ şá̌ʼֽẇl׃"],[6,6,"וַ⁠יֹּ֥אמֶר אִישׁ־הָ⁠אֱלֹהִ֖ים אָ֣נָה נָפָ֑ל וַ⁠יַּרְאֵ֨⁠הוּ֙ אֶת־הַ⁠מָּק֔וֹם וַ⁠יִּקְצָב־עֵץ֙ וַ⁠יַּשְׁלֶךְ־שָׁ֔מָּ⁠ה וַ⁠יָּ֖צֶף הַ⁠בַּרְזֶֽל׃","wa⁠yò֥̇ʼmer ʼiyş̌-há⁠ʼèlòhi֖ym ʼá֣náh nápá֑l wa⁠yȧrĕʼé֨⁠hẇ֙ ʼeţ-ha⁠má̇q֔wòm wa⁠yi̇qĕẕáb-ʻéẕ֙ wa⁠yȧşĕ̌lekĕ-şá̌֔má̇⁠h wa⁠yá֖̇ẕep ha⁠bȧrĕzeֽl׃"],[6,7,"וַ⁠יֹּ֖אמֶר הָ֣רֶם לָ֑⁠ךְ וַ⁠יִּשְׁלַ֥ח יָד֖⁠וֹ וַ⁠יִּקָּחֵֽ⁠הוּ׃פ","wa⁠yò֖̇ʼmer há֣rem lá֑⁠kĕ wa⁠yi̇şĕ̌la֥ẖ yád֖⁠wò wa⁠yi̇qá̇ẖéֽ⁠hẇ׃p"],[6,8,"וּ⁠מֶ֣לֶךְ אֲרָ֔ם הָיָ֥ה נִלְחָ֖ם בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יִּוָּעַץ֙ אֶל־עֲבָדָ֣י⁠ו לֵ⁠אמֹ֗ר אֶל־מְק֛וֹם פְּלֹנִ֥י אַלְמֹנִ֖י תַּחֲנֹתִֽ⁠י׃","ẇ⁠me֣lekĕ ʼàrá֔m háyá֥h nilĕẖá֖m bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yi̇wá̇ʻaẕ֙ ʼel-ʻàbádá֣y⁠w lé⁠ʼmò֗r ʼel-mĕq֛wòm pĕ̇lòni֥y ʼalĕmòni֖y ţȧẖànòţiֽ⁠y׃"],[6,9,"וַ⁠יִּשְׁלַ֞ח אִ֣ישׁ הָ⁠אֱלֹהִ֗ים אֶל־מֶ֤לֶךְ יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר הִשָּׁ֕מֶר מֵ⁠עֲבֹ֖ר הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה כִּֽי־שָׁ֖ם אֲרָ֥ם נְחִתִּֽים׃","wa⁠yi̇şĕ̌la֞ẖ ʼi֣yş̌ há⁠ʼèlòhi֗ym ʼel-me֤lekĕ yişĕ̂ráʼél֙ lé⁠ʼmò֔r hişá̇̌֕mer mé⁠ʻàbò֖r ha⁠má̇q֣wòm ha⁠zė֑h kiֽ̇y-şá֖̌m ʼàrá֥m nĕẖiţiֽ̇ym׃"],[6,10,"וַ⁠יִּשְׁלַ֞ח מֶ֣לֶךְ יִשְׂרָאֵ֗ל אֶֽל־הַ⁠מָּק֞וֹם אֲשֶׁ֨ר אָֽמַר־ל֧⁠וֹ אִישׁ־הָ⁠אֱלֹהִ֛ים ו⁠הזהיר⁠ה וְ⁠נִשְׁמַ֣ר שָׁ֑ם לֹ֥א אַחַ֖ת וְ⁠לֹ֥א שְׁתָּֽיִם׃","wa⁠yi̇şĕ̌la֞ẖ me֣lekĕ yişĕ̂ráʼé֗l ʼeֽl-ha⁠má̇q֞wòm ʼàşě֨r ʼáֽmar-l֧⁠wò ʼiyş̌-há⁠ʼèlòhi֛ym w⁠hzhyr⁠h wĕ⁠nişĕ̌ma֣r şá֑̌m lò֥ʼ ʼaẖa֖ţ wĕ⁠lò֥ʼ şĕ̌ţáֽ̇yim׃"],[6,11,"וַ⁠יִּסָּעֵר֙ לֵ֣ב מֶֽלֶךְ־אֲרָ֔ם עַל־הַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה וַ⁠יִּקְרָ֤א אֶל־עֲבָדָי⁠ו֙ וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם הֲ⁠לוֹא֙ תַּגִּ֣ידוּ לִ֔⁠י מִ֥י מִ⁠שֶּׁ⁠לָּ֖⁠נוּ אֶל־מֶ֥לֶךְ יִשְׂרָאֵֽל׃","wa⁠yi̇sá̇ʻér֙ lé֣b meֽlekĕ-ʼàrá֔m ʻal-ha⁠dá̇bá֖r ha⁠zė֑h wa⁠yi̇qĕrá֤ʼ ʼel-ʻàbádáy⁠w֙ wa⁠yò֣̇ʼmer ʼàléy⁠he֔m hà⁠lwòʼ֙ ţȧgi֣̇ydẇ li֔⁠y mi֥y mi⁠şė̌⁠lá֖̇⁠nẇ ʼel-me֥lekĕ yişĕ̂ráʼéֽl׃"],[6,12,"וַ⁠יֹּ֨אמֶר֙ אַחַ֣ד מֵֽ⁠עֲבָדָ֔י⁠ו ל֖וֹא אֲדֹנִ֣⁠י הַ⁠מֶּ֑לֶךְ כִּֽי־אֱלִישָׁ֤ע הַ⁠נָּבִיא֙ אֲשֶׁ֣ר בְּ⁠יִשְׂרָאֵ֔ל יַגִּיד֙ לְ⁠מֶ֣לֶךְ יִשְׂרָאֵ֔ל אֶת־הַ֨⁠דְּבָרִ֔ים אֲשֶׁ֥ר תְּדַבֵּ֖ר בַּ⁠חֲדַ֥ר מִשְׁכָּבֶֽ⁠ךָ׃","wa⁠yò̇֨ʼmer֙ ʼaẖa֣d méֽ⁠ʻàbádá֔y⁠w l֖wòʼ ʼàdòni֣⁠y ha⁠mė֑lekĕ kiֽ̇y-ʼèliyşá֤̌ʻ ha⁠ná̇biyʼ֙ ʼàşě֣r bĕ̇⁠yişĕ̂ráʼé֔l yagi̇yd֙ lĕ⁠me֣lekĕ yişĕ̂ráʼé֔l ʼeţ-ha֨⁠dĕ̇bári֔ym ʼàşě֥r ţĕ̇dabé֖̇r bȧ⁠ẖàda֥r mişĕ̌ká̇beֽ⁠ká׃"],[6,13,"וַ⁠יֹּ֗אמֶר לְכ֤וּ וּ⁠רְאוּ֙ אֵיכֹ֣ה ה֔וּא וְ⁠אֶשְׁלַ֖ח וְ⁠אֶקָּחֵ֑⁠הוּ וַ⁠יֻּגַּד־ל֥⁠וֹ לֵ⁠אמֹ֖ר הִנֵּ֥ה בְ⁠דֹתָֽן׃","wa⁠yò̇֗ʼmer lĕk֤ẇ ẇ⁠rĕʼẇ֙ ʼéykò֣h h֔ẇʼ wĕ⁠ʼeşĕ̌la֖ẖ wĕ⁠ʼeqá̇ẖé֑⁠hẇ wa⁠yu̇gȧd-l֥⁠wò lé⁠ʼmò֖r hiné֥̇h bĕ⁠dòţáֽn׃"],[6,14,"וַ⁠יִּשְׁלַח־שָׁ֛מָּ⁠ה סוּסִ֥ים וְ⁠רֶ֖כֶב וְ⁠חַ֣יִל כָּבֵ֑ד וַ⁠יָּבֹ֣אוּ לַ֔יְלָה וַ⁠יַּקִּ֖פוּ עַל־הָ⁠עִֽיר׃","wa⁠yi̇şĕ̌laẖ-şá֛̌má̇⁠h sẇsi֥ym wĕ⁠re֖keb wĕ⁠ẖa֣yil ká̇bé֑d wa⁠yá̇bò֣ʼẇ la֔yĕláh wa⁠yȧqi֖̇pẇ ʻal-há⁠ʻiֽyr׃"],[6,15,"וַ֠⁠יַּשְׁכֵּם מְשָׁרֵ֨ת אִ֥ישׁ הָֽ⁠אֱלֹהִים֮ לָ⁠קוּם֒ וַ⁠יֵּצֵ֕א וְ⁠הִנֵּה־חַ֛יִל סוֹבֵ֥ב אֶת־הָ⁠עִ֖יר וְ⁠ס֣וּס וָ⁠רָ֑כֶב וַ⁠יֹּ֨אמֶר נַעֲר֥⁠וֹ אֵלָ֛י⁠ו אֲהָ֥הּ אֲדֹנִ֖⁠י אֵיכָ֥ה נַֽעֲשֶֽׂה׃","wa֠⁠yȧşĕ̌ké̇m mĕşá̌ré֨ţ ʼi֥yş̌ háֽ⁠ʼèlòhiym֮ lá⁠qẇm֒ wa⁠yé̇ẕé֕ʼ wĕ⁠hiné̇h-ẖa֛yil swòbé֥b ʼeţ-há⁠ʻi֖yr wĕ⁠s֣ẇs wá⁠rá֑keb wa⁠yò̇֨ʼmer naʻàr֥⁠wò ʼélá֛y⁠w ʼàhá֥ḣ ʼàdòni֖⁠y ʼéyká֥h nֽaʻàşêֽh׃"],[6,16,"וַ⁠יֹּ֖אמֶר אַל־תִּירָ֑א כִּ֤י רַבִּים֙ אֲשֶׁ֣ר אִתָּ֔⁠נוּ מֵ⁠אֲשֶׁ֖ר אוֹתָֽ⁠ם׃","wa⁠yò֖̇ʼmer ʼal-ţi̇yrá֑ʼ ki֤̇y rabi̇ym֙ ʼàşě֣r ʼiţá̇֔⁠nẇ mé⁠ʼàşě֖r ʼwòţáֽ⁠m׃"],[6,17,"וַ⁠יִּתְפַּלֵּ֤ל אֱלִישָׁע֙ וַ⁠יֹּאמַ֔ר יְהוָ֕ה פְּקַח־נָ֥א אֶת־עֵינָ֖י⁠ו וְ⁠יִרְאֶ֑ה וַ⁠יִּפְקַ֤ח יְהוָה֙ אֶת־עֵינֵ֣י הַ⁠נַּ֔עַר וַ⁠יַּ֗רְא וְ⁠הִנֵּ֨ה הָ⁠הָ֜ר מָלֵ֨א סוּסִ֥ים וְ⁠רֶ֛כֶב אֵ֖שׁ סְבִיבֹ֥ת אֱלִישָֽׁע׃","wa⁠yi̇ţĕpȧlé֤̇l ʼèliyşá̌ʻ֙ wa⁠yò̇ʼma֔r yĕhwá֕h pĕ̇qaẖ-ná֥ʼ ʼeţ-ʻéyná֖y⁠w wĕ⁠yirĕʼe֑h wa⁠yi̇pĕqa֤ẖ yĕhwáh֙ ʼeţ-ʻéyné֣y ha⁠nȧ֔ʻar wa⁠yȧ֗rĕʼ wĕ⁠hiné̇֨h há⁠há֜r málé֨ʼ sẇsi֥ym wĕ⁠re֛keb ʼé֖ş̌ sĕbiybò֥ţ ʼèliyşáֽ̌ʻ׃"],[6,18,"וַ⁠יֵּרְדוּ֮ אֵלָי⁠ו֒ וַ⁠יִּתְפַּלֵּ֨ל אֱלִישָׁ֤ע אֶל־יְהוָה֙ וַ⁠יֹּאמַ֔ר הַךְ־נָ֥א אֶת־הַ⁠גּוֹי־הַ⁠זֶּ֖ה בַּ⁠סַּנְוֵרִ֑ים וַ⁠יַּכֵּ֥⁠ם בַּ⁠סַּנְוֵרִ֖ים כִּ⁠דְבַ֥ר אֱלִישָֽׁע׃","wa⁠yé̇rĕdẇ֮ ʼéláy⁠w֒ wa⁠yi̇ţĕpȧlé̇֨l ʼèliyşá֤̌ʻ ʼel-yĕhwáh֙ wa⁠yò̇ʼma֔r hakĕ-ná֥ʼ ʼeţ-ha⁠ġwòy-ha⁠zė֖h bȧ⁠sȧnĕwéri֑ym wa⁠yȧké֥̇⁠m bȧ⁠sȧnĕwéri֖ym ki̇⁠dĕba֥r ʼèliyşáֽ̌ʻ׃"],[6,19,"וַ⁠יֹּ֨אמֶר אֲלֵ⁠הֶ֜ם אֱלִישָׁ֗ע לֹ֣א זֶ֣ה הַ⁠דֶּרֶךְ֮ וְ⁠לֹ֣א זֹ֣ה הָ⁠עִיר֒ לְכ֣וּ אַחֲרַ֔⁠י וְ⁠אוֹלִ֣יכָה אֶתְ⁠כֶ֔ם אֶל־הָ⁠אִ֖ישׁ אֲשֶׁ֣ר תְּבַקֵּשׁ֑וּ⁠ן וַ⁠יֹּ֥לֶךְ אוֹתָ֖⁠ם שֹׁמְרֽוֹנָ⁠ה׃","wa⁠yò̇֨ʼmer ʼàlé⁠he֜m ʼèliyşá̌֗ʻ lò֣ʼ ze֣h ha⁠dėrekĕ֮ wĕ⁠lò֣ʼ zò֣h há⁠ʻiyr֒ lĕk֣ẇ ʼaẖàra֔⁠y wĕ⁠ʼwòli֣ykáh ʼeţĕ⁠ke֔m ʼel-há⁠ʼi֖yş̌ ʼàşě֣r ţĕ̇baqé̇ş֑̌ẇ⁠n wa⁠yò֥̇lekĕ ʼwòţá֖⁠m şò̌mĕrֽwòná⁠h׃"],[6,20,"וַ⁠יְהִי֮ כְּ⁠בֹאָ֣⁠ם שֹׁמְרוֹן֒ וַ⁠יֹּ֣אמֶר אֱלִישָׁ֔ע יְהוָ֕ה פְּקַ֥ח אֶת־עֵינֵֽי־אֵ֖לֶּה וְ⁠יִרְא֑וּ וַ⁠יִּפְקַ֤ח יְהוָה֙ אֶת־עֵ֣ינֵי⁠הֶ֔ם וַ⁠יִּרְא֕וּ וְ⁠הִנֵּ֖ה בְּ⁠ת֥וֹךְ שֹׁמְרֽוֹן׃","wa⁠yĕhiy֮ kĕ̇⁠bòʼá֣⁠m şò̌mĕrwòn֒ wa⁠yò֣̇ʼmer ʼèliyşá̌֔ʻ yĕhwá֕h pĕ̇qa֥ẖ ʼeţ-ʻéynéֽy-ʼé֖lėh wĕ⁠yirĕʼ֑ẇ wa⁠yi̇pĕqa֤ẖ yĕhwáh֙ ʼeţ-ʻé֣ynéy⁠he֔m wa⁠yi̇rĕʼ֕ẇ wĕ⁠hiné֖̇h bĕ̇⁠ţ֥wòkĕ şò̌mĕrֽwòn׃"],[6,21,"וַ⁠יֹּ֤אמֶר מֶֽלֶךְ־יִשְׂרָאֵל֙ אֶל־אֱלִישָׁ֔ע כִּ⁠רְאֹת֖⁠וֹ אוֹתָ֑⁠ם הַ⁠אַכֶּ֥ה אַכֶּ֖ה אָבִֽ⁠י׃","wa⁠yò֤̇ʼmer meֽlekĕ-yişĕ̂ráʼél֙ ʼel-ʼèliyşá̌֔ʻ ki̇⁠rĕʼòţ֖⁠wò ʼwòţá֑⁠m ha⁠ʼakė֥h ʼakė֖h ʼábiֽ⁠y׃"],[6,22,"וַ⁠יֹּ֨אמֶר֙ לֹ֣א תַכֶּ֔ה הַ⁠אֲשֶׁ֥ר שָׁבִ֛יתָ בְּ⁠חַרְבְּ⁠ךָ֥ וּֽ⁠בְ⁠קַשְׁתְּ⁠ךָ֖ אַתָּ֣ה מַכֶּ֑ה שִׂים֩ לֶ֨חֶם וָ⁠מַ֜יִם לִ⁠פְנֵי⁠הֶ֗ם וְ⁠יֹֽאכְלוּ֙ וְ⁠יִשְׁתּ֔וּ וְ⁠יֵלְכ֖וּ אֶל־אֲדֹנֵי⁠הֶֽם׃","wa⁠yò̇֨ʼmer֙ lò֣ʼ ţakė֔h ha⁠ʼàşě֥r şá̌bi֛yţá bĕ̇⁠ẖarĕbĕ̇⁠ká֥ ẇֽ⁠bĕ⁠qaşĕ̌ţĕ̇⁠ká֖ ʼaţá֣̇h makė֑h şîym֩ le֨ẖem wá⁠ma֜yim li⁠pĕnéy⁠he֗m wĕ⁠yòֽʼkĕlẇ֙ wĕ⁠yişĕ̌ţ̇֔ẇ wĕ⁠yélĕk֖ẇ ʼel-ʼàdònéy⁠heֽm׃"],[6,23,"וַ⁠יִּכְרֶ֨ה לָ⁠הֶ֜ם כֵּרָ֣ה גְדוֹלָ֗ה וַ⁠יֹּֽאכְלוּ֙ וַ⁠יִּשְׁתּ֔וּ וַֽ⁠יְשַׁלְּחֵ֔⁠ם וַ⁠יֵּלְכ֖וּ אֶל־אֲדֹֽנֵי⁠הֶ֑ם וְ⁠לֹֽא־יָ֤סְפוּ עוֹד֙ גְּדוּדֵ֣י אֲרָ֔ם לָ⁠ב֖וֹא בְּ⁠אֶ֥רֶץ יִשְׂרָאֵֽל׃פ","wa⁠yi̇kĕre֨h lá⁠he֜m ké̇rá֣h gĕdwòlá֗h wa⁠yòֽ̇ʼkĕlẇ֙ wa⁠yi̇şĕ̌ţ̇֔ẇ waֽ⁠yĕşǎlĕ̇ẖé֔⁠m wa⁠yé̇lĕk֖ẇ ʼel-ʼàdòֽnéy⁠he֑m wĕ⁠lòֽʼ-yá֤sĕpẇ ʻwòd֙ gĕ̇dẇdé֣y ʼàrá֔m lá⁠b֖wòʼ bĕ̇⁠ʼe֥reẕ yişĕ̂ráʼéֽl׃p"],[6,24,"וַֽ⁠יְהִי֙ אַחֲרֵי־כֵ֔ן וַ⁠יִּקְבֹּ֛ץ בֶּן־הֲדַ֥ד מֶֽלֶךְ־אֲרָ֖ם אֶת־כָּל־מַחֲנֵ֑⁠הוּ וַ⁠יַּ֕עַל וַ⁠יָּ֖צַר עַל־שֹׁמְרֽוֹן׃","waֽ⁠yĕhiy֙ ʼaẖàréy-ké֔n wa⁠yi̇qĕbò֛̇ẕ bėn-hàda֥d meֽlekĕ-ʼàrá֖m ʼeţ-ká̇l-maẖàné֑⁠hẇ wa⁠yȧ֕ʻal wa⁠yá֖̇ẕar ʻal-şò̌mĕrֽwòn׃"],[6,25,"וַ⁠יְהִ֨י רָעָ֤ב גָּדוֹל֙ בְּ⁠שֹׁ֣מְר֔וֹן וְ⁠הִנֵּ֖ה צָרִ֣ים עָלֶ֑י⁠הָ עַ֣ד הֱי֤וֹת רֹאשׁ־חֲמוֹר֙ בִּ⁠שְׁמֹנִ֣ים כֶּ֔סֶף וְ⁠רֹ֛בַע הַ⁠קַּ֥ב חרי יונים בַּ⁠חֲמִשָּׁה־כָֽסֶף׃","wa⁠yĕhi֨y ráʻá֤b gá̇dwòl֙ bĕ̇⁠şò֣̌mĕr֔wòn wĕ⁠hiné֖̇h ẕári֣ym ʻále֑y⁠há ʻa֣d hèy֤wòţ ròʼş̌-ẖàmwòr֙ bi̇⁠şĕ̌mòni֣ym kė֔sep wĕ⁠rò֛baʻ ha⁠qȧ֥b ẖry ywnym bȧ⁠ẖàmişá̇̌h-káֽsep׃"],[6,26,"וַֽ⁠יְהִי֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל עֹבֵ֖ר עַל־הַ⁠חֹמָ֑ה וְ⁠אִשָּׁ֗ה צָעֲקָ֤ה אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר הוֹשִׁ֖יעָ⁠ה אֲדֹנִ֥⁠י הַ⁠מֶּֽלֶךְ׃","waֽ⁠yĕhiy֙ me֣lekĕ yişĕ̂ráʼé֔l ʻòbé֖r ʻal-ha⁠ẖòmá֑h wĕ⁠ʼişá̇̌֗h ẕáʻàqá֤h ʼéláy⁠w֙ lé⁠ʼmò֔r hwòşǐ֖yʻá⁠h ʼàdòni֥⁠y ha⁠mėֽlekĕ׃"],[6,27,"וַ⁠יֹּ֨אמֶר֙ אַל־יוֹשִׁעֵ֣⁠ךְ יְהוָ֔ה מֵ⁠אַ֖יִן אֽוֹשִׁיעֵ֑⁠ךְ הֲ⁠מִן־הַ⁠גֹּ֖רֶן א֥וֹ מִן־הַ⁠יָּֽקֶב׃","wa⁠yò̇֨ʼmer֙ ʼal-ywòşǐʻé֣⁠kĕ yĕhwá֔h mé⁠ʼa֖yin ʼֽwòşǐyʻé֑⁠kĕ hà⁠min-ha⁠gò֖̇ren ʼ֥wò min-ha⁠yáֽ̇qeb׃"],[6,28,"וַ⁠יֹּֽאמֶר־לָ֥⁠הּ הַ⁠מֶּ֖לֶךְ מַה־לָּ֑⁠ךְ וַ⁠תֹּ֗אמֶר הָ⁠אִשָּׁ֨ה הַ⁠זֹּ֜את אָמְרָ֣ה אֵלַ֗⁠י תְּנִ֤י אֶת־בְּנֵ⁠ךְ֙ וְ⁠נֹאכְלֶ֣⁠נּוּ הַ⁠יּ֔וֹם וְ⁠אֶת־בְּנִ֖⁠י נֹאכַ֥ל מָחָֽר׃","wa⁠yòֽ̇ʼmer-lá֥⁠ḣ ha⁠mė֖lekĕ mah-lá֑̇⁠kĕ wa⁠ţò̇֗ʼmer há⁠ʼişá̇̌֨h ha⁠zò̇֜ʼţ ʼámĕrá֣h ʼéla֗⁠y ţĕ̇ni֤y ʼeţ-bĕ̇né⁠kĕ֙ wĕ⁠nòʼkĕle֣⁠ṅẇ ha⁠ẏ֔wòm wĕ⁠ʼeţ-bĕ̇ni֖⁠y nòʼka֥l máẖáֽr׃"],[6,29,"וַ⁠נְּבַשֵּׁ֥ל אֶת־בְּנִ֖⁠י וַ⁠נֹּֽאכְלֵ֑⁠הוּ וָ⁠אֹמַ֨ר אֵלֶ֜י⁠הָ בַּ⁠יּ֣וֹם הָ⁠אַחֵ֗ר תְּנִ֤י אֶת־בְּנֵ⁠ךְ֙ וְ⁠נֹ֣אכְלֶ֔⁠נּוּ וַ⁠תַּחְבִּ֖א אֶת־בְּנָֽ⁠הּ׃","wa⁠nĕ̇başé֥̇̌l ʼeţ-bĕ̇ni֖⁠y wa⁠nòֽ̇ʼkĕlé֑⁠hẇ wá⁠ʼòma֨r ʼéle֜y⁠há bȧ⁠ẏ֣wòm há⁠ʼaẖé֗r ţĕ̇ni֤y ʼeţ-bĕ̇né⁠kĕ֙ wĕ⁠nò֣ʼkĕle֔⁠ṅẇ wa⁠ţȧẖĕbi֖̇ʼ ʼeţ-bĕ̇náֽ⁠ḣ׃"],[6,30,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ הַ⁠מֶּ֜לֶךְ אֶת־דִּבְרֵ֤י הָֽ⁠אִשָּׁה֙ וַ⁠יִּקְרַ֣ע אֶת־בְּגָדָ֔י⁠ו וְ⁠ה֖וּא עֹבֵ֣ר עַל־הַ⁠חֹמָ֑ה וַ⁠יַּ֣רְא הָ⁠עָ֔ם וְ⁠הִנֵּ֥ה הַ⁠שַּׂ֛ק עַל־בְּשָׂר֖⁠וֹ מִ⁠בָּֽיִת׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa ha⁠mė֜lekĕ ʼeţ-di̇bĕré֤y háֽ⁠ʼişá̇̌h֙ wa⁠yi̇qĕra֣ʻ ʼeţ-bĕ̇gádá֔y⁠w wĕ⁠h֖ẇʼ ʻòbé֣r ʻal-ha⁠ẖòmá֑h wa⁠yȧ֣rĕʼ há⁠ʻá֔m wĕ⁠hiné֥̇h ha⁠şȧ֛̂q ʻal-bĕ̇şá̂r֖⁠wò mi⁠báֽ̇yiţ׃"],[6,31,"וַ⁠יֹּ֕אמֶר כֹּֽה־יַעֲשֶׂה־לִּ֥⁠י אֱלֹהִ֖ים וְ⁠כֹ֣ה יוֹסִ֑ף אִֽם־יַעֲמֹ֞ד רֹ֣אשׁ אֱלִישָׁ֧ע בֶּן־שָׁפָ֛ט עָלָ֖י⁠ו הַ⁠יּֽוֹם׃","wa⁠yò̇֕ʼmer kòֽ̇h-yaʻàşêh-li֥̇⁠y ʼèlòhi֖ym wĕ⁠kò֣h ywòsi֑p ʼiֽm-yaʻàmò֞d rò֣ʼş̌ ʼèliyşá֧̌ʻ bėn-şá̌pá֛t ʻálá֖y⁠w ha⁠ẏֽwòm׃"],[6,32,"וֶ⁠אֱלִישָׁע֙ יֹשֵׁ֣ב בְּ⁠בֵית֔⁠וֹ וְ⁠הַ⁠זְּקֵנִ֖ים יֹשְׁבִ֣ים אִתּ֑⁠וֹ וַ⁠יִּשְׁלַ֨ח אִ֜ישׁ מִ⁠לְּ⁠פָנָ֗י⁠ו בְּ⁠טֶ֣רֶם יָבֹא֩ הַ⁠מַּלְאָ֨ךְ אֵלָ֜י⁠ו וְ⁠ה֣וּא ׀ אָמַ֣ר אֶל־הַ⁠זְּקֵנִ֗ים הַ⁠רְּאִיתֶם֙ כִּֽי־שָׁלַ֞ח בֶּן־הַֽ⁠מְרַצֵּ֤חַ הַ⁠זֶּה֙ לְ⁠הָסִ֣יר אֶת־רֹאשִׁ֔⁠י רְא֣וּ ׀ כְּ⁠בֹ֣א הַ⁠מַּלְאָ֗ךְ סִגְר֤וּ הַ⁠דֶּ֨לֶת֙ וּ⁠לְחַצְתֶּ֤ם אֹת⁠וֹ֙ בַּ⁠דֶּ֔לֶת הֲ⁠ל֗וֹא ק֛וֹל רַגְלֵ֥י אֲדֹנָ֖י⁠ו אַחֲרָֽי⁠ו׃","we⁠ʼèliyşá̌ʻ֙ yòşé֣̌b bĕ̇⁠béyţ֔⁠wò wĕ⁠ha⁠zĕ̇qéni֖ym yòşĕ̌bi֣ym ʼiţ֑̇⁠wò wa⁠yi̇şĕ̌la֨ẖ ʼi֜yş̌ mi⁠lĕ̇⁠páná֗y⁠w bĕ̇⁠te֣rem yábòʼ֩ ha⁠mȧlĕʼá֨kĕ ʼélá֜y⁠w wĕ⁠h֣ẇʼ ׀ ʼáma֣r ʼel-ha⁠zĕ̇qéni֗ym ha⁠rĕ̇ʼiyţem֙ kiֽ̇y-şá̌la֞ẖ bėn-haֽ⁠mĕraẕé֤̇ẖa ha⁠zėh֙ lĕ⁠hási֣yr ʼeţ-ròʼşǐ֔⁠y rĕʼ֣ẇ ׀ kĕ̇⁠bò֣ʼ ha⁠mȧlĕʼá֗kĕ sigĕr֤ẇ ha⁠dė֨leţ֙ ẇ⁠lĕẖaẕĕţė֤m ʼòţ⁠wò֙ bȧ⁠dė֔leţ hà⁠l֗wòʼ q֛wòl ragĕlé֥y ʼàdòná֖y⁠w ʼaẖàráֽy⁠w׃"],[6,33,"עוֹדֶ֨⁠נּוּ֙ מְדַבֵּ֣ר עִמָּ֔⁠ם וְ⁠הִנֵּ֥ה הַ⁠מַּלְאָ֖ךְ יֹרֵ֣ד אֵלָ֑י⁠ו וַ⁠יֹּ֗אמֶר הִנֵּֽה־זֹ֤את הָֽ⁠רָעָה֙ מֵ⁠אֵ֣ת יְהוָ֔ה מָֽה־אוֹחִ֥יל לַ⁠יהוָ֖ה עֽוֹד׃ס","ʻwòde֨⁠ṅẇ֙ mĕdabé֣̇r ʻimá̇֔⁠m wĕ⁠hiné֥̇h ha⁠mȧlĕʼá֖kĕ yòré֣d ʼélá֑y⁠w wa⁠yò̇֗ʼmer hinéֽ̇h-zò֤ʼţ háֽ⁠ráʻáh֙ mé⁠ʼé֣ţ yĕhwá֔h máֽh-ʼwòẖi֥yl la⁠yhwá֖h ʻֽwòd׃s"],[7,1,"וַ⁠יֹּ֣אמֶר אֱלִישָׁ֔ע שִׁמְע֖וּ דְּבַר־יְהוָ֑ה כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה כָּ⁠עֵ֤ת ׀ מָחָר֙ סְאָֽה־סֹ֣לֶת בְּ⁠שֶׁ֗קֶל וְ⁠סָאתַ֧יִם שְׂעֹרִ֛ים בְּ⁠שֶׁ֖קֶל בְּ⁠שַׁ֥עַר שֹׁמְרֽוֹן׃","wa⁠yò֣̇ʼmer ʼèliyşá̌֔ʻ şǐmĕʻ֖ẇ dĕ̇bar-yĕhwá֑h kò֣̇h ׀ ʼáma֣r yĕhwá֗h ká̇⁠ʻé֤ţ ׀ máẖár֙ sĕʼáֽh-sò֣leţ bĕ̇⁠şě֗qel wĕ⁠sáʼţa֧yim şĕ̂ʻòri֛ym bĕ̇⁠şě֖qel bĕ̇⁠şǎ֥ʻar şò̌mĕrֽwòn׃"],[7,2,"וַ⁠יַּ֣עַן הַ⁠שָּׁלִ֡ישׁ אֲשֶׁר־לַ⁠מֶּלֶךְ֩ נִשְׁעָ֨ן עַל־יָד֜⁠וֹ אֶת־אִ֣ישׁ הָ⁠אֱלֹהִים֮ וַ⁠יֹּאמַר֒ הִנֵּ֣ה יְהוָ֗ה עֹשֶׂ֤ה אֲרֻבּוֹת֙ בַּ⁠שָּׁמַ֔יִם הֲ⁠יִהְיֶ֖ה הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַ⁠יֹּ֗אמֶר הִנְּ⁠כָ֤ה רֹאֶה֙ בְּ⁠עֵינֶ֔י⁠ךָ וּ⁠מִ⁠שָּׁ֖ם לֹ֥א תֹאכֵֽל׃ס","wa⁠yȧ֣ʻan ha⁠şá̇̌li֡yş̌ ʼàşěr-la⁠mėlekĕ֩ nişĕ̌ʻá֨n ʻal-yád֜⁠wò ʼeţ-ʼi֣yş̌ há⁠ʼèlòhiym֮ wa⁠yò̇ʼmar֒ hiné֣̇h yĕhwá֗h ʻòşê֤h ʼàruḃwòţ֙ bȧ⁠şá̇̌ma֔yim hà⁠yihĕye֖h ha⁠dá̇bá֣r ha⁠zė֑h wa⁠yò̇֗ʼmer hinĕ̇⁠ká֤h ròʼeh֙ bĕ̇⁠ʻéyne֔y⁠ká ẇ⁠mi⁠şá֖̇̌m lò֥ʼ ţòʼkéֽl׃s"],[7,3,"וְ⁠אַרְבָּעָ֧ה אֲנָשִׁ֛ים הָי֥וּ מְצֹרָעִ֖ים פֶּ֣תַח הַ⁠שָּׁ֑עַר וַ⁠יֹּֽאמְרוּ֙ אִ֣ישׁ אֶל־רֵעֵ֔⁠הוּ מָ֗ה אֲנַ֛חְנוּ יֹשְׁבִ֥ים פֹּ֖ה עַד־מָֽתְנוּ׃","wĕ⁠ʼarĕbá̇ʻá֧h ʼànáşǐ֛ym háy֥ẇ mĕẕòráʻi֖ym pė֣ţaẖ ha⁠şá֑̇̌ʻar wa⁠yòֽ̇ʼmĕrẇ֙ ʼi֣yş̌ ʼel-réʻé֔⁠hẇ má֗h ʼàna֛ẖĕnẇ yòşĕ̌bi֥ym pò֖̇h ʻad-máֽţĕnẇ׃"],[7,4,"אִם־אָמַרְנוּ֩ נָב֨וֹא הָ⁠עִ֜יר וְ⁠הָ⁠רָעָ֤ב בָּ⁠עִיר֙ וָ⁠מַ֣תְנוּ שָׁ֔ם וְ⁠אִם־יָשַׁ֥בְנוּ פֹ֖ה וָ⁠מָ֑תְנוּ וְ⁠עַתָּ֗ה לְכוּ֙ וְ⁠נִפְּלָה֙ אֶל־מַחֲנֵ֣ה אֲרָ֔ם אִם־יְחַיֻּ֣⁠נוּ נִֽחְיֶ֔ה וְ⁠אִם־יְמִיתֻ֖⁠נוּ וָ⁠מָֽתְנוּ׃","ʼim-ʼámarĕnẇ֩ náb֨wòʼ há⁠ʻi֜yr wĕ⁠há⁠ráʻá֤b bá̇⁠ʻiyr֙ wá⁠ma֣ţĕnẇ şá̌֔m wĕ⁠ʼim-yáşǎ֥bĕnẇ pò֖h wá⁠má֑ţĕnẇ wĕ⁠ʻaţá̇֗h lĕkẇ֙ wĕ⁠nipĕ̇láh֙ ʼel-maẖàné֣h ʼàrá֔m ʼim-yĕẖayu֣̇⁠nẇ niֽẖĕye֔h wĕ⁠ʼim-yĕmiyţu֖⁠nẇ wá⁠máֽţĕnẇ׃"],[7,5,"וַ⁠יָּק֣וּמוּ בַ⁠נֶּ֔שֶׁף לָ⁠ב֖וֹא אֶל־מַחֲנֵ֣ה אֲרָ֑ם וַ⁠יָּבֹ֗אוּ עַד־קְצֵה֙ מַחֲנֵ֣ה אֲרָ֔ם וְ⁠הִנֵּ֥ה אֵֽין־שָׁ֖ם אִֽישׁ׃","wa⁠yá̇q֣ẇmẇ ba⁠nė֔şěp lá⁠b֖wòʼ ʼel-maẖàné֣h ʼàrá֑m wa⁠yá̇bò֗ʼẇ ʻad-qĕẕéh֙ maẖàné֣h ʼàrá֔m wĕ⁠hiné֥̇h ʼéֽyn-şá֖̌m ʼiֽyş̌׃"],[7,6,"וַ⁠אדֹנָ֞⁠י הִשְׁמִ֣יעַ ׀ אֶת־מַחֲנֵ֣ה אֲרָ֗ם ק֥וֹל רֶ֨כֶב֙ ק֣וֹל ס֔וּס ק֖וֹל חַ֣יִל גָּד֑וֹל וַ⁠יֹּאמְר֞וּ אִ֣ישׁ אֶל־אָחִ֗י⁠ו הִנֵּ֣ה שָֽׂכַר־עָלֵי⁠נוּ֩ מֶ֨לֶךְ יִשְׂרָאֵ֜ל אֶת־מַלְכֵ֧י הַ⁠חִתִּ֛ים וְ⁠אֶת־מַלְכֵ֥י מִצְרַ֖יִם לָ⁠ב֥וֹא עָלֵֽי⁠נוּ׃","wa⁠ʼdòná֞⁠y hişĕ̌mi֣yʻa ׀ ʼeţ-maẖàné֣h ʼàrá֗m q֥wòl re֨keb֙ q֣wòl s֔ẇs q֖wòl ẖa֣yil gá̇d֑wòl wa⁠yò̇ʼmĕr֞ẇ ʼi֣yş̌ ʼel-ʼáẖi֗y⁠w hiné֣̇h şáֽ̂kar-ʻáléy⁠nẇ֩ me֨lekĕ yişĕ̂ráʼé֜l ʼeţ-malĕké֧y ha⁠ẖiţi֛̇ym wĕ⁠ʼeţ-malĕké֥y miẕĕra֖yim lá⁠b֥wòʼ ʻáléֽy⁠nẇ׃"],[7,7,"וַ⁠יָּקוּמוּ֮ וַ⁠יָּנ֣וּסוּ בַ⁠נֶּשֶׁף֒ וַ⁠יַּעַזְב֣וּ אֶת־אָהֳלֵי⁠הֶ֗ם וְ⁠אֶת־סֽוּסֵי⁠הֶם֙ וְ⁠אֶת־חֲמֹ֣רֵי⁠הֶ֔ם הַֽ⁠מַּחֲנֶ֖ה כַּ⁠אֲשֶׁר־הִ֑יא וַ⁠יָּנֻ֖סוּ אֶל־נַפְשָֽׁ⁠ם׃","wa⁠yá̇qẇmẇ֮ wa⁠yá̇n֣ẇsẇ ba⁠nėşěp֒ wa⁠yȧʻazĕb֣ẇ ʼeţ-ʼáholéy⁠he֗m wĕ⁠ʼeţ-sֽẇséy⁠hem֙ wĕ⁠ʼeţ-ẖàmò֣réy⁠he֔m haֽ⁠mȧẖàne֖h kȧ⁠ʼàşěr-hi֑yʼ wa⁠yá̇nu֖sẇ ʼel-napĕşáֽ̌⁠m׃"],[7,8,"וַ⁠יָּבֹאוּ֩ הַֽ⁠מְצֹרָעִ֨ים הָ⁠אֵ֜לֶּה עַד־קְצֵ֣ה הַֽ⁠מַּחֲנֶ֗ה וַ⁠יָּבֹ֜אוּ אֶל־אֹ֤הֶל אֶחָד֙ וַ⁠יֹּאכְל֣וּ וַ⁠יִּשְׁתּ֔וּ וַ⁠יִּשְׂא֣וּ מִ⁠שָּׁ֗ם כֶּ֤סֶף וְ⁠זָהָב֙ וּ⁠בְגָדִ֔ים וַ⁠יֵּלְכ֖וּ וַ⁠יַּטְמִ֑נוּ וַ⁠יָּשֻׁ֗בוּ וַ⁠יָּבֹ֨אוּ֙ אֶל־אֹ֣הֶל אַחֵ֔ר וַ⁠יִּשְׂא֣וּ מִ⁠שָּׁ֔ם וַ⁠יֵּלְכ֖וּ וַ⁠יַּטְמִֽנוּ׃","wa⁠yá̇bòʼẇ֩ haֽ⁠mĕẕòráʻi֨ym há⁠ʼé֜lėh ʻad-qĕẕé֣h haֽ⁠mȧẖàne֗h wa⁠yá̇bò֜ʼẇ ʼel-ʼò֤hel ʼeẖád֙ wa⁠yò̇ʼkĕl֣ẇ wa⁠yi̇şĕ̌ţ̇֔ẇ wa⁠yi̇şĕ̂ʼ֣ẇ mi⁠şá̇̌֗m kė֤sep wĕ⁠záháb֙ ẇ⁠bĕgádi֔ym wa⁠yé̇lĕk֖ẇ wa⁠yȧtĕmi֑nẇ wa⁠yá̇şǔ֗bẇ wa⁠yá̇bò֨ʼẇ֙ ʼel-ʼò֣hel ʼaẖé֔r wa⁠yi̇şĕ̂ʼ֣ẇ mi⁠şá̇̌֔m wa⁠yé̇lĕk֖ẇ wa⁠yȧtĕmiֽnẇ׃"],[7,9,"וַ⁠יֹּאמְרוּ֩ אִ֨ישׁ אֶל־רֵעֵ֜⁠הוּ לֹֽא־כֵ֣ן ׀ אֲנַ֣חְנוּ עֹשִׂ֗ים הַ⁠יּ֤וֹם הַ⁠זֶּה֙ יוֹם־בְּשֹׂרָ֣ה ה֔וּא וַ⁠אֲנַ֣חְנוּ מַחְשִׁ֗ים וְ⁠חִכִּ֛ינוּ עַד־א֥וֹר הַ⁠בֹּ֖קֶר וּ⁠מְצָאָ֣⁠נוּ עָו֑וֹן וְ⁠עַתָּה֙ לְכ֣וּ וְ⁠נָבֹ֔אָה וְ⁠נַגִּ֖ידָה בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇ʼmĕrẇ֩ ʼi֨yş̌ ʼel-réʻé֜⁠hẇ lòֽʼ-ké֣n ׀ ʼàna֣ẖĕnẇ ʻòşî֗ym ha⁠ẏ֤wòm ha⁠zėh֙ ywòm-bĕ̇şò̂rá֣h h֔ẇʼ wa⁠ʼàna֣ẖĕnẇ maẖĕşǐ֗ym wĕ⁠ẖiki֛̇ynẇ ʻad-ʼ֥wòr ha⁠bò֖̇qer ẇ⁠mĕẕáʼá֣⁠nẇ ʻáw֑wòn wĕ⁠ʻaţá̇h֙ lĕk֣ẇ wĕ⁠nábò֔ʼáh wĕ⁠nagi֖̇ydáh bé֥̇yţ ha⁠mėֽlekĕ׃"],[7,10,"וַ⁠יָּבֹ֗אוּ וַֽ⁠יִּקְרְאוּ֮ אֶל־שֹׁעֵ֣ר הָ⁠עִיר֒ וַ⁠יַּגִּ֤ידוּ לָ⁠הֶם֙ לֵ⁠אמֹ֔ר בָּ֚אנוּ אֶל־מַחֲנֵ֣ה אֲרָ֔ם וְ⁠הִנֵּ֥ה אֵֽין־שָׁ֛ם אִ֖ישׁ וְ⁠ק֣וֹל אָדָ֑ם כִּ֣י אִם־הַ⁠סּ֤וּס אָסוּר֙ וְ⁠הַ⁠חֲמ֣וֹר אָס֔וּר וְ⁠אֹהָלִ֖ים כַּ⁠אֲשֶׁר־הֵֽמָּה׃","wa⁠yá̇bò֗ʼẇ waֽ⁠yi̇qĕrĕʼẇ֮ ʼel-şò̌ʻé֣r há⁠ʻiyr֒ wa⁠yȧgi֤̇ydẇ lá⁠hem֙ lé⁠ʼmò֔r bá֚̇ʼnẇ ʼel-maẖàné֣h ʼàrá֔m wĕ⁠hiné֥̇h ʼéֽyn-şá֛̌m ʼi֖yş̌ wĕ⁠q֣wòl ʼádá֑m ki֣̇y ʼim-ha⁠ṡ֤ẇs ʼásẇr֙ wĕ⁠ha⁠ẖàm֣wòr ʼás֔ẇr wĕ⁠ʼòháli֖ym kȧ⁠ʼàşěr-héֽmá̇h׃"],[7,11,"וַ⁠יִּקְרָ֖א הַ⁠שֹּֽׁעֲרִ֑ים וַ⁠יַּגִּ֕ידוּ בֵּ֥ית הַ⁠מֶּ֖לֶךְ פְּנִֽימָה׃","wa⁠yi̇qĕrá֖ʼ ha⁠şòֽ̇̌ʻàri֑ym wa⁠yȧgi̇֕ydẇ bé֥̇yţ ha⁠mė֖lekĕ pĕ̇niֽymáh׃"],[7,12,"וַ⁠יָּ֨קָם הַ⁠מֶּ֜לֶךְ לַ֗יְלָה וַ⁠יֹּ֨אמֶר֙ אֶל־עֲבָדָ֔י⁠ו אַגִּֽידָה־נָּ֣א לָ⁠כֶ֔ם אֵ֛ת אֲשֶׁר־עָ֥שׂוּ לָ֖⁠נוּ אֲרָ֑ם יָדְע֞וּ כִּי־רְעֵבִ֣ים אֲנַ֗חְנוּ וַ⁠יֵּצְא֤וּ מִן־הַֽ⁠מַּחֲנֶה֙ לְ⁠הֵחָבֵ֤ה ב⁠ה⁠שדה לֵ⁠אמֹ֔ר כִּֽי־יֵצְא֤וּ מִן־הָ⁠עִיר֙ וְ⁠נִתְפְּשֵׂ֣⁠ם חַיִּ֔ים וְ⁠אֶל־הָ⁠עִ֖יר נָבֹֽא׃","wa⁠yá̇֨qám ha⁠mė֜lekĕ la֗yĕláh wa⁠yò̇֨ʼmer֙ ʼel-ʻàbádá֔y⁠w ʼagiֽ̇ydáh-ná֣̇ʼ lá⁠ke֔m ʼé֛ţ ʼàşěr-ʻá֥ş̂ẇ lá֖⁠nẇ ʼàrá֑m yádĕʻ֞ẇ ki̇y-rĕʻébi֣ym ʼàna֗ẖĕnẇ wa⁠yé̇ẕĕʼ֤ẇ min-haֽ⁠mȧẖàneh֙ lĕ⁠héẖábé֤h b⁠h⁠şdh lé⁠ʼmò֔r kiֽ̇y-yéẕĕʼ֤ẇ min-há⁠ʻiyr֙ wĕ⁠niţĕpĕ̇şé֣̂⁠m ẖayi̇֔ym wĕ⁠ʼel-há⁠ʻi֖yr nábòֽʼ׃"],[7,13,"וַ⁠יַּעַן֩ אֶחָ֨ד מֵ⁠עֲבָדָ֜י⁠ו וַ⁠יֹּ֗אמֶר וְ⁠יִקְחוּ־נָ֞א חֲמִשָּׁ֣ה מִן־הַ⁠סּוּסִים֮ הַֽ⁠נִּשְׁאָרִים֮ אֲשֶׁ֣ר נִשְׁאֲרוּ־בָ⁠הּ֒ הִנָּ֗⁠ם כְּ⁠כָל־ה⁠המון יִשְׂרָאֵל֙ אֲשֶׁ֣ר נִשְׁאֲרוּ־בָ֔⁠הּ הִנָּ֕⁠ם כְּ⁠כָל־הֲמ֥וֹן יִשְׂרָאֵ֖ל אֲשֶׁר־תָּ֑מּוּ וְ⁠נִשְׁלְחָ֖ה וְ⁠נִרְאֶֽה׃","wa⁠yȧʻan֩ ʼeẖá֨d mé⁠ʻàbádá֜y⁠w wa⁠yò̇֗ʼmer wĕ⁠yiqĕẖẇ-ná֞ʼ ẖàmişá֣̇̌h min-ha⁠ṡẇsiym֮ haֽ⁠ni̇şĕ̌ʼáriym֮ ʼàşě֣r nişĕ̌ʼàrẇ-bá⁠ḣ֒ hiná̇֗⁠m kĕ̇⁠kál-h⁠hmwn yişĕ̂ráʼél֙ ʼàşě֣r nişĕ̌ʼàrẇ-bá֔⁠ḣ hiná̇֕⁠m kĕ̇⁠kál-hàm֥wòn yişĕ̂ráʼé֖l ʼàşěr-ţá֑̇ṁẇ wĕ⁠nişĕ̌lĕẖá֖h wĕ⁠nirĕʼeֽh׃"],[7,14,"וַ⁠יִּקְח֕וּ שְׁנֵ֖י רֶ֣כֶב סוּסִ֑ים וַ⁠יִּשְׁלַ֨ח הַ⁠מֶּ֜לֶךְ אַחֲרֵ֧י מַחֲנֵֽה־אֲרָ֛ם לֵ⁠אמֹ֖ר לְכ֥וּ וּ⁠רְאֽוּ׃","wa⁠yi̇qĕẖ֕ẇ şĕ̌né֖y re֣keb sẇsi֑ym wa⁠yi̇şĕ̌la֨ẖ ha⁠mė֜lekĕ ʼaẖàré֧y maẖànéֽh-ʼàrá֛m lé⁠ʼmò֖r lĕk֥ẇ ẇ⁠rĕʼֽẇ׃"],[7,15,"וַ⁠יֵּלְכ֣וּ אַחֲרֵי⁠הֶם֮ עַד־הַ⁠יַּרְדֵּן֒ וְ⁠הִנֵּ֣ה כָל־הַ⁠דֶּ֗רֶךְ מְלֵאָ֤ה בְגָדִים֙ וְ⁠כֵלִ֔ים אֲשֶׁר־הִשְׁלִ֥יכוּ אֲרָ֖ם בהחפזם וַ⁠יָּשֻׁ֨בוּ֙ הַ⁠מַּלְאָכִ֔ים וַ⁠יַּגִּ֖דוּ לַ⁠מֶּֽלֶךְ׃","wa⁠yé̇lĕk֣ẇ ʼaẖàréy⁠hem֮ ʻad-ha⁠yȧrĕdé̇n֒ wĕ⁠hiné֣̇h kál-ha⁠dė֗rekĕ mĕléʼá֤h bĕgádiym֙ wĕ⁠kéli֔ym ʼàşěr-hişĕ̌li֥ykẇ ʼàrá֖m bhẖpzm wa⁠yá̇şǔ֨bẇ֙ ha⁠mȧlĕʼáki֔ym wa⁠yȧgi֖̇dẇ la⁠mėֽlekĕ׃"],[7,16,"וַ⁠יֵּצֵ֣א הָ⁠עָ֔ם וַ⁠יָּבֹ֕זּוּ אֵ֖ת מַחֲנֵ֣ה אֲרָ֑ם וַ⁠יְהִ֨י סְאָה־סֹ֜לֶת בְּ⁠שֶׁ֗קֶל וְ⁠סָאתַ֧יִם שְׂעֹרִ֛ים בְּ⁠שֶׁ֖קֶל כִּ⁠דְבַ֥ר יְהוָֽה׃","wa⁠yé̇ẕé֣ʼ há⁠ʻá֔m wa⁠yá̇bò֕żẇ ʼé֖ţ maẖàné֣h ʼàrá֑m wa⁠yĕhi֨y sĕʼáh-sò֜leţ bĕ̇⁠şě֗qel wĕ⁠sáʼţa֧yim şĕ̂ʻòri֛ym bĕ̇⁠şě֖qel ki̇⁠dĕba֥r yĕhwáֽh׃"],[7,17,"וְ⁠הַ⁠מֶּלֶךְ֩ הִפְקִ֨יד אֶת־הַ⁠שָּׁלִ֜ישׁ אֲשֶׁר־נִשְׁעָ֤ן עַל־יָד⁠וֹ֙ עַל־הַ⁠שַּׁ֔עַר וַ⁠יִּרְמְסֻ֧⁠הוּ הָ⁠עָ֛ם בַּ⁠שַּׁ֖עַר וַ⁠יָּמֹ֑ת כַּ⁠אֲשֶׁ֤ר דִּבֶּר֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠רֶ֥דֶת הַ⁠מֶּ֖לֶךְ אֵלָֽי⁠ו׃","wĕ⁠ha⁠mėlekĕ֩ hipĕqi֨yd ʼeţ-ha⁠şá̇̌li֜yş̌ ʼàşěr-nişĕ̌ʻá֤n ʻal-yád⁠wò֙ ʻal-ha⁠şȧ̌֔ʻar wa⁠yi̇rĕmĕsu֧⁠hẇ há⁠ʻá֛m bȧ⁠şȧ֖̌ʻar wa⁠yá̇mò֑ţ kȧ⁠ʼàşě֤r di̇bėr֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym ʼàşě֣r di̇bė֔r bĕ̇⁠re֥deţ ha⁠mė֖lekĕ ʼéláֽy⁠w׃"],[7,18,"וַ⁠יְהִ֗י כְּ⁠דַבֵּר֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים אֶל־הַ⁠מֶּ֖לֶךְ לֵ⁠אמֹ֑ר סָאתַ֨יִם שְׂעֹרִ֜ים בְּ⁠שֶׁ֗קֶל וּֽ⁠סְאָה־סֹ֨לֶת֙ בְּ⁠שֶׁ֔קֶל יִהְיֶה֙ כָּ⁠עֵ֣ת מָחָ֔ר בְּ⁠שַׁ֖עַר שֹׁמְרֽוֹן׃","wa⁠yĕhi֗y kĕ̇⁠dabé̇r֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym ʼel-ha⁠mė֖lekĕ lé⁠ʼmò֑r sáʼţa֨yim şĕ̂ʻòri֜ym bĕ̇⁠şě֗qel ẇֽ⁠sĕʼáh-sò֨leţ֙ bĕ̇⁠şě֔qel yihĕyeh֙ ká̇⁠ʻé֣ţ máẖá֔r bĕ̇⁠şǎ֖ʻar şò̌mĕrֽwòn׃"],[7,19,"וַ⁠יַּ֨עַן הַ⁠שָּׁלִ֜ישׁ אֶת־אִ֣ישׁ הָ⁠אֱלֹהִים֮ וַ⁠יֹּאמַר֒ וְ⁠הִנֵּ֣ה יְהוָ֗ה עֹשֶׂ֤ה אֲרֻבּוֹת֙ בַּ⁠שָּׁמַ֔יִם הֲ⁠יִהְיֶ֖ה כַּ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַ⁠יֹּ֗אמֶר הִנְּ⁠ךָ֤ רֹאֶה֙ בְּ⁠עֵינֶ֔י⁠ךָ וּ⁠מִ⁠שָּׁ֖ם לֹ֥א תֹאכֵֽל׃","wa⁠yȧ֨ʻan ha⁠şá̇̌li֜yş̌ ʼeţ-ʼi֣yş̌ há⁠ʼèlòhiym֮ wa⁠yò̇ʼmar֒ wĕ⁠hiné֣̇h yĕhwá֗h ʻòşê֤h ʼàruḃwòţ֙ bȧ⁠şá̇̌ma֔yim hà⁠yihĕye֖h kȧ⁠dá̇bá֣r ha⁠zė֑h wa⁠yò̇֗ʼmer hinĕ̇⁠ká֤ ròʼeh֙ bĕ̇⁠ʻéyne֔y⁠ká ẇ⁠mi⁠şá֖̇̌m lò֥ʼ ţòʼkéֽl׃"],[7,20,"וַ⁠יְהִי־ל֖⁠וֹ כֵּ֑ן וַ⁠יִּרְמְס֨וּ אֹת֥⁠וֹ הָ⁠עָ֛ם בַּ⁠שַּׁ֖עַר וַ⁠יָּמֹֽת׃ס","wa⁠yĕhiy-l֖⁠wò ké֑̇n wa⁠yi̇rĕmĕs֨ẇ ʼòţ֥⁠wò há⁠ʻá֛m bȧ⁠şȧ֖̌ʻar wa⁠yá̇mòֽţ׃s"],[8,1,"וֶ⁠אֱלִישָׁ֡ע דִּבֶּ֣ר אֶל־הָ⁠אִשָּׁה֩ אֲשֶׁר־הֶחֱיָ֨ה אֶת־בְּנָ֜⁠הּ לֵ⁠אמֹ֗ר ק֤וּמִי וּ⁠לְכִי֙ אתי וּ⁠בֵיתֵ֔⁠ךְ וְ⁠ג֖וּרִי בַּ⁠אֲשֶׁ֣ר תָּג֑וּרִי כִּֽי־קָרָ֤א יְהוָה֙ לָֽ⁠רָעָ֔ב וְ⁠גַם־בָּ֥א אֶל־הָ⁠אָ֖רֶץ שֶׁ֥בַע שָׁנִֽים׃","we⁠ʼèliyşá̌֡ʻ di̇bė֣r ʼel-há⁠ʼişá̇̌h֩ ʼàşěr-heẖèyá֨h ʼeţ-bĕ̇ná֜⁠ḣ lé⁠ʼmò֗r q֤ẇmiy ẇ⁠lĕkiy֙ ʼţy ẇ⁠béyţé֔⁠kĕ wĕ⁠g֖ẇriy bȧ⁠ʼàşě֣r ţá̇g֑ẇriy kiֽ̇y-qárá֤ʼ yĕhwáh֙ láֽ⁠ráʻá֔b wĕ⁠gam-bá֥̇ʼ ʼel-há⁠ʼá֖reẕ şě֥baʻ şá̌niֽym׃"],[8,2,"וַ⁠תָּ֨קָם֙ הָֽ⁠אִשָּׁ֔ה וַ⁠תַּ֕עַשׂ כִּ⁠דְבַ֖ר אִ֣ישׁ הָ⁠אֱלֹהִ֑ים וַ⁠תֵּ֤לֶךְ הִיא֙ וּ⁠בֵיתָ֔⁠הּ וַ⁠תָּ֥גָר בְּ⁠אֶֽרֶץ־פְּלִשְׁתִּ֖ים שֶׁ֥בַע שָׁנִֽים׃","wa⁠ţá̇֨qám֙ háֽ⁠ʼişá̇̌֔h wa⁠ţȧ֕ʻaş̂ ki̇⁠dĕba֖r ʼi֣yş̌ há⁠ʼèlòhi֑ym wa⁠ţé֤̇lekĕ hiyʼ֙ ẇ⁠béyţá֔⁠ḣ wa⁠ţá֥̇gár bĕ̇⁠ʼeֽreẕ-pĕ̇lişĕ̌ţi֖̇ym şě֥baʻ şá̌niֽym׃"],[8,3,"וַ⁠יְהִ֗י מִ⁠קְצֵה֙ שֶׁ֣בַע שָׁנִ֔ים וַ⁠תָּ֥שָׁב הָ⁠אִשָּׁ֖ה מֵ⁠אֶ֣רֶץ פְּלִשְׁתִּ֑ים וַ⁠תֵּצֵא֙ לִ⁠צְעֹ֣ק אֶל־הַ⁠מֶּ֔לֶךְ אֶל־בֵּיתָ֖⁠הּ וְ⁠אֶל־שָׂדָֽ⁠הּ׃","wa⁠yĕhi֗y mi⁠qĕẕéh֙ şě֣baʻ şá̌ni֔ym wa⁠ţá֥̇şá̌b há⁠ʼişá֖̇̌h mé⁠ʼe֣reẕ pĕ̇lişĕ̌ţi֑̇ym wa⁠ţé̇ẕéʼ֙ li⁠ẕĕʻò֣q ʼel-ha⁠mė֔lekĕ ʼel-bé̇yţá֖⁠ḣ wĕ⁠ʼel-şá̂dáֽ⁠ḣ׃"],[8,4,"וְ⁠הַ⁠מֶּ֗לֶךְ מְדַבֵּר֙ אֶל־גֵּ֣חֲזִ֔י נַ֥עַר אִישׁ־הָ⁠אֱלֹהִ֖ים לֵ⁠אמֹ֑ר סַפְּרָ⁠ה־נָּ֣א לִ֔⁠י אֵ֥ת כָּל־הַ⁠גְּדֹל֖וֹת אֲשֶׁר־עָשָׂ֥ה אֱלִישָֽׁע׃","wĕ⁠ha⁠mė֗lekĕ mĕdabé̇r֙ ʼel-gé֣̇ẖàzi֔y na֥ʻar ʼiyş̌-há⁠ʼèlòhi֖ym lé⁠ʼmò֑r sapĕ̇rá⁠h-ná֣̇ʼ li֔⁠y ʼé֥ţ ká̇l-ha⁠gĕ̇dòl֖wòţ ʼàşěr-ʻáşá֥̂h ʼèliyşáֽ̌ʻ׃"],[8,5,"וַ֠⁠יְהִי ה֥וּא מְסַפֵּ֣ר לַ⁠מֶּלֶךְ֮ אֵ֣ת אֲשֶׁר־הֶחֱיָ֣ה אֶת־הַ⁠מֵּת֒ וְ⁠הִנֵּ֨ה הָ⁠אִשָּׁ֜ה אֲשֶׁר־הֶחֱיָ֤ה אֶת־בְּנָ⁠הּ֙ צֹעֶ֣קֶת אֶל־הַ⁠מֶּ֔לֶךְ עַל־בֵּיתָ֖⁠הּ וְ⁠עַל־שָׂדָ֑⁠הּ וַ⁠יֹּ֤אמֶר גֵּֽחֲזִי֙ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ זֹ֚את הָֽ⁠אִשָּׁ֔ה וְ⁠זֶה־בְּנָ֖⁠הּ אֲשֶׁר־הֶחֱיָ֥ה אֱלִישָֽׁע׃","wa֠⁠yĕhiy h֥ẇʼ mĕsapé֣̇r la⁠mėlekĕ֮ ʼé֣ţ ʼàşěr-heẖèyá֣h ʼeţ-ha⁠mé̇ţ֒ wĕ⁠hiné̇֨h há⁠ʼişá̇̌֜h ʼàşěr-heẖèyá֤h ʼeţ-bĕ̇ná⁠ḣ֙ ẕòʻe֣qeţ ʼel-ha⁠mė֔lekĕ ʻal-bé̇yţá֖⁠ḣ wĕ⁠ʻal-şá̂dá֑⁠ḣ wa⁠yò֤̇ʼmer géֽ̇ẖàziy֙ ʼàdòni֣⁠y ha⁠mė֔lekĕ zò֚ʼţ háֽ⁠ʼişá̇̌֔h wĕ⁠zeh-bĕ̇ná֖⁠ḣ ʼàşěr-heẖèyá֥h ʼèliyşáֽ̌ʻ׃"],[8,6,"וַ⁠יִּשְׁאַ֥ל הַ⁠מֶּ֛לֶךְ לָ⁠אִשָּׁ֖ה וַ⁠תְּסַפֶּר־ל֑⁠וֹ וַ⁠יִּתֶּן־לָ֣⁠הּ הַ⁠מֶּלֶךְ֩ סָרִ֨יס אֶחָ֜ד לֵ⁠אמֹ֗ר הָשֵׁ֤יב אֶת־כָּל־אֲשֶׁר־לָ⁠הּ֙ וְ⁠אֵת֙ כָּל־תְּבוּאֹ֣ת הַ⁠שָּׂדֶ֔ה מִ⁠יּ֛וֹם עָזְבָ֥ה אֶת־הָ⁠אָ֖רֶץ וְ⁠עַד־עָֽתָּה׃פ","wa⁠yi̇şĕ̌ʼa֥l ha⁠mė֛lekĕ lá⁠ʼişá֖̇̌h wa⁠ţĕ̇sapėr-l֑⁠wò wa⁠yi̇ţėn-lá֣⁠ḣ ha⁠mėlekĕ֩ sári֨ys ʼeẖá֜d lé⁠ʼmò֗r háşé֤̌yb ʼeţ-ká̇l-ʼàşěr-lá⁠ḣ֙ wĕ⁠ʼéţ֙ ká̇l-ţĕ̇bẇʼò֣ţ ha⁠şá̇̂de֔h mi⁠ẏ֛wòm ʻázĕbá֥h ʼeţ-há⁠ʼá֖reẕ wĕ⁠ʻad-ʻáֽţá̇h׃p"],[8,7,"וַ⁠יָּבֹ֤א אֱלִישָׁע֙ דַּמֶּ֔שֶׂק וּ⁠בֶן־הֲדַ֥ד מֶֽלֶךְ־אֲרָ֖ם חֹלֶ֑ה וַ⁠יֻּגַּד־ל֣⁠וֹ לֵ⁠אמֹ֔ר בָּ֛א אִ֥ישׁ הָ⁠אֱלֹהִ֖ים עַד־הֵֽנָּה׃","wa⁠yá̇bò֤ʼ ʼèliyşá̌ʻ֙ dȧmė֔şêq ẇ⁠ben-hàda֥d meֽlekĕ-ʼàrá֖m ẖòle֑h wa⁠yu̇gȧd-l֣⁠wò lé⁠ʼmò֔r bá֛̇ʼ ʼi֥yş̌ há⁠ʼèlòhi֖ym ʻad-héֽná̇h׃"],[8,8,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ אֶל־חֲזָהאֵ֗ל קַ֤ח בְּ⁠יָֽדְ⁠ךָ֙ מִנְחָ֔ה וְ⁠לֵ֕ךְ לִ⁠קְרַ֖את אִ֣ישׁ הָ⁠אֱלֹהִ֑ים וְ⁠דָרַשְׁתָּ֨ אֶת־יְהוָ֤ה מֵֽ⁠אוֹת⁠וֹ֙ לֵ⁠אמֹ֔ר הַ⁠אֶחְיֶ֖ה מֵ⁠חֳלִ֥י זֶֽה׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ ʼel-ẖàzáhʼé֗l qa֤ẖ bĕ̇⁠yáֽdĕ⁠ká֙ minĕẖá֔h wĕ⁠lé֕kĕ li⁠qĕra֖ʼţ ʼi֣yş̌ há⁠ʼèlòhi֑ym wĕ⁠dáraşĕ̌ţá̇֨ ʼeţ-yĕhwá֤h méֽ⁠ʼwòţ⁠wò֙ lé⁠ʼmò֔r ha⁠ʼeẖĕye֖h mé⁠ẖoli֥y zeֽh׃"],[8,9,"וַ⁠יֵּ֣לֶךְ חֲזָאֵל֮ לִ⁠קְרָאת⁠וֹ֒ וַ⁠יִּקַּ֨ח מִנְחָ֤ה בְ⁠יָד⁠וֹ֙ וְ⁠כָל־ט֣וּב דַּמֶּ֔שֶׂק מַשָּׂ֖א אַרְבָּעִ֣ים גָּמָ֑ל וַ⁠יָּבֹא֙ וַ⁠יַּעֲמֹ֣ד לְ⁠פָנָ֔י⁠ו וַ⁠יֹּ֗אמֶר בִּנְ⁠ךָ֨ בֶן־הֲדַ֤ד מֶֽלֶךְ־אֲרָם֙ שְׁלָחַ֤⁠נִי אֵלֶ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר הַ⁠אֶחְיֶ֖ה מֵ⁠חֳלִ֥י זֶֽה׃","wa⁠yé֣̇lekĕ ẖàzáʼél֮ li⁠qĕráʼţ⁠wò֒ wa⁠yi̇qȧ֨ẖ minĕẖá֤h bĕ⁠yád⁠wò֙ wĕ⁠kál-t֣ẇb dȧmė֔şêq maşá֖̇̂ʼ ʼarĕbá̇ʻi֣ym gá̇má֑l wa⁠yá̇bòʼ֙ wa⁠yȧʻàmò֣d lĕ⁠páná֔y⁠w wa⁠yò̇֗ʼmer bi̇nĕ⁠ká֨ ben-hàda֤d meֽlekĕ-ʼàrám֙ şĕ̌láẖa֤⁠niy ʼéle֨y⁠ká֙ lé⁠ʼmò֔r ha⁠ʼeẖĕye֖h mé⁠ẖoli֥y zeֽh׃"],[8,10,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ אֱלִישָׁ֔ע לֵ֥ךְ אֱמָר־לא חָיֹ֣ה תִחְיֶ֑ה וְ⁠הִרְאַ֥⁠נִי יְהוָ֖ה כִּֽי־מ֥וֹת יָמֽוּת׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ʼèliyşá̌֔ʻ lé֥kĕ ʼèmár-lʼ ẖáyò֣h ţiẖĕye֑h wĕ⁠hirĕʼa֥⁠niy yĕhwá֖h kiֽ̇y-m֥wòţ yámֽẇţ׃"],[8,11,"וַ⁠יַּעֲמֵ֥ד אֶת־פָּנָ֖י⁠ו וַ⁠יָּ֣שֶׂם עַד־בֹּ֑שׁ וַ⁠יֵּ֖בְךְּ אִ֥ישׁ הָ⁠אֱלֹהִֽים׃","wa⁠yȧʻàmé֥d ʼeţ-pá̇ná֖y⁠w wa⁠yá֣̇şêm ʻad-bò֑̇ş̌ wa⁠yé֖̇bĕkĕ̇ ʼi֥yş̌ há⁠ʼèlòhiֽym׃"],[8,12,"וַ⁠יֹּ֣אמֶר חֲזָאֵ֔ל מַדּ֖וּעַ אֲדֹנִ֣⁠י בֹכֶ֑ה וַ⁠יֹּ֡אמֶר כִּֽי־יָדַ֡עְתִּי אֵ֣ת אֲשֶׁר־תַּעֲשֶׂה֩ לִ⁠בְנֵ֨י יִשְׂרָאֵ֜ל רָעָ֗ה מִבְצְרֵי⁠הֶ֞ם תְּשַׁלַּ֤ח בָּ⁠אֵשׁ֙ וּ⁠בַחֻֽרֵי⁠הֶם֙ בַּ⁠חֶ֣רֶב תַּהֲרֹ֔ג וְ⁠עֹלְלֵי⁠הֶ֣ם תְּרַטֵּ֔שׁ וְ⁠הָרֹתֵי⁠הֶ֖ם תְּבַקֵּֽעַ׃","wa⁠yò֣̇ʼmer ẖàzáʼé֔l maḋ֖ẇʻa ʼàdòni֣⁠y bòke֑h wa⁠yò̇֡ʼmer kiֽ̇y-yáda֡ʻĕţi̇y ʼé֣ţ ʼàşěr-ţȧʻàşêh֩ li⁠bĕné֨y yişĕ̂ráʼé֜l ráʻá֗h mibĕẕĕréy⁠he֞m ţĕ̇şǎlȧ֤ẖ bá̇⁠ʼéş̌֙ ẇ⁠baẖuֽréy⁠hem֙ bȧ⁠ẖe֣reb ţȧhàrò֔g wĕ⁠ʻòlĕléy⁠he֣m ţĕ̇raté̇֔ş̌ wĕ⁠háròţéy⁠he֖m ţĕ̇baqéֽ̇ʻa׃"],[8,13,"וַ⁠יֹּ֣אמֶר חֲזָהאֵ֔ל כִּ֣י מָ֤ה עַבְדְּ⁠ךָ֙ הַ⁠כֶּ֔לֶב כִּ֣י יַעֲשֶׂ֔ה הַ⁠דָּבָ֥ר הַ⁠גָּד֖וֹל הַ⁠זֶּ֑ה וַ⁠יֹּ֣אמֶר אֱלִישָׁ֔ע הִרְאַ֧⁠נִי יְהוָ֛ה אֹתְ⁠ךָ֖ מֶ֥לֶךְ עַל־אֲרָֽם׃","wa⁠yò֣̇ʼmer ẖàzáhʼé֔l ki֣̇y má֤h ʻabĕdĕ̇⁠ká֙ ha⁠kė֔leb ki֣̇y yaʻàşê֔h ha⁠dá̇bá֥r ha⁠gá̇d֖wòl ha⁠zė֑h wa⁠yò֣̇ʼmer ʼèliyşá̌֔ʻ hirĕʼa֧⁠niy yĕhwá֛h ʼòţĕ⁠ká֖ me֥lekĕ ʻal-ʼàráֽm׃"],[8,14,"וַ⁠יֵּ֣לֶךְ ׀ מֵ⁠אֵ֣ת אֱלִישָׁ֗ע וַ⁠יָּבֹא֙ אֶל־אֲדֹנָ֔י⁠ו וַ⁠יֹּ֣אמֶר ל֔⁠וֹ מָֽה־אָמַ֥ר לְ⁠ךָ֖ אֱלִישָׁ֑ע וַ⁠יֹּ֕אמֶר אָ֥מַר לִ֖⁠י חָיֹ֥ה תִחְיֶֽה׃","wa⁠yé֣̇lekĕ ׀ mé⁠ʼé֣ţ ʼèliyşá̌֗ʻ wa⁠yá̇bòʼ֙ ʼel-ʼàdòná֔y⁠w wa⁠yò֣̇ʼmer l֔⁠wò máֽh-ʼáma֥r lĕ⁠ká֖ ʼèliyşá֑̌ʻ wa⁠yò̇֕ʼmer ʼá֥mar li֖⁠y ẖáyò֥h ţiẖĕyeֽh׃"],[8,15,"וַ⁠יְהִ֣י מִֽ⁠מָּחֳרָ֗ת וַ⁠יִּקַּ֤ח הַ⁠מַּכְבֵּר֙ וַ⁠יִּטְבֹּ֣ל בַּ⁠מַּ֔יִם וַ⁠יִּפְרֹ֥שׂ עַל־פָּנָ֖י⁠ו וַ⁠יָּמֹ֑ת וַ⁠יִּמְלֹ֥ךְ חֲזָהאֵ֖ל תַּחְתָּֽי⁠ו׃פ","wa⁠yĕhi֣y miֽ⁠má̇ẖorá֗ţ wa⁠yi̇qȧ֤ẖ ha⁠mȧkĕbé̇r֙ wa⁠yi̇tĕbò֣̇l bȧ⁠mȧ֔yim wa⁠yi̇pĕrò֥ş̂ ʻal-pá̇ná֖y⁠w wa⁠yá̇mò֑ţ wa⁠yi̇mĕlò֥kĕ ẖàzáhʼé֖l ţȧẖĕţáֽ̇y⁠w׃p"],[8,16,"וּ⁠בִ⁠שְׁנַ֣ת חָמֵ֗שׁ לְ⁠יוֹרָ֤ם בֶּן־אַחְאָב֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וִ⁠יהוֹשָׁפָ֖ט מֶ֣לֶךְ יְהוּדָ֑ה מָלַ֛ךְ יְהוֹרָ֥ם בֶּן־יְהוֹשָׁפָ֖ט מֶ֥לֶךְ יְהוּדָֽה׃","ẇ⁠bi⁠şĕ̌na֣ţ ẖámé֗ş̌ lĕ⁠ywòrá֤m bėn-ʼaẖĕʼáb֙ me֣lekĕ yişĕ̂ráʼé֔l wi⁠yhwòşá̌pá֖t me֣lekĕ yĕhẇdá֑h mála֛kĕ yĕhwòrá֥m bėn-yĕhwòşá̌pá֖t me֥lekĕ yĕhẇdáֽh׃"],[8,17,"בֶּן־שְׁלֹשִׁ֥ים וּ⁠שְׁתַּ֛יִם שָׁנָ֖ה הָיָ֣ה בְ⁠מָלְכ֑⁠וֹ וּ⁠שְׁמֹנֶ֣ה שנה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-şĕ̌lòşǐ֥ym ẇ⁠şĕ̌ţȧ֛yim şá̌ná֖h háyá֣h bĕ⁠málĕk֑⁠wò ẇ⁠şĕ̌mòne֣h şnh mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[8,18,"וַ⁠יֵּ֜לֶךְ בְּ⁠דֶ֣רֶךְ ׀ מַלְכֵ֣י יִשְׂרָאֵ֗ל כַּ⁠אֲשֶׁ֤ר עָשׂוּ֙ בֵּ֣ית אַחְאָ֔ב כִּ֚י בַּת־אַחְאָ֔ב הָֽיְתָה־לּ֖⁠וֹ לְ⁠אִשָּׁ֑ה וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃","wa⁠yé̇֜lekĕ bĕ̇⁠de֣rekĕ ׀ malĕké֣y yişĕ̂ráʼé֗l kȧ⁠ʼàşě֤r ʻáş̂ẇ֙ bé֣̇yţ ʼaẖĕʼá֔b ki֚̇y bȧţ-ʼaẖĕʼá֔b háֽyĕţáh-l֖̇⁠wò lĕ⁠ʼişá֑̇̌h wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[8,19,"וְ⁠לֹֽא־אָבָ֤ה יְהוָה֙ לְ⁠הַשְׁחִ֣ית אֶת־יְהוּדָ֔ה לְמַ֖עַן דָּוִ֣ד עַבְדּ֑⁠וֹ כַּ⁠אֲשֶׁ֣ר אָֽמַר־ל֗⁠וֹ לָ⁠תֵ֨ת ל֥⁠וֹ נִ֛יר לְ⁠בָנָ֖י⁠ו כָּל־הַ⁠יָּמִֽים׃","wĕ⁠lòֽʼ-ʼábá֤h yĕhwáh֙ lĕ⁠haşĕ̌ẖi֣yţ ʼeţ-yĕhẇdá֔h lĕma֖ʻan dá̇wi֣d ʻabĕḋ֑⁠wò kȧ⁠ʼàşě֣r ʼáֽmar-l֗⁠wò lá⁠ţé֨ţ l֥⁠wò ni֛yr lĕ⁠báná֖y⁠w ká̇l-ha⁠yá̇miֽym׃"],[8,20,"בְּ⁠יָמָי⁠ו֙ פָּשַׁ֣ע אֱד֔וֹם מִ⁠תַּ֖חַת יַד־יְהוּדָ֑ה וַ⁠יַּמְלִ֥כוּ עֲלֵי⁠הֶ֖ם מֶֽלֶךְ׃","bĕ̇⁠yámáy⁠w֙ pá̇şǎ֣ʻ ʼèd֔wòm mi⁠ţȧ֖ẖaţ yad-yĕhẇdá֑h wa⁠yȧmĕli֥kẇ ʻàléy⁠he֖m meֽlekĕ׃"],[8,21,"וַ⁠יַּעֲבֹ֤ר יוֹרָם֙ צָעִ֔ירָ⁠ה וְ⁠כָל־הָ⁠רֶ֖כֶב עִמּ֑⁠וֹ וַֽ⁠יְהִי־ה֞וּא קָ֣ם לַ֗יְלָה וַ⁠יַּכֶּ֨ה אֶת־אֱד֜וֹם הַ⁠סֹּבֵ֤יב אֵלָי⁠ו֙ וְ⁠אֵת֙ שָׂרֵ֣י הָ⁠רֶ֔כֶב וַ⁠יָּ֥נָס הָ⁠עָ֖ם לְ⁠אֹהָלָֽי⁠ו׃","wa⁠yȧʻàbò֤r ywòrám֙ ẕáʻi֔yrá⁠h wĕ⁠kál-há⁠re֖keb ʻiṁ֑⁠wò waֽ⁠yĕhiy-h֞ẇʼ qá֣m la֗yĕláh wa⁠yȧkė֨h ʼeţ-ʼèd֜wòm ha⁠sò̇bé֤yb ʼéláy⁠w֙ wĕ⁠ʼéţ֙ şá̂ré֣y há⁠re֔keb wa⁠yá֥̇nás há⁠ʻá֖m lĕ⁠ʼòháláֽy⁠w׃"],[8,22,"וַ⁠יִּפְשַׁ֣ע אֱד֗וֹם מִ⁠תַּ֨חַת֙ יַד־יְהוּדָ֔ה עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה אָ֛ז תִּפְשַׁ֥ע לִבְנָ֖ה בָּ⁠עֵ֥ת הַ⁠הִֽיא׃","wa⁠yi̇pĕşǎ֣ʻ ʼèd֗wòm mi⁠ţȧ֨ẖaţ֙ yad-yĕhẇdá֔h ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ʼá֛z ţi̇pĕşǎ֥ʻ libĕná֖h bá̇⁠ʻé֥ţ ha⁠hiֽyʼ׃"],[8,23,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יוֹרָ֖ם וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֽוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y ywòrá֖m wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lֽwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[8,24,"וַ⁠יִּשְׁכַּ֤ב יוֹרָם֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֥ר עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֣יר דָּוִ֑ד וַ⁠יִּמְלֹ֛ךְ אֲחַזְיָ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ywòrám֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֥r ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֣yr dá̇wi֑d wa⁠yi̇mĕlò֛kĕ ʼàẖazĕyá֥hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[8,25,"בִּ⁠שְׁנַת֙ שְׁתֵּים־עֶשְׂרֵ֣ה שָׁנָ֔ה לְ⁠יוֹרָ֥ם בֶּן־אַחְאָ֖ב מֶ֣לֶךְ יִשְׂרָאֵ֑ל מָלַ֛ךְ אֲחַזְיָ֥הוּ בֶן־יְהוֹרָ֖ם מֶ֥לֶךְ יְהוּדָֽה׃","bi̇⁠şĕ̌naţ֙ şĕ̌ţé̇ym-ʻeşĕ̂ré֣h şá̌ná֔h lĕ⁠ywòrá֥m bėn-ʼaẖĕʼá֖b me֣lekĕ yişĕ̂ráʼé֑l mála֛kĕ ʼàẖazĕyá֥hẇ ben-yĕhwòrá֖m me֥lekĕ yĕhẇdáֽh׃"],[8,26,"בֶּן־עֶשְׂרִ֨ים וּ⁠שְׁתַּ֤יִם שָׁנָה֙ אֲחַזְיָ֣הוּ בְ⁠מָלְכ֔⁠וֹ וְ⁠שָׁנָ֣ה אַחַ֔ת מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֤ם אִמּ⁠וֹ֙ עֲתַלְיָ֔הוּ בַּת־עָמְרִ֖י מֶ֥לֶךְ יִשְׂרָאֵֽל׃","bėn-ʻeşĕ̂ri֨ym ẇ⁠şĕ̌ţȧ֤yim şá̌náh֙ ʼàẖazĕyá֣hẇ bĕ⁠málĕk֔⁠wò wĕ⁠şá̌ná֣h ʼaẖa֔ţ mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֤̌m ʼiṁ⁠wò֙ ʻàţalĕyá֔hẇ bȧţ-ʻámĕri֖y me֥lekĕ yişĕ̂ráʼéֽl׃"],[8,27,"וַ⁠יֵּ֗לֶךְ בְּ⁠דֶ֨רֶךְ֙ בֵּ֣ית אַחְאָ֔ב וַ⁠יַּ֧עַשׂ הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה כְּ⁠בֵ֣ית אַחְאָ֑ב כִּ֛י חֲתַ֥ן בֵּית־אַחְאָ֖ב הֽוּא׃","wa⁠yé̇֗lekĕ bĕ̇⁠de֨rekĕ֙ bé֣̇yţ ʼaẖĕʼá֔b wa⁠yȧ֧ʻaş̂ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h kĕ̇⁠bé֣yţ ʼaẖĕʼá֑b ki֛̇y ẖàţa֥n bé̇yţ-ʼaẖĕʼá֖b hֽẇʼ׃"],[8,28,"וַ⁠יֵּ֜לֶךְ אֶת־יוֹרָ֣ם בֶּן־אַחְאָ֗ב לַ⁠מִּלְחָמָ֛ה עִם־חֲזָהאֵ֥ל מֶֽלֶךְ־אֲרָ֖ם בְּ⁠רָמֹ֣ת גִּלְעָ֑ד וַ⁠יַּכּ֥וּ אֲרַמִּ֖ים אֶת־יוֹרָֽם׃","wa⁠yé̇֜lekĕ ʼeţ-ywòrá֣m bėn-ʼaẖĕʼá֗b la⁠mi̇lĕẖámá֛h ʻim-ẖàzáhʼé֥l meֽlekĕ-ʼàrá֖m bĕ̇⁠rámò֣ţ gi̇lĕʻá֑d wa⁠yȧk֥̇ẇ ʼàrami֖̇ym ʼeţ-ywòráֽm׃"],[8,29,"וַ⁠יָּשָׁב֩ יוֹרָ֨ם הַ⁠מֶּ֜לֶךְ לְ⁠הִתְרַפֵּ֣א בְ⁠יִזְרְעֶ֗אל מִן־הַ⁠מַּכִּים֙ אֲשֶׁ֨ר יַכֻּ֤⁠הוּ אֲרַמִּים֙ בָּֽ⁠רָמָ֔ה בְּ⁠הִלָּ֣חֲמ֔⁠וֹ אֶת־חֲזָהאֵ֖ל מֶ֣לֶךְ אֲרָ֑ם וַ⁠אֲחַזְיָ֨הוּ בֶן־יְהוֹרָ֜ם מֶ֣לֶךְ יְהוּדָ֗ה יָרַ֡ד לִ⁠רְא֞וֹת אֶת־יוֹרָ֧ם בֶּן־אַחְאָ֛ב בְּ⁠יִזְרְעֶ֖אל כִּֽי־חֹלֶ֥ה הֽוּא׃פ","wa⁠yá̇şá̌b֩ ywòrá֨m ha⁠mė֜lekĕ lĕ⁠hiţĕrapé֣̇ʼ bĕ⁠yizĕrĕʻe֗ʼl min-ha⁠mȧki̇ym֙ ʼàşě֨r yaku֤̇⁠hẇ ʼàrami̇ym֙ báֽ̇⁠rámá֔h bĕ̇⁠hilá֣̇ẖàm֔⁠wò ʼeţ-ẖàzáhʼé֖l me֣lekĕ ʼàrá֑m wa⁠ʼàẖazĕyá֨hẇ ben-yĕhwòrá֜m me֣lekĕ yĕhẇdá֗h yára֡d li⁠rĕʼ֞wòţ ʼeţ-ywòrá֧m bėn-ʼaẖĕʼá֛b bĕ̇⁠yizĕrĕʻe֖ʼl kiֽ̇y-ẖòle֥h hֽẇʼ׃p"],[9,1,"וֶ⁠אֱלִישָׁע֙ הַ⁠נָּבִ֔יא קָרָ֕א לְ⁠אַחַ֖ד מִ⁠בְּנֵ֣י הַ⁠נְּבִיאִ֑ים וַ⁠יֹּ֨אמֶר ל֜⁠וֹ חֲגֹ֣ר מָתְנֶ֗י⁠ךָ וְ֠⁠קַח פַּ֣ךְ הַ⁠שֶּׁ֤מֶן הַ⁠זֶּה֙ בְּ⁠יָדֶ֔⁠ךָ וְ⁠לֵ֖ךְ רָמֹ֥ת גִּלְעָֽד׃","we⁠ʼèliyşá̌ʻ֙ ha⁠ná̇bi֔yʼ qárá֕ʼ lĕ⁠ʼaẖa֖d mi⁠bĕ̇né֣y ha⁠nĕ̇biyʼi֑ym wa⁠yò̇֨ʼmer l֜⁠wò ẖàgò֣r máţĕne֗y⁠ká wĕ֠⁠qaẖ pȧ֣kĕ ha⁠şė֤̌men ha⁠zėh֙ bĕ̇⁠yáde֔⁠ká wĕ⁠lé֖kĕ rámò֥ţ gi̇lĕʻáֽd׃"],[9,2,"וּ⁠בָ֖אתָ שָׁ֑מָּ⁠ה וּ⁠רְאֵֽה־שָׁ֠ם יֵה֨וּא בֶן־יְהוֹשָׁפָ֜ט בֶּן־נִמְשִׁ֗י וּ⁠בָ֨אתָ֙ וַ⁠הֲקֵֽמֹת⁠וֹ֙ מִ⁠תּ֣וֹך אֶחָ֔י⁠ו וְ⁠הֵבֵיאתָ֥ אֹת֖⁠וֹ חֶ֥דֶר בְּ⁠חָֽדֶר׃","ẇ⁠bá֖ʼţá şá֑̌má̇⁠h ẇ⁠rĕʼéֽh-şá̌֠m yéh֨ẇʼ ben-yĕhwòşá̌pá֜t bėn-nimĕşǐ֗y ẇ⁠bá֨ʼţá֙ wa⁠hàqéֽmòţ⁠wò֙ mi⁠ţ֣̇wòk ʼeẖá֔y⁠w wĕ⁠hébéyʼţá֥ ʼòţ֖⁠wò ẖe֥der bĕ̇⁠ẖáֽder׃"],[9,3,"וְ⁠לָקַחְתָּ֤ פַךְ־הַ⁠שֶּׁ֨מֶן֙ וְ⁠יָצַקְתָּ֣ עַל־רֹאשׁ֔⁠וֹ וְ⁠אָֽמַרְתָּ֙ כֹּֽה־אָמַ֣ר יְהוָ֔ה מְשַׁחְתִּ֥י⁠ךָֽ לְ⁠מֶ֖לֶךְ אֶל־יִשְׂרָאֵ֑ל וּ⁠פָתַחְתָּ֥ הַ⁠דֶּ֛לֶת וְ⁠נַ֖סְתָּה וְ⁠לֹ֥א תְחַכֶּֽה׃","wĕ⁠láqaẖĕţá֤̇ pakĕ-ha⁠şė̌֨men֙ wĕ⁠yáẕaqĕţá֣̇ ʻal-ròʼş̌֔⁠wò wĕ⁠ʼáֽmarĕţá̇֙ kòֽ̇h-ʼáma֣r yĕhwá֔h mĕşǎẖĕţi֥̇y⁠káֽ lĕ⁠me֖lekĕ ʼel-yişĕ̂ráʼé֑l ẇ⁠páţaẖĕţá֥̇ ha⁠dė֛leţ wĕ⁠na֖sĕţá̇h wĕ⁠lò֥ʼ ţĕẖakėֽh׃"],[9,4,"וַ⁠יֵּ֧לֶךְ הַ⁠נַּ֛עַר הַ⁠נַּ֥עַר הַ⁠נָּבִ֖יא רָמֹ֥ת גִּלְעָֽד׃","wa⁠yé֧̇lekĕ ha⁠nȧ֛ʻar ha⁠nȧ֥ʻar ha⁠ná̇bi֖yʼ rámò֥ţ gi̇lĕʻáֽd׃"],[9,5,"וַ⁠יָּבֹ֗א וְ⁠הִנֵּ֨ה שָׂרֵ֤י הַ⁠חַ֨יִל֙ יֹֽשְׁבִ֔ים וַ⁠יֹּ֕אמֶר דָּבָ֥ר לִ֛⁠י אֵלֶ֖י⁠ךָ הַ⁠שָּׂ֑ר וַ⁠יֹּ֤אמֶר יֵהוּא֙ אֶל־מִ֣י מִ⁠כֻּלָּ֔⁠נוּ וַ⁠יֹּ֖אמֶר אֵלֶ֥י⁠ךָ הַ⁠שָּֽׂר׃","wa⁠yá̇bò֗ʼ wĕ⁠hiné̇֨h şá̂ré֤y ha⁠ẖa֨yil֙ yòֽşĕ̌bi֔ym wa⁠yò̇֕ʼmer dá̇bá֥r li֛⁠y ʼéle֖y⁠ká ha⁠şá֑̇̂r wa⁠yò֤̇ʼmer yéhẇʼ֙ ʼel-mi֣y mi⁠ku̇lá̇֔⁠nẇ wa⁠yò֖̇ʼmer ʼéle֥y⁠ká ha⁠şáֽ̇̂r׃"],[9,6,"וַ⁠יָּ֨קָם֙ וַ⁠יָּבֹ֣א הַ⁠בַּ֔יְתָ⁠ה וַ⁠יִּצֹ֥ק הַ⁠שֶּׁ֖מֶן אֶל־רֹאשׁ֑⁠וֹ וַ⁠יֹּ֣אמֶר ל֗⁠וֹ כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל מְשַׁחְתִּ֧י⁠ךָֽ לְ⁠מֶ֛לֶךְ אֶל־עַ֥ם יְהוָ֖ה אֶל־יִשְׂרָאֵֽל׃","wa⁠yá̇֨qám֙ wa⁠yá̇bò֣ʼ ha⁠bȧ֔yĕţá⁠h wa⁠yi̇ẕò֥q ha⁠şė֖̌men ʼel-ròʼş֑̌⁠wò wa⁠yò֣̇ʼmer l֗⁠wò kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l mĕşǎẖĕţi֧̇y⁠káֽ lĕ⁠me֛lekĕ ʼel-ʻa֥m yĕhwá֖h ʼel-yişĕ̂ráʼéֽl׃"],[9,7,"וְ⁠הִ֨כִּיתָ֔ה אֶת־בֵּ֥ית אַחְאָ֖ב אֲדֹנֶ֑י⁠ךָ וְ⁠נִקַּמְתִּ֞י דְּמֵ֣י ׀ עֲבָדַ֣⁠י הַ⁠נְּבִיאִ֗ים וּ⁠דְמֵ֛י כָּל־עַבְדֵ֥י יְהוָ֖ה מִ⁠יַּ֥ד אִיזָֽבֶל׃","wĕ⁠hi֨ki̇yţá֔h ʼeţ-bé֥̇yţ ʼaẖĕʼá֖b ʼàdòne֑y⁠ká wĕ⁠niqȧmĕţi̇֞y dĕ̇mé֣y ׀ ʻàbáda֣⁠y ha⁠nĕ̇biyʼi֗ym ẇ⁠dĕmé֛y ká̇l-ʻabĕdé֥y yĕhwá֖h mi⁠yȧ֥d ʼiyzáֽbel׃"],[9,8,"וְ⁠אָבַ֖ד כָּל־בֵּ֣ית אַחְאָ֑ב וְ⁠הִכְרַתִּ֤י לְ⁠אַחְאָב֙ מַשְׁתִּ֣ין בְּ⁠קִ֔יר וְ⁠עָצ֥וּר וְ⁠עָז֖וּב בְּ⁠יִשְׂרָאֵֽל׃","wĕ⁠ʼába֖d ká̇l-bé֣̇yţ ʼaẖĕʼá֑b wĕ⁠hikĕraţi֤̇y lĕ⁠ʼaẖĕʼáb֙ maşĕ̌ţi֣̇yn bĕ̇⁠qi֔yr wĕ⁠ʻáẕ֥ẇr wĕ⁠ʻáz֖ẇb bĕ̇⁠yişĕ̂ráʼéֽl׃"],[9,9,"וְ⁠נָֽתַתִּי֙ אֶת־בֵּ֣ית אַחְאָ֔ב כְּ⁠בֵ֖ית יָרָבְעָ֣ם בֶּן־נְבָ֑ט וּ⁠כְ⁠בֵ֖ית בַּעְשָׁ֥א בֶן־אֲחִיָּֽה׃","wĕ⁠náֽţaţi̇y֙ ʼeţ-bé֣̇yţ ʼaẖĕʼá֔b kĕ̇⁠bé֖yţ yárábĕʻá֣m bėn-nĕbá֑t ẇ⁠kĕ⁠bé֖yţ bȧʻĕşá֥̌ʼ ben-ʼàẖiyáֽ̇h׃"],[9,10,"וְ⁠אֶת־אִיזֶ֜בֶל יֹאכְל֧וּ הַ⁠כְּלָבִ֛ים בְּ⁠חֵ֥לֶק יִזְרְעֶ֖אל וְ⁠אֵ֣ין קֹבֵ֑ר וַ⁠יִּפְתַּ֥ח הַ⁠דֶּ֖לֶת וַ⁠יָּנֹֽס׃","wĕ⁠ʼeţ-ʼiyze֜bel yòʼkĕl֧ẇ ha⁠kĕ̇lábi֛ym bĕ̇⁠ẖé֥leq yizĕrĕʻe֖ʼl wĕ⁠ʼé֣yn qòbé֑r wa⁠yi̇pĕţȧ֥ẖ ha⁠dė֖leţ wa⁠yá̇nòֽs׃"],[9,11,"וְ⁠יֵה֗וּא יָצָא֙ אֶל־עַבְדֵ֣י אֲדֹנָ֔י⁠ו וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ הֲ⁠שָׁל֔וֹם מַדּ֛וּעַ בָּֽא־הַ⁠מְשֻׁגָּ֥ע הַ⁠זֶּ֖ה אֵלֶ֑י⁠ךָ וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֔ם אַתֶּ֛ם יְדַעְתֶּ֥ם אֶת־הָ⁠אִ֖ישׁ וְ⁠אֶת־שִׂיחֽ⁠וֹ׃","wĕ⁠yéh֗ẇʼ yáẕáʼ֙ ʼel-ʻabĕdé֣y ʼàdòná֔y⁠w wa⁠yò֤̇ʼmer l⁠wò֙ hà⁠şá̌l֔wòm maḋ֛ẇʻa báֽ̇ʼ-ha⁠mĕşǔgá֥̇ʻ ha⁠zė֖h ʼéle֑y⁠ká wa⁠yò֣̇ʼmer ʼàléy⁠he֔m ʼaţė֛m yĕdaʻĕţė֥m ʼeţ-há⁠ʼi֖yş̌ wĕ⁠ʼeţ-şîyẖֽ⁠wò׃"],[9,12,"וַ⁠יֹּאמְר֣וּ שֶׁ֔קֶר הַגֶּד־נָ֖א לָ֑⁠נוּ וַ⁠יֹּ֗אמֶר כָּ⁠זֹ֤את וְ⁠כָ⁠זֹאת֙ אָמַ֤ר אֵלַ⁠י֙ לֵ⁠אמֹ֔ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה מְשַׁחְתִּ֥י⁠ךָֽ לְ⁠מֶ֖לֶךְ אֶל־יִשְׂרָאֵֽל׃","wa⁠yò̇ʼmĕr֣ẇ şě֔qer hagėd-ná֖ʼ lá֑⁠nẇ wa⁠yò̇֗ʼmer ká̇⁠zò֤ʼţ wĕ⁠ká⁠zòʼţ֙ ʼáma֤r ʼéla⁠y֙ lé⁠ʼmò֔r kò֚̇h ʼáma֣r yĕhwá֔h mĕşǎẖĕţi֥̇y⁠káֽ lĕ⁠me֖lekĕ ʼel-yişĕ̂ráʼéֽl׃"],[9,13,"וַֽ⁠יְמַהֲר֗וּ וַ⁠יִּקְחוּ֙ אִ֣ישׁ בִּגְד֔⁠וֹ וַ⁠יָּשִׂ֥ימוּ תַחְתָּ֖י⁠ו אֶל־גֶּ֣רֶם הַֽ⁠מַּעֲל֑וֹת וַֽ⁠יִּתְקְעוּ֙ בַּ⁠שּׁוֹפָ֔ר וַ⁠יֹּאמְר֖וּ מָלַ֥ךְ יֵהֽוּא׃","waֽ⁠yĕmahàr֗ẇ wa⁠yi̇qĕẖẇ֙ ʼi֣yş̌ bi̇gĕd֔⁠wò wa⁠yá̇şî֥ymẇ ţaẖĕţá֖̇y⁠w ʼel-gė֣rem haֽ⁠mȧʻàl֑wòţ waֽ⁠yi̇ţĕqĕʻẇ֙ bȧ⁠ş̇̌wòpá֔r wa⁠yò̇ʼmĕr֖ẇ mála֥kĕ yéhֽẇʼ׃"],[9,14,"וַ⁠יִּתְקַשֵּׁ֗ר יֵה֛וּא בֶּן־יְהוֹשָׁפָ֥ט בֶּן־נִמְשִׁ֖י אֶל־יוֹרָ֑ם וְ⁠יוֹרָם֩ הָיָ֨ה שֹׁמֵ֜ר בְּ⁠רָמֹ֣ת גִּלְעָ֗ד ה֚וּא וְ⁠כָל־יִשְׂרָאֵ֔ל מִ⁠פְּנֵ֥י חֲזָאֵ֖ל מֶֽלֶךְ־אֲרָֽם׃","wa⁠yi̇ţĕqaşé̇̌֗r yéh֛ẇʼ bėn-yĕhwòşá̌pá֥t bėn-nimĕşǐ֖y ʼel-ywòrá֑m wĕ⁠ywòrám֩ háyá֨h şò̌mé֜r bĕ̇⁠rámò֣ţ gi̇lĕʻá֗d h֚ẇʼ wĕ⁠kál-yişĕ̂ráʼé֔l mi⁠pĕ̇né֥y ẖàzáʼé֖l meֽlekĕ-ʼàráֽm׃"],[9,15,"וַ⁠יָּשָׁב֩ יְהוֹרָ֨ם הַ⁠מֶּ֜לֶךְ לְ⁠הִתְרַפֵּ֣א בִ⁠יְזְרְעֶ֗אל מִן־הַ⁠מַּכִּים֙ אֲשֶׁ֣ר יַכֻּ֣⁠הוּ אֲרַמִּ֔ים בְּ⁠הִלָּ֣חֲמ֔⁠וֹ אֶת־חֲזָאֵ֖ל מֶ֣לֶךְ אֲרָ֑ם וַ⁠יֹּ֤אמֶר יֵהוּא֙ אִם־יֵ֣שׁ נַפְשְׁ⁠כֶ֔ם אַל־יֵצֵ֤א פָלִיט֙ מִן־הָ⁠עִ֔יר לָ⁠לֶ֖כֶת ל⁠גיד בְּ⁠יִזְרְעֶֽאל׃","wa⁠yá̇şá̌b֩ yĕhwòrá֨m ha⁠mė֜lekĕ lĕ⁠hiţĕrapé֣̇ʼ bi⁠yĕzĕrĕʻe֗ʼl min-ha⁠mȧki̇ym֙ ʼàşě֣r yaku֣̇⁠hẇ ʼàrami̇֔ym bĕ̇⁠hilá֣̇ẖàm֔⁠wò ʼeţ-ẖàzáʼé֖l me֣lekĕ ʼàrá֑m wa⁠yò֤̇ʼmer yéhẇʼ֙ ʼim-yé֣ş̌ napĕşĕ̌⁠ke֔m ʼal-yéẕé֤ʼ páliyt֙ min-há⁠ʻi֔yr lá⁠le֖keţ l⁠gyd bĕ̇⁠yizĕrĕʻeֽʼl׃"],[9,16,"וַ⁠יִּרְכַּ֤ב יֵהוּא֙ וַ⁠יֵּ֣לֶךְ יִזְרְעֶ֔אלָ⁠ה כִּ֥י יוֹרָ֖ם שֹׁכֵ֣ב שָׁ֑מָּ⁠ה וַֽ⁠אֲחַזְיָה֙ מֶ֣לֶךְ יְהוּדָ֔ה יָרַ֖ד לִ⁠רְא֥וֹת אֶת־יוֹרָֽם׃","wa⁠yi̇rĕkȧ֤b yéhẇʼ֙ wa⁠yé֣̇lekĕ yizĕrĕʻe֔ʼlá⁠h ki֥̇y ywòrá֖m şò̌ké֣b şá֑̌má̇⁠h wֽa⁠ʼàẖazĕyáh֙ me֣lekĕ yĕhẇdá֔h yára֖d li⁠rĕʼ֥wòţ ʼeţ-ywòráֽm׃"],[9,17,"וְ⁠הַ⁠צֹּפֶה֩ עֹמֵ֨ד עַֽל־הַ⁠מִּגְדָּ֜ל בְּ⁠יִזְרְעֶ֗אל וַ⁠יַּ֞רְא אֶת־שִׁפְעַ֤ת יֵהוּא֙ בְּ⁠בֹא֔⁠וֹ וַ⁠יֹּ֕אמֶר שִׁפְעַ֖ת אֲנִ֣י רֹאֶ֑ה וַ⁠יֹּ֣אמֶר יְהוֹרָ֗ם קַ֥ח רַכָּ֛ב וּֽ⁠שְׁלַ֥ח לִ⁠קְרָאתָ֖⁠ם וְ⁠יֹאמַ֥ר הֲ⁠שָׁלֽוֹם׃","wĕ⁠ha⁠ẕò̇peh֩ ʻòmé֨d ʻaֽl-ha⁠mi̇gĕdá̇֜l bĕ̇⁠yizĕrĕʻe֗ʼl wa⁠yȧ֞rĕʼ ʼeţ-şǐpĕʻa֤ţ yéhẇʼ֙ bĕ̇⁠bòʼ֔⁠wò wa⁠yò̇֕ʼmer şǐpĕʻa֖ţ ʼàni֣y ròʼe֑h wa⁠yò֣̇ʼmer yĕhwòrá֗m qa֥ẖ raká֛̇b ẇֽ⁠şĕ̌la֥ẖ li⁠qĕráʼţá֖⁠m wĕ⁠yòʼma֥r hà⁠şá̌lֽwòm׃"],[9,18,"וַ⁠יֵּלֶךְ֩ רֹכֵ֨ב הַ⁠סּ֜וּס לִ⁠קְרָאת֗⁠וֹ וַ⁠יֹּ֨אמֶר֙ כֹּֽה־אָמַ֤ר הַ⁠מֶּ֨לֶךְ֙ הֲ⁠שָׁל֔וֹם וַ⁠יֹּ֧אמֶר יֵה֛וּא מַה־לְּ⁠ךָ֥ וּ⁠לְ⁠שָׁל֖וֹם סֹ֣ב אֶֽל־אַחֲרָ֑⁠י וַ⁠יַּגֵּ֤ד הַ⁠צֹּפֶה֙ לֵ⁠אמֹ֔ר בָּֽא־הַ⁠מַּלְאָ֥ךְ עַד־הֵ֖ם וְ⁠לֹֽא־שָֽׁב׃","wa⁠yé̇lekĕ֩ ròké֨b ha⁠ṡ֜ẇs li⁠qĕráʼţ֗⁠wò wa⁠yò̇֨ʼmer֙ kòֽ̇h-ʼáma֤r ha⁠mė֨lekĕ֙ hà⁠şá̌l֔wòm wa⁠yò֧̇ʼmer yéh֛ẇʼ mah-lĕ̇⁠ká֥ ẇ⁠lĕ⁠şá̌l֖wòm sò֣b ʼeֽl-ʼaẖàrá֑⁠y wa⁠yȧgé֤̇d ha⁠ẕò̇peh֙ lé⁠ʼmò֔r báֽ̇ʼ-ha⁠mȧlĕʼá֥kĕ ʻad-hé֖m wĕ⁠lòֽʼ-şáֽ̌b׃"],[9,19,"וַ⁠יִּשְׁלַ֗ח רֹכֵ֣ב סוּס֮ שֵׁנִי֒ וַ⁠יָּבֹ֣א אֲלֵ⁠הֶ֔ם וַ⁠יֹּ֛אמֶר כֹּֽה־אָמַ֥ר הַ⁠מֶּ֖לֶךְ שָׁל֑וֹם וַ⁠יֹּ֧אמֶר יֵה֛וּא מַה־לְּ⁠ךָ֥ וּ⁠לְ⁠שָׁל֖וֹם סֹ֥ב אֶֽל־אַחֲרָֽ⁠י׃","wa⁠yi̇şĕ̌la֗ẖ ròké֣b sẇs֮ şé̌niy֒ wa⁠yá̇bò֣ʼ ʼàlé⁠he֔m wa⁠yò֛̇ʼmer kòֽ̇h-ʼáma֥r ha⁠mė֖lekĕ şá̌l֑wòm wa⁠yò֧̇ʼmer yéh֛ẇʼ mah-lĕ̇⁠ká֥ ẇ⁠lĕ⁠şá̌l֖wòm sò֥b ʼeֽl-ʼaẖàráֽ⁠y׃"],[9,20,"וַ⁠יַּגֵּ֤ד הַ⁠צֹּפֶה֙ לֵ⁠אמֹ֔ר בָּ֥א עַד־אֲלֵי⁠הֶ֖ם וְ⁠לֹֽא־שָׁ֑ב וְ⁠הַ⁠מִּנְהָ֗ג כְּ⁠מִנְהַג֙ יֵה֣וּא בֶן־נִמְשִׁ֔י כִּ֥י בְ⁠שִׁגָּע֖וֹן יִנְהָֽג׃","wa⁠yȧgé֤̇d ha⁠ẕò̇peh֙ lé⁠ʼmò֔r bá֥̇ʼ ʻad-ʼàléy⁠he֖m wĕ⁠lòֽʼ-şá֑̌b wĕ⁠ha⁠mi̇nĕhá֗g kĕ̇⁠minĕhag֙ yéh֣ẇʼ ben-nimĕşǐ֔y ki֥̇y bĕ⁠şǐgá̇ʻ֖wòn yinĕháֽg׃"],[9,21,"וַ⁠יֹּ֤אמֶר יְהוֹרָם֙ אֱסֹ֔ר וַ⁠יֶּאְסֹ֖ר רִכְבּ֑⁠וֹ וַ⁠יֵּצֵ֣א יְהוֹרָ֣ם מֶֽלֶךְ־יִ֠שְׂרָאֵל וַ⁠אֲחַזְיָ֨הוּ מֶֽלֶךְ־יְהוּדָ֜ה אִ֣ישׁ בְּ⁠רִכְבּ֗⁠וֹ וַ⁠יֵּֽצְאוּ֙ לִ⁠קְרַ֣את יֵה֔וּא וַ⁠יִּמְצָאֻ֔⁠הוּ בְּ⁠חֶלְקַ֖ת נָב֥וֹת הַ⁠יִּזְרְעֵאלִֽי׃","wa⁠yò֤̇ʼmer yĕhwòrám֙ ʼèsò֔r wa⁠yėʼĕsò֖r rikĕḃ֑⁠wò wa⁠yé̇ẕé֣ʼ yĕhwòrá֣m meֽlekĕ-yi֠şĕ̂ráʼél wa⁠ʼàẖazĕyá֨hẇ meֽlekĕ-yĕhẇdá֜h ʼi֣yş̌ bĕ̇⁠rikĕḃ֗⁠wò wa⁠yéֽ̇ẕĕʼẇ֙ li⁠qĕra֣ʼţ yéh֔ẇʼ wa⁠yi̇mĕẕáʼu֔⁠hẇ bĕ̇⁠ẖelĕqa֖ţ náb֥wòţ ha⁠yi̇zĕrĕʻéʼliֽy׃"],[9,22,"וַ⁠יְהִ֗י כִּ⁠רְא֤וֹת יְהוֹרָם֙ אֶת־יֵה֔וּא וַ⁠יֹּ֖אמֶר הֲ⁠שָׁל֣וֹם יֵה֑וּא וַ⁠יֹּ֨אמֶר֙ מָ֣ה הַ⁠שָּׁל֔וֹם עַד־זְנוּנֵ֞י אִיזֶ֧בֶל אִמְּ⁠ךָ֛ וּ⁠כְשָׁפֶ֖י⁠הָ הָ⁠רַבִּֽים׃","wa⁠yĕhi֗y ki̇⁠rĕʼ֤wòţ yĕhwòrám֙ ʼeţ-yéh֔ẇʼ wa⁠yò֖̇ʼmer hà⁠şá̌l֣wòm yéh֑ẇʼ wa⁠yò̇֨ʼmer֙ má֣h ha⁠şá̇̌l֔wòm ʻad-zĕnẇné֞y ʼiyze֧bel ʼimĕ̇⁠ká֛ ẇ⁠kĕşá̌pe֖y⁠há há⁠rabiֽ̇ym׃"],[9,23,"וַ⁠יַּהֲפֹ֧ךְ יְהוֹרָ֛ם יָדָ֖י⁠ו וַ⁠יָּנֹ֑ס וַ⁠יֹּ֥אמֶר אֶל־אֲחַזְיָ֖הוּ מִרְמָ֥ה אֲחַזְיָֽה׃","wa⁠yȧhàpò֧kĕ yĕhwòrá֛m yádá֖y⁠w wa⁠yá̇nò֑s wa⁠yò֥̇ʼmer ʼel-ʼàẖazĕyá֖hẇ mirĕmá֥h ʼàẖazĕyáֽh׃"],[9,24,"וְ⁠יֵה֞וּא מִלֵּ֧א יָד֣⁠וֹ בַ⁠קֶּ֗שֶׁת וַ⁠יַּ֤ךְ אֶת־יְהוֹרָם֙ בֵּ֣ין זְרֹעָ֔י⁠ו וַ⁠יֵּצֵ֥א הַ⁠חֵ֖צִי מִ⁠לִּבּ֑⁠וֹ וַ⁠יִּכְרַ֖ע בְּ⁠רִכְבּֽ⁠וֹ׃","wĕ⁠yéh֞ẇʼ milé֧̇ʼ yád֣⁠wò ba⁠qė֗şěţ wa⁠yȧ֤kĕ ʼeţ-yĕhwòrám֙ bé֣̇yn zĕròʻá֔y⁠w wa⁠yé̇ẕé֥ʼ ha⁠ẖé֖ẕiy mi⁠li̇ḃ֑⁠wò wa⁠yi̇kĕra֖ʻ bĕ̇⁠rikĕḃֽ⁠wò׃"],[9,25,"וַ⁠יֹּ֗אמֶר אֶל־בִּדְקַר֙ שלשה שָׂ֚א הַשְׁלִכֵ֔⁠הוּ בְּ⁠חֶלְקַ֕ת שְׂדֵ֖ה נָב֣וֹת הַ⁠יִּזְרְעֵאלִ֑י כִּֽי־זְכֹ֞ר אֲנִ֣י וָ⁠אַ֗תָּה אֵ֣ת רֹכְבִ֤ים צְמָדִים֙ אַֽחֲרֵי֙ אַחְאָ֣ב אָבִ֔י⁠ו וַֽ⁠יהוָה֙ נָשָׂ֣א עָלָ֔י⁠ו אֶת־הַ⁠מַּשָּׂ֖א הַ⁠זֶּֽה׃","wa⁠yò̇֗ʼmer ʼel-bi̇dĕqar֙ şlşh şá֚̂ʼ haşĕ̌liké֔⁠hẇ bĕ̇⁠ẖelĕqa֕ţ şĕ̂dé֖h náb֣wòţ ha⁠yi̇zĕrĕʻéʼli֑y kiֽ̇y-zĕkò֞r ʼàni֣y wá⁠ʼa֗ţá̇h ʼé֣ţ ròkĕbi֤ym ẕĕmádiym֙ ʼaֽẖàréy֙ ʼaẖĕʼá֣b ʼábi֔y⁠w waֽ⁠yhwáh֙ náşá֣̂ʼ ʻálá֔y⁠w ʼeţ-ha⁠mȧşá֖̇̂ʼ ha⁠zėֽh׃"],[9,26,"אִם־לֹ֡א אֶת־דְּמֵ֣י נָבוֹת֩ וְ⁠אֶת־דְּמֵ֨י בָנָ֜י⁠ו רָאִ֤יתִי אֶ֨מֶשׁ֙ נְאֻם־יְהוָ֔ה וְ⁠שִׁלַּמְתִּ֥י לְ⁠ךָ֛ בַּ⁠חֶלְקָ֥ה הַ⁠זֹּ֖את נְאֻם־יְהוָ֑ה וְ⁠עַתָּ֗ה שָׂ֧א הַשְׁלִכֵ֛⁠הוּ בַּ⁠חֶלְקָ֖ה כִּ⁠דְבַ֥ר יְהוָֽה׃","ʼim-lò֡ʼ ʼeţ-dĕ̇mé֣y nábwòţ֩ wĕ⁠ʼeţ-dĕ̇mé֨y báná֜y⁠w ráʼi֤yţiy ʼe֨meş̌֙ nĕʼum-yĕhwá֔h wĕ⁠şǐlȧmĕţi֥̇y lĕ⁠ká֛ bȧ⁠ẖelĕqá֥h ha⁠zò֖̇ʼţ nĕʼum-yĕhwá֑h wĕ⁠ʻaţá̇֗h şá֧̂ʼ haşĕ̌liké֛⁠hẇ bȧ⁠ẖelĕqá֖h ki̇⁠dĕba֥r yĕhwáֽh׃"],[9,27,"וַ⁠אֲחַזְיָ֤ה מֶֽלֶךְ־יְהוּדָה֙ רָאָ֔ה וַ⁠יָּ֕נָס דֶּ֖רֶךְ בֵּ֣ית הַגָּ֑ן וַ⁠יִּרְדֹּ֨ף אַחֲרָ֜י⁠ו יֵה֗וּא וַ֠⁠יֹּאמֶר גַּם־אֹת֞⁠וֹ הַכֻּ֣⁠הוּ אֶל־הַ⁠מֶּרְכָּבָ֗ה בְּ⁠מַֽעֲלֵה־גוּר֙ אֲשֶׁ֣ר אֶֽת־יִבְלְעָ֔ם וַ⁠יָּ֥נָס מְגִדּ֖וֹ וַ⁠יָּ֥מָת שָֽׁם׃","wa⁠ʼàẖazĕyá֤h meֽlekĕ-yĕhẇdáh֙ ráʼá֔h wa⁠yá̇֕nás dė֖rekĕ bé֣̇yţ hagá֑̇n wa⁠yi̇rĕdò̇֨p ʼaẖàrá֜y⁠w yéh֗ẇʼ wa֠⁠yò̇ʼmer gȧm-ʼòţ֞⁠wò haku֣̇⁠hẇ ʼel-ha⁠mėrĕká̇bá֗h bĕ̇⁠maֽʻàléh-gẇr֙ ʼàşě֣r ʼeֽţ-yibĕlĕʻá֔m wa⁠yá֥̇nás mĕgiḋ֖wò wa⁠yá֥̇máţ şáֽ̌m׃"],[9,28,"וַ⁠יַּרְכִּ֧בוּ אֹת֛⁠וֹ עֲבָדָ֖י⁠ו יְרוּשָׁלְָ֑מָ⁠ה וַ⁠יִּקְבְּר֨וּ אֹת֧⁠וֹ בִ⁠קְבֻרָת֛⁠וֹ עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֥יר דָּוִֽד׃פ","wa⁠yȧrĕki֧̇bẇ ʼòţ֛⁠wò ʻàbádá֖y⁠w yĕrẇşá̌lĕá֑má⁠h wa⁠yi̇qĕbĕ̇r֨ẇ ʼòţ֧⁠wò bi⁠qĕburáţ֛⁠wò ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֥yr dá̇wiֽd׃p"],[9,29,"וּ⁠בִ⁠שְׁנַת֙ אַחַ֣ת עֶשְׂרֵ֣ה שָׁנָ֔ה לְ⁠יוֹרָ֖ם בֶּן־אַחְאָ֑ב מָלַ֥ךְ אֲחַזְיָ֖ה עַל־יְהוּדָֽה׃","ẇ⁠bi⁠şĕ̌naţ֙ ʼaẖa֣ţ ʻeşĕ̂ré֣h şá̌ná֔h lĕ⁠ywòrá֖m bėn-ʼaẖĕʼá֑b mála֥kĕ ʼàẖazĕyá֖h ʻal-yĕhẇdáֽh׃"],[9,30,"וַ⁠יָּב֥וֹא יֵה֖וּא יִזְרְעֶ֑אלָ⁠ה וְ⁠אִיזֶ֣בֶל שָׁמְעָ֗ה וַ⁠תָּ֨שֶׂם בַּ⁠פּ֤וּךְ עֵינֶ֨י⁠הָ֙ וַ⁠תֵּ֣יטֶב אֶת־רֹאשָׁ֔⁠הּ וַ⁠תַּשְׁקֵ֖ף בְּעַ֥ד הַ⁠חַלּֽוֹן׃","wa⁠yá̇b֥wòʼ yéh֖ẇʼ yizĕrĕʻe֑ʼlá⁠h wĕ⁠ʼiyze֣bel şá̌mĕʻá֗h wa⁠ţá̇֨şêm bȧ⁠ṗ֤ẇkĕ ʻéyne֨y⁠há֙ wa⁠ţé֣̇yteb ʼeţ-ròʼşá̌֔⁠ḣ wa⁠ţȧşĕ̌qé֖p bĕ̇ʻa֥d ha⁠ẖalֽ̇wòn׃"],[9,31,"וְ⁠יֵה֖וּא בָּ֣א בַ⁠שָּׁ֑עַר וַ⁠תֹּ֣אמֶר הֲ⁠שָׁל֔וֹם זִמְרִ֖י הֹרֵ֥ג אֲדֹנָֽי⁠ו׃","wĕ⁠yéh֖ẇʼ bá֣̇ʼ ba⁠şá֑̇̌ʻar wa⁠ţò֣̇ʼmer hà⁠şá̌l֔wòm zimĕri֖y hòré֥g ʼàdònáֽy⁠w׃"],[9,32,"וַ⁠יִּשָּׂ֤א פָנָי⁠ו֙ אֶל־הַ֣⁠חַלּ֔וֹן וַ⁠יֹּ֕אמֶר מִ֥י אִתִּ֖⁠י מִ֑י וַ⁠יַּשְׁקִ֣יפוּ אֵלָ֔י⁠ו שְׁנַ֥יִם שְׁלֹשָׁ֖ה סָרִיסִֽים׃","wa⁠yi̇şá֤̇̂ʼ pánáy⁠w֙ ʼel-ha֣⁠ẖal̇֔wòn wa⁠yò̇֕ʼmer mi֥y ʼiţi֖̇⁠y mi֑y wa⁠yȧşĕ̌qi֣ypẇ ʼélá֔y⁠w şĕ̌na֥yim şĕ̌lòşá֖̌h sáriysiֽym׃"],[9,33,"וַ⁠יֹּ֥אמֶר שמט⁠הו וַֽ⁠יִּשְׁמְט֑וּ⁠הָ וַ⁠יִּ֨ז מִ⁠דָּמָ֧⁠הּ אֶל־הַ⁠קִּ֛יר וְ⁠אֶל־הַ⁠סּוּסִ֖ים וַֽ⁠יִּרְמְסֶֽ⁠נָּה׃","wa⁠yò֥̇ʼmer şmt⁠hw waֽ⁠yi̇şĕ̌mĕt֑ẇ⁠há wa⁠yi̇֨z mi⁠dá̇má֧⁠ḣ ʼel-ha⁠qi֛̇yr wĕ⁠ʼel-ha⁠ṡẇsi֖ym waֽ⁠yi̇rĕmĕseֽ⁠ná̇h׃"],[9,34,"וַ⁠יָּבֹ֖א וַ⁠יֹּ֣אכַל וַ⁠יֵּ֑שְׁתְּ וַ⁠יֹּ֗אמֶר פִּקְדוּ־נָ֞א אֶת־הָ⁠אֲרוּרָ֤ה הַ⁠זֹּאת֙ וְ⁠קִבְר֔וּ⁠הָ כִּ֥י בַת־מֶ֖לֶךְ הִֽיא׃","wa⁠yá̇bò֖ʼ wa⁠yò֣̇ʼkal wa⁠yé֑̇şĕ̌ţĕ̇ wa⁠yò̇֗ʼmer pi̇qĕdẇ-ná֞ʼ ʼeţ-há⁠ʼàrẇrá֤h ha⁠zò̇ʼţ֙ wĕ⁠qibĕr֔ẇ⁠há ki֥̇y baţ-me֖lekĕ hiֽyʼ׃"],[9,35,"וַ⁠יֵּלְכ֖וּ לְ⁠קָבְרָ֑⁠הּ וְ⁠לֹא־מָ֣צְאוּ בָ֗⁠הּ כִּ֧י אִם־הַ⁠גֻּלְגֹּ֛לֶת וְ⁠הָ⁠רַגְלַ֖יִם וְ⁠כַפּ֥וֹת הַ⁠יָּדָֽיִם׃","wa⁠yé̇lĕk֖ẇ lĕ⁠qábĕrá֑⁠ḣ wĕ⁠lòʼ-má֣ẕĕʼẇ bá֗⁠ḣ ki֧̇y ʼim-ha⁠gu̇lĕgò֛̇leţ wĕ⁠há⁠ragĕla֖yim wĕ⁠kaṗ֥wòţ ha⁠yá̇dáֽyim׃"],[9,36,"וַ⁠יָּשֻׁבוּ֮ וַ⁠יַּגִּ֣ידוּ ל⁠וֹ֒ וַ⁠יֹּ֨אמֶר֙ דְּבַר־יְהוָ֣ה ה֔וּא אֲשֶׁ֣ר דִּבֶּ֗ר בְּ⁠יַד־עַבְדּ֛⁠וֹ אֵלִיָּ֥הוּ הַ⁠תִּשְׁבִּ֖י לֵ⁠אמֹ֑ר בְּ⁠חֵ֣לֶק יִזְרְעֶ֔אל יֹאכְל֥וּ הַ⁠כְּלָבִ֖ים אֶת־בְּשַׂ֥ר אִיזָֽבֶל׃","wa⁠yá̇şǔbẇ֮ wa⁠yȧgi֣̇ydẇ l⁠wò֒ wa⁠yò̇֨ʼmer֙ dĕ̇bar-yĕhwá֣h h֔ẇʼ ʼàşě֣r di̇bė֗r bĕ̇⁠yad-ʻabĕḋ֛⁠wò ʼéliyá֥̇hẇ ha⁠ţi̇şĕ̌bi֖̇y lé⁠ʼmò֑r bĕ̇⁠ẖé֣leq yizĕrĕʻe֔ʼl yòʼkĕl֥ẇ ha⁠kĕ̇lábi֖ym ʼeţ-bĕ̇şâ֥r ʼiyzáֽbel׃"],[9,37,"ו⁠הית נִבְלַ֣ת אִיזֶ֗בֶל כְּ⁠דֹ֛מֶן עַל־פְּנֵ֥י הַ⁠שָּׂדֶ֖ה בְּ⁠חֵ֣לֶק יִזְרְעֶ֑אל אֲשֶׁ֥ר לֹֽא־יֹאמְר֖וּ זֹ֥את אִיזָֽבֶל׃פ","w⁠hyţ nibĕla֣ţ ʼiyze֗bel kĕ̇⁠dò֛men ʻal-pĕ̇né֥y ha⁠şá̇̂de֖h bĕ̇⁠ẖé֣leq yizĕrĕʻe֑ʼl ʼàşě֥r lòֽʼ-yòʼmĕr֖ẇ zò֥ʼţ ʼiyzáֽbel׃p"],[10,1,"וּ⁠לְ⁠אַחְאָ֛ב שִׁבְעִ֥ים בָּנִ֖ים בְּ⁠שֹׁמְר֑וֹן וַ⁠יִּכְתֹּב֩ יֵה֨וּא סְפָרִ֜ים וַ⁠יִּשְׁלַ֣ח שֹׁמְר֗וֹן אֶל־שָׂרֵ֤י יִזְרְעֶאל֙ הַ⁠זְּקֵנִ֔ים וְ⁠אֶל־הָ⁠אֹמְנִ֥ים אַחְאָ֖ב לֵ⁠אמֹֽר׃","ẇ⁠lĕ⁠ʼaẖĕʼá֛b şǐbĕʻi֥ym bá̇ni֖ym bĕ̇⁠şò̌mĕr֑wòn wa⁠yi̇kĕţò̇b֩ yéh֨ẇʼ sĕpári֜ym wa⁠yi̇şĕ̌la֣ẖ şò̌mĕr֗wòn ʼel-şá̂ré֤y yizĕrĕʻeʼl֙ ha⁠zĕ̇qéni֔ym wĕ⁠ʼel-há⁠ʼòmĕni֥ym ʼaẖĕʼá֖b lé⁠ʼmòֽr׃"],[10,2,"וְ⁠עַתָּ֗ה כְּ⁠בֹ֨א הַ⁠סֵּ֤פֶר הַ⁠זֶּה֙ אֲלֵי⁠כֶ֔ם וְ⁠אִתְּ⁠כֶ֖ם בְּנֵ֣י אֲדֹנֵי⁠כֶ֑ם וְ⁠אִתְּ⁠כֶם֙ הָ⁠רֶ֣כֶב וְ⁠הַ⁠סּוּסִ֔ים וְ⁠עִ֥יר מִבְצָ֖ר וְ⁠הַ⁠נָּֽשֶׁק׃","wĕ⁠ʻaţá̇֗h kĕ̇⁠bò֨ʼ ha⁠sé֤̇per ha⁠zėh֙ ʼàléy⁠ke֔m wĕ⁠ʼiţĕ̇⁠ke֖m bĕ̇né֣y ʼàdònéy⁠ke֑m wĕ⁠ʼiţĕ̇⁠kem֙ há⁠re֣keb wĕ⁠ha⁠ṡẇsi֔ym wĕ⁠ʻi֥yr mibĕẕá֖r wĕ⁠ha⁠náֽ̇şěq׃"],[10,3,"וּ⁠רְאִיתֶ֞ם הַ⁠טּ֤וֹב וְ⁠הַ⁠יָּשָׁר֙ מִ⁠בְּנֵ֣י אֲדֹנֵי⁠כֶ֔ם וְ⁠שַׂמְתֶּ֖ם עַל־כִּסֵּ֣א אָבִ֑י⁠ו וְ⁠הִֽלָּחֲמ֖וּ עַל־בֵּ֥ית אֲדֹנֵי⁠כֶֽם׃","ẇ⁠rĕʼiyţe֞m ha⁠ṫ֤wòb wĕ⁠ha⁠yá̇şá̌r֙ mi⁠bĕ̇né֣y ʼàdònéy⁠ke֔m wĕ⁠şâmĕţė֖m ʻal-ki̇sé֣̇ʼ ʼábi֑y⁠w wĕ⁠hiֽlá̇ẖàm֖ẇ ʻal-bé֥̇yţ ʼàdònéy⁠keֽm׃"],[10,4,"וַ⁠יִּֽרְאוּ֙ מְאֹ֣ד מְאֹ֔ד וַ⁠יֹּ֣אמְר֔וּ הִנֵּה֙ שְׁנֵ֣י הַ⁠מְּלָכִ֔ים לֹ֥א עָמְד֖וּ לְ⁠פָנָ֑י⁠ו וְ⁠אֵ֖יךְ נַעֲמֹ֥ד אֲנָֽחְנוּ׃","wa⁠yiֽ̇rĕʼẇ֙ mĕʼò֣d mĕʼò֔d wa⁠yò֣̇ʼmĕr֔ẇ hiné̇h֙ şĕ̌né֣y ha⁠mĕ̇láki֔ym lò֥ʼ ʻámĕd֖ẇ lĕ⁠páná֑y⁠w wĕ⁠ʼé֖ykĕ naʻàmò֥d ʼànáֽẖĕnẇ׃"],[10,5,"וַ⁠יִּשְׁלַ֣ח אֲשֶׁר־עַל־הַ⁠בַּ֣יִת וַ⁠אֲשֶׁ֪ר עַל־הָ⁠עִ֟יר וְ⁠הַ⁠זְּקֵנִים֩ וְ⁠הָ⁠אֹמְנִ֨ים אֶל־יֵה֤וּא ׀ לֵ⁠אמֹר֙ עֲבָדֶ֣י⁠ךָ אֲנַ֔חְנוּ וְ⁠כֹ֛ל אֲשֶׁר־תֹּאמַ֥ר אֵלֵ֖י⁠נוּ נַעֲשֶׂ֑ה לֹֽא־נַמְלִ֣יךְ אִ֔ישׁ הַ⁠טּ֥וֹב בְּ⁠עֵינֶ֖י⁠ךָ עֲשֵֽׂה׃","wa⁠yi̇şĕ̌la֣ẖ ʼàşěr-ʻal-ha⁠bȧ֣yiţ wa⁠ʼàşě֪r ʻal-há⁠ʻi֟yr wĕ⁠ha⁠zĕ̇qéniym֩ wĕ⁠há⁠ʼòmĕni֨ym ʼel-yéh֤ẇʼ ׀ lé⁠ʼmòr֙ ʻàbáde֣y⁠ká ʼàna֔ẖĕnẇ wĕ⁠kò֛l ʼàşěr-ţò̇ʼma֥r ʼélé֖y⁠nẇ naʻàşê֑h lòֽʼ-namĕli֣ykĕ ʼi֔yş̌ ha⁠ṫ֥wòb bĕ̇⁠ʻéyne֖y⁠ká ʻàşéֽ̂h׃"],[10,6,"וַ⁠יִּכְתֹּ֣ב אֲלֵי⁠הֶם֩ סֵ֨פֶר ׀ שֵׁנִ֜ית לֵ⁠אמֹ֗ר אִם־לִ֨⁠י אַתֶּ֜ם וּ⁠לְ⁠קֹלִ֣⁠י ׀ אַתֶּ֣ם שֹׁמְעִ֗ים קְחוּ֙ אֶת־רָאשֵׁי֙ אַנְשֵׁ֣י בְנֵֽי־אֲדֹנֵי⁠כֶ֔ם וּ⁠בֹ֧אוּ אֵלַ֛⁠י כָּ⁠עֵ֥ת מָחָ֖ר יִזְרְעֶ֑אלָ⁠ה וּ⁠בְנֵ֤י הַ⁠מֶּ֨לֶךְ֙ שִׁבְעִ֣ים אִ֔ישׁ אֶת־גְּדֹלֵ֥י הָ⁠עִ֖יר מְגַדְּלִ֥ים אוֹתָֽ⁠ם׃","wa⁠yi̇kĕţò֣̇b ʼàléy⁠hem֩ sé֨per ׀ şé̌ni֜yţ lé⁠ʼmò֗r ʼim-li֨⁠y ʼaţė֜m ẇ⁠lĕ⁠qòli֣⁠y ׀ ʼaţė֣m şò̌mĕʻi֗ym qĕẖẇ֙ ʼeţ-ráʼşé̌y֙ ʼanĕşé֣̌y bĕnéֽy-ʼàdònéy⁠ke֔m ẇ⁠bò֧ʼẇ ʼéla֛⁠y ká̇⁠ʻé֥ţ máẖá֖r yizĕrĕʻe֑ʼlá⁠h ẇ⁠bĕné֤y ha⁠mė֨lekĕ֙ şǐbĕʻi֣ym ʼi֔yş̌ ʼeţ-gĕ̇dòlé֥y há⁠ʻi֖yr mĕgadĕ̇li֥ym ʼwòţáֽ⁠m׃"],[10,7,"וַ⁠יְהִ֗י כְּ⁠בֹ֤א הַ⁠סֵּ֨פֶר֙ אֲלֵי⁠הֶ֔ם וַ⁠יִּקְחוּ֙ אֶת־בְּנֵ֣י הַ⁠מֶּ֔לֶךְ וַֽ⁠יִּשְׁחֲט֖וּ שִׁבְעִ֣ים אִ֑ישׁ וַ⁠יָּשִׂ֤ימוּ אֶת־רָֽאשֵׁי⁠הֶם֙ בַּ⁠דּוּדִ֔ים וַ⁠יִּשְׁלְח֥וּ אֵלָ֖י⁠ו יִזְרְעֶֽאלָ⁠ה׃","wa⁠yĕhi֗y kĕ̇⁠bò֤ʼ ha⁠sé̇֨per֙ ʼàléy⁠he֔m wa⁠yi̇qĕẖẇ֙ ʼeţ-bĕ̇né֣y ha⁠mė֔lekĕ waֽ⁠yi̇şĕ̌ẖàt֖ẇ şǐbĕʻi֣ym ʼi֑yş̌ wa⁠yá̇şî֤ymẇ ʼeţ-ráֽʼşé̌y⁠hem֙ bȧ⁠ḋẇdi֔ym wa⁠yi̇şĕ̌lĕẖ֥ẇ ʼélá֖y⁠w yizĕrĕʻeֽʼlá⁠h׃"],[10,8,"וַ⁠יָּבֹ֤א הַ⁠מַּלְאָךְ֙ וַ⁠יַּגֶּד־ל֣⁠וֹ לֵ⁠אמֹ֔ר הֵבִ֖יאוּ רָאשֵׁ֣י בְנֵֽי־הַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֗אמֶר שִׂ֣ימוּ אֹתָ֞⁠ם שְׁנֵ֧י צִבֻּרִ֛ים פֶּ֥תַח הַ⁠שַּׁ֖עַר עַד־הַ⁠בֹּֽקֶר׃","wa⁠yá̇bò֤ʼ ha⁠mȧlĕʼákĕ֙ wa⁠yȧgėd-l֣⁠wò lé⁠ʼmò֔r hébi֖yʼẇ ráʼşé֣̌y bĕnéֽy-ha⁠mė֑lekĕ wa⁠yò̇֗ʼmer şî֣ymẇ ʼòţá֞⁠m şĕ̌né֧y ẕibu̇ri֛ym pė֥ţaẖ ha⁠şȧ֖̌ʻar ʻad-ha⁠bòֽ̇qer׃"],[10,9,"וַ⁠יְהִ֤י בַ⁠בֹּ֨קֶר֙ וַ⁠יֵּצֵ֣א וַֽ⁠יַּעֲמֹ֔ד וַ⁠יֹּ֨אמֶר֙ אֶל־כָּל־הָ⁠עָ֔ם צַדִּקִ֖ים אַתֶּ֑ם הִנֵּ֨ה אֲנִ֜י קָשַׁ֤רְתִּי עַל־אֲדֹנִ⁠י֙ וָ⁠אֶהְרְגֵ֔⁠הוּ וּ⁠מִ֥י הִכָּ֖ה אֶת־כָּל־אֵֽלֶּה׃","wa⁠yĕhi֤y ba⁠bò̇֨qer֙ wa⁠yé̇ẕé֣ʼ waֽ⁠yȧʻàmò֔d wa⁠yò̇֨ʼmer֙ ʼel-ká̇l-há⁠ʻá֔m ẕadi̇qi֖ym ʼaţė֑m hiné̇֨h ʼàni֜y qáşǎ֤rĕţi̇y ʻal-ʼàdòni⁠y֙ wá⁠ʼehĕrĕgé֔⁠hẇ ẇ⁠mi֥y hiká֖̇h ʼeţ-ká̇l-ʼéֽlėh׃"],[10,10,"דְּע֣וּ אֵפ֗וֹא כִּי֩ לֹ֨א יִפֹּ֜ל מִ⁠דְּבַ֤ר יְהוָה֙ אַ֔רְצָ⁠ה אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה עַל־בֵּ֣ית אַחְאָ֑ב וַ⁠יהוָ֣ה עָשָׂ֔ה אֵ֚ת אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַ֖ד עַבְדּ֥⁠וֹ אֵלִיָּֽהוּ׃","dĕ̇ʻ֣ẇ ʼép֗wòʼ ki̇y֩ lò֨ʼ yipò̇֜l mi⁠dĕ̇ba֤r yĕhwáh֙ ʼa֔rĕẕá⁠h ʼàşěr-di̇bė֥r yĕhwá֖h ʻal-bé֣̇yţ ʼaẖĕʼá֑b wa⁠yhwá֣h ʻáşá̂֔h ʼé֚ţ ʼàşě֣r di̇bė֔r bĕ̇⁠ya֖d ʻabĕḋ֥⁠wò ʼéliyáֽ̇hẇ׃"],[10,11,"וַ⁠יַּ֣ךְ יֵה֗וּא אֵ֣ת כָּל־הַ⁠נִּשְׁאָרִ֤ים לְ⁠בֵית־אַחְאָב֙ בְּ⁠יִזְרְעֶ֔אל וְ⁠כָל־גְּדֹלָ֖י⁠ו וּ⁠מְיֻדָּעָ֣י⁠ו וְ⁠כֹהֲנָ֑י⁠ו עַד־בִּלְתִּ֥י הִשְׁאִֽיר־ל֖⁠וֹ שָׂרִֽיד׃","wa⁠yȧ֣kĕ yéh֗ẇʼ ʼé֣ţ ká̇l-ha⁠ni̇şĕ̌ʼári֤ym lĕ⁠béyţ-ʼaẖĕʼáb֙ bĕ̇⁠yizĕrĕʻe֔ʼl wĕ⁠kál-gĕ̇dòlá֖y⁠w ẇ⁠mĕyudá̇ʻá֣y⁠w wĕ⁠kòhàná֑y⁠w ʻad-bi̇lĕţi֥̇y hişĕ̌ʼiֽyr-l֖⁠wò şá̂riֽyd׃"],[10,12,"וַ⁠יָּ֨קָם֙ וַ⁠יָּבֹ֔א וַ⁠יֵּ֖לֶךְ שֹׁמְר֑וֹן ה֛וּא בֵּֽית־עֵ֥קֶד הָרֹעִ֖ים בַּ⁠דָּֽרֶךְ׃","wa⁠yá̇֨qám֙ wa⁠yá̇bò֔ʼ wa⁠yé֖̇lekĕ şò̌mĕr֑wòn h֛ẇʼ béֽ̇yţ-ʻé֥qed háròʻi֖ym bȧ⁠dáֽ̇rekĕ׃"],[10,13,"וְ⁠יֵה֗וּא מָצָא֙ אֶת־אֲחֵי֙ אֲחַזְיָ֣הוּ מֶֽלֶךְ־יְהוּדָ֔ה וַ⁠יֹּ֖אמֶר מִ֣י אַתֶּ֑ם וַ⁠יֹּאמְר֗וּ אֲחֵ֤י אֲחַזְיָ֨הוּ֙ אֲנַ֔חְנוּ וַ⁠נֵּ֛רֶד לִ⁠שְׁל֥וֹם בְּנֵֽי־הַ⁠מֶּ֖לֶךְ וּ⁠בְנֵ֥י הַ⁠גְּבִירָֽה׃","wĕ⁠yéh֗ẇʼ máẕáʼ֙ ʼeţ-ʼàẖéy֙ ʼàẖazĕyá֣hẇ meֽlekĕ-yĕhẇdá֔h wa⁠yò֖̇ʼmer mi֣y ʼaţė֑m wa⁠yò̇ʼmĕr֗ẇ ʼàẖé֤y ʼàẖazĕyá֨hẇ֙ ʼàna֔ẖĕnẇ wa⁠né֛̇red li⁠şĕ̌l֥wòm bĕ̇néֽy-ha⁠mė֖lekĕ ẇ⁠bĕné֥y ha⁠gĕ̇biyráֽh׃"],[10,14,"וַ⁠יֹּ֨אמֶר֙ תִּפְשׂ֣וּ⁠ם חַיִּ֔ים וַֽ⁠יִּתְפְּשׂ֖וּ⁠ם חַיִּ֑ים וַֽ⁠יִּשְׁחָט֞וּ⁠ם אֶל־בּ֣וֹר בֵּֽית־עֵ֗קֶד אַרְבָּעִ֤ים וּ⁠שְׁנַ֨יִם֙ אִ֔ישׁ וְ⁠לֹֽא־הִשְׁאִ֥יר אִ֖ישׁ מֵ⁠הֶֽם׃ס","wa⁠yò̇֨ʼmer֙ ţi̇pĕş֣̂ẇ⁠m ẖayi̇֔ym waֽ⁠yi̇ţĕpĕ̇ş֖̂ẇ⁠m ẖayi֑̇ym waֽ⁠yi̇şĕ̌ẖát֞ẇ⁠m ʼel-ḃ֣wòr béֽ̇yţ-ʻé֗qed ʼarĕbá̇ʻi֤ym ẇ⁠şĕ̌na֨yim֙ ʼi֔yş̌ wĕ⁠lòֽʼ-hişĕ̌ʼi֥yr ʼi֖yş̌ mé⁠heֽm׃s"],[10,15,"וַ⁠יֵּ֣לֶךְ מִ⁠שָּׁ֡ם וַ⁠יִּמְצָ֣א אֶת־יְהוֹנָדָב֩ בֶּן־רֵכָ֨ב לִ⁠קְרָאת֜⁠וֹ וַֽ⁠יְבָרְכֵ֗⁠הוּ וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו הֲ⁠יֵ֧שׁ אֶת־לְבָבְ⁠ךָ֣ יָשָׁ֗ר כַּ⁠אֲשֶׁ֤ר לְבָבִ⁠י֙ עִם־לְבָבֶ֔⁠ךָ וַ⁠יֹּ֨אמֶר יְהוֹנָדָ֥ב יֵ֛שׁ וָ⁠יֵ֖שׁ תְּנָ֣⁠ה אֶת־יָדֶ֑⁠ךָ וַ⁠יִּתֵּ֣ן יָד֔⁠וֹ וַ⁠יַּעֲלֵ֥⁠הוּ אֵלָ֖י⁠ו אֶל־הַ⁠מֶּרְכָּבָֽה׃","wa⁠yé֣̇lekĕ mi⁠şá̇̌֡m wa⁠yi̇mĕẕá֣ʼ ʼeţ-yĕhwònádáb֩ bėn-réká֨b li⁠qĕráʼţ֜⁠wò waֽ⁠yĕbárĕké֗⁠hẇ wa⁠yò̇֨ʼmer ʼélá֜y⁠w hà⁠yé֧ş̌ ʼeţ-lĕbábĕ⁠ká֣ yáşá̌֗r kȧ⁠ʼàşě֤r lĕbábi⁠y֙ ʻim-lĕbábe֔⁠ká wa⁠yò̇֨ʼmer yĕhwònádá֥b yé֛ş̌ wá⁠yé֖ş̌ ţĕ̇ná֣⁠h ʼeţ-yáde֑⁠ká wa⁠yi̇ţé֣̇n yád֔⁠wò wa⁠yȧʻàlé֥⁠hẇ ʼélá֖y⁠w ʼel-ha⁠mėrĕká̇báֽh׃"],[10,16,"וַ⁠יֹּ֨אמֶר֙ לְכָ֣⁠ה אִתִּ֔⁠י וּ⁠רְאֵ֖ה בְּ⁠קִנְאָתִ֣⁠י לַ⁠יהוָ֑ה וַ⁠יַּרְכִּ֥בוּ אֹת֖⁠וֹ בְּ⁠רִכְבּֽ⁠וֹ׃","wa⁠yò̇֨ʼmer֙ lĕká֣⁠h ʼiţi̇֔⁠y ẇ⁠rĕʼé֖h bĕ̇⁠qinĕʼáţi֣⁠y la⁠yhwá֑h wa⁠yȧrĕki֥̇bẇ ʼòţ֖⁠wò bĕ̇⁠rikĕḃֽ⁠wò׃"],[10,17,"וַ⁠יָּבֹא֙ שֹֽׁמְר֔וֹן וַ֠⁠יַּךְ אֶת־כָּל־הַ⁠נִּשְׁאָרִ֧ים לְ⁠אַחְאָ֛ב בְּ⁠שֹׁמְר֖וֹן עַד־הִשְׁמִיד֑⁠וֹ כִּ⁠דְבַ֣ר יְהוָ֔ה אֲשֶׁ֥ר דִּבֶּ֖ר אֶל־אֵלִיָּֽהוּ׃פ","wa⁠yá̇bòʼ֙ şòֽ̌mĕr֔wòn wa֠⁠yȧkĕ ʼeţ-ká̇l-ha⁠ni̇şĕ̌ʼári֧ym lĕ⁠ʼaẖĕʼá֛b bĕ̇⁠şò̌mĕr֖wòn ʻad-hişĕ̌miyd֑⁠wò ki̇⁠dĕba֣r yĕhwá֔h ʼàşě֥r di̇bė֖r ʼel-ʼéliyáֽ̇hẇ׃p"],[10,18,"וַ⁠יִּקְבֹּ֤ץ יֵהוּא֙ אֶת־כָּל־הָ⁠עָ֔ם וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם אַחְאָ֕ב עָבַ֥ד אֶת־הַ⁠בַּ֖עַל מְעָ֑ט יֵה֖וּא יַעַבְדֶ֥⁠נּוּ הַרְבֵּֽה׃","wa⁠yi̇qĕbò֤̇ẕ yéhẇʼ֙ ʼeţ-ká̇l-há⁠ʻá֔m wa⁠yò֣̇ʼmer ʼàlé⁠he֔m ʼaẖĕʼá֕b ʻába֥d ʼeţ-ha⁠bȧ֖ʻal mĕʻá֑t yéh֖ẇʼ yaʻabĕde֥⁠ṅẇ harĕbéֽ̇h׃"],[10,19,"וְ⁠עַתָּ֣ה כָל־נְבִיאֵ֣י הַ⁠בַּ֡עַל כָּל־עֹבְדָ֣י⁠ו וְ⁠כָל־כֹּהֲנָי⁠ו֩ קִרְא֨וּ אֵלַ֜⁠י אִ֣ישׁ אַל־יִפָּקֵ֗ד כִּי֩ זֶ֨בַח גָּד֥וֹל לִ⁠י֙ לַ⁠בַּ֔עַל כֹּ֥ל אֲשֶׁר־יִפָּקֵ֖ד לֹ֣א יִֽחְיֶ֑ה וְ⁠יֵהוּא֙ עָשָׂ֣ה בְ⁠עָקְבָּ֔ה לְמַ֥עַן הַאֲבִ֖יד אֶת־עֹבְדֵ֥י הַ⁠בָּֽעַל׃","wĕ⁠ʻaţá֣̇h kál-nĕbiyʼé֣y ha⁠bȧ֡ʻal ká̇l-ʻòbĕdá֣y⁠w wĕ⁠kál-kò̇hànáy⁠w֩ qirĕʼ֨ẇ ʼéla֜⁠y ʼi֣yş̌ ʼal-yipá̇qé֗d ki̇y֩ ze֨baẖ gá̇d֥wòl li⁠y֙ la⁠bȧ֔ʻal kò֥̇l ʼàşěr-yipá̇qé֖d lò֣ʼ yiֽẖĕye֑h wĕ⁠yéhẇʼ֙ ʻáşá֣̂h bĕ⁠ʻáqĕbá̇֔h lĕma֥ʻan haʼàbi֖yd ʼeţ-ʻòbĕdé֥y ha⁠báֽ̇ʻal׃"],[10,20,"וַ⁠יֹּ֣אמֶר יֵה֗וּא קַדְּשׁ֧וּ עֲצָרָ֛ה לַ⁠בַּ֖עַל וַ⁠יִּקְרָֽאוּ׃","wa⁠yò֣̇ʼmer yéh֗ẇʼ qadĕ̇ş֧̌ẇ ʻàẕárá֛h la⁠bȧ֖ʻal wa⁠yi̇qĕráֽʼẇ׃"],[10,21,"וַ⁠יִּשְׁלַ֤ח יֵהוּא֙ בְּ⁠כָל־יִשְׂרָאֵ֔ל וַ⁠יָּבֹ֨אוּ֙ כָּל־עֹבְדֵ֣י הַ⁠בַּ֔עַל וְ⁠לֹֽא־נִשְׁאַ֥ר אִ֖ישׁ אֲשֶׁ֣ר לֹֽא־בָ֑א וַ⁠יָּבֹ֨אוּ֙ בֵּ֣ית הַ⁠בַּ֔עַל וַ⁠יִּמָּלֵ֥א בֵית־הַ⁠בַּ֖עַל פֶּ֥ה לָ⁠פֶֽה׃","wa⁠yi̇şĕ̌la֤ẖ yéhẇʼ֙ bĕ̇⁠kál-yişĕ̂ráʼé֔l wa⁠yá̇bò֨ʼẇ֙ ká̇l-ʻòbĕdé֣y ha⁠bȧ֔ʻal wĕ⁠lòֽʼ-nişĕ̌ʼa֥r ʼi֖yş̌ ʼàşě֣r lòֽʼ-bá֑ʼ wa⁠yá̇bò֨ʼẇ֙ bé֣̇yţ ha⁠bȧ֔ʻal wa⁠yi̇má̇lé֥ʼ béyţ-ha⁠bȧ֖ʻal pė֥h lá⁠peֽh׃"],[10,22,"וַ⁠יֹּ֗אמֶר לַֽ⁠אֲשֶׁר֙ עַל־הַ⁠מֶּלְתָּחָ֔ה הוֹצֵ֣א לְב֔וּשׁ לְ⁠כֹ֖ל עֹבְדֵ֣י הַ⁠בָּ֑עַל וַ⁠יֹּצֵ֥א לָ⁠הֶ֖ם הַ⁠מַּלְבּֽוּשׁ׃","wa⁠yò̇֗ʼmer laֽ⁠ʼàşěr֙ ʻal-ha⁠mėlĕţá̇ẖá֔h hwòẕé֣ʼ lĕb֔ẇş̌ lĕ⁠kò֖l ʻòbĕdé֣y ha⁠bá֑̇ʻal wa⁠yò̇ẕé֥ʼ lá⁠he֖m ha⁠mȧlĕḃֽẇş̌׃"],[10,23,"וַ⁠יָּבֹ֥א יֵה֛וּא וִ⁠יהוֹנָדָ֥ב בֶּן־רֵכָ֖ב בֵּ֣ית הַ⁠בָּ֑עַל וַ⁠יֹּ֜אמֶר לְ⁠עֹבְדֵ֣י הַ⁠בַּ֗עַל חַפְּשׂ֤וּ וּ⁠רְאוּ֙ פֶּן־יֶשׁ־פֹּ֤ה עִמָּ⁠כֶם֙ מֵ⁠עַבְדֵ֣י יְהוָ֔ה כִּ֛י אִם־עֹבְדֵ֥י הַ⁠בַּ֖עַל לְ⁠בַדָּֽ⁠ם׃","wa⁠yá̇bò֥ʼ yéh֛ẇʼ wi⁠yhwònádá֥b bėn-réká֖b bé֣̇yţ ha⁠bá֑̇ʻal wa⁠yò̇֜ʼmer lĕ⁠ʻòbĕdé֣y ha⁠bȧ֗ʻal ẖapĕ̇ş֤̂ẇ ẇ⁠rĕʼẇ֙ pėn-yeş̌-pò֤̇h ʻimá̇⁠kem֙ mé⁠ʻabĕdé֣y yĕhwá֔h ki֛̇y ʼim-ʻòbĕdé֥y ha⁠bȧ֖ʻal lĕ⁠badáֽ̇⁠m׃"],[10,24,"וַ⁠יָּבֹ֕אוּ לַ⁠עֲשׂ֖וֹת זְבָחִ֣ים וְ⁠עֹל֑וֹת וְ⁠יֵה֞וּא שָׂם־ל֤⁠וֹ בַ⁠חוּץ֙ שְׁמֹנִ֣ים אִ֔ישׁ וַ⁠יֹּ֗אמֶר הָ⁠אִ֤ישׁ אֲשֶׁר־יִמָּלֵט֙ מִן־הָ⁠אֲנָשִׁ֗ים אֲשֶׁ֤ר אֲנִי֙ מֵבִ֣יא עַל־יְדֵי⁠כֶ֔ם נַפְשׁ֖⁠וֹ תַּ֥חַת נַפְשֽׁ⁠וֹ׃","wa⁠yá̇bò֕ʼẇ la⁠ʻàş֖̂wòţ zĕbáẖi֣ym wĕ⁠ʻòl֑wòţ wĕ⁠yéh֞ẇʼ şá̂m-l֤⁠wò ba⁠ẖẇẕ֙ şĕ̌mòni֣ym ʼi֔yş̌ wa⁠yò̇֗ʼmer há⁠ʼi֤yş̌ ʼàşěr-yimá̇lét֙ min-há⁠ʼànáşǐ֗ym ʼàşě֤r ʼàniy֙ mébi֣yʼ ʻal-yĕdéy⁠ke֔m napĕş֖̌⁠wò ţȧ֥ẖaţ napĕşֽ̌⁠wò׃"],[10,25,"וַ⁠יְהִ֞י כְּ⁠כַלֹּת֣⁠וֹ ׀ לַ⁠עֲשׂ֣וֹת הָ⁠עֹלָ֗ה וַ⁠יֹּ֣אמֶר יֵ֠הוּא לָ⁠רָצִ֨ים וְ⁠לַ⁠שָּׁלִשִׁ֜ים בֹּ֤אוּ הַכּוּ⁠ם֙ אִ֣ישׁ אַל־יֵצֵ֔א וַ⁠יַּכּ֖וּ⁠ם לְ⁠פִי־חָ֑רֶב וַ⁠יַּשְׁלִ֗כוּ הָֽ⁠רָצִים֙ וְ⁠הַ⁠שָּׁ֣לִשִׁ֔ים וַ⁠יֵּלְכ֖וּ עַד־עִ֥יר בֵּית־הַ⁠בָּֽעַל׃","wa⁠yĕhi֞y kĕ̇⁠kalò̇ţ֣⁠wò ׀ la⁠ʻàş֣̂wòţ há⁠ʻòlá֗h wa⁠yò֣̇ʼmer yé֠hẇʼ lá⁠ráẕi֨ym wĕ⁠la⁠şá̇̌lişǐ֜ym bò֤̇ʼẇ hak̇ẇ⁠m֙ ʼi֣yş̌ ʼal-yéẕé֔ʼ wa⁠yȧk֖̇ẇ⁠m lĕ⁠piy-ẖá֑reb wa⁠yȧşĕ̌li֗kẇ háֽ⁠ráẕiym֙ wĕ⁠ha⁠şá֣̇̌lişǐ֔ym wa⁠yé̇lĕk֖ẇ ʻad-ʻi֥yr bé̇yţ-ha⁠báֽ̇ʻal׃"],[10,26,"וַ⁠יֹּצִ֛אוּ אֶת־מַצְּב֥וֹת בֵּית־הַ⁠בַּ֖עַל וַֽ⁠יִּשְׂרְפֽוּ⁠הָ׃","wa⁠yò̇ẕi֛ʼẇ ʼeţ-maẕĕ̇b֥wòţ bé̇yţ-ha⁠bȧ֖ʻal waֽ⁠yi̇şĕ̂rĕpֽẇ⁠há׃"],[10,27,"וַֽ⁠יִּתְּצ֔וּ אֵ֖ת מַצְּבַ֣ת הַ⁠בָּ֑עַל וַֽ⁠יִּתְּצוּ֙ אֶת־בֵּ֣ית הַ⁠בַּ֔עַל וַ⁠יְשִׂמֻ֥⁠הוּ ל⁠מחראות עַד־הַ⁠יּֽוֹם׃","waֽ⁠yi̇ţĕ̇ẕ֔ẇ ʼé֖ţ maẕĕ̇ba֣ţ ha⁠bá֑̇ʻal waֽ⁠yi̇ţĕ̇ẕẇ֙ ʼeţ-bé֣̇yţ ha⁠bȧ֔ʻal wa⁠yĕşîmu֥⁠hẇ l⁠mẖrʼwţ ʻad-ha⁠ẏֽwòm׃"],[10,28,"וַ⁠יַּשְׁמֵ֥ד יֵה֛וּא אֶת־הַ⁠בַּ֖עַל מִ⁠יִּשְׂרָאֵֽל׃","wa⁠yȧşĕ̌mé֥d yéh֛ẇʼ ʼeţ-ha⁠bȧ֖ʻal mi⁠yi̇şĕ̂ráʼéֽl׃"],[10,29,"רַ֠ק חֲטָאֵ֞י יָרָבְעָ֤ם בֶּן־נְבָט֙ אֲשֶׁ֣ר הֶחֱטִ֣יא אֶת־יִשְׂרָאֵ֔ל לֹֽא־סָ֥ר יֵה֖וּא מֵ⁠אַֽחֲרֵי⁠הֶ֑ם עֶגְלֵי֙ הַ⁠זָּהָ֔ב אֲשֶׁ֥ר בֵּֽית־אֵ֖ל וַ⁠אֲשֶׁ֥ר בְּ⁠דָֽן׃ס","ra֠q ẖàtáʼé֞y yárábĕʻá֤m bėn-nĕbát֙ ʼàşě֣r heẖèti֣yʼ ʼeţ-yişĕ̂ráʼé֔l lòֽʼ-sá֥r yéh֖ẇʼ mé⁠ʼaֽẖàréy⁠he֑m ʻegĕléy֙ ha⁠zá̇há֔b ʼàşě֥r béֽ̇yţ-ʼé֖l wa⁠ʼàşě֥r bĕ̇⁠dáֽn׃s"],[10,30,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־יֵה֗וּא יַ֤עַן אֲשֶׁר־הֱטִיבֹ֨תָ֙ לַ⁠עֲשׂ֤וֹת הַ⁠יָּשָׁר֙ בְּ⁠עֵינַ֔⁠י כְּ⁠כֹל֙ אֲשֶׁ֣ר בִּ⁠לְבָבִ֔⁠י עָשִׂ֖יתָ לְ⁠בֵ֣ית אַחְאָ֑ב בְּנֵ֣י רְבִעִ֔ים יֵשְׁב֥וּ לְ⁠ךָ֖ עַל־כִּסֵּ֥א יִשְׂרָאֵֽל׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-yéh֗ẇʼ ya֤ʻan ʼàşěr-hètiybò֨ţá֙ la⁠ʻàş֤̂wòţ ha⁠yá̇şá̌r֙ bĕ̇⁠ʻéyna֔⁠y kĕ̇⁠kòl֙ ʼàşě֣r bi̇⁠lĕbábi֔⁠y ʻáşî֖yţá lĕ⁠bé֣yţ ʼaẖĕʼá֑b bĕ̇né֣y rĕbiʻi֔ym yéşĕ̌b֥ẇ lĕ⁠ká֖ ʻal-ki̇sé֥̇ʼ yişĕ̂ráʼéֽl׃"],[10,31,"וְ⁠יֵה֗וּא לֹ֥א שָׁמַ֛ר לָ⁠לֶ֛כֶת בְּ⁠תֽוֹרַת־יְהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל בְּ⁠כָל־לְבָב֑⁠וֹ לֹ֣א סָ֗ר מֵ⁠עַל֙ חַטֹּ֣אות יָֽרָבְעָ֔ם אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wĕ⁠yéh֗ẇʼ lò֥ʼ şá̌ma֛r lá⁠le֛keţ bĕ̇⁠ţֽwòraţ-yĕhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l bĕ̇⁠kál-lĕbáb֑⁠wò lò֣ʼ sá֗r mé⁠ʻal֙ ẖatò֣̇ʼwţ yáֽrábĕʻá֔m ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[10,32,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם הֵחֵ֣ל יְהוָ֔ה לְ⁠קַצּ֖וֹת בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יַּכֵּ֥⁠ם חֲזָאֵ֖ל בְּ⁠כָל־גְּב֥וּל יִשְׂרָאֵֽל׃","bȧ⁠yá̇mi֣ym há⁠hé֔m héẖé֣l yĕhwá֔h lĕ⁠qaẕ֖̇wòţ bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yȧké֥̇⁠m ẖàzáʼé֖l bĕ̇⁠kál-gĕ̇b֥ẇl yişĕ̂ráʼéֽl׃"],[10,33,"מִן־הַ⁠יַּרְדֵּן֙ מִזְרַ֣ח הַ⁠שֶּׁ֔מֶשׁ אֵ֚ת כָּל־אֶ֣רֶץ הַ⁠גִּלְעָ֔ד הַ⁠גָּדִ֥י וְ⁠הָ⁠רֻאובֵנִ֖י וְ⁠הַֽ⁠מְנַשִּׁ֑י מֵ⁠עֲרֹעֵר֙ אֲשֶׁ֣ר עַל־נַ֣חַל אַרְנֹ֔ן וְ⁠הַ⁠גִּלְעָ֖ד וְ⁠הַ⁠בָּשָֽׁן׃","min-ha⁠yȧrĕdé̇n֙ mizĕra֣ẖ ha⁠şė̌֔meş̌ ʼé֚ţ ká̇l-ʼe֣reẕ ha⁠gi̇lĕʻá֔d ha⁠gá̇di֥y wĕ⁠há⁠ruʼwbéni֖y wĕ⁠haֽ⁠mĕnaşi֑̇̌y mé⁠ʻàròʻér֙ ʼàşě֣r ʻal-na֣ẖal ʼarĕnò֔n wĕ⁠ha⁠gi̇lĕʻá֖d wĕ⁠ha⁠bá̇şáֽ̌n׃"],[10,34,"וְ⁠יֶ֨תֶר דִּבְרֵ֥י יֵה֛וּא וְ⁠כָל־אֲשֶׁ֥ר עָשָׂ֖ה וְ⁠כָל־גְּבוּרָת֑⁠וֹ הֲ⁠לֽוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer di̇bĕré֥y yéh֛ẇʼ wĕ⁠kál-ʼàşě֥r ʻáşá֖̂h wĕ⁠kál-gĕ̇bẇráţ֑⁠wò hà⁠lֽwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[10,35,"וַ⁠יִּשְׁכַּ֤ב יֵהוּא֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקְבְּר֥וּ אֹת֖⁠וֹ בְּ⁠שֹׁמְר֑וֹן וַ⁠יִּמְלֹ֛ךְ יְהוֹאָחָ֥ז בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yi̇şĕ̌kȧ֤b yéhẇʼ֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֖⁠wò bĕ̇⁠şò̌mĕr֑wòn wa⁠yi̇mĕlò֛kĕ yĕhwòʼáẖá֥z bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[10,36,"וְ⁠הַ⁠יָּמִ֗ים אֲשֶׁ֨ר מָלַ֤ךְ יֵהוּא֙ עַל־יִשְׂרָאֵ֔ל עֶשְׂרִ֥ים וּ⁠שְׁמֹנֶֽה־שָׁנָ֖ה בְּ⁠שֹׁמְרֽוֹן׃פ","wĕ⁠ha⁠yá̇mi֗ym ʼàşě֨r mála֤kĕ yéhẇʼ֙ ʻal-yişĕ̂ráʼé֔l ʻeşĕ̂ri֥ym ẇ⁠şĕ̌mòneֽh-şá̌ná֖h bĕ̇⁠şò̌mĕrֽwòn׃p"],[11,1,"וַֽ⁠עֲתַלְיָה֙ אֵ֣ם אֲחַזְיָ֔הוּ ו⁠ראתה כִּ֣י מֵ֣ת בְּנָ֑⁠הּ וַ⁠תָּ֨קָם֙ וַ⁠תְּאַבֵּ֔ד אֵ֖ת כָּל־זֶ֥רַע הַ⁠מַּמְלָכָֽה׃","waֽ⁠ʻàţalĕyáh֙ ʼé֣m ʼàẖazĕyá֔hẇ w⁠rʼţh ki֣̇y mé֣ţ bĕ̇ná֑⁠ḣ wa⁠ţá̇֨qám֙ wa⁠ţĕ̇ʼabé̇֔d ʼé֖ţ ká̇l-ze֥raʻ ha⁠mȧmĕlákáֽh׃"],[11,2,"וַ⁠תִּקַּ֣ח יְהוֹשֶׁ֣בַע בַּת־הַ⁠מֶּֽלֶךְ־י֠וֹרָם אֲח֨וֹת אֲחַזְיָ֜הוּ אֶת־יוֹאָ֣שׁ בֶּן־אֲחַזְיָ֗ה וַ⁠תִּגְנֹ֤ב אֹת⁠וֹ֙ מִ⁠תּ֤וֹךְ בְּנֵֽי־הַ⁠מֶּ֨לֶךְ֙ ה⁠ממותתים אֹת֥⁠וֹ וְ⁠אֶת־מֵינִקְתּ֖⁠וֹ בַּ⁠חֲדַ֣ר הַ⁠מִּטּ֑וֹת וַ⁠יַּסְתִּ֧רוּ אֹת֛⁠וֹ מִ⁠פְּנֵ֥י עֲתַלְיָ֖הוּ וְ⁠לֹ֥א הוּמָֽת׃","wa⁠ţi̇qȧ֣ẖ yĕhwòşě֣baʻ bȧţ-ha⁠mėֽlekĕ-y֠wòrám ʼàẖ֨wòţ ʼàẖazĕyá֜hẇ ʼeţ-ywòʼá֣ş̌ bėn-ʼàẖazĕyá֗h wa⁠ţi̇gĕnò֤b ʼòţ⁠wò֙ mi⁠ţ֤̇wòkĕ bĕ̇néֽy-ha⁠mė֨lekĕ֙ h⁠mmwţţym ʼòţ֥⁠wò wĕ⁠ʼeţ-méyniqĕţ֖̇⁠wò bȧ⁠ẖàda֣r ha⁠mi̇ṫ֑wòţ wa⁠yȧsĕţi֧̇rẇ ʼòţ֛⁠wò mi⁠pĕ̇né֥y ʻàţalĕyá֖hẇ wĕ⁠lò֥ʼ hẇmáֽţ׃"],[11,3,"וַ⁠יְהִ֤י אִתָּ⁠הּ֙ בֵּ֣ית יְהוָ֔ה מִתְחַבֵּ֖א שֵׁ֣שׁ שָׁנִ֑ים וַ⁠עֲתַלְיָ֖ה מֹלֶ֥כֶת עַל־הָ⁠אָֽרֶץ׃פ","wa⁠yĕhi֤y ʼiţá̇⁠ḣ֙ bé֣̇yţ yĕhwá֔h miţĕẖabé֖̇ʼ şé֣̌ş̌ şá̌ni֑ym wa⁠ʻàţalĕyá֖h mòle֥keţ ʻal-há⁠ʼáֽreẕ׃p"],[11,4,"וּ⁠בַ⁠שָּׁנָ֣ה הַ֠⁠שְּׁבִיעִית שָׁלַ֨ח יְהוֹיָדָ֜ע וַ⁠יִּקַּ֣ח ׀ אֶת־שָׂרֵ֣י ה⁠מאיות לַ⁠כָּרִי֙ וְ⁠לָ֣⁠רָצִ֔ים וַ⁠יָּבֵ֥א אֹתָ֛⁠ם אֵלָ֖י⁠ו בֵּ֣ית יְהוָ֑ה וַ⁠יִּכְרֹת֩ לָ⁠הֶ֨ם בְּרִ֜ית וַ⁠יַּשְׁבַּ֤ע אֹתָ⁠ם֙ בְּ⁠בֵ֣ית יְהוָ֔ה וַ⁠יַּ֥רְא אֹתָ֖⁠ם אֶת־בֶּן־הַ⁠מֶּֽלֶךְ׃","ẇ⁠ba⁠şá̇̌ná֣h ha֠⁠şĕ̇̌biyʻiyţ şá̌la֨ẖ yĕhwòyádá֜ʻ wa⁠yi̇qȧ֣ẖ ׀ ʼeţ-şá̂ré֣y h⁠mʼywţ la⁠ká̇riy֙ wĕ⁠lá֣⁠ráẕi֔ym wa⁠yá̇bé֥ʼ ʼòţá֛⁠m ʼélá֖y⁠w bé֣̇yţ yĕhwá֑h wa⁠yi̇kĕròţ֩ lá⁠he֨m bĕ̇ri֜yţ wa⁠yȧşĕ̌bȧ֤ʻ ʼòţá⁠m֙ bĕ̇⁠bé֣yţ yĕhwá֔h wa⁠yȧ֥rĕʼ ʼòţá֖⁠m ʼeţ-bėn-ha⁠mėֽlekĕ׃"],[11,5,"וַ⁠יְצַוֵּ֣⁠ם לֵ⁠אמֹ֔ר זֶ֥ה הַ⁠דָּבָ֖ר אֲשֶׁ֣ר תַּעֲשׂ֑וּ⁠ן הַ⁠שְּׁלִשִׁ֤ית מִ⁠כֶּם֙ בָּאֵ֣י הַ⁠שַּׁבָּ֔ת וְ⁠שֹׁ֣מְרֵ֔י מִשְׁמֶ֖רֶת בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","wa⁠yĕẕawé֣̇⁠m lé⁠ʼmò֔r ze֥h ha⁠dá̇bá֖r ʼàşě֣r ţȧʻàş֑̂ẇ⁠n ha⁠şĕ̇̌lişǐ֤yţ mi⁠kėm֙ bá̇ʼé֣y ha⁠şȧ̌bá̇֔ţ wĕ⁠şò֣̌mĕré֔y mişĕ̌me֖reţ bé֥̇yţ ha⁠mėֽlekĕ׃"],[11,6,"וְ⁠הַ⁠שְּׁלִשִׁית֙ בְּ⁠שַׁ֣עַר ס֔וּר וְ⁠הַ⁠שְּׁלִשִׁ֥ית בַּ⁠שַּׁ֖עַר אַחַ֣ר הָ⁠רָצִ֑ים וּ⁠שְׁמַרְתֶּ֛ם אֶת־מִשְׁמֶ֥רֶת הַ⁠בַּ֖יִת מַסָּֽח׃","wĕ⁠ha⁠şĕ̇̌lişǐyţ֙ bĕ̇⁠şǎ֣ʻar s֔ẇr wĕ⁠ha⁠şĕ̇̌lişǐ֥yţ bȧ⁠şȧ֖̌ʻar ʼaẖa֣r há⁠ráẕi֑ym ẇ⁠şĕ̌marĕţė֛m ʼeţ-mişĕ̌me֥reţ ha⁠bȧ֖yiţ masáֽ̇ẖ׃"],[11,7,"וּ⁠שְׁתֵּ֤י הַ⁠יָּדוֹת֙ בָּ⁠כֶ֔ם כֹּ֖ל יֹצְאֵ֣י הַ⁠שַּׁבָּ֑ת וְ⁠שָֽׁמְר֛וּ אֶת־מִשְׁמֶ֥רֶת בֵּית־יְהוָ֖ה אֶל־הַ⁠מֶּֽלֶךְ׃","ẇ⁠şĕ̌ţé֤̇y ha⁠yá̇dwòţ֙ bá̇⁠ke֔m kò֖̇l yòẕĕʼé֣y ha⁠şȧ̌bá֑̇ţ wĕ⁠şáֽ̌mĕr֛ẇ ʼeţ-mişĕ̌me֥reţ bé̇yţ-yĕhwá֖h ʼel-ha⁠mėֽlekĕ׃"],[11,8,"וְ⁠הִקַּפְתֶּ֨ם עַל־הַ⁠מֶּ֜לֶךְ סָבִ֗יב אִ֚ישׁ וְ⁠כֵלָ֣י⁠ו בְּ⁠יָד֔⁠וֹ וְ⁠הַ⁠בָּ֥א אֶל־הַ⁠שְּׂדֵר֖וֹת יוּמָ֑ת וִ⁠הְי֥וּ אֶת־הַ⁠מֶּ֖לֶךְ בְּ⁠צֵאת֥⁠וֹ וּ⁠בְ⁠בֹאֽ⁠וֹ׃","wĕ⁠hiqȧpĕţė֨m ʻal-ha⁠mė֜lekĕ sábi֗yb ʼi֚yş̌ wĕ⁠kélá֣y⁠w bĕ̇⁠yád֔⁠wò wĕ⁠ha⁠bá֥̇ʼ ʼel-ha⁠şĕ̇̂dér֖wòţ yẇmá֑ţ wi⁠hĕy֥ẇ ʼeţ-ha⁠mė֖lekĕ bĕ̇⁠ẕéʼţ֥⁠wò ẇ⁠bĕ⁠bòʼֽ⁠wò׃"],[11,9,"וַֽ⁠יַּעֲשׂ֞וּ שָׂרֵ֣י ה⁠מאיות כְּ⁠כֹ֣ל אֲשֶׁר־צִוָּה֮ יְהוֹיָדָ֣ע הַ⁠כֹּהֵן֒ וַ⁠יִּקְחוּ֙ אִ֣ישׁ אֶת־אֲנָשָׁ֔י⁠ו בָּאֵ֣י הַ⁠שַּׁבָּ֔ת עִ֖ם יֹצְאֵ֣י הַ⁠שַּׁבָּ֑ת וַ⁠יָּבֹ֖אוּ אֶל־יְהוֹיָדָ֥ע הַ⁠כֹּהֵֽן׃","waֽ⁠yȧʻàş̂֞ẇ şá̂ré֣y h⁠mʼywţ kĕ̇⁠kò֣l ʼàşěr-ẕiwá̇h֮ yĕhwòyádá֣ʻ ha⁠kò̇hén֒ wa⁠yi̇qĕẖẇ֙ ʼi֣yş̌ ʼeţ-ʼànáşá̌֔y⁠w bá̇ʼé֣y ha⁠şȧ̌bá̇֔ţ ʻi֖m yòẕĕʼé֣y ha⁠şȧ̌bá֑̇ţ wa⁠yá̇bò֖ʼẇ ʼel-yĕhwòyádá֥ʻ ha⁠kò̇héֽn׃"],[11,10,"וַ⁠יִּתֵּ֨ן הַ⁠כֹּהֵ֜ן לְ⁠שָׂרֵ֣י ה⁠מאיות אֶֽת־הַ⁠חֲנִית֙ וְ⁠אֶת־הַ⁠שְּׁלָטִ֔ים אֲשֶׁ֖ר לַ⁠מֶּ֣לֶךְ דָּוִ֑ד אֲשֶׁ֖ר בְּ⁠בֵ֥ית יְהוָֽה׃","wa⁠yi̇ţé̇֨n ha⁠kò̇hé֜n lĕ⁠şá̂ré֣y h⁠mʼywţ ʼeֽţ-ha⁠ẖàniyţ֙ wĕ⁠ʼeţ-ha⁠şĕ̇̌láti֔ym ʼàşě֖r la⁠mė֣lekĕ dá̇wi֑d ʼàşě֖r bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[11,11,"וַ⁠יַּעַמְד֨וּ הָ⁠רָצִ֜ים אִ֣ישׁ ׀ וְ⁠כֵלָ֣י⁠ו בְּ⁠יָד֗⁠וֹ מִ⁠כֶּ֨תֶף הַ⁠בַּ֤יִת הַ⁠יְמָנִית֙ עַד־כֶּ֤תֶף הַ⁠בַּ֨יִת֙ הַ⁠שְּׂמָאלִ֔ית לַ⁠מִּזְבֵּ֖חַ וְ⁠לַ⁠בָּ֑יִת עַל־הַ⁠מֶּ֖לֶךְ סָבִֽיב׃","wa⁠yȧʻamĕd֨ẇ há⁠ráẕi֜ym ʼi֣yş̌ ׀ wĕ⁠kélá֣y⁠w bĕ̇⁠yád֗⁠wò mi⁠kė֨ţep ha⁠bȧ֤yiţ ha⁠yĕmániyţ֙ ʻad-kė֤ţep ha⁠bȧ֨yiţ֙ ha⁠şĕ̇̂máʼli֔yţ la⁠mi̇zĕbé֖̇ẖa wĕ⁠la⁠bá֑̇yiţ ʻal-ha⁠mė֖lekĕ sábiֽyb׃"],[11,12,"וַ⁠יּוֹצִ֣א אֶת־בֶּן־הַ⁠מֶּ֗לֶךְ וַ⁠יִּתֵּ֤ן עָלָי⁠ו֙ אֶת־הַ⁠נֵּ֨זֶר֙ וְ⁠אֶת־הָ֣⁠עֵד֔וּת וַ⁠יַּמְלִ֥כוּ אֹת֖⁠וֹ וַ⁠יִּמְשָׁחֻ֑⁠הוּ וַ⁠יַּכּוּ־כָ֔ף וַ⁠יֹּאמְר֖וּ יְחִ֥י הַ⁠מֶּֽלֶךְ׃ס","wa⁠ẏwòẕi֣ʼ ʼeţ-bėn-ha⁠mė֗lekĕ wa⁠yi̇ţé֤̇n ʻáláy⁠w֙ ʼeţ-ha⁠né̇֨zer֙ wĕ⁠ʼeţ-há֣⁠ʻéd֔ẇţ wa⁠yȧmĕli֥kẇ ʼòţ֖⁠wò wa⁠yi̇mĕşá̌ẖu֑⁠hẇ wa⁠yȧk̇ẇ-ká֔p wa⁠yò̇ʼmĕr֖ẇ yĕẖi֥y ha⁠mėֽlekĕ׃s"],[11,13,"וַ⁠תִּשְׁמַ֣ע עֲתַלְיָ֔ה אֶת־ק֥וֹל הָֽ⁠רָצִ֖ין הָ⁠עָ֑ם וַ⁠תָּבֹ֥א אֶל־הָ⁠עָ֖ם בֵּ֥ית יְהוָֽה׃","wa⁠ţi̇şĕ̌ma֣ʻ ʻàţalĕyá֔h ʼeţ-q֥wòl háֽ⁠ráẕi֖yn há⁠ʻá֑m wa⁠ţá̇bò֥ʼ ʼel-há⁠ʻá֖m bé֥̇yţ yĕhwáֽh׃"],[11,14,"וַ⁠תֵּ֡רֶא וְ⁠הִנֵּ֣ה הַ⁠מֶּלֶךְ֩ עֹמֵ֨ד עַֽל־הָ⁠עַמּ֜וּד כַּ⁠מִּשְׁפָּ֗ט וְ⁠הַ⁠שָּׂרִ֤ים וְ⁠הַ⁠חֲצֹֽצְרוֹת֙ אֶל־הַ⁠מֶּ֔לֶךְ וְ⁠כָל־עַ֤ם הָ⁠אָ֨רֶץ֙ שָׂמֵ֔חַ וְ⁠תֹקֵ֖עַ בַּ⁠חֲצֹֽצְר֑וֹת וַ⁠תִּקְרַ֤ע עֲתַלְיָה֙ אֶת־בְּגָדֶ֔י⁠הָ וַ⁠תִּקְרָ֖א קֶ֥שֶׁר קָֽשֶׁר׃ס","wa⁠ţé̇֡reʼ wĕ⁠hiné֣̇h ha⁠mėlekĕ֩ ʻòmé֨d ʻaֽl-há⁠ʻaṁ֜ẇd kȧ⁠mi̇şĕ̌pá̇֗t wĕ⁠ha⁠şá̇̂ri֤ym wĕ⁠ha⁠ẖàẕòֽẕĕrwòţ֙ ʼel-ha⁠mė֔lekĕ wĕ⁠kál-ʻa֤m há⁠ʼá֨reẕ֙ şá̂mé֔ẖa wĕ⁠ţòqé֖ʻa bȧ⁠ẖàẕòֽẕĕr֑wòţ wa⁠ţi̇qĕra֤ʻ ʻàţalĕyáh֙ ʼeţ-bĕ̇gáde֔y⁠há wa⁠ţi̇qĕrá֖ʼ qe֥şěr qáֽşěr׃s"],[11,15,"וַ⁠יְצַו֩ יְהוֹיָדָ֨ע הַ⁠כֹּהֵ֜ן אֶת־שָׂרֵ֥י ה⁠מיאות ׀ פְּקֻדֵ֣י הַ⁠חַ֗יִל וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ הוֹצִ֤יאוּ אֹתָ⁠הּ֙ אֶל־מִ⁠בֵּ֣ית לַ⁠שְּׂדֵרֹ֔ת וְ⁠הַ⁠בָּ֥א אַחֲרֶ֖י⁠הָ הָמֵ֣ת בֶּ⁠חָ֑רֶב כִּ֚י אָמַ֣ר הַ⁠כֹּהֵ֔ן אַל־תּוּמַ֖ת בֵּ֥ית יְהוָֽה׃","wa⁠yĕẕaw֩ yĕhwòyádá֨ʻ ha⁠kò̇hé֜n ʼeţ-şá̂ré֥y h⁠myʼwţ ׀ pĕ̇qudé֣y ha⁠ẖa֗yil wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ hwòẕi֤yʼẇ ʼòţá⁠ḣ֙ ʼel-mi⁠bé֣̇yţ la⁠şĕ̇̂dérò֔ţ wĕ⁠ha⁠bá֥̇ʼ ʼaẖàre֖y⁠há hámé֣ţ bė⁠ẖá֑reb ki֚̇y ʼáma֣r ha⁠kò̇hé֔n ʼal-ţ̇ẇma֖ţ bé֥̇yţ yĕhwáֽh׃"],[11,16,"וַ⁠יָּשִׂ֤מוּ לָ⁠הּ֙ יָדַ֔יִם וַ⁠תָּב֛וֹא דֶּֽרֶךְ־מְב֥וֹא הַ⁠סּוּסִ֖ים בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠תּוּמַ֖ת שָֽׁם׃ס","wa⁠yá̇şî֤mẇ lá⁠ḣ֙ yáda֔yim wa⁠ţá̇b֛wòʼ dėֽrekĕ-mĕb֥wòʼ ha⁠ṡẇsi֖ym bé֣̇yţ ha⁠mė֑lekĕ wa⁠ţ̇ẇma֖ţ şáֽ̌m׃s"],[11,17,"וַ⁠יִּכְרֹ֨ת יְהוֹיָדָ֜ע אֶֽת־הַ⁠בְּרִ֗ית בֵּ֤ין יְהוָה֙ וּ⁠בֵ֤ין הַ⁠מֶּ֨לֶךְ֙ וּ⁠בֵ֣ין הָ⁠עָ֔ם לִ⁠הְי֥וֹת לְ⁠עָ֖ם לַֽ⁠יהוָ֑ה וּ⁠בֵ֥ין הַ⁠מֶּ֖לֶךְ וּ⁠בֵ֥ין הָ⁠עָֽם׃","wa⁠yi̇kĕrò֨ţ yĕhwòyádá֜ʻ ʼeֽţ-ha⁠bĕ̇ri֗yţ bé֤̇yn yĕhwáh֙ ẇ⁠bé֤yn ha⁠mė֨lekĕ֙ ẇ⁠bé֣yn há⁠ʻá֔m li⁠hĕy֥wòţ lĕ⁠ʻá֖m laֽ⁠yhwá֑h ẇ⁠bé֥yn ha⁠mė֖lekĕ ẇ⁠bé֥yn há⁠ʻáֽm׃"],[11,18,"וַ⁠יָּבֹ֣אוּ כָל־עַם֩ הָ⁠אָ֨רֶץ בֵּית־הַ⁠בַּ֜עַל וַֽ⁠יִּתְּצֻ֗⁠הוּ אֶת־מזבחת⁠ו וְ⁠אֶת־צְלָמָי⁠ו֙ שִׁבְּר֣וּ הֵיטֵ֔ב וְ⁠אֵ֗ת מַתָּן֙ כֹּהֵ֣ן הַ⁠בַּ֔עַל הָרְג֖וּ לִ⁠פְנֵ֣י הַֽ⁠מִּזְבְּח֑וֹת וַ⁠יָּ֧שֶׂם הַ⁠כֹּהֵ֛ן פְּקֻדּ֖וֹת עַל־בֵּ֥ית יְהוָֽה׃","wa⁠yá̇bò֣ʼẇ kál-ʻam֩ há⁠ʼá֨reẕ bé̇yţ-ha⁠bȧ֜ʻal waֽ⁠yi̇ţĕ̇ẕu֗⁠hẇ ʼeţ-mzbẖţ⁠w wĕ⁠ʼeţ-ẕĕlámáy⁠w֙ şǐbĕ̇r֣ẇ héyté֔b wĕ⁠ʼé֗ţ maţá̇n֙ kò̇hé֣n ha⁠bȧ֔ʻal hárĕg֖ẇ li⁠pĕné֣y haֽ⁠mi̇zĕbĕ̇ẖ֑wòţ wa⁠yá֧̇şêm ha⁠kò̇hé֛n pĕ̇quḋ֖wòţ ʻal-bé֥̇yţ yĕhwáֽh׃"],[11,19,"וַ⁠יִּקַּ֣ח אֶת־שָׂרֵ֣י הַ֠⁠מֵּאוֹת וְ⁠אֶת־הַ⁠כָּרִ֨י וְ⁠אֶת־הָ⁠רָצִ֜ים וְ⁠אֵ֣ת ׀ כָּל־עַ֣ם הָ⁠אָ֗רֶץ וַ⁠יֹּרִ֤ידוּ אֶת־הַ⁠מֶּ֨לֶךְ֙ מִ⁠בֵּ֣ית יְהוָ֔ה וַ⁠יָּב֛וֹאוּ דֶּֽרֶך־שַׁ֥עַר הָ⁠רָצִ֖ים בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יֵּ֖שֶׁב עַל־כִּסֵּ֥א הַ⁠מְּלָכִֽים׃","wa⁠yi̇qȧ֣ẖ ʼeţ-şá̂ré֣y ha֠⁠mé̇ʼwòţ wĕ⁠ʼeţ-ha⁠ká̇ri֨y wĕ⁠ʼeţ-há⁠ráẕi֜ym wĕ⁠ʼé֣ţ ׀ ká̇l-ʻa֣m há⁠ʼá֗reẕ wa⁠yò̇ri֤ydẇ ʼeţ-ha⁠mė֨lekĕ֙ mi⁠bé֣̇yţ yĕhwá֔h wa⁠yá̇b֛wòʼẇ dėֽrek-şǎ֥ʻar há⁠ráẕi֖ym bé֣̇yţ ha⁠mė֑lekĕ wa⁠yé֖̇şěb ʻal-ki̇sé֥̇ʼ ha⁠mĕ̇lákiֽym׃"],[11,20,"וַ⁠יִּשְׂמַ֥ח כָּל־עַם־הָ⁠אָ֖רֶץ וְ⁠הָ⁠עִ֣יר שָׁקָ֑טָה וְ⁠אֶת־עֲתַלְיָ֛הוּ הֵמִ֥יתוּ בַ⁠חֶ֖רֶב בֵּ֥ית מלך׃ס","wa⁠yi̇şĕ̂ma֥ẖ ká̇l-ʻam-há⁠ʼá֖reẕ wĕ⁠há⁠ʻi֣yr şá̌qá֑táh wĕ⁠ʼeţ-ʻàţalĕyá֛hẇ hémi֥yţẇ ba⁠ẖe֖reb bé֥̇yţ mlk׃s"],[11,21,"בֶּן־שֶׁ֥בַע שָׁנִ֖ים יְהוֹאָ֥שׁ בְּ⁠מָלְכֽ⁠וֹ׃פ","bėn-şě֥baʻ şá̌ni֖ym yĕhwòʼá֥ş̌ bĕ̇⁠málĕkֽ⁠wò׃p"],[12,1,"בִּ⁠שְׁנַת־שֶׁ֤בַע לְ⁠יֵהוּא֙ מָלַ֣ךְ יְהוֹאָ֔שׁ וְ⁠אַרְבָּעִ֣ים שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירֽוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ צִבְיָ֖ה מִ⁠בְּאֵ֥ר שָֽׁבַע׃","bi̇⁠şĕ̌naţ-şě֤baʻ lĕ⁠yéhẇʼ֙ mála֣kĕ yĕhwòʼá֔ş̌ wĕ⁠ʼarĕbá̇ʻi֣ym şá̌ná֔h mála֖kĕ bi̇⁠yrֽẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ẕibĕyá֖h mi⁠bĕ̇ʼé֥r şáֽ̌baʻ׃"],[12,2,"וַ⁠יַּ֨עַשׂ יְהוֹאָ֧שׁ הַ⁠יָּשָׁ֛ר בְּ⁠עֵינֵ֥י יְהוָ֖ה כָּל־יָמָ֑י⁠ו אֲשֶׁ֣ר הוֹרָ֔⁠הוּ יְהוֹיָדָ֖ע הַ⁠כֹּהֵֽן׃","wa⁠yȧ֨ʻaş̂ yĕhwòʼá֧ş̌ ha⁠yá̇şá֛̌r bĕ̇⁠ʻéyné֥y yĕhwá֖h ká̇l-yámá֑y⁠w ʼàşě֣r hwòrá֔⁠hẇ yĕhwòyádá֖ʻ ha⁠kò̇héֽn׃"],[12,3,"רַ֥ק הַ⁠בָּמ֖וֹת לֹא־סָ֑רוּ ע֥וֹד הָ⁠עָ֛ם מְזַבְּחִ֥ים וּֽ⁠מְקַטְּרִ֖ים בַּ⁠בָּמֽוֹת׃","ra֥q ha⁠bá̇m֖wòţ lòʼ-sá֑rẇ ʻ֥wòd há⁠ʻá֛m mĕzabĕ̇ẖi֥ym ẇֽ⁠mĕqatĕ̇ri֖ym bȧ⁠bá̇mֽwòţ׃"],[12,4,"וַ⁠יֹּ֨אמֶר יְהוֹאָ֜שׁ אֶל־הַ⁠כֹּהֲנִ֗ים כֹּל֩ כֶּ֨סֶף הַ⁠קֳּדָשִׁ֜ים אֲשֶׁר־יוּבָ֤א בֵית־יְהוָה֙ כֶּ֣סֶף עוֹבֵ֔ר אִ֕ישׁ כֶּ֥סֶף נַפְשׁ֖וֹת עֶרְכּ֑⁠וֹ כָּל־כֶּ֗סֶף אֲשֶׁ֤ר יַֽעֲלֶה֙ עַ֣ל לֶב־אִ֔ישׁ לְ⁠הָבִ֖יא בֵּ֥ית יְהוָֽה׃","wa⁠yò̇֨ʼmer yĕhwòʼá֜ş̌ ʼel-ha⁠kò̇hàni֗ym kò̇l֩ kė֨sep ha⁠qȯdáşǐ֜ym ʼàşěr-yẇbá֤ʼ béyţ-yĕhwáh֙ kė֣sep ʻwòbé֔r ʼi֕yş̌ kė֥sep napĕş֖̌wòţ ʻerĕk֑̇⁠wò ká̇l-kė֗sep ʼàşě֤r yaֽʻàleh֙ ʻa֣l leb-ʼi֔yş̌ lĕ⁠hábi֖yʼ bé֥̇yţ yĕhwáֽh׃"],[12,5,"יִקְח֤וּ לָ⁠הֶם֙ הַ⁠כֹּ֣הֲנִ֔ים אִ֖ישׁ מֵ⁠אֵ֣ת מַכָּר֑⁠וֹ וְ⁠הֵ֗ם יְחַזְּקוּ֙ אֶת־בֶּ֣דֶק הַ⁠בַּ֔יִת לְ⁠כֹ֛ל אֲשֶׁר־יִמָּצֵ֥א שָׁ֖ם בָּֽדֶק׃פ","yiqĕẖ֤ẇ lá⁠hem֙ ha⁠kò֣̇hàni֔ym ʼi֖yş̌ mé⁠ʼé֣ţ maká̇r֑⁠wò wĕ⁠hé֗m yĕẖazĕ̇qẇ֙ ʼeţ-bė֣deq ha⁠bȧ֔yiţ lĕ⁠kò֛l ʼàşěr-yimá̇ẕé֥ʼ şá֖̌m báֽ̇deq׃p"],[12,6,"וַ⁠יְהִ֗י בִּ⁠שְׁנַ֨ת עֶשְׂרִ֧ים וְ⁠שָׁלֹ֛שׁ שָׁנָ֖ה לַ⁠מֶּ֣לֶךְ יְהוֹאָ֑שׁ לֹֽא־חִזְּק֥וּ הַ⁠כֹּהֲנִ֖ים אֶת־בֶּ֥דֶק הַ⁠בָּֽיִת׃","wa⁠yĕhi֗y bi̇⁠şĕ̌na֨ţ ʻeşĕ̂ri֧ym wĕ⁠şá̌lò֛ş̌ şá̌ná֖h la⁠mė֣lekĕ yĕhwòʼá֑ş̌ lòֽʼ-ẖizĕ̇q֥ẇ ha⁠kò̇hàni֖ym ʼeţ-bė֥deq ha⁠báֽ̇yiţ׃"],[12,7,"וַ⁠יִּקְרָא֩ הַ⁠מֶּ֨לֶךְ יְהוֹאָ֜שׁ לִ⁠יהוֹיָדָ֤ע הַ⁠כֹּהֵן֙ וְ⁠לַ⁠כֹּ֣הֲנִ֔ים וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֔ם מַדּ֛וּעַ אֵינְ⁠כֶ֥ם מְחַזְּקִ֖ים אֶת־בֶּ֣דֶק הַ⁠בָּ֑יִת וְ⁠עַתָּ֗ה אַל־תִּקְחוּ־כֶ֨סֶף֙ מֵ⁠אֵ֣ת מַכָּֽרֵי⁠כֶ֔ם כִּֽי־לְ⁠בֶ֥דֶק הַ⁠בַּ֖יִת תִּתְּנֻֽ⁠הוּ׃","wa⁠yi̇qĕráʼ֩ ha⁠mė֨lekĕ yĕhwòʼá֜ş̌ li⁠yhwòyádá֤ʻ ha⁠kò̇hén֙ wĕ⁠la⁠kò֣̇hàni֔ym wa⁠yò֣̇ʼmer ʼàlé⁠he֔m maḋ֛ẇʻa ʼéynĕ⁠ke֥m mĕẖazĕ̇qi֖ym ʼeţ-bė֣deq ha⁠bá֑̇yiţ wĕ⁠ʻaţá̇֗h ʼal-ţi̇qĕẖẇ-ke֨sep֙ mé⁠ʼé֣ţ makáֽ̇réy⁠ke֔m kiֽ̇y-lĕ⁠be֥deq ha⁠bȧ֖yiţ ţi̇ţĕ̇nuֽ⁠hẇ׃"],[12,8,"וַ⁠יֵּאֹ֖תוּ הַ⁠כֹּֽהֲנִ֑ים לְ⁠בִלְתִּ֤י קְחַת־כֶּ֨סֶף֙ מֵ⁠אֵ֣ת הָ⁠עָ֔ם וּ⁠לְ⁠בִלְתִּ֥י חַזֵּ֖ק אֶת־בֶּ֥דֶק הַ⁠בָּֽיִת׃","wa⁠yé̇ʼò֖ţẇ ha⁠kòֽ̇hàni֑ym lĕ⁠bilĕţi֤̇y qĕẖaţ-kė֨sep֙ mé⁠ʼé֣ţ há⁠ʻá֔m ẇ⁠lĕ⁠bilĕţi֥̇y ẖazé֖̇q ʼeţ-bė֥deq ha⁠báֽ̇yiţ׃"],[12,9,"וַ⁠יִּקַּ֞ח יְהוֹיָדָ֤ע הַ⁠כֹּהֵן֙ אֲר֣וֹן אֶחָ֔ד וַ⁠יִּקֹּ֥ב חֹ֖ר בְּ⁠דַלְתּ֑⁠וֹ וַ⁠יִּתֵּ֣ן אֹת⁠וֹ֩ אֵ֨צֶל הַ⁠מִּזְבֵּ֜חַ ב⁠ימין בְּ⁠בֽוֹא־אִישׁ֙ בֵּ֣ית יְהוָ֔ה וְ⁠נָֽתְנוּ־שָׁ֤מָּ⁠ה הַ⁠כֹּֽהֲנִים֙ שֹׁמְרֵ֣י הַ⁠סַּ֔ף אֶת־כָּל־הַ⁠כֶּ֖סֶף הַ⁠מּוּבָ֥א בֵית־יְהוָֽה׃","wa⁠yi̇qȧ֞ẖ yĕhwòyádá֤ʻ ha⁠kò̇hén֙ ʼàr֣wòn ʼeẖá֔d wa⁠yi̇qò֥̇b ẖò֖r bĕ̇⁠dalĕţ֑̇⁠wò wa⁠yi̇ţé֣̇n ʼòţ⁠wò֩ ʼé֨ẕel ha⁠mi̇zĕbé̇֜ẖa b⁠ymyn bĕ̇⁠bֽwòʼ-ʼiyş̌֙ bé֣̇yţ yĕhwá֔h wĕ⁠náֽţĕnẇ-şá֤̌má̇⁠h ha⁠kòֽ̇hàniym֙ şò̌mĕré֣y ha⁠sȧ֔p ʼeţ-ká̇l-ha⁠kė֖sep ha⁠ṁẇbá֥ʼ béyţ-yĕhwáֽh׃"],[12,10,"וַֽ⁠יְהִי֙ כִּ⁠רְאוֹתָ֔⁠ם כִּֽי־רַ֥ב הַ⁠כֶּ֖סֶף בָּֽ⁠אָר֑וֹן וַ⁠יַּ֨עַל סֹפֵ֤ר הַ⁠מֶּ֨לֶךְ֙ וְ⁠הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל וַ⁠יָּצֻ֨רוּ֙ וַ⁠יִּמְנ֔וּ אֶת־הַ⁠כֶּ֖סֶף הַ⁠נִּמְצָ֥א בֵית־יְהוָֽה׃","waֽ⁠yĕhiy֙ ki̇⁠rĕʼwòţá֔⁠m kiֽ̇y-ra֥b ha⁠kė֖sep báֽ̇⁠ʼár֑wòn wa⁠yȧ֨ʻal sòpé֤r ha⁠mė֨lekĕ֙ wĕ⁠ha⁠kò̇hé֣n ha⁠gá̇d֔wòl wa⁠yá̇ẕu֨rẇ֙ wa⁠yi̇mĕn֔ẇ ʼeţ-ha⁠kė֖sep ha⁠ni̇mĕẕá֥ʼ béyţ-yĕhwáֽh׃"],[12,11,"וְ⁠נָתְנוּ֙ אֶת־הַ⁠כֶּ֣סֶף הַֽ⁠מְתֻכָּ֔ן עַל־יד עֹשֵׂ֣י הַ⁠מְּלָאכָ֔ה ה⁠פקדים בֵּ֣ית יְהוָ֑ה וַ⁠יּוֹצִיאֻ֜⁠הוּ לְ⁠חָרָשֵׁ֤י הָ⁠עֵץ֙ וְ⁠לַ⁠בֹּנִ֔ים הָ⁠עֹשִׂ֖ים בֵּ֥ית יְהוָֽה׃","wĕ⁠náţĕnẇ֙ ʼeţ-ha⁠kė֣sep haֽ⁠mĕţuká̇֔n ʻal-yd ʻòşé֣̂y ha⁠mĕ̇láʼká֔h h⁠pqdym bé֣̇yţ yĕhwá֑h wa⁠ẏwòẕiyʼu֜⁠hẇ lĕ⁠ẖáráşé֤̌y há⁠ʻéẕ֙ wĕ⁠la⁠bò̇ni֔ym há⁠ʻòşî֖ym bé֥̇yţ yĕhwáֽh׃"],[12,12,"וְ⁠לַ⁠גֹּֽדְרִים֙ וּ⁠לְ⁠חֹצְבֵ֣י הָ⁠אֶ֔בֶן וְ⁠לִ⁠קְנ֤וֹת עֵצִים֙ וְ⁠אַבְנֵ֣י מַחְצֵ֔ב לְ⁠חַזֵּ֖ק אֶת־בֶּ֣דֶק בֵּית־יְהוָ֑ה וּ⁠לְ⁠כֹ֛ל אֲשֶׁר־יֵצֵ֥א עַל־הַ⁠בַּ֖יִת לְ⁠חָזְקָֽה׃","wĕ⁠la⁠gòֽ̇dĕriym֙ ẇ⁠lĕ⁠ẖòẕĕbé֣y há⁠ʼe֔ben wĕ⁠li⁠qĕn֤wòţ ʻéẕiym֙ wĕ⁠ʼabĕné֣y maẖĕẕé֔b lĕ⁠ẖazé֖̇q ʼeţ-bė֣deq bé̇yţ-yĕhwá֑h ẇ⁠lĕ⁠kò֛l ʼàşěr-yéẕé֥ʼ ʻal-ha⁠bȧ֖yiţ lĕ⁠ẖázĕqáֽh׃"],[12,13,"אַךְ֩ לֹ֨א יֵעָשֶׂ֜ה בֵּ֣ית יְהוָ֗ה סִפּ֥וֹת כֶּ֨סֶף֙ מְזַמְּר֤וֹת מִזְרָקוֹת֙ חֲצֹ֣צְר֔וֹת כָּל־כְּלִ֥י זָהָ֖ב וּ⁠כְלִי־כָ֑סֶף מִן־הַ⁠כֶּ֖סֶף הַ⁠מּוּבָ֥א בֵית־יְהוָֽה׃","ʼakĕ֩ lò֨ʼ yéʻáşê֜h bé֣̇yţ yĕhwá֗h siṗ֥wòţ kė֨sep֙ mĕzamĕ̇r֤wòţ mizĕráqwòţ֙ ẖàẕò֣ẕĕr֔wòţ ká̇l-kĕ̇li֥y záhá֖b ẇ⁠kĕliy-ká֑sep min-ha⁠kė֖sep ha⁠ṁẇbá֥ʼ béyţ-yĕhwáֽh׃"],[12,14,"כִּֽי־לְ⁠עֹשֵׂ֥י הַ⁠מְּלָאכָ֖ה יִתְּנֻ֑⁠הוּ וְ⁠חִזְּקוּ־ב֖⁠וֹ אֶת־בֵּ֥ית יְהוָֽה׃","kiֽ̇y-lĕ⁠ʻòşé֥̂y ha⁠mĕ̇láʼká֖h yiţĕ̇nu֑⁠hẇ wĕ⁠ẖizĕ̇qẇ-b֖⁠wò ʼeţ-bé֥̇yţ yĕhwáֽh׃"],[12,15,"וְ⁠לֹ֧א יְחַשְּׁב֣וּ אֶת־הָ⁠אֲנָשִׁ֗ים אֲשֶׁ֨ר יִתְּנ֤וּ אֶת־הַ⁠כֶּ֨סֶף֙ עַל־יָדָ֔⁠ם לָ⁠תֵ֖ת לְ⁠עֹשֵׂ֣י הַ⁠מְּלָאכָ֑ה כִּ֥י בֶ⁠אֱמֻנָ֖ה הֵ֥ם עֹשִֽׂים׃","wĕ⁠lò֧ʼ yĕẖaşĕ̇̌b֣ẇ ʼeţ-há⁠ʼànáşǐ֗ym ʼàşě֨r yiţĕ̇n֤ẇ ʼeţ-ha⁠kė֨sep֙ ʻal-yádá֔⁠m lá⁠ţé֖ţ lĕ⁠ʻòşé֣̂y ha⁠mĕ̇láʼká֑h ki֥̇y be⁠ʼèmuná֖h hé֥m ʻòşîֽym׃"],[12,16,"כֶּ֤סֶף אָשָׁם֙ וְ⁠כֶ֣סֶף חַטָּא֔וֹת לֹ֥א יוּבָ֖א בֵּ֣ית יְהוָ֑ה לַ⁠כֹּהֲנִ֖ים יִהְיֽוּ׃פ","kė֤sep ʼáşá̌m֙ wĕ⁠ke֣sep ẖatá̇ʼ֔wòţ lò֥ʼ yẇbá֖ʼ bé֣̇yţ yĕhwá֑h la⁠kò̇hàni֖ym yihĕyֽẇ׃p"],[12,17,"אָ֣ז יַעֲלֶ֗ה חֲזָאֵל֙ מֶ֣לֶךְ אֲרָ֔ם וַ⁠יִּלָּ֥חֶם עַל־גַּ֖ת וַֽ⁠יִּלְכְּדָ֑⁠הּ וַ⁠יָּ֤שֶׂם חֲזָאֵל֙ פָּנָ֔י⁠ו לַ⁠עֲל֖וֹת עַל־יְרוּשָׁלִָֽם׃","ʼá֣z yaʻàle֗h ẖàzáʼél֙ me֣lekĕ ʼàrá֔m wa⁠yi̇lá֥̇ẖem ʻal-gȧ֖ţ waֽ⁠yi̇lĕkĕ̇dá֑⁠ḣ wa⁠yá֤̇şêm ẖàzáʼél֙ pá̇ná֔y⁠w la⁠ʻàl֖wòţ ʻal-yĕrẇşá̌liáֽm׃"],[12,18,"וַ⁠יִּקַּ֞ח יְהוֹאָ֣שׁ מֶֽלֶךְ־יְהוּדָ֗ה אֵ֣ת כָּל־הַ⁠קֳּדָשִׁ֡ים אֲשֶׁר־הִקְדִּ֣ישׁוּ יְהוֹשָׁפָ֣ט וִ⁠יהוֹרָם֩ וַ⁠אֲחַזְיָ֨הוּ אֲבֹתָ֜י⁠ו מַלְכֵ֤י יְהוּדָה֙ וְ⁠אֶת־קֳדָשָׁ֔י⁠ו וְ⁠אֵ֣ת כָּל־הַ⁠זָּהָ֗ב הַ⁠נִּמְצָ֛א בְּ⁠אֹצְר֥וֹת בֵּית־יְהוָ֖ה וּ⁠בֵ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׁלַ֗ח לַֽ⁠חֲזָאֵל֙ מֶ֣לֶךְ אֲרָ֔ם וַ⁠יַּ֖עַל מֵ⁠עַ֥ל יְרוּשָׁלִָֽם׃","wa⁠yi̇qȧ֞ẖ yĕhwòʼá֣ş̌ meֽlekĕ-yĕhẇdá֗h ʼé֣ţ ká̇l-ha⁠qȯdáşǐ֡ym ʼàşěr-hiqĕdi֣̇yş̌ẇ yĕhwòşá̌pá֣t wi⁠yhwòrám֩ wa⁠ʼàẖazĕyá֨hẇ ʼàbòţá֜y⁠w malĕké֤y yĕhẇdáh֙ wĕ⁠ʼeţ-qodáşá̌֔y⁠w wĕ⁠ʼé֣ţ ká̇l-ha⁠zá̇há֗b ha⁠ni̇mĕẕá֛ʼ bĕ̇⁠ʼòẕĕr֥wòţ bé̇yţ-yĕhwá֖h ẇ⁠bé֣yţ ha⁠mė֑lekĕ wa⁠yi̇şĕ̌la֗ẖ laֽ⁠ẖàzáʼél֙ me֣lekĕ ʼàrá֔m wa⁠yȧ֖ʻal mé⁠ʻa֥l yĕrẇşá̌liáֽm׃"],[12,19,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יוֹאָ֖שׁ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y ywòʼá֖ş̌ wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[12,20,"וַ⁠יָּקֻ֥מוּ עֲבָדָ֖י⁠ו וַ⁠יִּקְשְׁרֽוּ־קָ֑שֶׁר וַ⁠יַּכּוּ֙ אֶת־יוֹאָ֔שׁ בֵּ֥ית מִלֹּ֖א הַ⁠יּוֹרֵ֥ד סִלָּֽא׃","wa⁠yá̇qu֥mẇ ʻàbádá֖y⁠w wa⁠yi̇qĕşĕ̌rֽẇ-qá֑şěr wa⁠yȧk̇ẇ֙ ʼeţ-ywòʼá֔ş̌ bé֥̇yţ milò֖̇ʼ ha⁠ẏwòré֥d siláֽ̇ʼ׃"],[12,21,"וְ⁠יוֹזָבָ֣ד בֶּן־שִׁ֠מְעָת וִ⁠יהוֹזָבָ֨ד בֶּן־שֹׁמֵ֤ר ׀ עֲבָדָי⁠ו֙ הִכֻּ֣⁠הוּ וַ⁠יָּמֹ֔ת וַ⁠יִּקְבְּר֥וּ אֹת֛⁠וֹ עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֣יר דָּוִ֑ד וַ⁠יִּמְלֹ֛ךְ אֲמַצְיָ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wĕ⁠ywòzábá֣d bėn-şǐ֠mĕʻáţ wi⁠yhwòzábá֨d bėn-şò̌mé֤r ׀ ʻàbádáy⁠w֙ hiku֣̇⁠hẇ wa⁠yá̇mò֔ţ wa⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֛⁠wò ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֣yr dá̇wi֑d wa⁠yi̇mĕlò֛kĕ ʼàmaẕĕyá֥h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[13,1,"בִּ⁠שְׁנַ֨ת עֶשְׂרִ֤ים וְ⁠שָׁלֹשׁ֙ שָׁנָ֔ה לְ⁠יוֹאָ֥שׁ בֶּן־אֲחַזְיָ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ יְהוֹאָחָ֨ז בֶּן־יֵה֤וּא עַל־יִשְׂרָאֵל֙ בְּ⁠שֹׁ֣מְר֔וֹן שְׁבַ֥ע עֶשְׂרֵ֖ה שָׁנָֽה׃","bi̇⁠şĕ̌na֨ţ ʻeşĕ̂ri֤ym wĕ⁠şá̌lòş̌֙ şá̌ná֔h lĕ⁠ywòʼá֥ş̌ bėn-ʼàẖazĕyá֖hẇ me֣lekĕ yĕhẇdá֑h má֠lakĕ yĕhwòʼáẖá֨z bėn-yéh֤ẇʼ ʻal-yişĕ̂ráʼél֙ bĕ̇⁠şò֣̌mĕr֔wòn şĕ̌ba֥ʻ ʻeşĕ̂ré֖h şá̌náֽh׃"],[13,2,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ֠⁠יֵּלֶךְ אַחַ֨ר חַטֹּ֜את יָרָבְעָ֧ם בֶּן־נְבָ֛ט אֲשֶׁר־הֶחֱטִ֥יא אֶת־יִשְׂרָאֵ֖ל לֹא־סָ֥ר מִמֶּֽ⁠נָּה׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa֠⁠yé̇lekĕ ʼaẖa֨r ẖatò̇֜ʼţ yárábĕʻá֧m bėn-nĕbá֛t ʼàşěr-heẖèti֥yʼ ʼeţ-yişĕ̂ráʼé֖l lòʼ-sá֥r mimėֽ⁠ná̇h׃"],[13,3,"וַ⁠יִּֽחַר־אַ֥ף יְהוָ֖ה בְּ⁠יִשְׂרָאֵ֑ל וַֽ⁠יִּתְּנֵ֞⁠ם בְּ⁠יַ֣ד ׀ חֲזָאֵ֣ל מֶֽלֶךְ־אֲרָ֗ם וּ⁠בְ⁠יַ֛ד בֶּן־הֲדַ֥ד בֶּן־חֲזָאֵ֖ל כָּל־הַ⁠יָּמִֽים׃","wa⁠yiֽ̇ẖar-ʼa֥p yĕhwá֖h bĕ̇⁠yişĕ̂ráʼé֑l waֽ⁠yi̇ţĕ̇né֞⁠m bĕ̇⁠ya֣d ׀ ẖàzáʼé֣l meֽlekĕ-ʼàrá֗m ẇ⁠bĕ⁠ya֛d bėn-hàda֥d bėn-ẖàzáʼé֖l ká̇l-ha⁠yá̇miֽym׃"],[13,4,"וַ⁠יְחַ֥ל יְהוֹאָחָ֖ז אֶת־פְּנֵ֣י יְהוָ֑ה וַ⁠יִּשְׁמַ֤ע אֵלָי⁠ו֙ יְהוָ֔ה כִּ֤י רָאָה֙ אֶת־לַ֣חַץ יִשְׂרָאֵ֔ל כִּֽי־לָחַ֥ץ אֹתָ֖⁠ם מֶ֥לֶךְ אֲרָֽם׃","wa⁠yĕẖa֥l yĕhwòʼáẖá֖z ʼeţ-pĕ̇né֣y yĕhwá֑h wa⁠yi̇şĕ̌ma֤ʻ ʼéláy⁠w֙ yĕhwá֔h ki֤̇y ráʼáh֙ ʼeţ-la֣ẖaẕ yişĕ̂ráʼé֔l kiֽ̇y-láẖa֥ẕ ʼòţá֖⁠m me֥lekĕ ʼàráֽm׃"],[13,5,"וַ⁠יִּתֵּ֨ן יְהוָ֤ה לְ⁠יִשְׂרָאֵל֙ מוֹשִׁ֔יעַ וַ⁠יֵּ֣צְא֔וּ מִ⁠תַּ֖חַת יַד־אֲרָ֑ם וַ⁠יֵּשְׁב֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל בְּ⁠אָהֳלֵי⁠הֶ֖ם כִּ⁠תְמ֥וֹל שִׁלְשֽׁוֹם׃","wa⁠yi̇ţé̇֨n yĕhwá֤h lĕ⁠yişĕ̂ráʼél֙ mwòşǐ֔yʻa wa⁠yé֣̇ẕĕʼ֔ẇ mi⁠ţȧ֖ẖaţ yad-ʼàrá֑m wa⁠yé̇şĕ̌b֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l bĕ̇⁠ʼáholéy⁠he֖m ki̇⁠ţĕm֥wòl şǐlĕşֽ̌wòm׃"],[13,6,"אַ֠ךְ לֹֽא־סָ֜רוּ מֵ⁠חַטֹּ֧אות בֵּית־יָרָבְעָ֛ם אֲשֶׁר־החטי אֶת־יִשְׂרָאֵ֖ל בָּ֣⁠הּ הָלָ֑ךְ וְ⁠גַם֙ הָ⁠אֲשֵׁרָ֔ה עָמְדָ֖ה בְּ⁠שֹׁמְרֽוֹן׃","ʼa֠kĕ lòֽʼ-sá֜rẇ mé⁠ẖatò֧̇ʼwţ bé̇yţ-yárábĕʻá֛m ʼàşěr-hẖty ʼeţ-yişĕ̂ráʼé֖l bá֣̇⁠ḣ hálá֑kĕ wĕ⁠gam֙ há⁠ʼàşé̌rá֔h ʻámĕdá֖h bĕ̇⁠şò̌mĕrֽwòn׃"],[13,7,"כִּ֣י לֹא֩ הִשְׁאִ֨יר לִ⁠יהוֹאָחָ֜ז עָ֗ם כִּ֣י אִם־חֲמִשִּׁ֤ים פָּֽרָשִׁים֙ וַ⁠עֲשָׂ֣רָה רֶ֔כֶב וַ⁠עֲשֶׂ֥רֶת אֲלָפִ֖ים רַגְלִ֑י כִּ֤י אִבְּדָ⁠ם֙ מֶ֣לֶךְ אֲרָ֔ם וַ⁠יְשִׂמֵ֥⁠ם כֶּֽ⁠עָפָ֖ר לָ⁠דֻֽשׁ׃","ki֣̇y lòʼ֩ hişĕ̌ʼi֨yr li⁠yhwòʼáẖá֜z ʻá֗m ki֣̇y ʼim-ẖàmişi֤̇̌ym páֽ̇ráşǐym֙ wa⁠ʻàşá֣̂ráh re֔keb wa⁠ʻàşê֥reţ ʼàlápi֖ym ragĕli֑y ki֤̇y ʼibĕ̇dá⁠m֙ me֣lekĕ ʼàrá֔m wa⁠yĕşîmé֥⁠m kėֽ⁠ʻápá֖r lá⁠duֽş̌׃"],[13,8,"וְ⁠יֶ֨תֶר דִּבְרֵ֧י יְהוֹאָחָ֛ז וְ⁠כָל־אֲשֶׁ֥ר עָשָׂ֖ה וּ⁠גְבוּרָת֑⁠וֹ הֲ⁠לוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer di̇bĕré֧y yĕhwòʼáẖá֛z wĕ⁠kál-ʼàşě֥r ʻáşá֖̂h ẇ⁠gĕbẇráţ֑⁠wò hà⁠lwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[13,9,"וַ⁠יִּשְׁכַּ֤ב יְהֽוֹאָחָז֙ עִם־אֲבֹתָ֔י⁠ו וַֽ⁠יִּקְבְּרֻ֖⁠הוּ בְּ⁠שֹׁמְר֑וֹן וַ⁠יִּמְלֹ֛ךְ יוֹאָ֥שׁ בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b yĕhֽwòʼáẖáz֙ ʻim-ʼàbòţá֔y⁠w waֽ⁠yi̇qĕbĕ̇ru֖⁠hẇ bĕ̇⁠şò̌mĕr֑wòn wa⁠yi̇mĕlò֛kĕ ywòʼá֥ş̌ bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[13,10,"בִּ⁠שְׁנַ֨ת שְׁלֹשִׁ֤ים וָ⁠שֶׁ֨בַע֙ שָׁנָ֔ה לְ⁠יוֹאָ֖שׁ מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ יְהוֹאָ֨שׁ בֶּן־יְהוֹאָחָ֤ז עַל־יִשְׂרָאֵל֙ בְּ⁠שֹׁ֣מְר֔וֹן שֵׁ֥שׁ עֶשְׂרֵ֖ה שָׁנָֽה׃","bi̇⁠şĕ̌na֨ţ şĕ̌lòşǐ֤ym wá⁠şě֨baʻ֙ şá̌ná֔h lĕ⁠ywòʼá֖ş̌ me֣lekĕ yĕhẇdá֑h má֠lakĕ yĕhwòʼá֨ş̌ bėn-yĕhwòʼáẖá֤z ʻal-yişĕ̂ráʼél֙ bĕ̇⁠şò֣̌mĕr֔wòn şé֥̌ş̌ ʻeşĕ̂ré֖h şá̌náֽh׃"],[13,11,"וַ⁠יַּֽעֲשֶׂ֥ה הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה לֹ֣א סָ֗ר מִ⁠כָּל־חַטֹּ֞אות יָרָבְעָ֧ם בֶּן־נְבָ֛ט אֲשֶׁר־הֶחֱטִ֥יא אֶת־יִשְׂרָאֵ֖ל בָּ֥⁠הּ הָלָֽךְ׃","wa⁠yȧֽʻàşê֥h há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h lò֣ʼ sá֗r mi⁠ká̇l-ẖatò̇֞ʼwţ yárábĕʻá֧m bėn-nĕbá֛t ʼàşěr-heẖèti֥yʼ ʼeţ-yişĕ̂ráʼé֖l bá֥̇⁠ḣ háláֽkĕ׃"],[13,12,"וְ⁠יֶ֨תֶר דִּבְרֵ֤י יוֹאָשׁ֙ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֔ה וּ⁠גְב֣וּרָת֔⁠וֹ אֲשֶׁ֣ר נִלְחַ֔ם עִ֖ם אֲמַצְיָ֣ה מֶֽלֶךְ־יְהוּדָ֑ה הֲ⁠לֽוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer di̇bĕré֤y ywòʼáş̌֙ wĕ⁠kál-ʼàşě֣r ʻáşá̂֔h ẇ⁠gĕb֣ẇráţ֔⁠wò ʼàşě֣r nilĕẖa֔m ʻi֖m ʼàmaẕĕyá֣h meֽlekĕ-yĕhẇdá֑h hà⁠lֽwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[13,13,"וַ⁠יִּשְׁכַּ֤ב יוֹאָשׁ֙ עִם־אֲבֹתָ֔י⁠ו וְ⁠יָרָבְעָ֖ם יָשַׁ֣ב עַל־כִּסְא֑⁠וֹ וַ⁠יִּקָּבֵ֤ר יוֹאָשׁ֙ בְּ⁠שֹׁ֣מְר֔וֹן עִ֖ם מַלְכֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yi̇şĕ̌kȧ֤b ywòʼáş̌֙ ʻim-ʼàbòţá֔y⁠w wĕ⁠yárábĕʻá֖m yáşǎ֣b ʻal-ki̇sĕʼ֑⁠wò wa⁠yi̇qá̇bé֤r ywòʼáş̌֙ bĕ̇⁠şò֣̌mĕr֔wòn ʻi֖m malĕké֥y yişĕ̂ráʼéֽl׃p"],[13,14,"וֶֽ⁠אֱלִישָׁע֙ חָלָ֣ה אֶת־חָלְי֔⁠וֹ אֲשֶׁ֥ר יָמ֖וּת בּ֑⁠וֹ וַ⁠יֵּ֨רֶד אֵלָ֜י⁠ו יוֹאָ֣שׁ מֶֽלֶךְ־יִשְׂרָאֵ֗ל וַ⁠יֵּ֤בְךְּ עַל־פָּנָי⁠ו֙ וַ⁠יֹּאמַ֔ר אָבִ֣⁠י ׀ אָבִ֔⁠י רֶ֥כֶב יִשְׂרָאֵ֖ל וּ⁠פָרָשָֽׁי⁠ו׃","weֽ⁠ʼèliyşá̌ʻ֙ ẖálá֣h ʼeţ-ẖálĕy֔⁠wò ʼàşě֥r yám֖ẇţ ḃ֑⁠wò wa⁠yé̇֨red ʼélá֜y⁠w ywòʼá֣ş̌ meֽlekĕ-yişĕ̂ráʼé֗l wa⁠yé֤̇bĕkĕ̇ ʻal-pá̇náy⁠w֙ wa⁠yò̇ʼma֔r ʼábi֣⁠y ׀ ʼábi֔⁠y re֥keb yişĕ̂ráʼé֖l ẇ⁠páráşáֽ̌y⁠w׃"],[13,15,"וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ אֱלִישָׁ֔ע קַ֖ח קֶ֣שֶׁת וְ⁠חִצִּ֑ים וַ⁠יִּקַּ֥ח אֵלָ֖י⁠ו קֶ֥שֶׁת וְ⁠חִצִּֽים׃","wa⁠yò֤̇ʼmer l⁠wò֙ ʼèliyşá̌֔ʻ qa֖ẖ qe֣şěţ wĕ⁠ẖiẕi֑̇ym wa⁠yi̇qȧ֥ẖ ʼélá֖y⁠w qe֥şěţ wĕ⁠ẖiẕiֽ̇ym׃"],[13,16,"וַ⁠יֹּ֣אמֶר ׀ לְ⁠מֶ֣לֶךְ יִשְׂרָאֵ֗ל הַרְכֵּ֤ב יָֽדְ⁠ךָ֙ עַל־הַ⁠קֶּ֔שֶׁת וַ⁠יַּרְכֵּ֖ב יָד֑⁠וֹ וַ⁠יָּ֧שֶׂם אֱלִישָׁ֛ע יָדָ֖י⁠ו עַל־יְדֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yò֣̇ʼmer ׀ lĕ⁠me֣lekĕ yişĕ̂ráʼé֗l harĕké֤̇b yáֽdĕ⁠ká֙ ʻal-ha⁠qė֔şěţ wa⁠yȧrĕké֖̇b yád֑⁠wò wa⁠yá֧̇şêm ʼèliyşá֛̌ʻ yádá֖y⁠w ʻal-yĕdé֥y ha⁠mėֽlekĕ׃"],[13,17,"וַ⁠יֹּ֗אמֶר פְּתַ֧ח הַ⁠חַלּ֛וֹן קֵ֖דְמָ⁠ה וַ⁠יִּפְתָּ֑ח וַ⁠יֹּ֤אמֶר אֱלִישָׁ֤ע יְרֵה֙ וַ⁠יּ֔וֹר וַ⁠יֹּ֗אמֶר חֵץ־תְּשׁוּעָ֤ה לַֽ⁠יהוָה֙ וְ⁠חֵ֣ץ תְּשׁוּעָ֣ה בַֽ⁠אֲרָ֔ם וְ⁠הִכִּיתָ֧ אֶת־אֲרָ֛ם בַּ⁠אֲפֵ֖ק עַד־כַּלֵּֽה׃","wa⁠yò̇֗ʼmer pĕ̇ţa֧ẖ ha⁠ẖal֛̇wòn qé֖dĕmá⁠h wa⁠yi̇pĕţá֑̇ẖ wa⁠yò֤̇ʼmer ʼèliyşá֤̌ʻ yĕréh֙ wa⁠ẏ֔wòr wa⁠yò̇֗ʼmer ẖéẕ-ţĕ̇ş̌ẇʻá֤h laֽ⁠yhwáh֙ wĕ⁠ẖé֣ẕ ţĕ̇ş̌ẇʻá֣h baֽ⁠ʼàrá֔m wĕ⁠hiki̇yţá֧ ʼeţ-ʼàrá֛m bȧ⁠ʼàpé֖q ʻad-kȧléֽ̇h׃"],[13,18,"וַ⁠יֹּ֛אמֶר קַ֥ח הַ⁠חִצִּ֖ים וַ⁠יִּקָּ֑ח וַ⁠יֹּ֤אמֶר לְ⁠מֶֽלֶךְ־יִשְׂרָאֵל֙ הַךְ־אַ֔רְצָ⁠ה וַ⁠יַּ֥ךְ שָֽׁלֹשׁ־פְּעָמִ֖ים וַֽ⁠יַּעֲמֹֽד׃","wa⁠yò֛̇ʼmer qa֥ẖ ha⁠ẖiẕi֖̇ym wa⁠yi̇qá֑̇ẖ wa⁠yò֤̇ʼmer lĕ⁠meֽlekĕ-yişĕ̂ráʼél֙ hakĕ-ʼa֔rĕẕá⁠h wa⁠yȧ֥kĕ şáֽ̌lòş̌-pĕ̇ʻámi֖ym waֽ⁠yȧʻàmòֽd׃"],[13,19,"וַ⁠יִּקְצֹ֨ף עָלָ֜י⁠ו אִ֣ישׁ הָ⁠אֱלֹהִ֗ים וַ⁠יֹּ֨אמֶר֙ לְ⁠הַכּ֨וֹת חָמֵ֤שׁ אוֹ־שֵׁשׁ֙ פְּעָמִ֔ים אָ֛ז הִכִּ֥יתָ אֶת־אֲרָ֖ם עַד־כַּלֵּ֑ה וְ⁠עַתָּ֕ה שָׁלֹ֥שׁ פְּעָמִ֖ים תַּכֶּ֥ה אֶת־אֲרָֽם׃ס","wa⁠yi̇qĕẕò֨p ʻálá֜y⁠w ʼi֣yş̌ há⁠ʼèlòhi֗ym wa⁠yò̇֨ʼmer֙ lĕ⁠hak̇֨wòţ ẖámé֤ş̌ ʼwò-şé̌ş̌֙ pĕ̇ʻámi֔ym ʼá֛z hiki֥̇yţá ʼeţ-ʼàrá֖m ʻad-kȧlé֑̇h wĕ⁠ʻaţá̇֕h şá̌lò֥ş̌ pĕ̇ʻámi֖ym ţȧkė֥h ʼeţ-ʼàráֽm׃s"],[13,20,"וַ⁠יָּ֥מָת אֱלִישָׁ֖ע וַֽ⁠יִּקְבְּרֻ֑⁠הוּ וּ⁠גְדוּדֵ֥י מוֹאָ֛ב יָבֹ֥אוּ בָ⁠אָ֖רֶץ בָּ֥א שָׁנָֽה׃","wa⁠yá֥̇máţ ʼèliyşá֖̌ʻ waֽ⁠yi̇qĕbĕ̇ru֑⁠hẇ ẇ⁠gĕdẇdé֥y mwòʼá֛b yábò֥ʼẇ bá⁠ʼá֖reẕ bá֥̇ʼ şá̌náֽh׃"],[13,21,"וַ⁠יְהִ֞י הֵ֣ם ׀ קֹבְרִ֣ים אִ֗ישׁ וְ⁠הִנֵּה֙ רָא֣וּ אֶֽת־הַ⁠גְּד֔וּד וַ⁠יַּשְׁלִ֥יכוּ אֶת־הָ⁠אִ֖ישׁ בְּ⁠קֶ֣בֶר אֱלִישָׁ֑ע וַ⁠יֵּ֜לֶךְ וַ⁠יִּגַּ֤ע הָ⁠אִישׁ֙ בְּ⁠עַצְמ֣וֹת אֱלִישָׁ֔ע וַ⁠יְחִ֖י וַ⁠יָּ֥קָם עַל־רַגְלָֽי⁠ו׃פ","wa⁠yĕhi֞y hé֣m ׀ qòbĕri֣ym ʼi֗yş̌ wĕ⁠hiné̇h֙ ráʼ֣ẇ ʼeֽţ-ha⁠gĕ̇d֔ẇd wa⁠yȧşĕ̌li֥ykẇ ʼeţ-há⁠ʼi֖yş̌ bĕ̇⁠qe֣ber ʼèliyşá֑̌ʻ wa⁠yé̇֜lekĕ wa⁠yi̇gȧ֤ʻ há⁠ʼiyş̌֙ bĕ̇⁠ʻaẕĕm֣wòţ ʼèliyşá̌֔ʻ wa⁠yĕẖi֖y wa⁠yá֥̇qám ʻal-ragĕláֽy⁠w׃p"],[13,22,"וַֽ⁠חֲזָאֵל֙ מֶ֣לֶךְ אֲרָ֔ם לָחַ֖ץ אֶת־יִשְׂרָאֵ֑ל כֹּ֖ל יְמֵ֥י יְהוֹאָחָֽז׃","waֽ⁠ẖàzáʼél֙ me֣lekĕ ʼàrá֔m láẖa֖ẕ ʼeţ-yişĕ̂ráʼé֑l kò֖̇l yĕmé֥y yĕhwòʼáẖáֽz׃"],[13,23,"וַ⁠יָּחָן֩ יְהוָ֨ה אֹתָ֤⁠ם וַֽ⁠יְרַחֲמֵ⁠ם֙ וַ⁠יִּ֣פֶן אֲלֵי⁠הֶ֔ם לְמַ֣עַן בְּרִית֔⁠וֹ אֶת־אַבְרָהָ֖ם יִצְחָ֣ק וְ⁠יַֽעֲקֹ֑ב וְ⁠לֹ֤א אָבָה֙ הַשְׁחִיתָ֔⁠ם וְ⁠לֹֽא־הִשְׁלִיכָ֥⁠ם מֵֽ⁠עַל־פָּנָ֖י⁠ו עַד־עָֽתָּה׃","wa⁠yá̇ẖán֩ yĕhwá֨h ʼòţá֤⁠m waֽ⁠yĕraẖàmé⁠m֙ wa⁠yi֣̇pen ʼàléy⁠he֔m lĕma֣ʻan bĕ̇riyţ֔⁠wò ʼeţ-ʼabĕráhá֖m yiẕĕẖá֣q wĕ⁠yaֽʻàqò֑b wĕ⁠lò֤ʼ ʼábáh֙ haşĕ̌ẖiyţá֔⁠m wĕ⁠lòֽʼ-hişĕ̌liyká֥⁠m méֽ⁠ʻal-pá̇ná֖y⁠w ʻad-ʻáֽţá̇h׃"],[13,24,"וַ⁠יָּ֖מָת חֲזָאֵ֣ל מֶֽלֶךְ־אֲרָ֑ם וַ⁠יִּמְלֹ֛ךְ בֶּן־הֲדַ֥ד בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yá֖̇máţ ẖàzáʼé֣l meֽlekĕ-ʼàrá֑m wa⁠yi̇mĕlò֛kĕ bėn-hàda֥d bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[13,25,"וַ⁠יָּ֜שָׁב יְהוֹאָ֣שׁ בֶּן־יְהוֹאָחָ֗ז וַ⁠יִּקַּ֤ח אֶת־הֶֽ⁠עָרִים֙ מִ⁠יַּד֙ בֶּן־הֲדַ֣ד בֶּן־חֲזָאֵ֔ל אֲשֶׁ֣ר לָקַ֗ח מִ⁠יַּ֛ד יְהוֹאָחָ֥ז אָבִ֖י⁠ו בַּ⁠מִּלְחָמָ֑ה שָׁלֹ֤שׁ פְּעָמִים֙ הִכָּ֣⁠הוּ יוֹאָ֔שׁ וַ⁠יָּ֖שֶׁב אֶת־עָרֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yá̇֜şá̌b yĕhwòʼá֣ş̌ bėn-yĕhwòʼáẖá֗z wa⁠yi̇qȧ֤ẖ ʼeţ-heֽ⁠ʻáriym֙ mi⁠yȧd֙ bėn-hàda֣d bėn-ẖàzáʼé֔l ʼàşě֣r láqa֗ẖ mi⁠yȧ֛d yĕhwòʼáẖá֥z ʼábi֖y⁠w bȧ⁠mi̇lĕẖámá֑h şá̌lò֤ş̌ pĕ̇ʻámiym֙ hiká֣̇⁠hẇ ywòʼá֔ş̌ wa⁠yá֖̇şěb ʼeţ-ʻáré֥y yişĕ̂ráʼéֽl׃p"],[14,1,"בִּ⁠שְׁנַ֣ת שְׁתַּ֔יִם לְ⁠יוֹאָ֥שׁ בֶּן־יוֹאָחָ֖ז מֶ֣לֶךְ יִשְׂרָאֵ֑ל מָלַ֛ךְ אֲמַצְיָ֥הוּ בֶן־יוֹאָ֖שׁ מֶ֥לֶךְ יְהוּדָֽה׃","bi̇⁠şĕ̌na֣ţ şĕ̌ţȧ֔yim lĕ⁠ywòʼá֥ş̌ bėn-ywòʼáẖá֖z me֣lekĕ yişĕ̂ráʼé֑l mála֛kĕ ʼàmaẕĕyá֥hẇ ben-ywòʼá֖ş̌ me֥lekĕ yĕhẇdáֽh׃"],[14,2,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ הָיָ֣ה בְ⁠מָלְכ֔⁠וֹ וְ⁠עֶשְׂרִ֤ים וָ⁠תֵ֨שַׁע֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יהועדין מִן־יְרוּשָׁלִָֽם׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ háyá֣h bĕ⁠málĕk֔⁠wò wĕ⁠ʻeşĕ̂ri֤ym wá⁠ţé֨şǎʻ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò yhwʻdyn min-yĕrẇşá̌liáֽm׃"],[14,3,"וַ⁠יַּ֤עַשׂ הַ⁠יָּשָׁר֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה רַ֕ק לֹ֖א כְּ⁠דָוִ֣ד אָבִ֑י⁠ו כְּ⁠כֹ֧ל אֲשֶׁר־עָשָׂ֛ה יוֹאָ֥שׁ אָבִ֖י⁠ו עָשָֽׂה׃","wa⁠yȧ֤ʻaş̂ ha⁠yá̇şá̌r֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h ra֕q lò֖ʼ kĕ̇⁠dáwi֣d ʼábi֑y⁠w kĕ̇⁠kò֧l ʼàşěr-ʻáşá֛̂h ywòʼá֥ş̌ ʼábi֖y⁠w ʻáşáֽ̂h׃"],[14,4,"רַ֥ק הַ⁠בָּמ֖וֹת לֹא־סָ֑רוּ ע֥וֹד הָ⁠עָ֛ם מְזַבְּחִ֥ים וּֽ⁠מְקַטְּרִ֖ים בַּ⁠בָּמֽוֹת׃","ra֥q ha⁠bá̇m֖wòţ lòʼ-sá֑rẇ ʻ֥wòd há⁠ʻá֛m mĕzabĕ̇ẖi֥ym ẇֽ⁠mĕqatĕ̇ri֖ym bȧ⁠bá̇mֽwòţ׃"],[14,5,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֛ר חָזְקָ֥ה הַ⁠מַּמְלָכָ֖ה בְּ⁠יָד֑⁠וֹ וַ⁠יַּךְ֙ אֶת־עֲבָדָ֔י⁠ו הַ⁠מַּכִּ֖ים אֶת־הַ⁠מֶּ֥לֶךְ אָבִֽי⁠ו׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֛r ẖázĕqá֥h ha⁠mȧmĕláká֖h bĕ̇⁠yád֑⁠wò wa⁠yȧkĕ֙ ʼeţ-ʻàbádá֔y⁠w ha⁠mȧki֖̇ym ʼeţ-ha⁠mė֥lekĕ ʼábiֽy⁠w׃"],[14,6,"וְ⁠אֶת־בְּנֵ֥י הַ⁠מַּכִּ֖ים לֹ֣א הֵמִ֑ית כַּ⁠כָּת֣וּב בְּ⁠סֵ֣פֶר תּֽוֹרַת־מֹ֠שֶׁה אֲשֶׁר־צִוָּ֨ה יְהוָ֜ה לֵ⁠אמֹ֗ר לֹא־יוּמְת֨וּ אָב֤וֹת עַל־בָּנִים֙ וּ⁠בָנִים֙ לֹא־יוּמְת֣וּ עַל־אָב֔וֹת כִּ֛י אִם־אִ֥ישׁ בְּ⁠חֶטְא֖⁠וֹ ימות׃","wĕ⁠ʼeţ-bĕ̇né֥y ha⁠mȧki֖̇ym lò֣ʼ hémi֑yţ kȧ⁠ká̇ţ֣ẇb bĕ̇⁠sé֣per ţֽ̇wòraţ-mò֠şěh ʼàşěr-ẕiwá̇֨h yĕhwá֜h lé⁠ʼmò֗r lòʼ-yẇmĕţ֨ẇ ʼáb֤wòţ ʻal-bá̇niym֙ ẇ⁠bániym֙ lòʼ-yẇmĕţ֣ẇ ʻal-ʼáb֔wòţ ki֛̇y ʼim-ʼi֥yş̌ bĕ̇⁠ẖetĕʼ֖⁠wò ymwţ׃"],[14,7,"הוּא־הִכָּ֨ה אֶת־אֱד֤וֹם בְּ⁠גֵיא־המלח עֲשֶׂ֣רֶת אֲלָפִ֔ים וְ⁠תָפַ֥שׂ אֶת־הַ⁠סֶּ֖לַע בַּ⁠מִּלְחָמָ֑ה וַ⁠יִּקְרָ֤א אֶת־שְׁמָ⁠הּ֙ יָקְתְאֵ֔ל עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","hẇʼ-hiká̇֨h ʼeţ-ʼèd֤wòm bĕ̇⁠géyʼ-hmlẖ ʻàşê֣reţ ʼàlápi֔ym wĕ⁠ţápa֥ş̂ ʼeţ-ha⁠sė֖laʻ bȧ⁠mi̇lĕẖámá֑h wa⁠yi̇qĕrá֤ʼ ʼeţ-şĕ̌má⁠ḣ֙ yáqĕţĕʼé֔l ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[14,8,"אָ֣ז שָׁלַ֤ח אֲמַצְיָה֙ מַלְאָכִ֔ים אֶל־יְהוֹאָ֨שׁ בֶּן־יְהוֹאָחָ֧ז בֶּן־יֵה֛וּא מֶ֥לֶךְ יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר לְכָ֖⁠ה נִתְרָאֶ֥ה פָנִֽים׃","ʼá֣z şá̌la֤ẖ ʼàmaẕĕyáh֙ malĕʼáki֔ym ʼel-yĕhwòʼá֨ş̌ bėn-yĕhwòʼáẖá֧z bėn-yéh֛ẇʼ me֥lekĕ yişĕ̂ráʼé֖l lé⁠ʼmò֑r lĕká֖⁠h niţĕráʼe֥h pániֽym׃"],[14,9,"וַ⁠יִּשְׁלַ֞ח יְהוֹאָ֣שׁ מֶֽלֶךְ־יִשְׂרָאֵ֗ל אֶל־אֲמַצְיָ֣הוּ מֶֽלֶךְ־יְהוּדָה֮ לֵ⁠אמֹר֒ הַ⁠ח֜וֹחַ אֲשֶׁ֣ר בַּ⁠לְּבָנ֗וֹן שָׁ֠לַח אֶל־הָ⁠אֶ֜רֶז אֲשֶׁ֤ר בַּ⁠לְּבָנוֹן֙ לֵ⁠אמֹ֔ר תְּנָֽ⁠ה־אֶת־בִּתְּ⁠ךָ֥ לִ⁠בְנִ֖⁠י לְ⁠אִשָּׁ֑ה וַֽ⁠תַּעֲבֹ֞ר חַיַּ֤ת הַ⁠שָּׂדֶה֙ אֲשֶׁ֣ר בַּ⁠לְּבָנ֔וֹן וַ⁠תִּרְמֹ֖ס אֶת־הַ⁠חֽוֹחַ׃","wa⁠yi̇şĕ̌la֞ẖ yĕhwòʼá֣ş̌ meֽlekĕ-yişĕ̂ráʼé֗l ʼel-ʼàmaẕĕyá֣hẇ meֽlekĕ-yĕhẇdáh֮ lé⁠ʼmòr֒ ha⁠ẖ֜wòẖa ʼàşě֣r bȧ⁠lĕ̇bán֗wòn şá̌֠laẖ ʼel-há⁠ʼe֜rez ʼàşě֤r bȧ⁠lĕ̇bánwòn֙ lé⁠ʼmò֔r ţĕ̇náֽ⁠h-ʼeţ-bi̇ţĕ̇⁠ká֥ li⁠bĕni֖⁠y lĕ⁠ʼişá֑̇̌h waֽ⁠ţȧʻàbò֞r ẖayȧ֤ţ ha⁠şá̇̂deh֙ ʼàşě֣r bȧ⁠lĕ̇bán֔wòn wa⁠ţi̇rĕmò֖s ʼeţ-ha⁠ẖֽwòẖa׃"],[14,10,"הַכֵּ֤ה הִכִּ֨יתָ֙ אֶת־אֱד֔וֹם וּֽ⁠נְשָׂאֲ⁠ךָ֖ לִבֶּ֑⁠ךָ הִכָּבֵד֙ וְ⁠שֵׁ֣ב בְּ⁠בֵיתֶ֔⁠ךָ וְ⁠לָ֤⁠מָּה תִתְגָּרֶה֙ בְּ⁠רָעָ֔ה וְ⁠נָ֣פַלְתָּ֔ה אַתָּ֖ה וִ⁠יהוּדָ֥ה עִמָּֽ⁠ךְ׃","haké֤̇h hiki̇֨yţá֙ ʼeţ-ʼèd֔wòm ẇֽ⁠nĕşá̂ʼà⁠ká֖ libė֑⁠ká hiká̇béd֙ wĕ⁠şé֣̌b bĕ̇⁠béyţe֔⁠ká wĕ⁠lá֤⁠má̇h ţiţĕgá̇reh֙ bĕ̇⁠ráʻá֔h wĕ⁠ná֣palĕţá̇֔h ʼaţá֖̇h wi⁠yhẇdá֥h ʻimáֽ̇⁠kĕ׃"],[14,11,"וְ⁠לֹא־שָׁמַ֣ע אֲמַצְיָ֔הוּ וַ⁠יַּ֨עַל יְהוֹאָ֤שׁ מֶֽלֶךְ־יִשְׂרָאֵל֙ וַ⁠יִּתְרָא֣וּ פָנִ֔ים ה֖וּא וַ⁠אֲמַצְיָ֣הוּ מֶֽלֶךְ־יְהוּדָ֑ה בְּ⁠בֵ֥ית שֶׁ֖מֶשׁ אֲשֶׁ֥ר לִ⁠יהוּדָֽה׃","wĕ⁠lòʼ-şá̌ma֣ʻ ʼàmaẕĕyá֔hẇ wa⁠yȧ֨ʻal yĕhwòʼá֤ş̌ meֽlekĕ-yişĕ̂ráʼél֙ wa⁠yi̇ţĕráʼ֣ẇ páni֔ym h֖ẇʼ wa⁠ʼàmaẕĕyá֣hẇ meֽlekĕ-yĕhẇdá֑h bĕ̇⁠bé֥yţ şě֖meş̌ ʼàşě֥r li⁠yhẇdáֽh׃"],[14,12,"וַ⁠יִּנָּ֥גֶף יְהוּדָ֖ה לִ⁠פְנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יָּנֻ֖סוּ אִ֥ישׁ ל⁠אהל⁠ו׃","wa⁠yi̇ná֥̇gep yĕhẇdá֖h li⁠pĕné֣y yişĕ̂ráʼé֑l wa⁠yá̇nu֖sẇ ʼi֥yş̌ l⁠ʼhl⁠w׃"],[14,13,"וְ⁠אֵת֩ אֲמַצְיָ֨הוּ מֶֽלֶךְ־יְהוּדָ֜ה בֶּן־יְהוֹאָ֣שׁ בֶּן־אֲחַזְיָ֗הוּ תָּפַ֛שׂ יְהוֹאָ֥שׁ מֶֽלֶךְ־יִשְׂרָאֵ֖ל בְּ⁠בֵ֣ית שָׁ֑מֶשׁ ו⁠יבאו יְר֣וּשָׁלִַ֔ם וַ⁠יִּפְרֹץ֩ בְּ⁠חוֹמַ֨ת יְרוּשָׁלִַ֜ם בְּ⁠שַׁ֤עַר אֶפְרַ֨יִם֙ עַד־שַׁ֣עַר הַ⁠פִּנָּ֔ה אַרְבַּ֥ע מֵא֖וֹת אַמָּֽה׃","wĕ⁠ʼéţ֩ ʼàmaẕĕyá֨hẇ meֽlekĕ-yĕhẇdá֜h bėn-yĕhwòʼá֣ş̌ bėn-ʼàẖazĕyá֗hẇ ţá̇pa֛ş̂ yĕhwòʼá֥ş̌ meֽlekĕ-yişĕ̂ráʼé֖l bĕ̇⁠bé֣yţ şá֑̌meş̌ w⁠ybʼw yĕr֣ẇşá̌lia֔m wa⁠yi̇pĕròẕ֩ bĕ̇⁠ẖwòma֨ţ yĕrẇşá̌lia֜m bĕ̇⁠şǎ֤ʻar ʼepĕra֨yim֙ ʻad-şǎ֣ʻar ha⁠pi̇ná̇֔h ʼarĕbȧ֥ʻ méʼ֖wòţ ʼamáֽ̇h׃"],[14,14,"וְ⁠לָקַ֣ח אֶת־כָּל־הַ⁠זָּהָב־וְ֠⁠הַ⁠כֶּסֶף וְ⁠אֵ֨ת כָּל־הַ⁠כֵּלִ֜ים הַ⁠נִּמְצְאִ֣ים בֵּית־יְהוָ֗ה וּ⁠בְ⁠אֹֽצְרוֹת֙ בֵּ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠אֵ֖ת בְּנֵ֣י הַ⁠תַּֽעֲרֻב֑וֹת וַ⁠יָּ֖שָׁב שֹׁמְרֽוֹנָ⁠ה׃","wĕ⁠láqa֣ẖ ʼeţ-ká̇l-ha⁠zá̇háb-wĕ֠⁠ha⁠kėsep wĕ⁠ʼé֨ţ ká̇l-ha⁠ké̇li֜ym ha⁠ni̇mĕẕĕʼi֣ym bé̇yţ-yĕhwá֗h ẇ⁠bĕ⁠ʼòֽẕĕrwòţ֙ bé֣̇yţ ha⁠mė֔lekĕ wĕ⁠ʼé֖ţ bĕ̇né֣y ha⁠ţȧֽʻàrub֑wòţ wa⁠yá֖̇şá̌b şò̌mĕrֽwòná⁠h׃"],[14,15,"וְ⁠יֶתֶר֩ דִּבְרֵ֨י יְהוֹאָ֜שׁ אֲשֶׁ֤ר עָשָׂה֙ וּ⁠גְב֣וּרָת֔⁠וֹ וַ⁠אֲשֶׁ֣ר נִלְחַ֔ם עִ֖ם אֲמַצְיָ֣הוּ מֶֽלֶךְ־יְהוּדָ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠yeţer֩ di̇bĕré֨y yĕhwòʼá֜ş̌ ʼàşě֤r ʻáşá̂h֙ ẇ⁠gĕb֣ẇráţ֔⁠wò wa⁠ʼàşě֣r nilĕẖa֔m ʻi֖m ʼàmaẕĕyá֣hẇ meֽlekĕ-yĕhẇdá֑h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[14,16,"וַ⁠יִּשְׁכַּ֤ב יְהוֹאָשׁ֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵר֙ בְּ⁠שֹׁ֣מְר֔וֹן עִ֖ם מַלְכֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּמְלֹ֛ךְ יָרָבְעָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b yĕhwòʼáş̌֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bér֙ bĕ̇⁠şò֣̌mĕr֔wòn ʻi֖m malĕké֣y yişĕ̂ráʼé֑l wa⁠yi̇mĕlò֛kĕ yárábĕʻá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[14,17,"וַ⁠יְחִ֨י אֲמַצְיָ֤הוּ בֶן־יוֹאָשׁ֙ מֶ֣לֶךְ יְהוּדָ֔ה אַֽחֲרֵ֣י מ֔וֹת יְהוֹאָ֥שׁ בֶּן־יְהֽוֹאָחָ֖ז מֶ֣לֶךְ יִשְׂרָאֵ֑ל חֲמֵ֥שׁ עֶשְׂרֵ֖ה שָׁנָֽה׃","wa⁠yĕẖi֨y ʼàmaẕĕyá֤hẇ ben-ywòʼáş̌֙ me֣lekĕ yĕhẇdá֔h ʼaֽẖàré֣y m֔wòţ yĕhwòʼá֥ş̌ bėn-yĕhֽwòʼáẖá֖z me֣lekĕ yişĕ̂ráʼé֑l ẖàmé֥ş̌ ʻeşĕ̂ré֖h şá̌náֽh׃"],[14,18,"וְ⁠יֶ֖תֶר דִּבְרֵ֣י אֲמַצְיָ֑הוּ הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֖ţer di̇bĕré֣y ʼàmaẕĕyá֑hẇ hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[14,19,"וַ⁠יִּקְשְׁר֨וּ עָלָ֥י⁠ו קֶ֛שֶׁר בִּ⁠ירוּשָׁלִַ֖ם וַ⁠יָּ֣נָס לָכִ֑ישָׁ⁠ה וַ⁠יִּשְׁלְח֤וּ אַֽחֲרָי⁠ו֙ לָכִ֔ישָׁ⁠ה וַ⁠יְמִתֻ֖⁠הוּ שָֽׁם׃","wa⁠yi̇qĕşĕ̌r֨ẇ ʻálá֥y⁠w qe֛şěr bi̇⁠yrẇşá̌lia֖m wa⁠yá֣̇nás láki֑yşá̌⁠h wa⁠yi̇şĕ̌lĕẖ֤ẇ ʼaֽẖàráy⁠w֙ láki֔yşá̌⁠h wa⁠yĕmiţu֖⁠hẇ şáֽ̌m׃"],[14,20,"וַ⁠יִּשְׂא֥וּ אֹת֖⁠וֹ עַל־הַ⁠סּוּסִ֑ים וַ⁠יִּקָּבֵ֧ר בִּ⁠ירוּשָׁלִַ֛ם עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֥יר דָּוִֽד׃","wa⁠yi̇şĕ̂ʼ֥ẇ ʼòţ֖⁠wò ʻal-ha⁠ṡẇsi֑ym wa⁠yi̇qá̇bé֧r bi̇⁠yrẇşá̌lia֛m ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֥yr dá̇wiֽd׃"],[14,21,"וַ⁠יִּקְח֞וּ כָּל־עַ֤ם יְהוּדָה֙ אֶת־עֲזַרְיָ֔ה וְ⁠ה֕וּא בֶּן־שֵׁ֥שׁ עֶשְׂרֵ֖ה שָׁנָ֑ה וַ⁠יַּמְלִ֣כוּ אֹת֔⁠וֹ תַּ֖חַת אָבִ֥י⁠ו אֲמַצְיָֽהוּ׃","wa⁠yi̇qĕẖ֞ẇ ká̇l-ʻa֤m yĕhẇdáh֙ ʼeţ-ʻàzarĕyá֔h wĕ⁠h֕ẇʼ bėn-şé֥̌ş̌ ʻeşĕ̂ré֖h şá̌ná֑h wa⁠yȧmĕli֣kẇ ʼòţ֔⁠wò ţȧ֖ẖaţ ʼábi֥y⁠w ʼàmaẕĕyáֽhẇ׃"],[14,22,"ה֚וּא בָּנָ֣ה אֶת־אֵילַ֔ת וַ⁠יְשִׁבֶ֖⁠הָ לִֽ⁠יהוּדָ֑ה אַחֲרֵ֥י שְׁכַֽב־הַ⁠מֶּ֖לֶךְ עִם־אֲבֹתָֽי⁠ו׃פ","h֚ẇʼ bá̇ná֣h ʼeţ-ʼéyla֔ţ wa⁠yĕşǐbe֖⁠há liֽ⁠yhẇdá֑h ʼaẖàré֥y şĕ̌kaֽb-ha⁠mė֖lekĕ ʻim-ʼàbòţáֽy⁠w׃p"],[14,23,"בִּ⁠שְׁנַת֙ חֲמֵשׁ־עֶשְׂרֵ֣ה שָׁנָ֔ה לַ⁠אֲמַצְיָ֥הוּ בֶן־יוֹאָ֖שׁ מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ יָרָבְעָ֨ם בֶּן־יוֹאָ֤שׁ מֶֽלֶךְ־יִשְׂרָאֵל֙ בְּ⁠שֹׁ֣מְר֔וֹן אַרְבָּעִ֥ים וְ⁠אַחַ֖ת שָׁנָֽה׃","bi̇⁠şĕ̌naţ֙ ẖàméş̌-ʻeşĕ̂ré֣h şá̌ná֔h la⁠ʼàmaẕĕyá֥hẇ ben-ywòʼá֖ş̌ me֣lekĕ yĕhẇdá֑h má֠lakĕ yárábĕʻá֨m bėn-ywòʼá֤ş̌ meֽlekĕ-yişĕ̂ráʼél֙ bĕ̇⁠şò֣̌mĕr֔wòn ʼarĕbá̇ʻi֥ym wĕ⁠ʼaẖa֖ţ şá̌náֽh׃"],[14,24,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה לֹ֣א סָ֗ר מִ⁠כָּל־חַטֹּאות֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h lò֣ʼ sá֗r mi⁠ká̇l-ẖatò̇ʼwţ֙ yárábĕʻá֣m bėn-nĕbá֔t ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[14,25,"ה֗וּא הֵשִׁיב֙ אֶת־גְּב֣וּל יִשְׂרָאֵ֔ל מִ⁠לְּב֥וֹא חֲמָ֖ת עַד־יָ֣ם הָ⁠עֲרָבָ֑ה כִּ⁠דְבַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֣ר דִּבֶּ֗ר בְּ⁠יַד־עַבְדּ֞⁠וֹ יוֹנָ֤ה בֶן־אֲמִתַּי֙ הַ⁠נָּבִ֔יא אֲשֶׁ֖ר מִ⁠גַּ֥ת הַחֵֽפֶר׃","h֗ẇʼ héşǐyb֙ ʼeţ-gĕ̇b֣ẇl yişĕ̂ráʼé֔l mi⁠lĕ̇b֥wòʼ ẖàmá֖ţ ʻad-yá֣m há⁠ʻàrábá֑h ki̇⁠dĕba֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşě֣r di̇bė֗r bĕ̇⁠yad-ʻabĕḋ֞⁠wò ywòná֤h ben-ʼàmiţȧy֙ ha⁠ná̇bi֔yʼ ʼàşě֖r mi⁠gȧ֥ţ haẖéֽper׃"],[14,26,"כִּי־רָאָ֧ה יְהוָ֛ה אֶת־עֳנִ֥י יִשְׂרָאֵ֖ל מֹרֶ֣ה מְאֹ֑ד וְ⁠אֶ֤פֶס עָצוּר֙ וְ⁠אֶ֣פֶס עָז֔וּב וְ⁠אֵ֥ין עֹזֵ֖ר לְ⁠יִשְׂרָאֵֽל׃","ki̇y-ráʼá֧h yĕhwá֛h ʼeţ-ʻoni֥y yişĕ̂ráʼé֖l mòre֣h mĕʼò֑d wĕ⁠ʼe֤pes ʻáẕẇr֙ wĕ⁠ʼe֣pes ʻáz֔ẇb wĕ⁠ʼé֥yn ʻòzé֖r lĕ⁠yişĕ̂ráʼéֽl׃"],[14,27,"וְ⁠לֹא־דִבֶּ֣ר יְהוָ֔ה לִ⁠מְחוֹת֙ אֶת־שֵׁ֣ם יִשְׂרָאֵ֔ל מִ⁠תַּ֖חַת הַ⁠שָּׁמָ֑יִם וַ⁠יּ֣וֹשִׁיעֵ֔⁠ם בְּ⁠יַ֖ד יָרָבְעָ֥ם בֶּן־יוֹאָֽשׁ׃","wĕ⁠lòʼ-dibė֣r yĕhwá֔h li⁠mĕẖwòţ֙ ʼeţ-şé֣̌m yişĕ̂ráʼé֔l mi⁠ţȧ֖ẖaţ ha⁠şá̇̌má֑yim wa⁠ẏ֣wòşǐyʻé֔⁠m bĕ̇⁠ya֖d yárábĕʻá֥m bėn-ywòʼáֽş̌׃"],[14,28,"וְ⁠יֶתֶר֩ דִּבְרֵ֨י יָרָבְעָ֜ם וְ⁠כָל־אֲשֶׁ֤ר עָשָׂה֙ וּ⁠גְבוּרָת֣⁠וֹ אֲשֶׁר־נִלְחָ֔ם וַ⁠אֲשֶׁ֨ר הֵשִׁ֜יב אֶת־דַּמֶּ֧שֶׂק וְ⁠אֶת־חֲמָ֛ת לִ⁠יהוּדָ֖ה בְּ⁠יִשְׂרָאֵ֑ל הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠yeţer֩ di̇bĕré֨y yárábĕʻá֜m wĕ⁠kál-ʼàşě֤r ʻáşá̂h֙ ẇ⁠gĕbẇráţ֣⁠wò ʼàşěr-nilĕẖá֔m wa⁠ʼàşě֨r héşǐ֜yb ʼeţ-dȧmė֧şêq wĕ⁠ʼeţ-ẖàmá֛ţ li⁠yhẇdá֖h bĕ̇⁠yişĕ̂ráʼé֑l hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[14,29,"וַ⁠יִּשְׁכַּ֤ב יָֽרָבְעָם֙ עִם־אֲבֹתָ֔י⁠ו עִ֖ם מַלְכֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּמְלֹ֛ךְ זְכַרְיָ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b yáֽrábĕʻám֙ ʻim-ʼàbòţá֔y⁠w ʻi֖m malĕké֣y yişĕ̂ráʼé֑l wa⁠yi̇mĕlò֛kĕ zĕkarĕyá֥h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[15,1,"בִּ⁠שְׁנַ֨ת עֶשְׂרִ֤ים וָ⁠שֶׁ֨בַע֙ שָׁנָ֔ה לְ⁠יָרָבְעָ֖ם מֶ֣לֶךְ יִשְׂרָאֵ֑ל מָלַ֛ךְ עֲזַרְיָ֥ה בֶן־אֲמַצְיָ֖ה מֶ֥לֶךְ יְהוּדָֽה׃","bi̇⁠şĕ̌na֨ţ ʻeşĕ̂ri֤ym wá⁠şě֨baʻ֙ şá̌ná֔h lĕ⁠yárábĕʻá֖m me֣lekĕ yişĕ̂ráʼé֑l mála֛kĕ ʻàzarĕyá֥h ben-ʼàmaẕĕyá֖h me֥lekĕ yĕhẇdáֽh׃"],[15,2,"בֶּן־שֵׁ֨שׁ עֶשְׂרֵ֤ה שָׁנָה֙ הָיָ֣ה בְ⁠מָלְכ֔⁠וֹ וַ⁠חֲמִשִּׁ֤ים וּ⁠שְׁתַּ֨יִם֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יְכָלְיָ֖הוּ מִ⁠ירוּשָׁלִָֽם׃","bėn-şé̌֨ş̌ ʻeşĕ̂ré֤h şá̌náh֙ háyá֣h bĕ⁠málĕk֔⁠wò wa⁠ẖàmişi֤̇̌ym ẇ⁠şĕ̌ţȧ֨yim֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò yĕkálĕyá֖hẇ mi⁠yrẇşá̌liáֽm׃"],[15,3,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה אֲמַצְיָ֥הוּ אָבִֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h ʼàmaẕĕyá֥hẇ ʼábiֽy⁠w׃"],[15,4,"רַ֥ק הַ⁠בָּמ֖וֹת לֹא־סָ֑רוּ ע֥וֹד הָ⁠עָ֛ם מְזַבְּחִ֥ים וּֽ⁠מְקַטְּרִ֖ים בַּ⁠בָּמֽוֹת׃","ra֥q ha⁠bá̇m֖wòţ lòʼ-sá֑rẇ ʻ֥wòd há⁠ʻá֛m mĕzabĕ̇ẖi֥ym ẇֽ⁠mĕqatĕ̇ri֖ym bȧ⁠bá̇mֽwòţ׃"],[15,5,"וַ⁠יְנַגַּ֨ע יְהוָ֜ה אֶת־הַ⁠מֶּ֗לֶךְ וַ⁠יְהִ֤י מְצֹרָע֙ עַד־י֣וֹם מֹת֔⁠וֹ וַ⁠יֵּ֖שֶׁב בְּ⁠בֵ֣ית הַ⁠חָפְשִׁ֑ית וְ⁠יוֹתָ֤ם בֶּן־הַ⁠מֶּ֨לֶךְ֙ עַל־הַ⁠בַּ֔יִת שֹׁפֵ֖ט אֶת־עַ֥ם הָ⁠אָֽרֶץ׃","wa⁠yĕnagȧ֨ʻ yĕhwá֜h ʼeţ-ha⁠mė֗lekĕ wa⁠yĕhi֤y mĕẕòráʻ֙ ʻad-y֣wòm mòţ֔⁠wò wa⁠yé֖̇şěb bĕ̇⁠bé֣yţ ha⁠ẖápĕşǐ֑yţ wĕ⁠ywòţá֤m bėn-ha⁠mė֨lekĕ֙ ʻal-ha⁠bȧ֔yiţ şò̌pé֖t ʼeţ-ʻa֥m há⁠ʼáֽreẕ׃"],[15,6,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י עֲזַרְיָ֖הוּ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y ʻàzarĕyá֖hẇ wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[15,7,"וַ⁠יִּשְׁכַּ֤ב עֲזַרְיָה֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקְבְּר֥וּ אֹת֛⁠וֹ עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֣יר דָּוִ֑ד וַ⁠יִּמְלֹ֛ךְ יוֹתָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ʻàzarĕyáh֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֛⁠wò ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֣yr dá̇wi֑d wa⁠yi̇mĕlò֛kĕ ywòţá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[15,8,"בִּ⁠שְׁנַ֨ת שְׁלֹשִׁ֤ים וּ⁠שְׁמֹנֶה֙ שָׁנָ֔ה לַ⁠עֲזַרְיָ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ זְכַרְיָ֨הוּ בֶן־יָרָבְעָ֧ם עַל־יִשְׂרָאֵ֛ל בְּ⁠שֹׁמְר֖וֹן שִׁשָּׁ֥ה חֳדָשִֽׁים׃","bi̇⁠şĕ̌na֨ţ şĕ̌lòşǐ֤ym ẇ⁠şĕ̌mòneh֙ şá̌ná֔h la⁠ʻàzarĕyá֖hẇ me֣lekĕ yĕhẇdá֑h má֠lakĕ zĕkarĕyá֨hẇ ben-yárábĕʻá֧m ʻal-yişĕ̂ráʼé֛l bĕ̇⁠şò̌mĕr֖wòn şǐşá֥̇̌h ẖodáşǐֽym׃"],[15,9,"וַ⁠יַּ֤עַשׂ הָ⁠רַע֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה כַּ⁠אֲשֶׁ֥ר עָשׂ֖וּ אֲבֹתָ֑י⁠ו לֹ֣א סָ֗ר מֵֽ⁠חַטֹּאות֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧ֤ʻaş̂ há⁠raʻ֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h kȧ⁠ʼàşě֥r ʻáş֖̂ẇ ʼàbòţá֑y⁠w lò֣ʼ sá֗r méֽ⁠ẖatò̇ʼwţ֙ yárábĕʻá֣m bėn-nĕbá֔t ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[15,10,"וַ⁠יִּקְשֹׁ֤ר עָלָי⁠ו֙ שַׁלֻּ֣ם בֶּן־יָבֵ֔שׁ וַ⁠יַּכֵּ֥⁠הוּ קָֽבָלְ־עָ֖ם וַ⁠יְמִיתֵ֑⁠הוּ וַ⁠יִּמְלֹ֖ךְ תַּחְתָּֽי⁠ו׃","wa⁠yi̇qĕşò֤̌r ʻáláy⁠w֙ şǎlu֣̇m bėn-yábé֔ş̌ wa⁠yȧké֥̇⁠hẇ qáֽbálĕ-ʻá֖m wa⁠yĕmiyţé֑⁠hẇ wa⁠yi̇mĕlò֖kĕ ţȧẖĕţáֽ̇y⁠w׃"],[15,11,"וְ⁠יֶ֖תֶר דִּבְרֵ֣י זְכַרְיָ֑ה הִנָּ֣⁠ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֖ţer di̇bĕré֣y zĕkarĕyá֑h hiná֣̇⁠m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[15,12,"ה֣וּא דְבַר־יְהוָ֗ה אֲשֶׁ֨ר דִּבֶּ֤ר אֶל־יֵהוּא֙ לֵ⁠אמֹ֔ר בְּנֵ֣י רְבִיעִ֔ים יֵשְׁב֥וּ לְ⁠ךָ֖ עַל־כִּסֵּ֣א יִשְׂרָאֵ֑ל וַֽ⁠יְהִי־כֵֽן׃פ","h֣ẇʼ dĕbar-yĕhwá֗h ʼàşě֨r di̇bė֤r ʼel-yéhẇʼ֙ lé⁠ʼmò֔r bĕ̇né֣y rĕbiyʻi֔ym yéşĕ̌b֥ẇ lĕ⁠ká֖ ʻal-ki̇sé֣̇ʼ yişĕ̂ráʼé֑l wֽa⁠yĕhiy-kéֽn׃p"],[15,13,"שַׁלּ֤וּם בֶּן־יָבֵישׁ֙ מָלַ֔ךְ בִּ⁠שְׁנַ֨ת שְׁלֹשִׁ֤ים וָ⁠תֵ֨שַׁע֙ שָׁנָ֔ה לְ⁠עֻזִיָּ֖ה מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּמְלֹ֥ךְ יֶֽרַח־יָמִ֖ים בְּ⁠שֹׁמְרֽוֹן׃","şǎl֤̇ẇm bėn-yábéyş̌֙ mála֔kĕ bi̇⁠şĕ̌na֨ţ şĕ̌lòşǐ֤ym wá⁠ţé֨şǎʻ֙ şá̌ná֔h lĕ⁠ʻuziyá֖̇h me֣lekĕ yĕhẇdá֑h wa⁠yi̇mĕlò֥kĕ yeֽraẖ-yámi֖ym bĕ̇⁠şò̌mĕrֽwòn׃"],[15,14,"וַ⁠יַּעַל֩ מְנַחֵ֨ם בֶּן־גָּדִ֜י מִ⁠תִּרְצָ֗ה וַ⁠יָּבֹא֙ שֹׁמְר֔וֹן וַ⁠יַּ֛ךְ אֶת־שַׁלּ֥וּם בֶּן־יָבֵ֖ישׁ בְּ⁠שֹׁמְר֑וֹן וַ⁠יְמִיתֵ֖⁠הוּ וַ⁠יִּמְלֹ֥ךְ תַּחְתָּֽי⁠ו׃","wa⁠yȧʻal֩ mĕnaẖé֨m bėn-gá̇di֜y mi⁠ţi̇rĕẕá֗h wa⁠yá̇bòʼ֙ şò̌mĕr֔wòn wa⁠yȧ֛kĕ ʼeţ-şǎl֥̇ẇm bėn-yábé֖yş̌ bĕ̇⁠şò̌mĕr֑wòn wa⁠yĕmiyţé֖⁠hẇ wa⁠yi̇mĕlò֥kĕ ţȧẖĕţáֽ̇y⁠w׃"],[15,15,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י שַׁלּ֔וּם וְ⁠קִשְׁר֖⁠וֹ אֲשֶׁ֣ר קָשָׁ֑ר הִנָּ֣⁠ם כְּתֻבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃ס","wĕ⁠ye֨ţer֙ di̇bĕré֣y şǎl̇֔ẇm wĕ⁠qişĕ̌r֖⁠wò ʼàşě֣r qáşá֑̌r hiná֣̇⁠m kĕ̇ţubi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃s"],[15,16,"אָ֣ז יַכֶּֽה־מְ֠נַחֵם אֶת־תִּפְסַ֨ח וְ⁠אֶת־כָּל־אֲשֶׁר־בָּ֤⁠הּ וְ⁠אֶת־גְּבוּלֶ֨י⁠הָ֙ מִ⁠תִּרְצָ֔ה כִּ֛י לֹ֥א פָתַ֖ח וַ⁠יַּ֑ךְ אֵ֛ת כָּל־הֶ⁠הָ֥רוֹתֶ֖י⁠הָ בִּקֵּֽעַ׃פ","ʼá֣z yakėֽh-mĕ֠naẖém ʼeţ-ţi̇pĕsa֨ẖ wĕ⁠ʼeţ-ká̇l-ʼàşěr-bá֤̇⁠ḣ wĕ⁠ʼeţ-gĕ̇bẇle֨y⁠há֙ mi⁠ţi̇rĕẕá֔h ki֛̇y lò֥ʼ páţa֖ẖ wa⁠yȧ֑kĕ ʼé֛ţ ká̇l-he⁠há֥rwòţe֖y⁠há bi̇qéֽ̇ʻa׃p"],[15,17,"בִּ⁠שְׁנַ֨ת שְׁלֹשִׁ֤ים וָ⁠תֵ֨שַׁע֙ שָׁנָ֔ה לַ⁠עֲזַרְיָ֖ה מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ מְנַחֵ֨ם בֶּן־גָּדִ֧י עַל־יִשְׂרָאֵ֛ל עֶ֥שֶׂר שָׁנִ֖ים בְּ⁠שֹׁמְרֽוֹן׃","bi̇⁠şĕ̌na֨ţ şĕ̌lòşǐ֤ym wá⁠ţé֨şǎʻ֙ şá̌ná֔h la⁠ʻàzarĕyá֖h me֣lekĕ yĕhẇdá֑h má֠lakĕ mĕnaẖé֨m bėn-gá̇di֧y ʻal-yişĕ̂ráʼé֛l ʻe֥şêr şá̌ni֖ym bĕ̇⁠şò̌mĕrֽwòn׃"],[15,18,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה לֹ֣א סָ֠ר מֵ⁠עַ֨ל חַטֹּ֜אות יָרָבְעָ֧ם בֶּן־נְבָ֛ט אֲשֶׁר־הֶחֱטִ֥יא אֶת־יִשְׂרָאֵ֖ל כָּל־יָמָֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h lò֣ʼ sá֠r mé⁠ʻa֨l ẖatò̇֜ʼwţ yárábĕʻá֧m bėn-nĕbá֛t ʼàşěr-heẖèti֥yʼ ʼeţ-yişĕ̂ráʼé֖l ká̇l-yámáֽy⁠w׃"],[15,19,"בָּ֣א פ֤וּל מֶֽלֶךְ־אַשּׁוּר֙ עַל־הָ⁠אָ֔רֶץ וַ⁠יִּתֵּ֤ן מְנַחֵם֙ לְ⁠פ֔וּל אֶ֖לֶף כִּכַּר־כָּ֑סֶף לִ⁠הְי֤וֹת יָדָי⁠ו֙ אִתּ֔⁠וֹ לְ⁠הַחֲזִ֥יק הַ⁠מַּמְלָכָ֖ה בְּ⁠יָדֽ⁠וֹ׃","bá֣̇ʼ p֤ẇl meֽlekĕ-ʼaş̇̌ẇr֙ ʻal-há⁠ʼá֔reẕ wa⁠yi̇ţé֤̇n mĕnaẖém֙ lĕ⁠p֔ẇl ʼe֖lep ki̇kȧr-ká֑̇sep li⁠hĕy֤wòţ yádáy⁠w֙ ʼiţ̇֔⁠wò lĕ⁠haẖàzi֥yq ha⁠mȧmĕláká֖h bĕ̇⁠yádֽ⁠wò׃"],[15,20,"וַ⁠יֹּצֵא֩ מְנַחֵ֨ם אֶת־הַ⁠כֶּ֜סֶף עַל־יִשְׂרָאֵ֗ל עַ֚ל כָּל־גִּבּוֹרֵ֣י הַ⁠חַ֔יִל לָ⁠תֵת֙ לְ⁠מֶ֣לֶךְ אַשּׁ֔וּר חֲמִשִּׁ֧ים שְׁקָלִ֛ים כֶּ֖סֶף לְ⁠אִ֣ישׁ אֶחָ֑ד וַ⁠יָּ֨שָׁב֙ מֶ֣לֶךְ אַשּׁ֔וּר וְ⁠לֹא־עָ֥מַד שָׁ֖ם בָּ⁠אָֽרֶץ׃","wa⁠yò̇ẕéʼ֩ mĕnaẖé֨m ʼeţ-ha⁠kė֜sep ʻal-yişĕ̂ráʼé֗l ʻa֚l ká̇l-gi̇ḃwòré֣y ha⁠ẖa֔yil lá⁠ţéţ֙ lĕ⁠me֣lekĕ ʼaş̇̌֔ẇr ẖàmişi֧̇̌ym şĕ̌qáli֛ym kė֖sep lĕ⁠ʼi֣yş̌ ʼeẖá֑d wa⁠yá̇֨şá̌b֙ me֣lekĕ ʼaş̇̌֔ẇr wĕ⁠lòʼ-ʻá֥mad şá֖̌m bá̇⁠ʼáֽreẕ׃"],[15,21,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י מְנַחֵ֖ם וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֛ţer di̇bĕré֥y mĕnaẖé֖m wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[15,22,"וַ⁠יִּשְׁכַּ֥ב מְנַחֵ֖ם עִם־אֲבֹתָ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ פְּקַחְיָ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֥b mĕnaẖé֖m ʻim-ʼàbòţá֑y⁠w wa⁠yi̇mĕlò֛kĕ pĕ̇qaẖĕyá֥h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[15,23,"בִּ⁠שְׁנַת֙ חֲמִשִּׁ֣ים שָׁנָ֔ה לַ⁠עֲזַרְיָ֖ה מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ פְּקַֽחְיָ֨ה בֶן־מְנַחֵ֧ם עַל־יִשְׂרָאֵ֛ל בְּ⁠שֹׁמְר֖וֹן שְׁנָתָֽיִם׃","bi̇⁠şĕ̌naţ֙ ẖàmişi֣̇̌ym şá̌ná֔h la⁠ʻàzarĕyá֖h me֣lekĕ yĕhẇdá֑h má֠lakĕ pĕ̇qaֽẖĕyá֨h ben-mĕnaẖé֧m ʻal-yişĕ̂ráʼé֛l bĕ̇⁠şò̌mĕr֖wòn şĕ̌náţáֽyim׃"],[15,24,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה לֹ֣א סָ֗ר מֵֽ⁠חַטֹּאות֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h lò֣ʼ sá֗r méֽ⁠ẖatò̇ʼwţ֙ yárábĕʻá֣m bėn-nĕbá֔t ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[15,25,"וַ⁠יִּקְשֹׁ֣ר עָלָי⁠ו֩ פֶּ֨קַח בֶּן־רְמַלְיָ֜הוּ שָׁלִישׁ֗⁠וֹ וַ⁠יַּכֵּ֨⁠הוּ בְ⁠שֹׁמְר֜וֹן בְּ⁠אַרְמ֤וֹן בֵּית־מלך אֶת־אַרְגֹּ֣ב וְ⁠אֶת־הָ⁠אַרְיֵ֔ה וְ⁠עִמּ֛⁠וֹ חֲמִשִּׁ֥ים אִ֖ישׁ מִ⁠בְּנֵ֣י גִלְעָדִ֑ים וַ⁠יְמִיתֵ֖⁠הוּ וַ⁠יִּמְלֹ֥ךְ תַּחְתָּֽי⁠ו׃","wa⁠yi̇qĕşò֣̌r ʻáláy⁠w֩ pė֨qaẖ bėn-rĕmalĕyá֜hẇ şá̌liyş̌֗⁠wò wa⁠yȧké̇֨⁠hẇ bĕ⁠şò̌mĕr֜wòn bĕ̇⁠ʼarĕm֤wòn bé̇yţ-mlk ʼeţ-ʼarĕgò֣̇b wĕ⁠ʼeţ-há⁠ʼarĕyé֔h wĕ⁠ʻiṁ֛⁠wò ẖàmişi֥̇̌ym ʼi֖yş̌ mi⁠bĕ̇né֣y gilĕʻádi֑ym wa⁠yĕmiyţé֖⁠hẇ wa⁠yi̇mĕlò֥kĕ ţȧẖĕţáֽ̇y⁠w׃"],[15,26,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י פְקַחְיָ֖ה וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הִנָּ֣⁠ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠ye֛ţer di̇bĕré֥y pĕqaẖĕyá֖h wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hiná֣̇⁠m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃p"],[15,27,"בִּ⁠שְׁנַ֨ת חֲמִשִּׁ֤ים וּ⁠שְׁתַּ֨יִם֙ שָׁנָ֔ה לַ⁠עֲזַרְיָ֖ה מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ פֶּ֣קַח בֶּן־רְמַלְיָ֧הוּ עַל־יִשְׂרָאֵ֛ל בְּ⁠שֹׁמְר֖וֹן עֶשְׂרִ֥ים שָׁנָֽה׃","bi̇⁠şĕ̌na֨ţ ẖàmişi֤̇̌ym ẇ⁠şĕ̌ţȧ֨yim֙ şá̌ná֔h la⁠ʻàzarĕyá֖h me֣lekĕ yĕhẇdá֑h má֠lakĕ pė֣qaẖ bėn-rĕmalĕyá֧hẇ ʻal-yişĕ̂ráʼé֛l bĕ̇⁠şò̌mĕr֖wòn ʻeşĕ̂ri֥ym şá̌náֽh׃"],[15,28,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה לֹ֣א סָ֗ר מִן־חַטֹּאות֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h lò֣ʼ sá֗r min-ẖatò̇ʼwţ֙ yárábĕʻá֣m bėn-nĕbá֔t ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[15,29,"בִּ⁠ימֵ֞י פֶּ֣קַח מֶֽלֶךְ־יִשְׂרָאֵ֗ל בָּא֮ תִּגְלַ֣ת פִּלְאֶסֶר֮ מֶ֣לֶךְ אַשּׁוּר֒ וַ⁠יִּקַּ֣ח אֶת־עִיּ֡וֹן וְ⁠אֶת־אָבֵ֣ל בֵּֽית־מַעֲכָ֡ה וְ⁠אֶת־יָ֠נוֹחַ וְ⁠אֶת־קֶ֨דֶשׁ וְ⁠אֶת־חָצ֤וֹר וְ⁠אֶת־הַ⁠גִּלְעָד֙ וְ⁠אֶת־הַ⁠גָּלִ֔ילָ⁠ה כֹּ֖ל אֶ֣רֶץ נַפְתָּלִ֑י וַ⁠יַּגְלֵ֖⁠ם אַשּֽׁוּרָ⁠ה׃","bi̇⁠ymé֞y pė֣qaẖ meֽlekĕ-yişĕ̂ráʼé֗l bá̇ʼ֮ ţi̇gĕla֣ţ pi̇lĕʼeser֮ me֣lekĕ ʼaş̇̌ẇr֒ wa⁠yi̇qȧ֣ẖ ʼeţ-ʻiẏ֡wòn wĕ⁠ʼeţ-ʼábé֣l béֽ̇yţ-maʻàká֡h wĕ⁠ʼeţ-yá֠nwòẖa wĕ⁠ʼeţ-qe֨deş̌ wĕ⁠ʼeţ-ẖáẕ֤wòr wĕ⁠ʼeţ-ha⁠gi̇lĕʻád֙ wĕ⁠ʼeţ-ha⁠gá̇li֔ylá⁠h kò֖̇l ʼe֣reẕ napĕţá̇li֑y wa⁠yȧgĕlé֖⁠m ʼaşֽ̇̌ẇrá⁠h׃"],[15,30,"וַ⁠יִּקְשָׁר־קֶ֜שֶׁר הוֹשֵׁ֣עַ בֶּן־אֵלָ֗ה עַל־פֶּ֨קַח֙ בֶּן־רְמַלְיָ֔הוּ וַ⁠יַּכֵּ֨⁠הוּ֙ וַ⁠יְמִיתֵ֔⁠הוּ וַ⁠יִּמְלֹ֖ךְ תַּחְתָּ֑י⁠ו בִּ⁠שְׁנַ֣ת עֶשְׂרִ֔ים לְ⁠יוֹתָ֖ם בֶּן־עֻזִיָּֽה׃","wa⁠yi̇qĕşá̌r-qe֜şěr hwòşé֣̌ʻa bėn-ʼélá֗h ʻal-pė֨qaẖ֙ bėn-rĕmalĕyá֔hẇ wa⁠yȧké̇֨⁠hẇ֙ wa⁠yĕmiyţé֔⁠hẇ wa⁠yi̇mĕlò֖kĕ ţȧẖĕţá֑̇y⁠w bi̇⁠şĕ̌na֣ţ ʻeşĕ̂ri֔ym lĕ⁠ywòţá֖m bėn-ʻuziyáֽ̇h׃"],[15,31,"וְ⁠יֶ֥תֶר דִּבְרֵי־פֶ֖קַח וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הִנָּ֣⁠ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠ye֥ţer di̇bĕréy-pe֖qaẖ wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hiná֣̇⁠m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃p"],[15,32,"בִּ⁠שְׁנַ֣ת שְׁתַּ֔יִם לְ⁠פֶ֥קַח בֶּן־רְמַלְיָ֖הוּ מֶ֣לֶךְ יִשְׂרָאֵ֑ל מָלַ֛ךְ יוֹתָ֥ם בֶּן־עֻזִיָּ֖הוּ מֶ֥לֶךְ יְהוּדָֽה׃","bi̇⁠şĕ̌na֣ţ şĕ̌ţȧ֔yim lĕ⁠pe֥qaẖ bėn-rĕmalĕyá֖hẇ me֣lekĕ yişĕ̂ráʼé֑l mála֛kĕ ywòţá֥m bėn-ʻuziyá֖̇hẇ me֥lekĕ yĕhẇdáֽh׃"],[15,33,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ הָיָ֣ה בְ⁠מָלְכ֔⁠וֹ וְ⁠שֵׁשׁ־עֶשְׂרֵ֣ה שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יְרוּשָׁ֖א בַּת־צָדֽוֹק׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ háyá֣h bĕ⁠málĕk֔⁠wò wĕ⁠şé̌ş̌-ʻeşĕ̂ré֣h şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò yĕrẇşá֖̌ʼ bȧţ-ẕádֽwòq׃"],[15,34,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֧ל אֲשֶׁר־עָשָׂ֛ה עֻזִיָּ֥הוּ אָבִ֖י⁠ו עָשָֽׂה׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֧l ʼàşěr-ʻáşá֛̂h ʻuziyá֥̇hẇ ʼábi֖y⁠w ʻáşáֽ̂h׃"],[15,35,"רַ֤ק הַ⁠בָּמוֹת֙ לֹ֣א סָ֔רוּ ע֗וֹד הָ⁠עָ֛ם מְזַבְּחִ֥ים וּֽ⁠מְקַטְּרִ֖ים בַּ⁠בָּמ֑וֹת ה֗וּא בָּנָ֛ה אֶת־שַׁ֥עַר בֵּית־יְהוָ֖ה הָ⁠עֶלְיֽוֹן׃","ra֤q ha⁠bá̇mwòţ֙ lò֣ʼ sá֔rẇ ʻ֗wòd há⁠ʻá֛m mĕzabĕ̇ẖi֥ym ẇֽ⁠mĕqatĕ̇ri֖ym bȧ⁠bá̇m֑wòţ h֗ẇʼ bá̇ná֛h ʼeţ-şǎ֥ʻar bé̇yţ-yĕhwá֖h há⁠ʻelĕyֽwòn׃"],[15,36,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יוֹתָ֖ם אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y ywòţá֖m ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[15,37,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם הֵחֵ֣ל יְהוָ֗ה לְ⁠הַשְׁלִ֨יחַ֙ בִּֽ⁠יהוּדָ֔ה רְצִ֖ין מֶ֣לֶךְ אֲרָ֑ם וְ⁠אֵ֖ת פֶּ֥קַח בֶּן־רְמַלְיָֽהוּ׃","bȧ⁠yá̇mi֣ym há⁠hé֔m héẖé֣l yĕhwá֗h lĕ⁠haşĕ̌li֨yẖa֙ biֽ̇⁠yhẇdá֔h rĕẕi֖yn me֣lekĕ ʼàrá֑m wĕ⁠ʼé֖ţ pė֥qaẖ bėn-rĕmalĕyáֽhẇ׃"],[15,38,"וַ⁠יִּשְׁכַּ֤ב יוֹתָם֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵר֙ עִם־אֲבֹתָ֔י⁠ו בְּ⁠עִ֖יר דָּוִ֣ד אָבִ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ אָחָ֥ז בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ywòţám֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bér֙ ʻim-ʼàbòţá֔y⁠w bĕ̇⁠ʻi֖yr dá̇wi֣d ʼábi֑y⁠w wa⁠yi̇mĕlò֛kĕ ʼáẖá֥z bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[16,1,"בִּ⁠שְׁנַת֙ שְׁבַֽע־עֶשְׂרֵ֣ה שָׁנָ֔ה לְ⁠פֶ֖קַח בֶּן־רְמַלְיָ֑הוּ מָלַ֛ךְ אָחָ֥ז בֶּן־יוֹתָ֖ם מֶ֥לֶךְ יְהוּדָֽה׃","bi̇⁠şĕ̌naţ֙ şĕ̌baֽʻ-ʻeşĕ̂ré֣h şá̌ná֔h lĕ⁠pe֖qaẖ bėn-rĕmalĕyá֑hẇ mála֛kĕ ʼáẖá֥z bėn-ywòţá֖m me֥lekĕ yĕhẇdáֽh׃"],[16,2,"בֶּן־עֶשְׂרִ֤ים שָׁנָה֙ אָחָ֣ז בְּ⁠מָלְכ֔⁠וֹ וְ⁠שֵׁשׁ־עֶשְׂרֵ֣ה שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠לֹא־עָשָׂ֣ה הַ⁠יָּשָׁ֗ר בְּ⁠עֵינֵ֛י יְהוָ֥ה אֱלֹהָ֖י⁠ו כְּ⁠דָוִ֥ד אָבִֽי⁠ו׃","bėn-ʻeşĕ̂ri֤ym şá̌náh֙ ʼáẖá֣z bĕ̇⁠málĕk֔⁠wò wĕ⁠şé̌ş̌-ʻeşĕ̂ré֣h şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠lòʼ-ʻáşá֣̂h ha⁠yá̇şá̌֗r bĕ̇⁠ʻéyné֛y yĕhwá֥h ʼèlòhá֖y⁠w kĕ̇⁠dáwi֥d ʼábiֽy⁠w׃"],[16,3,"וַ⁠יֵּ֕לֶךְ בְּ⁠דֶ֖רֶךְ מַלְכֵ֣י יִשְׂרָאֵ֑ל וְ⁠גַ֤ם אֶת־בְּנ⁠וֹ֙ הֶעֱבִ֣יר בָּ⁠אֵ֔שׁ כְּ⁠תֹֽעֲבוֹת֙ הַ⁠גּוֹיִ֔ם אֲשֶׁ֨ר הוֹרִ֤ישׁ יְהוָה֙ אֹתָ֔⁠ם מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yé̇֕lekĕ bĕ̇⁠de֖rekĕ malĕké֣y yişĕ̂ráʼé֑l wĕ⁠ga֤m ʼeţ-bĕ̇n⁠wò֙ heʻèbi֣yr bá̇⁠ʼé֔ş̌ kĕ̇⁠ţòֽʻàbwòţ֙ ha⁠ġwòyi֔m ʼàşě֨r hwòri֤yş̌ yĕhwáh֙ ʼòţá֔⁠m mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[16,4,"וַ⁠יְזַבֵּ֧חַ וַ⁠יְקַטֵּ֛ר בַּ⁠בָּמ֖וֹת וְ⁠עַל־הַ⁠גְּבָע֑וֹת וְ⁠תַ֖חַת כָּל־עֵ֥ץ רַעֲנָֽן׃","wa⁠yĕzabé֧̇ẖa wa⁠yĕqaté֛̇r bȧ⁠bá̇m֖wòţ wĕ⁠ʻal-ha⁠gĕ̇báʻ֑wòţ wĕ⁠ţa֖ẖaţ ká̇l-ʻé֥ẕ raʻànáֽn׃"],[16,5,"אָ֣ז יַעֲלֶ֣ה רְצִ֣ין מֶֽלֶךְ־אֲ֠רָם וּ⁠פֶ֨קַח בֶּן־רְמַלְיָ֧הוּ מֶֽלֶךְ־יִשְׂרָאֵ֛ל יְרוּשָׁלִַ֖ם לַ⁠מִּלְחָמָ֑ה וַ⁠יָּצֻ֨רוּ֙ עַל־אָחָ֔ז וְ⁠לֹ֥א יָכְל֖וּ לְ⁠הִלָּחֵֽם׃","ʼá֣z yaʻàle֣h rĕẕi֣yn meֽlekĕ-ʼà֠rám ẇ⁠pe֨qaẖ bėn-rĕmalĕyá֧hẇ meֽlekĕ-yişĕ̂ráʼé֛l yĕrẇşá̌lia֖m la⁠mi̇lĕẖámá֑h wa⁠yá̇ẕu֨rẇ֙ ʻal-ʼáẖá֔z wĕ⁠lò֥ʼ yákĕl֖ẇ lĕ⁠hilá̇ẖéֽm׃"],[16,6,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא הֵ֠שִׁיב רְצִ֨ין מֶֽלֶךְ־אֲרָ֤ם אֶת־אֵילַת֙ לַֽ⁠אֲרָ֔ם וַ⁠יְנַשֵּׁ֥ל אֶת־הַ⁠יְהוּדִ֖ים מֵֽ⁠אֵיל֑וֹת ו⁠ארמים בָּ֣אוּ אֵילַ֔ת וַ⁠יֵּ֣שְׁבוּ שָׁ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ hé֠şǐyb rĕẕi֨yn meֽlekĕ-ʼàrá֤m ʼeţ-ʼéylaţ֙ laֽ⁠ʼàrá֔m wa⁠yĕnaşé֥̇̌l ʼeţ-ha⁠yĕhẇdi֖ym méֽ⁠ʼéyl֑wòţ w⁠ʼrmym bá֣̇ʼẇ ʼéyla֔ţ wa⁠yé֣̇şĕ̌bẇ şá̌֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[16,7,"וַ⁠יִּשְׁלַ֨ח אָחָ֜ז מַלְאָכִ֗ים אֶל־תִּ֠גְלַת פְּלֶ֤סֶר מֶֽלֶךְ־אַשּׁוּר֙ לֵ⁠אמֹ֔ר עַבְדְּ⁠ךָ֥ וּ⁠בִנְ⁠ךָ֖ אָ֑נִי עֲלֵ֨ה וְ⁠הוֹשִׁעֵ֜⁠נִי מִ⁠כַּ֣ף מֶֽלֶךְ־אֲרָ֗ם וּ⁠מִ⁠כַּף֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל הַ⁠קּוֹמִ֖ים עָלָֽ⁠י׃","wa⁠yi̇şĕ̌la֨ẖ ʼáẖá֜z malĕʼáki֗ym ʼel-ţi̇֠gĕlaţ pĕ̇le֤ser meֽlekĕ-ʼaş̇̌ẇr֙ lé⁠ʼmò֔r ʻabĕdĕ̇⁠ká֥ ẇ⁠binĕ⁠ká֖ ʼá֑niy ʻàlé֨h wĕ⁠hwòşǐʻé֜⁠niy mi⁠kȧ֣p meֽlekĕ-ʼàrá֗m ẇ⁠mi⁠kȧp֙ me֣lekĕ yişĕ̂ráʼé֔l ha⁠q̇wòmi֖ym ʻáláֽ⁠y׃"],[16,8,"וַ⁠יִּקַּ֨ח אָחָ֜ז אֶת־הַ⁠כֶּ֣סֶף וְ⁠אֶת־הַ⁠זָּהָ֗ב הַ⁠נִּמְצָא֙ בֵּ֣ית יְהוָ֔ה וּ⁠בְ⁠אֹֽצְר֖וֹת בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׁלַ֥ח לְ⁠מֶֽלֶךְ־אַשּׁ֖וּר שֹֽׁחַד׃","wa⁠yi̇qȧ֨ẖ ʼáẖá֜z ʼeţ-ha⁠kė֣sep wĕ⁠ʼeţ-ha⁠zá̇há֗b ha⁠ni̇mĕẕáʼ֙ bé֣̇yţ yĕhwá֔h ẇ⁠bĕ⁠ʼòֽẕĕr֖wòţ bé֣̇yţ ha⁠mė֑lekĕ wa⁠yi̇şĕ̌la֥ẖ lĕ⁠meֽlekĕ-ʼaş֖̇̌ẇr şòֽ̌ẖad׃"],[16,9,"וַ⁠יִּשְׁמַ֤ע אֵלָי⁠ו֙ מֶ֣לֶךְ אַשּׁ֔וּר וַ⁠יַּעַל֩ מֶ֨לֶךְ אַשּׁ֤וּר אֶל־דַּמֶּ֨שֶׂק֙ וַֽ⁠יִּתְפְּשֶׂ֔⁠הָ וַ⁠יַּגְלֶ֖⁠הָ קִ֑ירָ⁠ה וְ⁠אֶת־רְצִ֖ין הֵמִֽית׃","wa⁠yi̇şĕ̌ma֤ʻ ʼéláy⁠w֙ me֣lekĕ ʼaş̇̌֔ẇr wa⁠yȧʻal֩ me֨lekĕ ʼaş֤̇̌ẇr ʼel-dȧmė֨şêq֙ waֽ⁠yi̇ţĕpĕ̇şê֔⁠há wa⁠yȧgĕle֖⁠há qi֑yrá⁠h wĕ⁠ʼeţ-rĕẕi֖yn hémiֽyţ׃"],[16,10,"וַ⁠יֵּ֣לֶךְ הַ⁠מֶּ֣לֶךְ אָחָ֡ז לִ֠⁠קְרַאת תִּגְלַ֨ת פִּלְאֶ֤סֶר מֶֽלֶךְ־אַשּׁוּר֙ דּוּמֶּ֔שֶׂק וַ⁠יַּ֥רְא אֶת־הַ⁠מִּזְבֵּ֖חַ אֲשֶׁ֣ר בְּ⁠דַמָּ֑שֶׂק וַ⁠יִּשְׁלַח֩ הַ⁠מֶּ֨לֶךְ אָחָ֜ז אֶל־אוּרִיָּ֣ה הַ⁠כֹּהֵ֗ן אֶת־דְּמ֧וּת הַ⁠מִּזְבֵּ֛חַ וְ⁠אֶת־תַּבְנִית֖⁠וֹ לְ⁠כָֽל־מַעֲשֵֽׂ⁠הוּ׃","wa⁠yé֣̇lekĕ ha⁠mė֣lekĕ ʼáẖá֡z li֠⁠qĕraʼţ ţi̇gĕla֨ţ pi̇lĕʼe֤ser meֽlekĕ-ʼaş̇̌ẇr֙ ḋẇmė֔şêq wa⁠yȧ֥rĕʼ ʼeţ-ha⁠mi̇zĕbé֖̇ẖa ʼàşě֣r bĕ̇⁠damá֑̇şêq wa⁠yi̇şĕ̌laẖ֩ ha⁠mė֨lekĕ ʼáẖá֜z ʼel-ʼẇriyá֣̇h ha⁠kò̇hé֗n ʼeţ-dĕ̇m֧ẇţ ha⁠mi̇zĕbé֛̇ẖa wĕ⁠ʼeţ-ţȧbĕniyţ֖⁠wò lĕ⁠káֽl-maʻàşéֽ̂⁠hẇ׃"],[16,11,"וַ⁠יִּ֛בֶן אוּרִיָּ֥ה הַ⁠כֹּהֵ֖ן אֶת־הַ⁠מִּזְבֵּ֑חַ כְּ⁠כֹ֣ל אֲשֶׁר־שָׁלַח֩ הַ⁠מֶּ֨לֶךְ אָחָ֜ז מִ⁠דַּמֶּ֗שֶׂק כֵּ֤ן עָשָׂה֙ אוּרִיָּ֣ה הַ⁠כֹּהֵ֔ן עַד־בּ֥וֹא הַ⁠מֶּֽלֶךְ־אָחָ֖ז מִ⁠דַּמָּֽשֶׂק׃","wa⁠yi֛̇ben ʼẇriyá֥̇h ha⁠kò̇hé֖n ʼeţ-ha⁠mi̇zĕbé֑̇ẖa kĕ̇⁠kò֣l ʼàşěr-şá̌laẖ֩ ha⁠mė֨lekĕ ʼáẖá֜z mi⁠dȧmė֗şêq ké֤̇n ʻáşá̂h֙ ʼẇriyá֣̇h ha⁠kò̇hé֔n ʻad-ḃ֥wòʼ ha⁠mėֽlekĕ-ʼáẖá֖z mi⁠dȧmáֽ̇şêq׃"],[16,12,"וַ⁠יָּבֹ֤א הַ⁠מֶּ֨לֶךְ֙ מִ⁠דַּמֶּ֔שֶׂק וַ⁠יַּ֥רְא הַ⁠מֶּ֖לֶךְ אֶת־הַ⁠מִּזְבֵּ֑חַ וַ⁠יִּקְרַ֥ב הַ⁠מֶּ֛לֶךְ עַל־הַ⁠מִּזְבֵּ֖חַ וַ⁠יַּ֥עַל עָלָֽי⁠ו׃","wa⁠yá̇bò֤ʼ ha⁠mė֨lekĕ֙ mi⁠dȧmė֔şêq wa⁠yȧ֥rĕʼ ha⁠mė֖lekĕ ʼeţ-ha⁠mi̇zĕbé֑̇ẖa wa⁠yi̇qĕra֥b ha⁠mė֛lekĕ ʻal-ha⁠mi̇zĕbé֖̇ẖa wa⁠yȧ֥ʻal ʻáláֽy⁠w׃"],[16,13,"וַ⁠יַּקְטֵ֤ר אֶת־עֹֽלָת⁠וֹ֙ וְ⁠אֶת־מִנְחָת֔⁠וֹ וַ⁠יַּסֵּ֖ךְ אֶת־נִסְכּ֑⁠וֹ וַ⁠יִּזְרֹ֛ק אֶת־דַּֽם־הַ⁠שְּׁלָמִ֥ים אֲשֶׁר־ל֖⁠וֹ עַל־הַ⁠מִּזְבֵּֽחַ׃","wa⁠yȧqĕté֤r ʼeţ-ʻòֽláţ⁠wò֙ wĕ⁠ʼeţ-minĕẖáţ֔⁠wò wa⁠yȧsé֖̇kĕ ʼeţ-nisĕk֑̇⁠wò wa⁠yi̇zĕrò֛q ʼeţ-dȧֽm-ha⁠şĕ̇̌lámi֥ym ʼàşěr-l֖⁠wò ʻal-ha⁠mi̇zĕbéֽ̇ẖa׃"],[16,14,"וְ⁠אֵ֨ת הַ⁠מִּזְבַּ֣ח הַ⁠נְּחֹשֶׁת֮ אֲשֶׁ֣ר לִ⁠פְנֵ֣י יְהוָה֒ וַ⁠יַּקְרֵ֗ב מֵ⁠אֵת֙ פְּנֵ֣י הַ⁠בַּ֔יִת מִ⁠בֵּין֙ הַ⁠מִּזְבֵּ֔חַ וּ⁠מִ⁠בֵּ֖ין בֵּ֣ית יְהוָ֑ה וַ⁠יִּתֵּ֥ן אֹת֛⁠וֹ עַל־יֶ֥רֶךְ הַ⁠מִּזְבֵּ֖חַ צָפֽוֹנָ⁠ה׃","wĕ⁠ʼé֨ţ ha⁠mi̇zĕbȧ֣ẖ ha⁠nĕ̇ẖòşěţ֮ ʼàşě֣r li⁠pĕné֣y yĕhwáh֒ wa⁠yȧqĕré֗b mé⁠ʼéţ֙ pĕ̇né֣y ha⁠bȧ֔yiţ mi⁠bé̇yn֙ ha⁠mi̇zĕbé̇֔ẖa ẇ⁠mi⁠bé֖̇yn bé֣̇yţ yĕhwá֑h wa⁠yi̇ţé֥̇n ʼòţ֛⁠wò ʻal-ye֥rekĕ ha⁠mi̇zĕbé֖̇ẖa ẕápֽwòná⁠h׃"],[16,15,"ו⁠יצו⁠הו הַ⁠מֶּֽלֶךְ־אָ֠חָז אֶת־אוּרִיָּ֨ה הַ⁠כֹּהֵ֜ן לֵ⁠אמֹ֗ר עַ֣ל הַ⁠מִּזְבֵּ֣חַ הַ⁠גָּד֡וֹל הַקְטֵ֣ר אֶת־עֹֽלַת־הַ⁠בֹּקֶר֩ וְ⁠אֶת־מִנְחַ֨ת הָ⁠עֶ֜רֶב וְֽ⁠אֶת־עֹלַ֧ת הַ⁠מֶּ֣לֶךְ וְ⁠אֶת־מִנְחָת֗⁠וֹ וְ֠⁠אֵת עֹלַ֞ת כָּל־עַ֤ם הָ⁠אָ֨רֶץ֙ וּ⁠מִנְחָתָ֣⁠ם וְ⁠נִסְכֵּי⁠הֶ֔ם וְ⁠כָל־דַּ֥ם עֹלָ֛ה וְ⁠כָל־דַּם־זֶ֖בַח עָלָ֣י⁠ו תִּזְרֹ֑ק וּ⁠מִזְבַּ֧ח הַ⁠נְּחֹ֛שֶׁת יִֽהְיֶה־לִּ֖⁠י לְ⁠בַקֵּֽר׃","w⁠yẕw⁠hw ha⁠mėֽlekĕ-ʼá֠ẖáz ʼeţ-ʼẇriyá̇֨h ha⁠kò̇hé֜n lé⁠ʼmò֗r ʻa֣l ha⁠mi̇zĕbé֣̇ẖa ha⁠gá̇d֡wòl haqĕté֣r ʼeţ-ʻòֽlaţ-ha⁠bò̇qer֩ wĕ⁠ʼeţ-minĕẖa֨ţ há⁠ʻe֜reb wĕֽ⁠ʼeţ-ʻòla֧ţ ha⁠mė֣lekĕ wĕ⁠ʼeţ-minĕẖáţ֗⁠wò wĕ֠⁠ʼéţ ʻòla֞ţ ká̇l-ʻa֤m há⁠ʼá֨reẕ֙ ẇ⁠minĕẖáţá֣⁠m wĕ⁠nisĕké̇y⁠he֔m wĕ⁠kál-dȧ֥m ʻòlá֛h wĕ⁠kál-dȧm-ze֖baẖ ʻálá֣y⁠w ţi̇zĕrò֑q ẇ⁠mizĕbȧ֧ẖ ha⁠nĕ̇ẖò֛şěţ yiֽhĕyeh-li֖̇⁠y lĕ⁠baqéֽ̇r׃"],[16,16,"וַ⁠יַּ֖עַשׂ אוּרִיָּ֣ה הַ⁠כֹּהֵ֑ן כְּ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖ה הַ⁠מֶּ֥לֶךְ אָחָֽז׃","wa⁠yȧ֖ʻaş̂ ʼẇriyá֣̇h ha⁠kò̇hé֑n kĕ̇⁠kò֥l ʼàşěr-ẕiwá֖̇h ha⁠mė֥lekĕ ʼáẖáֽz׃"],[16,17,"וַ⁠יְקַצֵּץ֩ הַ⁠מֶּ֨לֶךְ אָחָ֜ז אֶת־הַ⁠מִּסְגְּר֣וֹת הַ⁠מְּכֹנ֗וֹת וַ⁠יָּ֤סַר מֵֽ⁠עֲלֵי⁠הֶם֙ ו⁠את־הַ⁠כִּיֹּ֔ר וְ⁠אֶת־הַ⁠יָּ֣ם הוֹרִ֔ד מֵ⁠עַ֛ל הַ⁠בָּקָ֥ר הַ⁠נְּחֹ֖שֶׁת אֲשֶׁ֣ר תַּחְתֶּ֑י⁠הָ וַ⁠יִּתֵּ֣ן אֹת֔⁠וֹ עַ֖ל מַרְצֶ֥פֶת אֲבָנִֽים׃","wa⁠yĕqaẕé̇ẕ֩ ha⁠mė֨lekĕ ʼáẖá֜z ʼeţ-ha⁠mi̇sĕgĕ̇r֣wòţ ha⁠mĕ̇kòn֗wòţ wa⁠yá֤̇sar méֽ⁠ʻàléy⁠hem֙ w⁠ʼţ-ha⁠ki̇yò̇֔r wĕ⁠ʼeţ-ha⁠yá֣̇m hwòri֔d mé⁠ʻa֛l ha⁠bá̇qá֥r ha⁠nĕ̇ẖò֖şěţ ʼàşě֣r ţȧẖĕţė֑y⁠há wa⁠yi̇ţé֣̇n ʼòţ֔⁠wò ʻa֖l marĕẕe֥peţ ʼàbániֽym׃"],[16,18,"וְ⁠אֶת־מיסך הַ⁠שַּׁבָּ֜ת אֲשֶׁר־בָּנ֣וּ בַ⁠בַּ֗יִת וְ⁠אֶת־מְב֤וֹא הַ⁠מֶּ֨לֶךְ֙ הַֽ⁠חִיצ֔וֹנָ⁠ה הֵסֵ֖ב בֵּ֣ית יְהוָ֑ה מִ⁠פְּנֵ֖י מֶ֥לֶךְ אַשּֽׁוּר׃","wĕ⁠ʼeţ-mysk ha⁠şȧ̌bá̇֜ţ ʼàşěr-bá̇n֣ẇ ba⁠bȧ֗yiţ wĕ⁠ʼeţ-mĕb֤wòʼ ha⁠mė֨lekĕ֙ hֽa⁠ẖiyẕ֔wòná⁠h hésé֖b bé֣̇yţ yĕhwá֑h mi⁠pĕ̇né֖y me֥lekĕ ʼaşֽ̇̌ẇr׃"],[16,19,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י אָחָ֖ז אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y ʼáẖá֖z ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[16,20,"וַ⁠יִּשְׁכַּ֤ב אָחָז֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֥ר עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֣יר דָּוִ֑ד וַ⁠יִּמְלֹ֛ךְ חִזְקִיָּ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ʼáẖáz֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֥r ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֣yr dá̇wi֑d wa⁠yi̇mĕlò֛kĕ ẖizĕqiyá֥̇hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[17,1,"בִּ⁠שְׁנַת֙ שְׁתֵּ֣ים עֶשְׂרֵ֔ה לְ⁠אָחָ֖ז מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ הוֹשֵׁ֨עַ בֶּן־אֵלָ֧ה בְ⁠שֹׁמְר֛וֹן עַל־יִשְׂרָאֵ֖ל תֵּ֥שַׁע שָׁנִֽים׃","bi̇⁠şĕ̌naţ֙ şĕ̌ţé֣̇ym ʻeşĕ̂ré֔h lĕ⁠ʼáẖá֖z me֣lekĕ yĕhẇdá֑h má֠lakĕ hwòşé̌֨ʻa bėn-ʼélá֧h bĕ⁠şò̌mĕr֛wòn ʻal-yişĕ̂ráʼé֖l ţé֥̇şǎʻ şá̌niֽym׃"],[17,2,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה רַ֗ק לֹ֚א כְּ⁠מַלְכֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֥ר הָי֖וּ לְ⁠פָנָֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h ra֗q lò֚ʼ kĕ̇⁠malĕké֣y yişĕ̂ráʼé֔l ʼàşě֥r háy֖ẇ lĕ⁠pánáֽy⁠w׃"],[17,3,"עָלָ֣י⁠ו עָלָ֔ה שַׁלְמַנְאֶ֖סֶר מֶ֣לֶךְ אַשּׁ֑וּר וַֽ⁠יְהִי־ל֤⁠וֹ הוֹשֵׁ֨עַ֙ עֶ֔בֶד וַ⁠יָּ֥שֶׁב ל֖⁠וֹ מִנְחָֽה׃","ʻálá֣y⁠w ʻálá֔h şǎlĕmanĕʼe֖ser me֣lekĕ ʼaş֑̇̌ẇr waֽ⁠yĕhiy-l֤⁠wò hwòşé̌֨ʻa֙ ʻe֔bed wa⁠yá֥̇şěb l֖⁠wò minĕẖáֽh׃"],[17,4,"וַ⁠יִּמְצָא֩ מֶֽלֶךְ־אַשּׁ֨וּר בְּ⁠הוֹשֵׁ֜עַ קֶ֗שֶׁר אֲשֶׁ֨ר שָׁלַ֤ח מַלְאָכִים֙ אֶל־ס֣וֹא מֶֽלֶךְ־מִצְרַ֔יִם וְ⁠לֹא־הֶעֱלָ֥ה מִנְחָ֛ה לְ⁠מֶ֥לֶךְ אַשּׁ֖וּר כְּ⁠שָׁנָ֣ה בְ⁠שָׁנָ֑ה וַֽ⁠יַּעַצְרֵ֨⁠הוּ֙ מֶ֣לֶךְ אַשּׁ֔וּר וַ⁠יַּאַסְרֵ֖⁠הוּ בֵּ֥ית כֶּֽלֶא׃","wa⁠yi̇mĕẕáʼ֩ meֽlekĕ-ʼaş̇̌֨ẇr bĕ̇⁠hwòşé̌֜ʻa qe֗şěr ʼàşě֨r şá̌la֤ẖ malĕʼákiym֙ ʼel-s֣wòʼ meֽlekĕ-miẕĕra֔yim wĕ⁠lòʼ-heʻèlá֥h minĕẖá֛h lĕ⁠me֥lekĕ ʼaş֖̇̌ẇr kĕ̇⁠şá̌ná֣h bĕ⁠şá̌ná֑h waֽ⁠yȧʻaẕĕré֨⁠hẇ֙ me֣lekĕ ʼaş̇̌֔ẇr wa⁠yȧʼasĕré֖⁠hẇ bé֥̇yţ kėֽleʼ׃"],[17,5,"וַ⁠יַּ֥עַל מֶֽלֶךְ־אַשּׁ֖וּר בְּ⁠כָל־הָ⁠אָ֑רֶץ וַ⁠יַּ֨עַל֙ שֹׁמְר֔וֹן וַ⁠יָּ֥צַר עָלֶ֖י⁠הָ שָׁלֹ֥שׁ שָׁנִֽים׃","wa⁠yȧ֥ʻal meֽlekĕ-ʼaş֖̇̌ẇr bĕ̇⁠kál-há⁠ʼá֑reẕ wa⁠yȧ֨ʻal֙ şò̌mĕr֔wòn wa⁠yá֥̇ẕar ʻále֖y⁠há şá̌lò֥ş̌ şá̌niֽym׃"],[17,6,"בִּ⁠שְׁנַ֨ת הַ⁠תְּשִׁיעִ֜ית לְ⁠הוֹשֵׁ֗עַ לָכַ֤ד מֶֽלֶךְ־אַשּׁוּר֙ אֶת־שֹׁ֣מְר֔וֹן וַ⁠יֶּ֥גֶל אֶת־יִשְׂרָאֵ֖ל אַשּׁ֑וּרָ⁠ה וַ⁠יֹּ֨שֶׁב אֹתָ֜⁠ם בַּ⁠חְלַ֧ח וּ⁠בְ⁠חָב֛וֹר נְהַ֥ר גּוֹזָ֖ן וְ⁠עָרֵ֥י מָדָֽי׃פ","bi̇⁠şĕ̌na֨ţ ha⁠ţĕ̇şǐyʻi֜yţ lĕ⁠hwòşé̌֗ʻa láka֤d meֽlekĕ-ʼaş̇̌ẇr֙ ʼeţ-şò֣̌mĕr֔wòn wa⁠yė֥gel ʼeţ-yişĕ̂ráʼé֖l ʼaş֑̇̌ẇrá⁠h wa⁠yò̇֨şěb ʼòţá֜⁠m bȧ⁠ẖĕla֧ẖ ẇ⁠bĕ⁠ẖáb֛wòr nĕha֥r ġwòzá֖n wĕ⁠ʻáré֥y mádáֽy׃p"],[17,7,"וַ⁠יְהִ֗י כִּֽי־חָטְא֤וּ בְנֵֽי־יִשְׂרָאֵל֙ לַ⁠יהוָ֣ה אֱלֹהֵי⁠הֶ֔ם הַ⁠מַּעֲלֶ֤ה אֹתָ⁠ם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם מִ⁠תַּ֕חַת יַ֖ד פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרָ֑יִם וַ⁠יִּֽירְא֖וּ אֱלֹהִ֥ים אֲחֵרִֽים׃","wa⁠yĕhi֗y kiֽ̇y-ẖátĕʼ֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ la⁠yhwá֣h ʼèlòhéy⁠he֔m ha⁠mȧʻàle֤h ʼòţá⁠m֙ mé⁠ʼe֣reẕ miẕĕra֔yim mi⁠ţȧ֕ẖaţ ya֖d pȧrĕʻò֣h meֽlekĕ-miẕĕrá֑yim wa⁠yiֽ̇yrĕʼ֖ẇ ʼèlòhi֥ym ʼàẖériֽym׃"],[17,8,"וַ⁠יֵּֽלְכוּ֙ בְּ⁠חֻקּ֣וֹת הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל וּ⁠מַלְכֵ֥י יִשְׂרָאֵ֖ל אֲשֶׁ֥ר עָשֽׂוּ׃","wa⁠yéֽ̇lĕkẇ֙ bĕ̇⁠ẖuq֣̇wòţ ha⁠ġwòyi֔m ʼàşěr֙ hwòri֣yş̌ yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֣y yişĕ̂ráʼé֑l ẇ⁠malĕké֥y yişĕ̂ráʼé֖l ʼàşě֥r ʻáşֽ̂ẇ׃"],[17,9,"וַ⁠יְחַפְּא֣וּ בְנֵֽי־יִשְׂרָאֵ֗ל דְּבָרִים֙ אֲשֶׁ֣ר לֹא־כֵ֔ן עַל־יְהוָ֖ה אֱלֹהֵי⁠הֶ֑ם וַ⁠יִּבְנ֨וּ לָ⁠הֶ֤ם בָּמוֹת֙ בְּ⁠כָל־עָ֣רֵי⁠הֶ֔ם מִ⁠מִּגְדַּ֥ל נוֹצְרִ֖ים עַד־עִ֥יר מִבְצָֽר׃","wa⁠yĕẖapĕ̇ʼ֣ẇ bĕnéֽy-yişĕ̂ráʼé֗l dĕ̇báriym֙ ʼàşě֣r lòʼ-ké֔n ʻal-yĕhwá֖h ʼèlòhéy⁠he֑m wa⁠yi̇bĕn֨ẇ lá⁠he֤m bá̇mwòţ֙ bĕ̇⁠kál-ʻá֣réy⁠he֔m mi⁠mi̇gĕdȧ֥l nwòẕĕri֖ym ʻad-ʻi֥yr mibĕẕáֽr׃"],[17,10,"וַ⁠יַּצִּ֧בוּ לָ⁠הֶ֛ם מַצֵּב֖וֹת וַ⁠אֲשֵׁרִ֑ים עַ֚ל כָּל־גִּבְעָ֣ה גְבֹהָ֔ה וְ⁠תַ֖חַת כָּל־עֵ֥ץ רַעֲנָֽן׃","wa⁠yȧẕi֧̇bẇ lá⁠he֛m maẕé̇b֖wòţ wa⁠ʼàşé̌ri֑ym ʻa֚l ká̇l-gi̇bĕʻá֣h gĕbòhá֔h wĕ⁠ţa֖ẖaţ ká̇l-ʻé֥ẕ raʻànáֽn׃"],[17,11,"וַ⁠יְקַטְּרוּ־שָׁם֙ בְּ⁠כָל־בָּמ֔וֹת כַּ⁠גּוֹיִ֕ם אֲשֶׁר־הֶגְלָ֥ה יְהוָ֖ה מִ⁠פְּנֵי⁠הֶ֑ם וַֽ⁠יַּעֲשׂוּ֙ דְּבָרִ֣ים רָעִ֔ים לְ⁠הַכְעִ֖יס אֶת־יְהוָֽה׃","wa⁠yĕqatĕ̇rẇ-şá̌m֙ bĕ̇⁠kál-bá̇m֔wòţ kȧ⁠ġwòyi֕m ʼàşěr-hegĕlá֥h yĕhwá֖h mi⁠pĕ̇néy⁠he֑m waֽ⁠yȧʻàş̂ẇ֙ dĕ̇bári֣ym ráʻi֔ym lĕ⁠hakĕʻi֖ys ʼeţ-yĕhwáֽh׃"],[17,12,"וַ⁠יַּֽעַבְד֖וּ הַ⁠גִּלֻּלִ֑ים אֲשֶׁ֨ר אָמַ֤ר יְהוָה֙ לָ⁠הֶ֔ם לֹ֥א תַעֲשׂ֖וּ אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yȧֽʻabĕd֖ẇ ha⁠gi̇lu̇li֑ym ʼàşě֨r ʼáma֤r yĕhwáh֙ lá⁠he֔m lò֥ʼ ţaʻàş֖̂ẇ ʼeţ-ha⁠dá̇bá֥r ha⁠zėֽh׃"],[17,13,"וַ⁠יָּ֣עַד יְהוָ֡ה בְּ⁠יִשְׂרָאֵ֣ל וּ⁠בִ⁠יהוּדָ֡ה בְּ⁠יַד֩ כָּל־נביא⁠ו כָל־חֹזֶ֜ה לֵ⁠אמֹ֗ר שֻׁ֝֠בוּ מִ⁠דַּרְכֵי⁠כֶ֤ם הָֽ⁠רָעִים֙ וְ⁠שִׁמְרוּ֙ מִצְוֺתַ֣⁠י חֻקּוֹתַ֔⁠י כְּ⁠כָ֨ל־הַ⁠תּוֹרָ֔ה אֲשֶׁ֥ר צִוִּ֖יתִי אֶת־אֲבֹֽתֵי⁠כֶ֑ם וַֽ⁠אֲשֶׁר֙ שָׁלַ֣חְתִּי אֲלֵי⁠כֶ֔ם בְּ⁠יַ֖ד עֲבָדַ֥⁠י הַ⁠נְּבִיאִֽים׃","wa⁠yá֣̇ʻad yĕhwá֡h bĕ̇⁠yişĕ̂ráʼé֣l ẇ⁠bi⁠yhẇdá֡h bĕ̇⁠yad֩ ká̇l-nbyʼ⁠w kál-ẖòze֜h lé⁠ʼmò֗r şǔ֝֠bẇ mi⁠dȧrĕkéy⁠ke֤m háֽ⁠ráʻiym֙ wĕ⁠şǐmĕrẇ֙ miẕĕwֺţa֣⁠y ẖuq̇wòţa֔⁠y kĕ̇⁠ká֨l-ha⁠ţ̇wòrá֔h ʼàşě֥r ẕiwi֖̇yţiy ʼeţ-ʼàbòֽţéy⁠ke֑m wֽa⁠ʼàşěr֙ şá̌la֣ẖĕţi̇y ʼàléy⁠ke֔m bĕ̇⁠ya֖d ʻàbáda֥⁠y ha⁠nĕ̇biyʼiֽym׃"],[17,14,"וְ⁠לֹ֖א שָׁמֵ֑עוּ וַ⁠יַּקְשׁ֤וּ אֶת־עָרְפָּ⁠ם֙ כְּ⁠עֹ֣רֶף אֲבוֹתָ֔⁠ם אֲשֶׁר֙ לֹ֣א הֶאֱמִ֔ינוּ בַּֽ⁠יהוָ֖ה אֱלֹהֵי⁠הֶֽם׃","wĕ⁠lò֖ʼ şá̌mé֑ʻẇ wa⁠yȧqĕş֤̌ẇ ʼeţ-ʻárĕpá̇⁠m֙ kĕ̇⁠ʻò֣rep ʼàbwòţá֔⁠m ʼàşěr֙ lò֣ʼ heʼèmi֔ynẇ bȧֽ⁠yhwá֖h ʼèlòhéy⁠heֽm׃"],[17,15,"וַ⁠יִּמְאֲס֣וּ אֶת־חֻקָּ֗י⁠ו וְ⁠אֶת־בְּרִית⁠וֹ֙ אֲשֶׁ֣ר כָּרַ֣ת אֶת־אֲבוֹתָ֔⁠ם וְ⁠אֵת֙ עֵֽדְוֺתָ֔י⁠ו אֲשֶׁ֥ר הֵעִ֖יד בָּ֑⁠ם וַ⁠יֵּ֨לְכ֜וּ אַחֲרֵ֤י הַ⁠הֶ֨בֶל֙ וַ⁠יֶּהְבָּ֔לוּ וְ⁠אַחֲרֵ֤י הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר סְבִֽיבֹתָ֔⁠ם אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ אֹתָ֔⁠ם לְ⁠בִלְתִּ֖י עֲשׂ֥וֹת כָּ⁠הֶֽם׃","wa⁠yi̇mĕʼàs֣ẇ ʼeţ-ẖuqá̇֗y⁠w wĕ⁠ʼeţ-bĕ̇riyţ⁠wò֙ ʼàşě֣r ká̇ra֣ţ ʼeţ-ʼàbwòţá֔⁠m wĕ⁠ʼéţ֙ ʻéֽdĕwֺţá֔y⁠w ʼàşě֥r héʻi֖yd bá֑̇⁠m wa⁠yé̇֨lĕk֜ẇ ʼaẖàré֤y ha⁠he֨bel֙ wa⁠yėhĕbá̇֔lẇ wĕ⁠ʼaẖàré֤y ha⁠ġwòyim֙ ʼàşě֣r sĕbiֽybòţá֔⁠m ʼàşě֨r ẕiwá֤̇h yĕhwáh֙ ʼòţá֔⁠m lĕ⁠bilĕţi֖̇y ʻàş֥̂wòţ ká̇⁠heֽm׃"],[17,16,"וַ⁠יַּעַזְב֗וּ אֶת־כָּל־מִצְוֺת֙ יְהוָ֣ה אֱלֹהֵי⁠הֶ֔ם וַ⁠יַּעֲשׂ֥וּ לָ⁠הֶ֛ם מַסֵּכָ֖ה שנים עֲגָלִ֑ים וַ⁠יַּעֲשׂ֣וּ אֲשֵׁירָ֗ה וַ⁠יִּֽשְׁתַּחֲווּ֙ לְ⁠כָל־צְבָ֣א הַ⁠שָּׁמַ֔יִם וַ⁠יַּעַבְד֖וּ אֶת־הַ⁠בָּֽעַל׃","wa⁠yȧʻazĕb֗ẇ ʼeţ-ká̇l-miẕĕwֺţ֙ yĕhwá֣h ʼèlòhéy⁠he֔m wa⁠yȧʻàş֥̂ẇ lá⁠he֛m masé̇ká֖h şnym ʻàgáli֑ym wa⁠yȧʻàş֣̂ẇ ʼàşé̌yrá֗h wa⁠yiֽ̇şĕ̌ţȧẖàwẇ֙ lĕ⁠kál-ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim wa⁠yȧʻabĕd֖ẇ ʼeţ-ha⁠báֽ̇ʻal׃"],[17,17,"וַֽ֠⁠יַּעֲבִירוּ אֶת־בְּנֵי⁠הֶ֤ם וְ⁠אֶת־בְּנֽוֹתֵי⁠הֶם֙ בָּ⁠אֵ֔שׁ וַ⁠יִּקְסְמ֥וּ קְסָמִ֖ים וַ⁠יְנַחֵ֑שׁוּ וַ⁠יִּֽתְמַכְּר֗וּ לַ⁠עֲשׂ֥וֹת הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה לְ⁠הַכְעִיסֽ⁠וֹ׃","waֽ֠⁠yȧʻàbiyrẇ ʼeţ-bĕ̇néy⁠he֤m wĕ⁠ʼeţ-bĕ̇nֽwòţéy⁠hem֙ bá̇⁠ʼé֔ş̌ wa⁠yi̇qĕsĕm֥ẇ qĕsámi֖ym wa⁠yĕnaẖé֑ş̌ẇ wa⁠yiֽ̇ţĕmakĕ̇r֗ẇ la⁠ʻàş֥̂wòţ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h lĕ⁠hakĕʻiysֽ⁠wò׃"],[17,18,"וַ⁠יִּתְאַנַּ֨ף יְהוָ֤ה מְאֹד֙ בְּ⁠יִשְׂרָאֵ֔ל וַ⁠יְסִרֵ֖⁠ם מֵ⁠עַ֣ל פָּנָ֑י⁠ו לֹ֣א נִשְׁאַ֔ר רַ֛ק שֵׁ֥בֶט יְהוּדָ֖ה לְ⁠בַדּֽ⁠וֹ׃","wa⁠yi̇ţĕʼanȧ֨p yĕhwá֤h mĕʼòd֙ bĕ̇⁠yişĕ̂ráʼé֔l wa⁠yĕsiré֖⁠m mé⁠ʻa֣l pá̇ná֑y⁠w lò֣ʼ nişĕ̌ʼa֔r ra֛q şé֥̌bet yĕhẇdá֖h lĕ⁠baḋֽ⁠wò׃"],[17,19,"גַּם־יְהוּדָ֕ה לֹ֣א שָׁמַ֔ר אֶת־מִצְוֺ֖ת יְהוָ֣ה אֱלֹהֵי⁠הֶ֑ם וַ⁠יֵּ֣לְכ֔וּ בְּ⁠חֻקּ֥וֹת יִשְׂרָאֵ֖ל אֲשֶׁ֥ר עָשֽׂוּ׃","gȧm-yĕhẇdá֕h lò֣ʼ şá̌ma֔r ʼeţ-miẕĕwֺ֖ţ yĕhwá֣h ʼèlòhéy⁠he֑m wa⁠yé֣̇lĕk֔ẇ bĕ̇⁠ẖuq֥̇wòţ yişĕ̂ráʼé֖l ʼàşě֥r ʻáşֽ̂ẇ׃"],[17,20,"וַ⁠יִּמְאַ֨ס יְהוָ֜ה בְּ⁠כָל־זֶ֤רַע יִשְׂרָאֵל֙ וַ⁠יְעַנֵּ֔⁠ם וַֽ⁠יִּתְּנֵ֖⁠ם בְּ⁠יַד־שֹׁסִ֑ים עַ֛ד אֲשֶׁ֥ר הִשְׁלִיכָ֖⁠ם מִ⁠פָּנָֽי⁠ו׃","wa⁠yi̇mĕʼa֨s yĕhwá֜h bĕ̇⁠kál-ze֤raʻ yişĕ̂ráʼél֙ wa⁠yĕʻané̇֔⁠m waֽ⁠yi̇ţĕ̇né֖⁠m bĕ̇⁠yad-şò̌si֑ym ʻa֛d ʼàşě֥r hişĕ̌liyká֖⁠m mi⁠pá̇náֽy⁠w׃"],[17,21,"כִּֽי־קָרַ֣ע יִשְׂרָאֵ֗ל מֵ⁠עַל֙ בֵּ֣ית דָּוִ֔ד וַ⁠יַּמְלִ֖יכוּ אֶת־יָרָבְעָ֣ם בֶּן־נְבָ֑ט ו⁠ידא יָרָבְעָ֤ם אֶת־יִשְׂרָאֵל֙ מֵ⁠אַחֲרֵ֣י יְהוָ֔ה וְ⁠הֶחֱטֵיאָ֖⁠ם חֲטָאָ֥ה גְדוֹלָֽה׃","kiֽ̇y-qára֣ʻ yişĕ̂ráʼé֗l mé⁠ʻal֙ bé֣̇yţ dá̇wi֔d wa⁠yȧmĕli֖ykẇ ʼeţ-yárábĕʻá֣m bėn-nĕbá֑t w⁠ydʼ yárábĕʻá֤m ʼeţ-yişĕ̂ráʼél֙ mé⁠ʼaẖàré֣y yĕhwá֔h wĕ⁠heẖètéyʼá֖⁠m ẖàtáʼá֥h gĕdwòláֽh׃"],[17,22,"וַ⁠יֵּֽלְכוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל בְּ⁠כָל־חַטֹּ֥אות יָרָבְעָ֖ם אֲשֶׁ֣ר עָשָׂ֑ה לֹא־סָ֖רוּ מִמֶּֽ⁠נָּה׃","wa⁠yéֽ̇lĕkẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l bĕ̇⁠kál-ẖatò֥̇ʼwţ yárábĕʻá֖m ʼàşě֣r ʻáşá֑̂h lòʼ-sá֖rẇ mimėֽ⁠ná̇h׃"],[17,23,"עַ֠ד אֲשֶׁר־הֵסִ֨יר יְהוָ֤ה אֶת־יִשְׂרָאֵל֙ מֵ⁠עַ֣ל פָּנָ֔י⁠ו כַּ⁠אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַ֖ד כָּל־עֲבָדָ֣י⁠ו הַ⁠נְּבִיאִ֑ים וַ⁠יִּ֨גֶל יִשְׂרָאֵ֜ל מֵ⁠עַ֤ל אַדְמָת⁠וֹ֙ אַשּׁ֔וּרָ⁠ה עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","ʻa֠d ʼàşěr-hési֨yr yĕhwá֤h ʼeţ-yişĕ̂ráʼél֙ mé⁠ʻa֣l pá̇ná֔y⁠w kȧ⁠ʼàşě֣r di̇bė֔r bĕ̇⁠ya֖d ká̇l-ʻàbádá֣y⁠w ha⁠nĕ̇biyʼi֑ym wa⁠yi̇֨gel yişĕ̂ráʼé֜l mé⁠ʻa֤l ʼadĕmáţ⁠wò֙ ʼaş̇̌֔ẇrá⁠h ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[17,24,"וַ⁠יָּבֵ֣א מֶֽלֶךְ־אַשּׁ֡וּר מִ⁠בָּבֶ֡ל וּ֠⁠מִ⁠כּוּ֠תָ⁠ה וּ⁠מֵ⁠עַוָּ֤א וּ⁠מֵֽ⁠חֲמָת֙ וּ⁠סְפַרְוַ֔יִם וַ⁠יֹּ֨שֶׁב֙ בְּ⁠עָרֵ֣י שֹֽׁמְר֔וֹן תַּ֖חַת בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּֽרְשׁוּ֙ אֶת־שֹׁ֣מְר֔וֹן וַ⁠יֵּֽשְׁב֖וּ בְּ⁠עָרֶֽי⁠הָ׃","wa⁠yá̇bé֣ʼ meֽlekĕ-ʼaş̇̌֡ẇr mi⁠bá̇be֡l ẇ֠⁠mi⁠k̇ẇ֠ţá⁠h ẇ⁠mé⁠ʻawá֤̇ʼ ẇ⁠méֽ⁠ẖàmáţ֙ ẇ⁠sĕparĕwa֔yim wa⁠yò̇֨şěb֙ bĕ̇⁠ʻáré֣y şòֽ̌mĕr֔wòn ţȧ֖ẖaţ bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yiֽ̇rĕş̌ẇ֙ ʼeţ-şò֣̌mĕr֔wòn wa⁠yéֽ̇şĕ̌b֖ẇ bĕ̇⁠ʻáreֽy⁠há׃"],[17,25,"וַ⁠יְהִ֗י בִּ⁠תְחִלַּת֙ שִׁבְתָּ֣⁠ם שָׁ֔ם לֹ֥א יָרְא֖וּ אֶת־יְהוָ֑ה וַ⁠יְשַׁלַּ֨ח יְהוָ֤ה בָּ⁠הֶם֙ אֶת־הָ֣⁠אֲרָי֔וֹת וַ⁠יִּֽהְי֥וּ הֹרְגִ֖ים בָּ⁠הֶֽם׃","wa⁠yĕhi֗y bi̇⁠ţĕẖilȧţ֙ şǐbĕţá֣̇⁠m şá̌֔m lò֥ʼ yárĕʼ֖ẇ ʼeţ-yĕhwá֑h wa⁠yĕşǎlȧ֨ẖ yĕhwá֤h bá̇⁠hem֙ ʼeţ-há֣⁠ʼàráy֔wòţ wa⁠yiֽ̇hĕy֥ẇ hòrĕgi֖ym bá̇⁠heֽm׃"],[17,26,"וַ⁠יֹּאמְר֗וּ לְ⁠מֶ֣לֶךְ אַשּׁוּר֮ לֵ⁠אמֹר֒ הַ⁠גּוֹיִ֗ם אֲשֶׁ֤ר הִגְלִ֨יתָ֙ וַ⁠תּ֨וֹשֶׁב֙ בְּ⁠עָרֵ֣י שֹׁמְר֔וֹן לֹ֣א יָֽדְע֔וּ אֶת־מִשְׁפַּ֖ט אֱלֹהֵ֣י הָ⁠אָ֑רֶץ וַ⁠יְשַׁלַּח־בָּ֣⁠ם אֶת־הָ⁠אֲרָי֗וֹת וְ⁠הִנָּ⁠ם֙ מְמִיתִ֣ים אוֹתָ֔⁠ם כַּ⁠אֲשֶׁר֙ אֵינָ֣⁠ם יֹדְעִ֔ים אֶת־מִשְׁפַּ֖ט אֱלֹהֵ֥י הָ⁠אָֽרֶץ׃","wa⁠yò̇ʼmĕr֗ẇ lĕ⁠me֣lekĕ ʼaş̇̌ẇr֮ lé⁠ʼmòr֒ ha⁠ġwòyi֗m ʼàşě֤r higĕli֨yţá֙ wa⁠ţ̇֨wòşěb֙ bĕ̇⁠ʻáré֣y şò̌mĕr֔wòn lò֣ʼ yáֽdĕʻ֔ẇ ʼeţ-mişĕ̌pȧ֖t ʼèlòhé֣y há⁠ʼá֑reẕ wa⁠yĕşǎlȧẖ-bá֣̇⁠m ʼeţ-há⁠ʼàráy֗wòţ wĕ⁠hiná̇⁠m֙ mĕmiyţi֣ym ʼwòţá֔⁠m kȧ⁠ʼàşěr֙ ʼéyná֣⁠m yòdĕʻi֔ym ʼeţ-mişĕ̌pȧ֖t ʼèlòhé֥y há⁠ʼáֽreẕ׃"],[17,27,"וַ⁠יְצַ֨ו מֶֽלֶךְ־אַשּׁ֜וּר לֵ⁠אמֹ֗ר הֹלִ֤יכוּ שָׁ֨מָּ⁠ה֙ אֶחָ֤ד מֵ⁠הַ⁠כֹּֽהֲנִים֙ אֲשֶׁ֣ר הִגְלִיתֶ֣ם מִ⁠שָּׁ֔ם וְ⁠יֵלְכ֖וּ וְ⁠יֵ֣שְׁבוּ שָׁ֑ם וְ⁠יֹרֵ֕⁠ם אֶת־מִשְׁפַּ֖ט אֱלֹהֵ֥י הָ⁠אָֽרֶץ׃","wa⁠yĕẕa֨w meֽlekĕ-ʼaş̇̌֜ẇr lé⁠ʼmò֗r hòli֤ykẇ şá̌֨má̇⁠h֙ ʼeẖá֤d mé⁠ha⁠kòֽ̇hàniym֙ ʼàşě֣r higĕliyţe֣m mi⁠şá̇̌֔m wĕ⁠yélĕk֖ẇ wĕ⁠yé֣şĕ̌bẇ şá֑̌m wĕ⁠yòré֕⁠m ʼeţ-mişĕ̌pȧ֖t ʼèlòhé֥y há⁠ʼáֽreẕ׃"],[17,28,"וַ⁠יָּבֹ֞א אֶחָ֣ד מֵ⁠הַ⁠כֹּהֲנִ֗ים אֲשֶׁ֤ר הִגְלוּ֙ מִ⁠שֹּׁ֣מְר֔וֹן וַ⁠יֵּ֖שֶׁב בְּ⁠בֵֽית־אֵ֑ל וַֽ⁠יְהִי֙ מוֹרֶ֣ה אֹתָ֔⁠ם אֵ֖יךְ יִֽירְא֥וּ אֶת־יְהוָֽה׃","wa⁠yá̇bò֞ʼ ʼeẖá֣d mé⁠ha⁠kò̇hàni֗ym ʼàşě֤r higĕlẇ֙ mi⁠şò֣̇̌mĕr֔wòn wa⁠yé֖̇şěb bĕ̇⁠béֽyţ-ʼé֑l waֽ⁠yĕhiy֙ mwòre֣h ʼòţá֔⁠m ʼé֖ykĕ yiֽyrĕʼ֥ẇ ʼeţ-yĕhwáֽh׃"],[17,29,"וַ⁠יִּהְי֣וּ עֹשִׂ֔ים גּ֥וֹי גּ֖וֹי אֱלֹהָ֑י⁠ו וַ⁠יַּנִּ֣יחוּ ׀ בְּ⁠בֵ֣ית הַ⁠בָּמ֗וֹת אֲשֶׁ֤ר עָשׂוּ֙ הַ⁠שֹּׁ֣מְרֹנִ֔ים גּ֥וֹי גּוֹי֙ בְּ⁠עָ֣רֵי⁠הֶ֔ם אֲשֶׁ֛ר הֵ֥ם יֹשְׁבִ֖ים שָֽׁם׃","wa⁠yi̇hĕy֣ẇ ʻòşî֔ym ġ֥wòy ġ֖wòy ʼèlòhá֑y⁠w wa⁠yȧni֣̇yẖẇ ׀ bĕ̇⁠bé֣yţ ha⁠bá̇m֗wòţ ʼàşě֤r ʻáş̂ẇ֙ ha⁠şò֣̇̌mĕròni֔ym ġ֥wòy ġwòy֙ bĕ̇⁠ʻá֣réy⁠he֔m ʼàşě֛r hé֥m yòşĕ̌bi֖ym şáֽ̌m׃"],[17,30,"וְ⁠אַנְשֵׁ֣י בָבֶ֗ל עָשׂוּ֙ אֶת־סֻכּ֣וֹת בְּנ֔וֹת וְ⁠אַנְשֵׁי־כ֔וּת עָשׂ֖וּ אֶת־נֵֽרְגַ֑ל וְ⁠אַנְשֵׁ֥י חֲמָ֖ת עָשׂ֥וּ אֶת־אֲשִׁימָֽא׃","wĕ⁠ʼanĕşé֣̌y bábe֗l ʻáş̂ẇ֙ ʼeţ-suk֣̇wòţ bĕ̇n֔wòţ wĕ⁠ʼanĕşé̌y-k֔ẇţ ʻáş֖̂ẇ ʼeţ-néֽrĕga֑l wĕ⁠ʼanĕşé֥̌y ẖàmá֖ţ ʻáş֥̂ẇ ʼeţ-ʼàşǐymáֽʼ׃"],[17,31,"וְ⁠הָ⁠עַוִּ֛ים עָשׂ֥וּ נִבְחַ֖ז וְ⁠אֶת־תַּרְתָּ֑ק וְ⁠הַ⁠סְפַרְוִ֗ים שֹׂרְפִ֤ים אֶת־בְּנֵי⁠הֶם֙ בָּ⁠אֵ֔שׁ לְ⁠אַדְרַמֶּ֥לֶךְ וַֽ⁠עֲנַמֶּ֖לֶךְ אלה ספרים׃","wĕ⁠há⁠ʻawi֛̇ym ʻáş֥̂ẇ nibĕẖa֖z wĕ⁠ʼeţ-ţȧrĕţá֑̇q wĕ⁠ha⁠sĕparĕwi֗ym şò̂rĕpi֤ym ʼeţ-bĕ̇néy⁠hem֙ bá̇⁠ʼé֔ş̌ lĕ⁠ʼadĕramė֥lekĕ waֽ⁠ʻànamė֖lekĕ ʼlh sprym׃"],[17,32,"וַ⁠יִּהְי֥וּ יְרֵאִ֖ים אֶת־יְהוָ֑ה וַ⁠יַּעֲשׂ֨וּ לָ⁠הֶ֤ם מִ⁠קְצוֹתָ⁠ם֙ כֹּהֲנֵ֣י בָמ֔וֹת וַ⁠יִּהְי֛וּ עֹשִׂ֥ים לָ⁠הֶ֖ם בְּ⁠בֵ֥ית הַ⁠בָּמֽוֹת׃","wa⁠yi̇hĕy֥ẇ yĕréʼi֖ym ʼeţ-yĕhwá֑h wa⁠yȧʻàş̂֨ẇ lá⁠he֤m mi⁠qĕẕwòţá⁠m֙ kò̇hàné֣y bám֔wòţ wa⁠yi̇hĕy֛ẇ ʻòşî֥ym lá⁠he֖m bĕ̇⁠bé֥yţ ha⁠bá̇mֽwòţ׃"],[17,33,"אֶת־יְהוָ֖ה הָי֣וּ יְרֵאִ֑ים וְ⁠אֶת־אֱלֹֽהֵי⁠הֶם֙ הָי֣וּ עֹֽבְדִ֔ים כְּ⁠מִשְׁפַּט֙ הַ⁠גּוֹיִ֔ם אֲשֶׁר־הִגְל֥וּ אֹתָ֖⁠ם מִ⁠שָּֽׁם׃","ʼeţ-yĕhwá֖h háy֣ẇ yĕréʼi֑ym wĕ⁠ʼeţ-ʼèlòֽhéy⁠hem֙ háy֣ẇ ʻòֽbĕdi֔ym kĕ̇⁠mişĕ̌pȧt֙ ha⁠ġwòyi֔m ʼàşěr-higĕl֥ẇ ʼòţá֖⁠m mi⁠şáֽ̇̌m׃"],[17,34,"עַ֣ד הַ⁠יּ֤וֹם הַ⁠זֶּה֙ הֵ֣ם עֹשִׂ֔ים כַּ⁠מִּשְׁפָּטִ֖ים הָ⁠רִֽאשֹׁנִ֑ים אֵינָ֤⁠ם יְרֵאִים֙ אֶת־יְהוָ֔ה וְ⁠אֵינָ֣⁠ם עֹשִׂ֗ים כְּ⁠חֻקֹּתָ⁠ם֙ וּ⁠כְ⁠מִשְׁפָּטָ֔⁠ם וְ⁠כַ⁠תּוֹרָ֣ה וְ⁠כַ⁠מִּצְוָ֗ה אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ אֶת־בְּנֵ֣י יַעֲקֹ֔ב אֲשֶׁר־שָׂ֥ם שְׁמ֖⁠וֹ יִשְׂרָאֵֽל׃","ʻa֣d ha⁠ẏ֤wòm ha⁠zėh֙ hé֣m ʻòşî֔ym kȧ⁠mi̇şĕ̌pá̇ti֖ym há⁠riֽʼşò̌ni֑ym ʼéyná֤⁠m yĕréʼiym֙ ʼeţ-yĕhwá֔h wĕ⁠ʼéyná֣⁠m ʻòşî֗ym kĕ̇⁠ẖuqò̇ţá⁠m֙ ẇ⁠kĕ⁠mişĕ̌pá̇tá֔⁠m wĕ⁠ka⁠ţ̇wòrá֣h wĕ⁠ka⁠mi̇ẕĕwá֗h ʼàşě֨r ẕiwá֤̇h yĕhwáh֙ ʼeţ-bĕ̇né֣y yaʻàqò֔b ʼàşěr-şá֥̂m şĕ̌m֖⁠wò yişĕ̂ráʼéֽl׃"],[17,35,"וַ⁠יִּכְרֹ֨ת יְהוָ֤ה אִתָּ⁠ם֙ בְּרִ֔ית וַ⁠יְצַוֵּ֣⁠ם לֵ⁠אמֹ֔ר לֹ֥א תִֽירְא֖וּ אֱלֹהִ֣ים אֲחֵרִ֑ים וְ⁠לֹא־תִשְׁתַּחֲו֣וּ לָ⁠הֶ֔ם וְ⁠לֹ֣א תַעַבְד֔וּ⁠ם וְ⁠לֹ֥א תִזְבְּח֖וּ לָ⁠הֶֽם׃","wa⁠yi̇kĕrò֨ţ yĕhwá֤h ʼiţá̇⁠m֙ bĕ̇ri֔yţ wa⁠yĕẕawé֣̇⁠m lé⁠ʼmò֔r lò֥ʼ ţiֽyrĕʼ֖ẇ ʼèlòhi֣ym ʼàẖéri֑ym wĕ⁠lòʼ-ţişĕ̌ţȧẖàw֣ẇ lá⁠he֔m wĕ⁠lò֣ʼ ţaʻabĕd֔ẇ⁠m wĕ⁠lò֥ʼ ţizĕbĕ̇ẖ֖ẇ lá⁠heֽm׃"],[17,36,"כִּ֣י אִֽם־אֶת־יְהוָ֗ה אֲשֶׁר֩ הֶעֱלָ֨ה אֶתְ⁠כֶ֜ם מֵ⁠אֶ֧רֶץ מִצְרַ֛יִם בְּ⁠כֹ֧חַ גָּד֛וֹל וּ⁠בִ⁠זְר֥וֹעַ נְטוּיָ֖ה אֹת֣⁠וֹ תִירָ֑אוּ וְ⁠ל֥⁠וֹ תִֽשְׁתַּחֲו֖וּ וְ⁠ל֥⁠וֹ תִזְבָּֽחוּ׃","ki֣̇y ʼiֽm-ʼeţ-yĕhwá֗h ʼàşěr֩ heʻèlá֨h ʼeţĕ⁠ke֜m mé⁠ʼe֧reẕ miẕĕra֛yim bĕ̇⁠kò֧ẖa gá̇d֛wòl ẇ⁠bi⁠zĕr֥wòʻa nĕtẇyá֖h ʼòţ֣⁠wò ţiyrá֑ʼẇ wĕ⁠l֥⁠wò ţiֽşĕ̌ţȧẖàw֖ẇ wĕ⁠l֥⁠wò ţizĕbáֽ̇ẖẇ׃"],[17,37,"וְ⁠אֶת־הַ⁠חֻקִּ֨ים וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֜ים וְ⁠הַ⁠תּוֹרָ֤ה וְ⁠הַ⁠מִּצְוָה֙ אֲשֶׁ֣ר כָּתַ֣ב לָ⁠כֶ֔ם תִּשְׁמְר֥וּ⁠ן לַ⁠עֲשׂ֖וֹת כָּל־הַ⁠יָּמִ֑ים וְ⁠לֹ֥א תִֽירְא֖וּ אֱלֹהִ֥ים אֲחֵרִֽים׃","wĕ⁠ʼeţ-ha⁠ẖuqi̇֨ym wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֜ym wĕ⁠ha⁠ţ̇wòrá֤h wĕ⁠ha⁠mi̇ẕĕwáh֙ ʼàşě֣r ká̇ţa֣b lá⁠ke֔m ţi̇şĕ̌mĕr֥ẇ⁠n la⁠ʻàş֖̂wòţ ká̇l-ha⁠yá̇mi֑ym wĕ⁠lò֥ʼ ţiֽyrĕʼ֖ẇ ʼèlòhi֥ym ʼàẖériֽym׃"],[17,38,"וְ⁠הַ⁠בְּרִ֛ית אֲשֶׁר־כָּרַ֥תִּי אִתְּ⁠כֶ֖ם לֹ֣א תִשְׁכָּ֑חוּ וְ⁠לֹ֥א תִֽירְא֖וּ אֱלֹהִ֥ים אֲחֵרִֽים׃","wĕ⁠ha⁠bĕ̇ri֛yţ ʼàşěr-ká̇ra֥ţi̇y ʼiţĕ̇⁠ke֖m lò֣ʼ ţişĕ̌ká֑̇ẖẇ wĕ⁠lò֥ʼ ţiֽyrĕʼ֖ẇ ʼèlòhi֥ym ʼàẖériֽym׃"],[17,39,"כִּ֛י אִֽם־אֶת־יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם תִּירָ֑אוּ וְ⁠הוּא֙ יַצִּ֣יל אֶתְ⁠כֶ֔ם מִ⁠יַּ֖ד כָּל־אֹיְבֵי⁠כֶֽם׃","ki֛̇y ʼiֽm-ʼeţ-yĕhwá֥h ʼèlòhéy⁠ke֖m ţi̇yrá֑ʼẇ wĕ⁠hẇʼ֙ yaẕi֣̇yl ʼeţĕ⁠ke֔m mi⁠yȧ֖d ká̇l-ʼòyĕbéy⁠keֽm׃"],[17,40,"וְ⁠לֹ֖א שָׁמֵ֑עוּ כִּ֛י אִֽם־כְּ⁠מִשְׁפָּטָ֥⁠ם הָֽ⁠רִאשׁ֖וֹן הֵ֥ם עֹשִֽׂים׃","wĕ⁠lò֖ʼ şá̌mé֑ʻẇ ki֛̇y ʼiֽm-kĕ̇⁠mişĕ̌pá̇tá֥⁠m háֽ⁠riʼş֖̌wòn hé֥m ʻòşîֽym׃"],[17,41,"וַ⁠יִּהְי֣וּ ׀ הַ⁠גּוֹיִ֣ם הָ⁠אֵ֗לֶּה יְרֵאִים֙ אֶת־יְהוָ֔ה וְ⁠אֶת־פְּסִֽילֵי⁠הֶ֖ם הָי֣וּ עֹֽבְדִ֑ים גַּם־בְּנֵי⁠הֶ֣ם ׀ וּ⁠בְנֵ֣י בְנֵי⁠הֶ֗ם כַּ⁠אֲשֶׁ֨ר עָשׂ֤וּ אֲבֹתָ⁠ם֙ הֵ֣ם עֹשִׂ֔ים עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yi̇hĕy֣ẇ ׀ ha⁠ġwòyi֣m há⁠ʼé֗lėh yĕréʼiym֙ ʼeţ-yĕhwá֔h wĕ⁠ʼeţ-pĕ̇siֽyléy⁠he֖m háy֣ẇ ʻòֽbĕdi֑ym gȧm-bĕ̇néy⁠he֣m ׀ ẇ⁠bĕné֣y bĕnéy⁠he֗m kȧ⁠ʼàşě֨r ʻáş֤̂ẇ ʼàbòţá⁠m֙ hé֣m ʻòşî֔ym ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[18,1,"וַֽ⁠יְהִי֙ בִּ⁠שְׁנַ֣ת שָׁלֹ֔שׁ לְ⁠הוֹשֵׁ֥עַ בֶּן־אֵלָ֖ה מֶ֣לֶךְ יִשְׂרָאֵ֑ל מָלַ֛ךְ חִזְקִיָּ֥ה בֶן־אָחָ֖ז מֶ֥לֶךְ יְהוּדָֽה׃","waֽ⁠yĕhiy֙ bi̇⁠şĕ̌na֣ţ şá̌lò֔ş̌ lĕ⁠hwòşé֥̌ʻa bėn-ʼélá֖h me֣lekĕ yişĕ̂ráʼé֑l mála֛kĕ ẖizĕqiyá֥̇h ben-ʼáẖá֖z me֥lekĕ yĕhẇdáֽh׃"],[18,2,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ הָיָ֣ה בְ⁠מָלְכ֔⁠וֹ וְ⁠עֶשְׂרִ֤ים וָ⁠תֵ֨שַׁע֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ אֲבִ֖י בַּת־זְכַרְיָֽה׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ háyá֣h bĕ⁠málĕk֔⁠wò wĕ⁠ʻeşĕ̂ri֤ym wá⁠ţé֨şǎʻ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ʼàbi֖y bȧţ-zĕkarĕyáֽh׃"],[18,3,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה דָּוִ֥ד אָבִֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h dá̇wi֥d ʼábiֽy⁠w׃"],[18,4,"ה֣וּא ׀ הֵסִ֣יר אֶת־הַ⁠בָּמ֗וֹת וְ⁠שִׁבַּר֙ אֶת־הַ⁠מַּצֵּבֹ֔ת וְ⁠כָרַ֖ת אֶת־הָֽ⁠אֲשֵׁרָ֑ה וְ⁠כִתַּת֩ נְחַ֨שׁ הַ⁠נְּחֹ֜שֶׁת אֲשֶׁר־עָשָׂ֣ה מֹשֶׁ֗ה כִּ֣י עַד־הַ⁠יָּמִ֤ים הָ⁠הֵ֨מָּה֙ הָי֤וּ בְנֵֽי־יִשְׂרָאֵל֙ מְקַטְּרִ֣ים ל֔⁠וֹ וַ⁠יִּקְרָא־ל֖⁠וֹ נְחֻשְׁתָּֽן׃","h֣ẇʼ ׀ hési֣yr ʼeţ-ha⁠bá̇m֗wòţ wĕ⁠şǐbȧr֙ ʼeţ-ha⁠mȧẕé̇bò֔ţ wĕ⁠kára֖ţ ʼeţ-háֽ⁠ʼàşé̌rá֑h wĕ⁠kiţȧţ֩ nĕẖa֨ş̌ ha⁠nĕ̇ẖò֜şěţ ʼàşěr-ʻáşá֣̂h mòşě֗h ki֣̇y ʻad-ha⁠yá̇mi֤ym há⁠hé֨má̇h֙ háy֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ mĕqatĕ̇ri֣ym l֔⁠wò wa⁠yi̇qĕráʼ-l֖⁠wò nĕẖuşĕ̌ţáֽ̇n׃"],[18,5,"בַּ⁠יהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל בָּטָ֑ח וְ⁠אַחֲרָ֞י⁠ו לֹא־הָיָ֣ה כָמֹ֗⁠הוּ בְּ⁠כֹל֙ מַלְכֵ֣י יְהוּדָ֔ה וַ⁠אֲשֶׁ֥ר הָי֖וּ לְ⁠פָנָֽי⁠ו׃","bȧ⁠yhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l bá̇tá֑ẖ wĕ⁠ʼaẖàrá֞y⁠w lòʼ-háyá֣h kámò֗⁠hẇ bĕ̇⁠kòl֙ malĕké֣y yĕhẇdá֔h wa⁠ʼàşě֥r háy֖ẇ lĕ⁠pánáֽy⁠w׃"],[18,6,"וַ⁠יִּדְבַּק֙ בַּֽ⁠יהוָ֔ה לֹא־סָ֖ר מֵ⁠אַֽחֲרָ֑י⁠ו וַ⁠יִּשְׁמֹר֙ מִצְוֺתָ֔י⁠ו אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wa⁠yi̇dĕbȧq֙ bȧֽ⁠yhwá֔h lòʼ-sá֖r mé⁠ʼaֽẖàrá֑y⁠w wa⁠yi̇şĕ̌mòr֙ miẕĕwֺţá֔y⁠w ʼàşěr-ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[18,7,"וְ⁠הָיָ֤ה יְהוָה֙ עִמּ֔⁠וֹ בְּ⁠כֹ֥ל אֲשֶׁר־יֵצֵ֖א יַשְׂכִּ֑יל וַ⁠יִּמְרֹ֥ד בְּ⁠מֶֽלֶךְ־אַשּׁ֖וּר וְ⁠לֹ֥א עֲבָדֽ⁠וֹ׃","wĕ⁠háyá֤h yĕhwáh֙ ʻiṁ֔⁠wò bĕ̇⁠kò֥l ʼàşěr-yéẕé֖ʼ yaşĕ̂ki֑̇yl wa⁠yi̇mĕrò֥d bĕ̇⁠meֽlekĕ-ʼaş֖̇̌ẇr wĕ⁠lò֥ʼ ʻàbádֽ⁠wò׃"],[18,8,"הֽוּא־הִכָּ֧ה אֶת־פְּלִשְׁתִּ֛ים עַד־עַזָּ֖ה וְ⁠אֶת־גְּבוּלֶ֑י⁠הָ מִ⁠מִּגְדַּ֥ל נוֹצְרִ֖ים עַד־עִ֥יר מִבְצָֽר׃פ","hֽẇʼ-hiká֧̇h ʼeţ-pĕ̇lişĕ̌ţi֛̇ym ʻad-ʻazá֖̇h wĕ⁠ʼeţ-gĕ̇bẇle֑y⁠há mi⁠mi̇gĕdȧ֥l nwòẕĕri֖ym ʻad-ʻi֥yr mibĕẕáֽr׃p"],[18,9,"וַֽ⁠יְהִ֞י בַּ⁠שָּׁנָ֤ה הָֽ⁠רְבִיעִית֙ לַ⁠מֶּ֣לֶךְ חִזְקִיָּ֔הוּ הִ֚יא הַ⁠שָּׁנָ֣ה הַ⁠שְּׁבִיעִ֔ית לְ⁠הוֹשֵׁ֥עַ בֶּן־אֵלָ֖ה מֶ֣לֶךְ יִשְׂרָאֵ֑ל עָלָ֞ה שַׁלְמַנְאֶ֧סֶר מֶֽלֶךְ־אַשּׁ֛וּר עַל־שֹׁמְר֖וֹן וַ⁠יָּ֥צַר עָלֶֽי⁠הָ׃","waֽ⁠yĕhi֞y bȧ⁠şá̇̌ná֤h háֽ⁠rĕbiyʻiyţ֙ la⁠mė֣lekĕ ẖizĕqiyá̇֔hẇ hi֚yʼ ha⁠şá̇̌ná֣h ha⁠şĕ̇̌biyʻi֔yţ lĕ⁠hwòşé֥̌ʻa bėn-ʼélá֖h me֣lekĕ yişĕ̂ráʼé֑l ʻálá֞h şǎlĕmanĕʼe֧ser meֽlekĕ-ʼaş֛̇̌ẇr ʻal-şò̌mĕr֖wòn wa⁠yá֥̇ẕar ʻáleֽy⁠há׃"],[18,10,"וַֽ⁠יִּלְכְּדֻ֗⁠הָ מִ⁠קְצֵה֙ שָׁלֹ֣שׁ שָׁנִ֔ים בִּ⁠שְׁנַת־שֵׁ֖שׁ לְ⁠חִזְקִיָּ֑ה הִ֣יא שְׁנַת־תֵּ֗שַׁע לְ⁠הוֹשֵׁ֨עַ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל נִלְכְּדָ֖ה שֹׁמְרֽוֹן׃","waֽ⁠yi̇lĕkĕ̇du֗⁠há mi⁠qĕẕéh֙ şá̌lò֣ş̌ şá̌ni֔ym bi̇⁠şĕ̌naţ-şé֖̌ş̌ lĕ⁠ẖizĕqiyá֑̇h hi֣yʼ şĕ̌naţ-ţé̇֗şǎʻ lĕ⁠hwòşé̌֨ʻa֙ me֣lekĕ yişĕ̂ráʼé֔l nilĕkĕ̇dá֖h şò̌mĕrֽwòn׃"],[18,11,"וַ⁠יֶּ֧גֶל מֶֽלֶךְ־אַשּׁ֛וּר אֶת־יִשְׂרָאֵ֖ל אַשּׁ֑וּרָ⁠ה וַ⁠יַּנְחֵ֞⁠ם בַּ⁠חְלַ֧ח וּ⁠בְ⁠חָב֛וֹר נְהַ֥ר גּוֹזָ֖ן וְ⁠עָרֵ֥י מָדָֽי׃","wa⁠yė֧gel meֽlekĕ-ʼaş֛̇̌ẇr ʼeţ-yişĕ̂ráʼé֖l ʼaş֑̇̌ẇrá⁠h wa⁠yȧnĕẖé֞⁠m bȧ⁠ẖĕla֧ẖ ẇ⁠bĕ⁠ẖáb֛wòr nĕha֥r ġwòzá֖n wĕ⁠ʻáré֥y mádáֽy׃"],[18,12,"עַ֣ל ׀ אֲשֶׁ֣ר לֹֽא־שָׁמְע֗וּ בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהֵי⁠הֶ֔ם וַ⁠יַּעַבְרוּ֙ אֶת־בְּרִית֔⁠וֹ אֵ֚ת כָּל־אֲשֶׁ֣ר צִוָּ֔ה מֹשֶׁ֖ה עֶ֣בֶד יְהוָ֑ה וְ⁠לֹ֥א שָׁמְע֖וּ וְ⁠לֹ֥א עָשֽׂוּ׃פ","ʻa֣l ׀ ʼàşě֣r lòֽʼ-şá̌mĕʻ֗ẇ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhéy⁠he֔m wa⁠yȧʻabĕrẇ֙ ʼeţ-bĕ̇riyţ֔⁠wò ʼé֚ţ ká̇l-ʼàşě֣r ẕiwá̇֔h mòşě֖h ʻe֣bed yĕhwá֑h wĕ⁠lò֥ʼ şá̌mĕʻ֖ẇ wĕ⁠lò֥ʼ ʻáşֽ̂ẇ׃p"],[18,13,"וּ⁠בְ⁠אַרְבַּע֩ עֶשְׂרֵ֨ה שָׁנָ֜ה לַ⁠מֶּ֣לֶךְ חִזְקִיָּ֗ה עָלָ֞ה סַנְחֵרִ֤יב מֶֽלֶךְ־אַשּׁוּר֙ עַ֣ל כָּל־עָרֵ֧י יְהוּדָ֛ה הַ⁠בְּצֻר֖וֹת וַֽ⁠יִּתְפְּשֵֽׂ⁠ם׃","ẇ⁠bĕ⁠ʼarĕbȧʻ֩ ʻeşĕ̂ré֨h şá̌ná֜h la⁠mė֣lekĕ ẖizĕqiyá̇֗h ʻálá֞h sanĕẖéri֤yb meֽlekĕ-ʼaş̇̌ẇr֙ ʻa֣l ká̇l-ʻáré֧y yĕhẇdá֛h ha⁠bĕ̇ẕur֖wòţ waֽ⁠yi̇ţĕpĕ̇şéֽ̂⁠m׃"],[18,14,"וַ⁠יִּשְׁלַ֣ח חִזְקִיָּ֣ה מֶֽלֶךְ־יְהוּדָ֣ה אֶל־מֶֽלֶךְ־אַשּׁוּר֩ ׀ לָכִ֨ישָׁ⁠ה ׀ לֵ⁠אמֹ֤ר ׀ חָטָ֨אתִי֙ שׁ֣וּב מֵֽ⁠עָלַ֔⁠י אֵ֛ת אֲשֶׁר־תִּתֵּ֥ן עָלַ֖⁠י אֶשָּׂ֑א וַ⁠יָּ֨שֶׂם מֶֽלֶךְ־אַשּׁ֜וּר עַל־חִזְקִיָּ֣ה מֶֽלֶךְ־יְהוּדָ֗ה שְׁלֹ֤שׁ מֵאוֹת֙ כִּכַּר־כֶּ֔סֶף וּ⁠שְׁלֹשִׁ֖ים כִּכַּ֥ר זָהָֽב׃","wa⁠yi̇şĕ̌la֣ẖ ẖizĕqiyá֣̇h meֽlekĕ-yĕhẇdá֣h ʼel-meֽlekĕ-ʼaş̇̌ẇr֩ ׀ láki֨yşá̌⁠h ׀ lé⁠ʼmò֤r ׀ ẖátá֨ʼţiy֙ ş֣̌ẇb méֽ⁠ʻála֔⁠y ʼé֛ţ ʼàşěr-ţi̇ţé֥̇n ʻála֖⁠y ʼeşá֑̇̂ʼ wa⁠yá̇֨şêm meֽlekĕ-ʼaş̇̌֜ẇr ʻal-ẖizĕqiyá֣̇h meֽlekĕ-yĕhẇdá֗h şĕ̌lò֤ş̌ méʼwòţ֙ ki̇kȧr-kė֔sep ẇ⁠şĕ̌lòşǐ֖ym ki̇kȧ֥r záháֽb׃"],[18,15,"וַ⁠יִּתֵּן֙ חִזְקִיָּ֔ה אֶת־כָּל־הַ⁠כֶּ֖סֶף הַ⁠נִּמְצָ֣א בֵית־יְהוָ֑ה וּ⁠בְ⁠אֹצְר֖וֹת בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇ţé̇n֙ ẖizĕqiyá̇֔h ʼeţ-ká̇l-ha⁠kė֖sep ha⁠ni̇mĕẕá֣ʼ béyţ-yĕhwá֑h ẇ⁠bĕ⁠ʼòẕĕr֖wòţ bé֥̇yţ ha⁠mėֽlekĕ׃"],[18,16,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא קִצַּ֨ץ חִזְקִיָּ֜ה אֶת־דַּלְת֨וֹת הֵיכַ֤ל יְהוָה֙ וְ⁠אֶת־הָ⁠אֹ֣מְנ֔וֹת אֲשֶׁ֣ר צִפָּ֔ה חִזְקִיָּ֖ה מֶ֣לֶךְ יְהוּדָ֑ה וַֽ⁠יִּתְּנֵ֖⁠ם לְ⁠מֶ֥לֶךְ אַשּֽׁוּר׃פ","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ qiẕȧ֨ẕ ẖizĕqiyá̇֜h ʼeţ-dȧlĕţ֨wòţ héyka֤l yĕhwáh֙ wĕ⁠ʼeţ-há⁠ʼò֣mĕn֔wòţ ʼàşě֣r ẕipá̇֔h ẖizĕqiyá֖̇h me֣lekĕ yĕhẇdá֑h waֽ⁠yi̇ţĕ̇né֖⁠m lĕ⁠me֥lekĕ ʼaşֽ̇̌ẇr׃p"],[18,17,"וַ⁠יִּשְׁלַ֣ח מֶֽלֶךְ־אַשּׁ֡וּר אֶת־תַּרְתָּ֥ן וְ⁠אֶת־רַב־סָרִ֣יס ׀ וְ⁠אֶת־רַב־שָׁקֵ֨ה מִן־לָכִ֜ישׁ אֶל־הַ⁠מֶּ֧לֶךְ חִזְקִיָּ֛הוּ בְּ⁠חֵ֥יל כָּבֵ֖ד יְרוּשָׁלִָ֑ם וַֽ⁠יַּעֲלוּ֙ וַ⁠יָּבֹ֣אוּ יְרוּשָׁלִַ֔ם וַ⁠יַּעֲל֣וּ וַ⁠יָּבֹ֗אוּ וַ⁠יַּֽעַמְדוּ֙ בִּ⁠תְעָלַת֙ הַ⁠בְּרֵכָ֣ה הָֽ⁠עֶלְיוֹנָ֔ה אֲשֶׁ֕ר בִּ⁠מְסִלַּ֖ת שְׂדֵ֥ה כוֹבֵֽס׃","wa⁠yi̇şĕ̌la֣ẖ meֽlekĕ-ʼaş̇̌֡ẇr ʼeţ-ţȧrĕţá֥̇n wĕ⁠ʼeţ-rab-sári֣ys ׀ wĕ⁠ʼeţ-rab-şá̌qé֨h min-láki֜yş̌ ʼel-ha⁠mė֧lekĕ ẖizĕqiyá֛̇hẇ bĕ̇⁠ẖé֥yl ká̇bé֖d yĕrẇşá̌liá֑m waֽ⁠yȧʻàlẇ֙ wa⁠yá̇bò֣ʼẇ yĕrẇşá̌lia֔m wa⁠yȧʻàl֣ẇ wa⁠yá̇bò֗ʼẇ wa⁠yȧֽʻamĕdẇ֙ bi̇⁠ţĕʻálaţ֙ ha⁠bĕ̇réká֣h háֽ⁠ʻelĕywòná֔h ʼàşě֕r bi̇⁠mĕsilȧ֖ţ şĕ̂dé֥h kwòbéֽs׃"],[18,18,"וַֽ⁠יִּקְרְאוּ֙ אֶל־הַ⁠מֶּ֔לֶךְ וַ⁠יֵּצֵ֧א אֲלֵ⁠הֶ֛ם אֶלְיָקִ֥ים בֶּן־חִלְקִיָּ֖הוּ אֲשֶׁ֣ר עַל־הַ⁠בָּ֑יִת וְ⁠שֶׁבְנָה֙ הַ⁠סֹּפֵ֔ר וְ⁠יוֹאָ֥ח בֶּן־אָסָ֖ף הַ⁠מַּזְכִּֽיר׃","waֽ⁠yi̇qĕrĕʼẇ֙ ʼel-ha⁠mė֔lekĕ wa⁠yé̇ẕé֧ʼ ʼàlé⁠he֛m ʼelĕyáqi֥ym bėn-ẖilĕqiyá֖̇hẇ ʼàşě֣r ʻal-ha⁠bá֑̇yiţ wĕ⁠şěbĕnáh֙ ha⁠sò̇pé֔r wĕ⁠ywòʼá֥ẖ bėn-ʼásá֖p ha⁠mȧzĕkiֽ̇yr׃"],[18,19,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ רַב־שָׁקֵ֔ה אִמְרוּ־נָ֖א אֶל־חִזְקִיָּ֑הוּ כֹּֽה־אָמַ֞ר הַ⁠מֶּ֤לֶךְ הַ⁠גָּדוֹל֙ מֶ֣לֶךְ אַשּׁ֔וּר מָ֧ה הַ⁠בִּטָּח֛וֹן הַ⁠זֶּ֖ה אֲשֶׁ֥ר בָּטָֽחְתָּ׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ rab-şá̌qé֔h ʼimĕrẇ-ná֖ʼ ʼel-ẖizĕqiyá֑̇hẇ kòֽ̇h-ʼáma֞r ha⁠mė֤lekĕ ha⁠gá̇dwòl֙ me֣lekĕ ʼaş̇̌֔ẇr má֧h ha⁠bi̇tá̇ẖ֛wòn ha⁠zė֖h ʼàşě֥r bá̇táֽẖĕţá̇׃"],[18,20,"אָמַ֨רְתָּ֙ אַךְ־דְּבַר־שְׂפָתַ֔יִם עֵצָ֥ה וּ⁠גְבוּרָ֖ה לַ⁠מִּלְחָמָ֑ה עַתָּה֙ עַל־מִ֣י בָטַ֔חְתָּ כִּ֥י מָרַ֖דְתָּ בִּֽ⁠י׃","ʼáma֨rĕţá̇֙ ʼakĕ-dĕ̇bar-şĕ̂páţa֔yim ʻéẕá֥h ẇ⁠gĕbẇrá֖h la⁠mi̇lĕẖámá֑h ʻaţá̇h֙ ʻal-mi֣y báta֔ẖĕţá̇ ki֥̇y mára֖dĕţá̇ biֽ̇⁠y׃"],[18,21,"עַתָּ֡ה הִנֵּ֣ה בָטַ֣חְתָּ לְּ⁠ךָ֡ עַל־מִשְׁעֶנֶת֩ הַ⁠קָּנֶ֨ה הָ⁠רָצ֤וּץ הַ⁠זֶּה֙ עַל־מִצְרַ֔יִם אֲשֶׁ֨ר יִסָּמֵ֥ךְ אִישׁ֙ עָלָ֔י⁠ו וּ⁠בָ֥א בְ⁠כַפּ֖⁠וֹ וּ⁠נְקָבָ֑⁠הּ כֵּ֚ן פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם לְ⁠כָֽל־הַ⁠בֹּטְחִ֖ים עָלָֽי⁠ו׃","ʻaţá̇֡h hiné֣̇h báta֣ẖĕţá̇ lĕ̇⁠ká֡ ʻal-mişĕ̌ʻeneţ֩ ha⁠qá̇ne֨h há⁠ráẕ֤ẇẕ ha⁠zėh֙ ʻal-miẕĕra֔yim ʼàşě֨r yisá̇mé֥kĕ ʼiyş̌֙ ʻálá֔y⁠w ẇ⁠bá֥ʼ bĕ⁠kaṗ֖⁠wò ẇ⁠nĕqábá֑⁠ḣ ké֚̇n pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim lĕ⁠káֽl-ha⁠bò̇tĕẖi֖ym ʻáláֽy⁠w׃"],[18,22,"וְ⁠כִי־תֹאמְר֣וּ⁠ן אֵלַ֔⁠י אֶל־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ בָּטָ֑חְנוּ הֲ⁠לוֹא־ה֗וּא אֲשֶׁ֨ר הֵסִ֤יר חִזְקִיָּ֨הוּ֙ אֶת־בָּמֹתָ֣י⁠ו וְ⁠אֶת־מִזְבְּחֹתָ֔י⁠ו וַ⁠יֹּ֤אמֶר לִֽ⁠יהוּדָה֙ וְ⁠לִ⁠יר֣וּשָׁלִַ֔ם לִ⁠פְנֵי֙ הַ⁠מִּזְבֵּ֣חַ הַ⁠זֶּ֔ה תִּֽשְׁתַּחֲו֖וּ בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠kiy-ţòʼmĕr֣ẇ⁠n ʼéla֔⁠y ʼel-yĕhwá֥h ʼèlòhé֖y⁠nẇ bá̇tá֑ẖĕnẇ hà⁠lwòʼ-h֗ẇʼ ʼàşě֨r hési֤yr ẖizĕqiyá̇֨hẇ֙ ʼeţ-bá̇mòţá֣y⁠w wĕ⁠ʼeţ-mizĕbĕ̇ẖòţá֔y⁠w wa⁠yò֤̇ʼmer liֽ⁠yhẇdáh֙ wĕ⁠li⁠yr֣ẇşá̌lia֔m li⁠pĕnéy֙ ha⁠mi̇zĕbé֣̇ẖa ha⁠zė֔h ţiֽ̇şĕ̌ţȧẖàw֖ẇ bi̇⁠yrẇşá̌liáֽm׃"],[18,23,"וְ⁠עַתָּה֙ הִתְעָ֣רֶב נָ֔א אֶת־אֲדֹנִ֖⁠י אֶת־מֶ֣לֶךְ אַשּׁ֑וּר וְ⁠אֶתְּנָ֤ה לְ⁠ךָ֙ אַלְפַּ֣יִם סוּסִ֔ים אִם־תּוּכַ֕ל לָ֥⁠תֶת לְ⁠ךָ֖ רֹכְבִ֥ים עֲלֵי⁠הֶֽם׃","wĕ⁠ʻaţá̇h֙ hiţĕʻá֣reb ná֔ʼ ʼeţ-ʼàdòni֖⁠y ʼeţ-me֣lekĕ ʼaş֑̇̌ẇr wĕ⁠ʼeţĕ̇ná֤h lĕ⁠ká֙ ʼalĕpȧ֣yim sẇsi֔ym ʼim-ţ̇ẇka֕l lá֥⁠ţeţ lĕ⁠ká֖ ròkĕbi֥ym ʻàléy⁠heֽm׃"],[18,24,"וְ⁠אֵ֣יךְ תָּשִׁ֗יב אֵ֠ת פְּנֵ֨י פַחַ֥ת אַחַ֛ד עַבְדֵ֥י אֲדֹנִ֖⁠י הַ⁠קְּטַנִּ֑ים וַ⁠תִּבְטַ֤ח לְ⁠ךָ֙ עַל־מִצְרַ֔יִם לְ⁠רֶ֖כֶב וּ⁠לְ⁠פָרָשִֽׁים׃","wĕ⁠ʼé֣ykĕ ţá̇şǐ֗yb ʼé֠ţ pĕ̇né֨y paẖa֥ţ ʼaẖa֛d ʻabĕdé֥y ʼàdòni֖⁠y ha⁠qĕ̇tani֑̇ym wa⁠ţi̇bĕta֤ẖ lĕ⁠ká֙ ʻal-miẕĕra֔yim lĕ⁠re֖keb ẇ⁠lĕ⁠páráşǐֽym׃"],[18,25,"עַתָּה֙ הֲ⁠מִ⁠בַּלְעֲדֵ֣י יְהוָ֔ה עָלִ֛יתִי עַל־הַ⁠מָּק֥וֹם הַ⁠זֶּ֖ה לְ⁠הַשְׁחִת֑⁠וֹ יְהוָה֙ אָמַ֣ר אֵלַ֔⁠י עֲלֵ֛ה עַל־הָ⁠אָ֥רֶץ הַ⁠זֹּ֖את וְ⁠הַשְׁחִיתָֽ⁠הּ׃","ʻaţá̇h֙ hà⁠mi⁠bȧlĕʻàdé֣y yĕhwá֔h ʻáli֛yţiy ʻal-ha⁠má̇q֥wòm ha⁠zė֖h lĕ⁠haşĕ̌ẖiţ֑⁠wò yĕhwáh֙ ʼáma֣r ʼéla֔⁠y ʻàlé֛h ʻal-há⁠ʼá֥reẕ ha⁠zò֖̇ʼţ wĕ⁠haşĕ̌ẖiyţáֽ⁠ḣ׃"],[18,26,"וַ⁠יֹּ֣אמֶר אֶלְיָקִ֣ים בֶּן־חִ֠לְקִיָּהוּ וְ⁠שֶׁבְנָ֨ה וְ⁠יוֹאָ֜ח אֶל־רַב־שָׁקֵ֗ה דַּבֶּר־נָ֤א אֶל־עֲבָדֶ֨י⁠ךָ֙ אֲרָמִ֔ית כִּ֥י שֹׁמְעִ֖ים אֲנָ֑חְנוּ וְ⁠אַל־תְּדַבֵּ֤ר עִמָּ֨⁠נוּ֙ יְהוּדִ֔ית בְּ⁠אָזְנֵ֣י הָ⁠עָ֔ם אֲשֶׁ֖ר עַל־הַ⁠חֹמָֽה׃","wa⁠yò֣̇ʼmer ʼelĕyáqi֣ym bėn-ẖi֠lĕqiyá̇hẇ wĕ⁠şěbĕná֨h wĕ⁠ywòʼá֜ẖ ʼel-rab-şá̌qé֗h dȧbėr-ná֤ʼ ʼel-ʻàbáde֨y⁠ká֙ ʼàrámi֔yţ ki֥̇y şò̌mĕʻi֖ym ʼàná֑ẖĕnẇ wĕ⁠ʼal-ţĕ̇dabé֤̇r ʻimá̇֨⁠nẇ֙ yĕhẇdi֔yţ bĕ̇⁠ʼázĕné֣y há⁠ʻá֔m ʼàşě֖r ʻal-ha⁠ẖòmáֽh׃"],[18,27,"וַ⁠יֹּ֨אמֶר אֲלֵי⁠הֶ֜ם רַב־שָׁקֵ֗ה הַ⁠עַ֨ל אֲדֹנֶ֤י⁠ךָ וְ⁠אֵלֶ֨י⁠ךָ֙ שְׁלָחַ֣⁠נִי אֲדֹנִ֔⁠י לְ⁠דַבֵּ֖ר אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה הֲ⁠לֹ֣א עַל־הָ⁠אֲנָשִׁ֗ים הַ⁠יֹּֽשְׁבִים֙ עַל־הַ֣⁠חֹמָ֔ה לֶ⁠אֱכֹ֣ל אֶת חרי⁠הם וְ⁠לִ⁠שְׁתּ֛וֹת אֶת־שיני⁠הם עִמָּ⁠כֶֽם׃","wa⁠yò̇֨ʼmer ʼàléy⁠he֜m rab-şá̌qé֗h ha⁠ʻa֨l ʼàdòne֤y⁠ká wĕ⁠ʼéle֨y⁠ká֙ şĕ̌láẖa֣⁠niy ʼàdòni֔⁠y lĕ⁠dabé֖̇r ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh hà⁠lò֣ʼ ʻal-há⁠ʼànáşǐ֗ym ha⁠yòֽ̇şĕ̌biym֙ ʻal-ha֣⁠ẖòmá֔h le⁠ʼèkò֣l ʼeţ ẖry⁠hm wĕ⁠li⁠şĕ̌ţ֛̇wòţ ʼeţ-şyny⁠hm ʻimá̇⁠keֽm׃"],[18,28,"וַֽ⁠יַּעֲמֹד֙ רַב־שָׁקֵ֔ה וַ⁠יִּקְרָ֥א בְ⁠קוֹל־גָּד֖וֹל יְהוּדִ֑ית וַ⁠יְדַבֵּ֣ר וַ⁠יֹּ֔אמֶר שִׁמְע֛וּ דְּבַר־הַ⁠מֶּ֥לֶךְ הַ⁠גָּד֖וֹל מֶ֥לֶךְ אַשּֽׁוּר׃","waֽ⁠yȧʻàmòd֙ rab-şá̌qé֔h wa⁠yi̇qĕrá֥ʼ bĕ⁠qwòl-gá̇d֖wòl yĕhẇdi֑yţ wa⁠yĕdabé֣̇r wa⁠yò̇֔ʼmer şǐmĕʻ֛ẇ dĕ̇bar-ha⁠mė֥lekĕ ha⁠gá̇d֖wòl me֥lekĕ ʼaşֽ̇̌ẇr׃"],[18,29,"כֹּ֚ה אָמַ֣ר הַ⁠מֶּ֔לֶךְ אַל־יַשִּׁ֥יא לָ⁠כֶ֖ם חִזְקִיָּ֑הוּ כִּי־לֹ֣א יוּכַ֔ל לְ⁠הַצִּ֥יל אֶתְ⁠כֶ֖ם מִ⁠יָּדֽ⁠וֹ׃","kò֚̇h ʼáma֣r ha⁠mė֔lekĕ ʼal-yaşi֥̇̌yʼ lá⁠ke֖m ẖizĕqiyá֑̇hẇ ki̇y-lò֣ʼ yẇka֔l lĕ⁠haẕi֥̇yl ʼeţĕ⁠ke֖m mi⁠yá̇dֽ⁠wò׃"],[18,30,"וְ⁠אַל־יַבְטַ֨ח אֶתְ⁠כֶ֤ם חִזְקִיָּ֨הוּ֙ אֶל־יְהוָ֣ה לֵ⁠אמֹ֔ר הַצֵּ֥ל יַצִּילֵ֖⁠נוּ יְהוָ֑ה וְ⁠לֹ֤א תִנָּתֵן֙ אֶת־הָ⁠עִ֣יר הַ⁠זֹּ֔את בְּ⁠יַ֖ד מֶ֥לֶךְ אַשּֽׁוּר׃","wĕ⁠ʼal-yabĕta֨ẖ ʼeţĕ⁠ke֤m ẖizĕqiyá̇֨hẇ֙ ʼel-yĕhwá֣h lé⁠ʼmò֔r haẕé֥̇l yaẕi̇ylé֖⁠nẇ yĕhwá֑h wĕ⁠lò֤ʼ ţiná̇ţén֙ ʼeţ-há⁠ʻi֣yr ha⁠zò̇֔ʼţ bĕ̇⁠ya֖d me֥lekĕ ʼaşֽ̇̌ẇr׃"],[18,31,"אַֽל־תִּשְׁמְע֖וּ אֶל־חִזְקִיָּ֑הוּ כִּי֩ כֹ֨ה אָמַ֜ר מֶ֣לֶךְ אַשּׁ֗וּר עֲשֽׂוּ־אִתִּ֤⁠י בְרָכָה֙ וּ⁠צְא֣וּ אֵלַ֔⁠י וְ⁠אִכְל֤וּ אִישׁ־גַּפְנ⁠וֹ֙ וְ⁠אִ֣ישׁ תְּאֵֽנָת֔⁠וֹ וּ⁠שְׁת֖וּ אִ֥ישׁ מֵֽי־בוֹרֽ⁠וֹ׃","ʼaֽl-ţi̇şĕ̌mĕʻ֖ẇ ʼel-ẖizĕqiyá֑̇hẇ ki̇y֩ kò֨h ʼáma֜r me֣lekĕ ʼaş̇̌֗ẇr ʻàşֽ̂ẇ-ʼiţi֤̇⁠y bĕrákáh֙ ẇ⁠ẕĕʼ֣ẇ ʼéla֔⁠y wĕ⁠ʼikĕl֤ẇ ʼiyş̌-gȧpĕn⁠wò֙ wĕ⁠ʼi֣yş̌ ţĕ̇ʼéֽnáţ֔⁠wò ẇ⁠şĕ̌ţ֖ẇ ʼi֥yş̌ méֽy-bwòrֽ⁠wò׃"],[18,32,"עַד־בֹּאִ⁠י֩ וְ⁠לָקַחְתִּ֨י אֶתְ⁠כֶ֜ם אֶל־אֶ֣רֶץ כְּ⁠אַרְצְ⁠כֶ֗ם אֶרֶץ֩ דָּגָ֨ן וְ⁠תִיר֜וֹשׁ אֶ֧רֶץ לֶ֣חֶם וּ⁠כְרָמִ֗ים אֶ֣רֶץ זֵ֤ית יִצְהָר֙ וּ⁠דְבַ֔שׁ וִֽ⁠חְי֖וּ וְ⁠לֹ֣א תָמֻ֑תוּ וְ⁠אַֽל־תִּשְׁמְעוּ֙ אֶל־חִזְקִיָּ֔הוּ כִּֽי־יַסִּ֤ית אֶתְ⁠כֶם֙ לֵ⁠אמֹ֔ר יְהוָ֖ה יַצִּילֵֽ⁠נוּ׃","ʻad-bò̇ʼi⁠y֩ wĕ⁠láqaẖĕţi̇֨y ʼeţĕ⁠ke֜m ʼel-ʼe֣reẕ kĕ̇⁠ʼarĕẕĕ⁠ke֗m ʼereẕ֩ dá̇gá֨n wĕ⁠ţiyr֜wòş̌ ʼe֧reẕ le֣ẖem ẇ⁠kĕrámi֗ym ʼe֣reẕ zé֤yţ yiẕĕhár֙ ẇ⁠dĕba֔ş̌ wiֽ⁠ẖĕy֖ẇ wĕ⁠lò֣ʼ ţámu֑ţẇ wĕ⁠ʼaֽl-ţi̇şĕ̌mĕʻẇ֙ ʼel-ẖizĕqiyá̇֔hẇ kiֽ̇y-yasi֤̇yţ ʼeţĕ⁠kem֙ lé⁠ʼmò֔r yĕhwá֖h yaẕi̇yléֽ⁠nẇ׃"],[18,33,"הַ⁠הַצֵּ֥ל הִצִּ֛ילוּ אֱלֹהֵ֥י הַ⁠גּוֹיִ֖ם אִ֣ישׁ אֶת־אַרְצ֑⁠וֹ מִ⁠יַּ֖ד מֶ֥לֶךְ אַשּֽׁוּר׃","ha⁠haẕé֥̇l hiẕi֛̇ylẇ ʼèlòhé֥y ha⁠ġwòyi֖m ʼi֣yş̌ ʼeţ-ʼarĕẕ֑⁠wò mi⁠yȧ֖d me֥lekĕ ʼaşֽ̇̌ẇr׃"],[18,34,"אַיֵּה֩ אֱלֹהֵ֨י חֲמָ֜ת וְ⁠אַרְפָּ֗ד אַיֵּ֛ה אֱלֹהֵ֥י סְפַרְוַ֖יִם הֵנַ֣ע וְ⁠עִוָּ֑ה כִּֽי־הִצִּ֥ילוּ אֶת־שֹׁמְר֖וֹן מִ⁠יָּדִֽ⁠י׃","ʼayé̇h֩ ʼèlòhé֨y ẖàmá֜ţ wĕ⁠ʼarĕpá̇֗d ʼayé֛̇h ʼèlòhé֥y sĕparĕwa֖yim héna֣ʻ wĕ⁠ʻiwá֑̇h kiֽ̇y-hiẕi֥̇ylẇ ʼeţ-şò̌mĕr֖wòn mi⁠yá̇diֽ⁠y׃"],[18,35,"מִ֚י בְּ⁠כָל־אֱלֹהֵ֣י הָֽ⁠אֲרָצ֔וֹת אֲשֶׁר־הִצִּ֥ילוּ אֶת־אַרְצָ֖⁠ם מִ⁠יָּדִ֑⁠י כִּי־יַצִּ֧יל יְהוָ֛ה אֶת־יְרוּשָׁלִַ֖ם מִ⁠יָּדִֽ⁠י׃","mi֚y bĕ̇⁠kál-ʼèlòhé֣y háֽ⁠ʼàráẕ֔wòţ ʼàşěr-hiẕi֥̇ylẇ ʼeţ-ʼarĕẕá֖⁠m mi⁠yá̇di֑⁠y ki̇y-yaẕi֧̇yl yĕhwá֛h ʼeţ-yĕrẇşá̌lia֖m mi⁠yá̇diֽ⁠y׃"],[18,36,"וְ⁠הֶחֱרִ֣ישׁוּ הָ⁠עָ֔ם וְ⁠לֹֽא־עָנ֥וּ אֹת֖⁠וֹ דָּבָ֑ר כִּי־מִצְוַ֨ת הַ⁠מֶּ֥לֶךְ הִ֛יא לֵ⁠אמֹ֖ר לֹ֥א תַעֲנֻֽ⁠הוּ׃","wĕ⁠heẖèri֣yş̌ẇ há⁠ʻá֔m wĕ⁠lòֽʼ-ʻán֥ẇ ʼòţ֖⁠wò dá̇bá֑r ki̇y-miẕĕwa֨ţ ha⁠mė֥lekĕ hi֛yʼ lé⁠ʼmò֖r lò֥ʼ ţaʻànuֽ⁠hẇ׃"],[18,37,"וַ⁠יָּבֹ֣א אֶלְיָקִ֣ים בֶּן־חִלְקִיָּ֣ה אֲשֶׁר־עַל־הַ֠⁠בַּיִת וְ⁠שֶׁבְנָ֨א הַ⁠סֹּפֵ֜ר וְ⁠יוֹאָ֨ח בֶּן־אָסָ֧ף הַ⁠מַּזְכִּ֛יר אֶל־חִזְקִיָּ֖הוּ קְרוּעֵ֣י בְגָדִ֑ים וַ⁠יַּגִּ֣דוּ ל֔⁠וֹ דִּבְרֵ֖י רַב־שָׁקֵֽה׃","wa⁠yá̇bò֣ʼ ʼelĕyáqi֣ym bėn-ẖilĕqiyá֣̇h ʼàşěr-ʻal-ha֠⁠bȧyiţ wĕ⁠şěbĕná֨ʼ ha⁠sò̇pé֜r wĕ⁠ywòʼá֨ẖ bėn-ʼásá֧p ha⁠mȧzĕki֛̇yr ʼel-ẖizĕqiyá֖̇hẇ qĕrẇʻé֣y bĕgádi֑ym wa⁠yȧgi֣̇dẇ l֔⁠wò di̇bĕré֖y rab-şá̌qéֽh׃"],[19,1,"וַ⁠יְהִ֗י כִּ⁠שְׁמֹ֨עַ֙ הַ⁠מֶּ֣לֶךְ חִזְקִיָּ֔הוּ וַ⁠יִּקְרַ֖ע אֶת־בְּגָדָ֑י⁠ו וַ⁠יִּתְכַּ֣ס בַּ⁠שָּׂ֔ק וַ⁠יָּבֹ֖א בֵּ֥ית יְהוָֽה׃","wa⁠yĕhi֗y ki̇⁠şĕ̌mò֨ʻa֙ ha⁠mė֣lekĕ ẖizĕqiyá̇֔hẇ wa⁠yi̇qĕra֖ʻ ʼeţ-bĕ̇gádá֑y⁠w wa⁠yi̇ţĕkȧ֣s bȧ⁠şá̇̂֔q wa⁠yá̇bò֖ʼ bé֥̇yţ yĕhwáֽh׃"],[19,2,"וַ֠⁠יִּשְׁלַח אֶת־אֶלְיָקִ֨ים אֲשֶׁר־עַל־הַ⁠בַּ֜יִת וְ⁠שֶׁבְנָ֣א הַ⁠סֹּפֵ֗ר וְ⁠אֵת֙ זִקְנֵ֣י הַ⁠כֹּֽהֲנִ֔ים מִתְכַּסִּ֖ים בַּ⁠שַּׂקִּ֑ים אֶל־יְשַֽׁעְיָ֥הוּ הַ⁠נָּבִ֖יא בֶּן־אָמֽוֹץ׃","wa֠⁠yi̇şĕ̌laẖ ʼeţ-ʼelĕyáqi֨ym ʼàşěr-ʻal-ha⁠bȧ֜yiţ wĕ⁠şěbĕná֣ʼ ha⁠sò̇pé֗r wĕ⁠ʼéţ֙ ziqĕné֣y ha⁠kòֽ̇hàni֔ym miţĕkȧsi֖̇ym bȧ⁠şȧ̂qi֑̇ym ʼel-yĕşǎֽʻĕyá֥hẇ ha⁠ná̇bi֖yʼ bėn-ʼámֽwòẕ׃"],[19,3,"וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר חִזְקִיָּ֔הוּ יוֹם־צָרָ֧ה וְ⁠תוֹכֵחָ֛ה וּ⁠נְאָצָ֖ה הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֣י בָ֤אוּ בָנִים֙ עַד־מַשְׁבֵּ֔ר וְ⁠כֹ֥חַ אַ֖יִן לְ⁠לֵדָֽה׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w kò֚̇h ʼáma֣r ẖizĕqiyá̇֔hẇ ywòm-ẕárá֧h wĕ⁠ţwòkéẖá֛h ẇ⁠nĕʼáẕá֖h ha⁠ẏ֣wòm ha⁠zė֑h ki֣̇y bá֤ʼẇ bániym֙ ʻad-maşĕ̌bé̇֔r wĕ⁠kò֥ẖa ʼa֖yin lĕ⁠lédáֽh׃"],[19,4,"אוּלַ֡י יִשְׁמַע֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ אֵ֣ת ׀ כָּל־דִּבְרֵ֣י רַב־שָׁקֵ֗ה אֲשֶׁר֩ שְׁלָח֨⁠וֹ מֶֽלֶךְ־אַשּׁ֤וּר ׀ אֲדֹנָי⁠ו֙ לְ⁠חָרֵף֙ אֱלֹהִ֣ים חַ֔י וְ⁠הוֹכִ֨יחַ֙ בַּ⁠דְּבָרִ֔ים אֲשֶׁ֥ר שָׁמַ֖ע יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠נָשָׂ֣אתָ תְפִלָּ֔ה בְּעַ֥ד הַ⁠שְּׁאֵרִ֖ית הַ⁠נִּמְצָאָֽה׃","ʼẇla֡y yişĕ̌maʻ֩ yĕhwá֨h ʼèlòhe֜y⁠ká ʼé֣ţ ׀ ká̇l-di̇bĕré֣y rab-şá̌qé֗h ʼàşěr֩ şĕ̌láẖ֨⁠wò meֽlekĕ-ʼaş֤̇̌ẇr ׀ ʼàdònáy⁠w֙ lĕ⁠ẖárép֙ ʼèlòhi֣ym ẖa֔y wĕ⁠hwòki֨yẖa֙ bȧ⁠dĕ̇bári֔ym ʼàşě֥r şá̌ma֖ʻ yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠náşá֣̂ʼţá ţĕpilá̇֔h bĕ̇ʻa֥d ha⁠şĕ̇̌ʼéri֖yţ ha⁠ni̇mĕẕáʼáֽh׃"],[19,5,"וַ⁠יָּבֹ֗אוּ עַבְדֵ֛י הַ⁠מֶּ֥לֶךְ חִזְקִיָּ֖הוּ אֶל־יְשַֽׁעַיָֽהוּ׃","wa⁠yá̇bò֗ʼẇ ʻabĕdé֛y ha⁠mė֥lekĕ ẖizĕqiyá֖̇hẇ ʼel-yĕşǎֽʻayáֽhẇ׃"],[19,6,"וַ⁠יֹּ֤אמֶר לָ⁠הֶם֙ יְשַֽׁעְיָ֔הוּ כֹּ֥ה תֹאמְר֖וּ⁠ן אֶל־אֲדֹֽנֵי⁠כֶ֑ם כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אַל־תִּירָא֙ מִ⁠פְּנֵ֤י הַ⁠דְּבָרִים֙ אֲשֶׁ֣ר שָׁמַ֗עְתָּ אֲשֶׁ֧ר גִּדְּפ֛וּ נַעֲרֵ֥י מֶֽלֶךְ־אַשּׁ֖וּר אֹתִֽ⁠י׃","wa⁠yò֤̇ʼmer lá⁠hem֙ yĕşǎֽʻĕyá֔hẇ kò֥̇h ţòʼmĕr֖ẇ⁠n ʼel-ʼàdòֽnéy⁠ke֑m kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼal-ţi̇yráʼ֙ mi⁠pĕ̇né֤y ha⁠dĕ̇báriym֙ ʼàşě֣r şá̌ma֗ʻĕţá̇ ʼàşě֧r gi̇dĕ̇p֛ẇ naʻàré֥y meֽlekĕ-ʼaş֖̇̌ẇr ʼòţiֽ⁠y׃"],[19,7,"הִנְ⁠נִ֨י נֹתֵ֥ן בּ⁠וֹ֙ ר֔וּחַ וְ⁠שָׁמַ֥ע שְׁמוּעָ֖ה וְ⁠שָׁ֣ב לְ⁠אַרְצ֑⁠וֹ וְ⁠הִפַּלְתִּ֥י⁠ו בַּ⁠חֶ֖רֶב בְּ⁠אַרְצֽ⁠וֹ׃","hinĕ⁠ni֨y nòţé֥n ḃ⁠wò֙ r֔ẇẖa wĕ⁠şá̌ma֥ʻ şĕ̌mẇʻá֖h wĕ⁠şá֣̌b lĕ⁠ʼarĕẕ֑⁠wò wĕ⁠hipȧlĕţi֥̇y⁠w bȧ⁠ẖe֖reb bĕ̇⁠ʼarĕẕֽ⁠wò׃"],[19,8,"וַ⁠יָּ֨שָׁב֙ רַב־שָׁקֵ֔ה וַ⁠יִּמְצָא֙ אֶת־מֶ֣לֶךְ אַשּׁ֔וּר נִלְחָ֖ם עַל־לִבְנָ֑ה כִּ֣י שָׁמַ֔ע כִּ֥י נָסַ֖ע מִ⁠לָּכִֽישׁ׃","wa⁠yá̇֨şá̌b֙ rab-şá̌qé֔h wa⁠yi̇mĕẕáʼ֙ ʼeţ-me֣lekĕ ʼaş̇̌֔ẇr nilĕẖá֖m ʻal-libĕná֑h ki֣̇y şá̌ma֔ʻ ki֥̇y nása֖ʻ mi⁠lá̇kiֽyş̌׃"],[19,9,"וַ⁠יִּשְׁמַ֗ע אֶל־תִּרְהָ֤קָה מֶֽלֶך־כּוּשׁ֙ לֵ⁠אמֹ֔ר הִנֵּ֥ה יָצָ֖א לְ⁠הִלָּחֵ֣ם אִתָּ֑⁠ךְ וַ⁠יָּ֨שָׁב֙ וַ⁠יִּשְׁלַ֣ח מַלְאָכִ֔ים אֶל־חִזְקִיָּ֖הוּ לֵ⁠אמֹֽר׃","wa⁠yi̇şĕ̌ma֗ʻ ʼel-ţi̇rĕhá֤qáh meֽlek-k̇ẇş̌֙ lé⁠ʼmò֔r hiné֥̇h yáẕá֖ʼ lĕ⁠hilá̇ẖé֣m ʼiţá֑̇⁠kĕ wa⁠yá̇֨şá̌b֙ wa⁠yi̇şĕ̌la֣ẖ malĕʼáki֔ym ʼel-ẖizĕqiyá֖̇hẇ lé⁠ʼmòֽr׃"],[19,10,"כֹּ֣ה תֹאמְר֗וּ⁠ן אֶל־חִזְקִיָּ֤הוּ מֶֽלֶךְ־יְהוּדָה֙ לֵ⁠אמֹ֔ר אַל־יַשִּׁאֲ⁠ךָ֣ אֱלֹהֶ֔י⁠ךָ אֲשֶׁ֥ר אַתָּ֛ה בֹּטֵ֥חַ בּ֖⁠וֹ לֵ⁠אמֹ֑ר לֹ֤א תִנָּתֵן֙ יְר֣וּשָׁלִַ֔ם בְּ⁠יַ֖ד מֶ֥לֶךְ אַשּֽׁוּר׃","kò֣̇h ţòʼmĕr֗ẇ⁠n ʼel-ẖizĕqiyá֤̇hẇ meֽlekĕ-yĕhẇdáh֙ lé⁠ʼmò֔r ʼal-yaşi̇̌ʼà⁠ká֣ ʼèlòhe֔y⁠ká ʼàşě֥r ʼaţá֛̇h bò̇té֥ẖa ḃ֖⁠wò lé⁠ʼmò֑r lò֤ʼ ţiná̇ţén֙ yĕr֣ẇşá̌lia֔m bĕ̇⁠ya֖d me֥lekĕ ʼaşֽ̇̌ẇr׃"],[19,11,"הִנֵּ֣ה ׀ אַתָּ֣ה שָׁמַ֗עְתָּ אֵת֩ אֲשֶׁ֨ר עָשׂ֜וּ מַלְכֵ֥י אַשּׁ֛וּר לְ⁠כָל־הָ⁠אֲרָצ֖וֹת לְ⁠הַֽחֲרִימָ֑⁠ם וְ⁠אַתָּ֖ה תִּנָּצֵֽל׃","hiné֣̇h ׀ ʼaţá֣̇h şá̌ma֗ʻĕţá̇ ʼéţ֩ ʼàşě֨r ʻáş̂֜ẇ malĕké֥y ʼaş֛̇̌ẇr lĕ⁠kál-há⁠ʼàráẕ֖wòţ lĕ⁠haֽẖàriymá֑⁠m wĕ⁠ʼaţá֖̇h ţi̇ná̇ẕéֽl׃"],[19,12,"הַ⁠הִצִּ֨ילוּ אֹתָ֜⁠ם אֱלֹהֵ֤י הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר שִׁחֲת֣וּ אֲבוֹתַ֔⁠י אֶת־גּוֹזָ֖ן וְ⁠אֶת־חָרָ֑ן וְ⁠רֶ֥צֶף וּ⁠בְנֵי־עֶ֖דֶן אֲשֶׁ֥ר בִּ⁠תְלַאשָּֽׂר׃","ha⁠hiẕi̇֨ylẇ ʼòţá֜⁠m ʼèlòhé֤y ha⁠ġwòyim֙ ʼàşě֣r şǐẖàţ֣ẇ ʼàbwòţa֔⁠y ʼeţ-ġwòzá֖n wĕ⁠ʼeţ-ẖárá֑n wĕ⁠re֥ẕep ẇ⁠bĕnéy-ʻe֖den ʼàşě֥r bi̇⁠ţĕlaʼşáֽ̇̂r׃"],[19,13,"אַיּ֤⁠וֹ מֶֽלֶךְ־חֲמָת֙ וּ⁠מֶ֣לֶךְ אַרְפָּ֔ד וּ⁠מֶ֖לֶךְ לָעִ֣יר סְפַרְוָ֑יִם הֵנַ֖ע וְ⁠עִוָּֽה׃","ʼaẏ֤⁠wò meֽlekĕ-ẖàmáţ֙ ẇ⁠me֣lekĕ ʼarĕpá̇֔d ẇ⁠me֖lekĕ láʻi֣yr sĕparĕwá֑yim héna֖ʻ wĕ⁠ʻiwáֽ̇h׃"],[19,14,"וַ⁠יִּקַּ֨ח חִזְקִיָּ֧הוּ אֶת־הַ⁠סְּפָרִ֛ים מִ⁠יַּ֥ד הַ⁠מַּלְאָכִ֖ים וַ⁠יִּקְרָאֵ֑⁠ם וַ⁠יַּ֨עַל֙ בֵּ֣ית יְהוָ֔ה וַ⁠יִּפְרְשֵׂ֥⁠הוּ חִזְקִיָּ֖הוּ לִ⁠פְנֵ֥י יְהוָֽה׃פ","wa⁠yi̇qȧ֨ẖ ẖizĕqiyá֧̇hẇ ʼeţ-ha⁠sĕ̇pári֛ym mi⁠yȧ֥d ha⁠mȧlĕʼáki֖ym wa⁠yi̇qĕráʼé֑⁠m wa⁠yȧ֨ʻal֙ bé֣̇yţ yĕhwá֔h wa⁠yi̇pĕrĕşé֥̂⁠hẇ ẖizĕqiyá֖̇hẇ li⁠pĕné֥y yĕhwáֽh׃p"],[19,15,"וַ⁠יִּתְפַּלֵּ֨ל חִזְקִיָּ֜הוּ לִ⁠פְנֵ֣י יְהוָה֮ וַ⁠יֹּאמַר֒ יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ יֹשֵׁ֣ב הַ⁠כְּרֻבִ֔ים אַתָּה־ה֤וּא הָֽ⁠אֱלֹהִים֙ לְ⁠בַדְּ⁠ךָ֔ לְ⁠כֹ֖ל מַמְלְכ֣וֹת הָ⁠אָ֑רֶץ אַתָּ֣ה עָשִׂ֔יתָ אֶת־הַ⁠שָּׁמַ֖יִם וְ⁠אֶת־הָ⁠אָֽרֶץ׃","wa⁠yi̇ţĕpȧlé̇֨l ẖizĕqiyá̇֜hẇ li⁠pĕné֣y yĕhwáh֮ wa⁠yò̇ʼmar֒ yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ yòşé֣̌b ha⁠kĕ̇rubi֔ym ʼaţá̇h-h֤ẇʼ háֽ⁠ʼèlòhiym֙ lĕ⁠badĕ̇⁠ká֔ lĕ⁠kò֖l mamĕlĕk֣wòţ há⁠ʼá֑reẕ ʼaţá֣̇h ʻáşî֔yţá ʼeţ-ha⁠şá̇̌ma֖yim wĕ⁠ʼeţ-há⁠ʼáֽreẕ׃"],[19,16,"הַטֵּ֨ה יְהוָ֤ה ׀ אָזְנְ⁠ךָ֙ וּֽ⁠שֲׁמָ֔ע פְּקַ֧ח יְהוָ֛ה עֵינֶ֖י⁠ךָ וּ⁠רְאֵ֑ה וּ⁠שְׁמַ֗ע אֵ֚ת דִּבְרֵ֣י סַנְחֵרִ֔יב אֲשֶׁ֣ר שְׁלָח֔⁠וֹ לְ⁠חָרֵ֖ף אֱלֹהִ֥ים חָֽי׃","haté̇֨h yĕhwá֤h ׀ ʼázĕnĕ⁠ká֙ ẇֽ⁠şà̌má֔ʻ pĕ̇qa֧ẖ yĕhwá֛h ʻéyne֖y⁠ká ẇ⁠rĕʼé֑h ẇ⁠şĕ̌ma֗ʻ ʼé֚ţ di̇bĕré֣y sanĕẖéri֔yb ʼàşě֣r şĕ̌láẖ֔⁠wò lĕ⁠ẖáré֖p ʼèlòhi֥ym ẖáֽy׃"],[19,17,"אָמְנָ֖ם יְהוָ֑ה הֶחֱרִ֜יבוּ מַלְכֵ֥י אַשּׁ֛וּר אֶת־הַ⁠גּוֹיִ֖ם וְ⁠אֶת־אַרְצָֽ⁠ם׃","ʼámĕná֖m yĕhwá֑h heẖèri֜ybẇ malĕké֥y ʼaş֛̇̌ẇr ʼeţ-ha⁠ġwòyi֖m wĕ⁠ʼeţ-ʼarĕẕáֽ⁠m׃"],[19,18,"וְ⁠נָתְנ֥וּ אֶת־אֱלֹהֵי⁠הֶ֖ם בָּ⁠אֵ֑שׁ כִּי֩ לֹ֨א אֱלֹהִ֜ים הֵ֗מָּה כִּ֣י אִם־מַעֲשֵׂ֧ה יְדֵֽי־אָדָ֛ם עֵ֥ץ וָ⁠אֶ֖בֶן וַֽ⁠יְאַבְּדֽוּ⁠ם׃","wĕ⁠náţĕn֥ẇ ʼeţ-ʼèlòhéy⁠he֖m bá̇⁠ʼé֑ş̌ ki̇y֩ lò֨ʼ ʼèlòhi֜ym hé֗má̇h ki֣̇y ʼim-maʻàşé֧̂h yĕdéֽy-ʼádá֛m ʻé֥ẕ wá⁠ʼe֖ben waֽ⁠yĕʼabĕ̇dֽẇ⁠m׃"],[19,19,"וְ⁠עַתָּה֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ הוֹשִׁיעֵ֥⁠נוּ נָ֖א מִ⁠יָּד֑⁠וֹ וְ⁠יֵֽדְעוּ֙ כָּל־מַמְלְכ֣וֹת הָ⁠אָ֔רֶץ כִּ֥י אַתָּ֛ה יְהוָ֥ה אֱלֹהִ֖ים לְ⁠בַדֶּֽ⁠ךָ׃ס","wĕ⁠ʻaţá̇h֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ hwòşǐyʻé֥⁠nẇ ná֖ʼ mi⁠yá̇d֑⁠wò wĕ⁠yéֽdĕʻẇ֙ ká̇l-mamĕlĕk֣wòţ há⁠ʼá֔reẕ ki֥̇y ʼaţá֛̇h yĕhwá֥h ʼèlòhi֖ym lĕ⁠badėֽ⁠ká׃s"],[19,20,"וַ⁠יִּשְׁלַח֙ יְשַֽׁעְיָ֣הוּ בֶן־אָמ֔וֹץ אֶל־חִזְקִיָּ֖הוּ לֵ⁠אמֹ֑ר כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֨ר הִתְפַּלַּ֧לְתָּ אֵלַ֛⁠י אֶל־סַנְחֵרִ֥ב מֶֽלֶךְ־אַשּׁ֖וּר שָׁמָֽעְתִּי׃","wa⁠yi̇şĕ̌laẖ֙ yĕşǎֽʻĕyá֣hẇ ben-ʼám֔wòẕ ʼel-ẖizĕqiyá֖̇hẇ lé⁠ʼmò֑r kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşě֨r hiţĕpȧlȧ֧lĕţá̇ ʼéla֛⁠y ʼel-sanĕẖéri֥b meֽlekĕ-ʼaş֖̇̌ẇr şá̌máֽʻĕţi̇y׃"],[19,21,"זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה עָלָ֑י⁠ו בָּזָ֨ה לְ⁠ךָ֜ לָעֲגָ֣ה לְ⁠ךָ֗ בְּתוּלַת֙ בַּת־צִיּ֔וֹן אַחֲרֶ֨י⁠ךָ֙ רֹ֣אשׁ הֵנִ֔יעָה בַּ֖ת יְרוּשָׁלִָֽם׃","ze֣h ha⁠dá̇bá֔r ʼàşěr-di̇bė֥r yĕhwá֖h ʻálá֑y⁠w bá̇zá֨h lĕ⁠ká֜ láʻàgá֣h lĕ⁠ká֗ bĕ̇ţẇlaţ֙ bȧţ-ẕiẏ֔wòn ʼaẖàre֨y⁠ká֙ rò֣ʼş̌ héni֔yʻáh bȧ֖ţ yĕrẇşá̌liáֽm׃"],[19,22,"אֶת־מִ֤י חֵרַ֨פְתָּ֙ וְ⁠גִדַּ֔פְתָּ וְ⁠עַל־מִ֖י הֲרִימ֣וֹתָ קּ֑וֹל וַ⁠תִּשָּׂ֥א מָר֛וֹם עֵינֶ֖י⁠ךָ עַל־קְד֥וֹשׁ יִשְׂרָאֵֽל׃","ʼeţ-mi֤y ẖéra֨pĕţá̇֙ wĕ⁠gidȧ֔pĕţá̇ wĕ⁠ʻal-mi֖y hàriym֣wòţá q֑̇wòl wa⁠ţi̇şá֥̇̂ʼ már֛wòm ʻéyne֖y⁠ká ʻal-qĕd֥wòş̌ yişĕ̂ráʼéֽl׃"],[19,23,"בְּ⁠יַ֣ד מַלְאָכֶי⁠ךָ֮ חֵרַ֣פְתָּ ׀ אֲדֹנָ⁠י֒ וַ⁠תֹּ֗אמֶר ב⁠רכב רִכְבִּ֛⁠י אֲנִ֥י עָלִ֛יתִי מְר֥וֹם הָרִ֖ים יַרְכְּתֵ֣י לְבָנ֑וֹן וְ⁠אֶכְרֹ֞ת קוֹמַ֤ת אֲרָזָי⁠ו֙ מִבְח֣וֹר בְּרֹשָׁ֔י⁠ו וְ⁠אָב֨וֹאָה֙ מְל֣וֹן קִצֹּ֔⁠ה יַ֖עַר כַּרְמִלּֽ⁠וֹ׃","bĕ̇⁠ya֣d malĕʼákey⁠ká֮ ẖéra֣pĕţá̇ ׀ ʼàdòná⁠y֒ wa⁠ţò̇֗ʼmer b⁠rkb rikĕbi֛̇⁠y ʼàni֥y ʻáli֛yţiy mĕr֥wòm hári֖ym yarĕkĕ̇ţé֣y lĕbán֑wòn wĕ⁠ʼekĕrò֞ţ qwòma֤ţ ʼàrázáy⁠w֙ mibĕẖ֣wòr bĕ̇ròşá̌֔y⁠w wĕ⁠ʼáb֨wòʼáh֙ mĕl֣wòn qiẕò̇֔⁠h ya֖ʻar kȧrĕmilֽ̇⁠wò׃"],[19,24,"אֲנִ֣י קַ֔רְתִּי וְ⁠שָׁתִ֖יתִי מַ֣יִם זָרִ֑ים וְ⁠אַחְרִב֙ בְּ⁠כַף־פְּעָמַ֔⁠י כֹּ֖ל יְאֹרֵ֥י מָצֽוֹר׃","ʼàni֣y qa֔rĕţi̇y wĕ⁠şá̌ţi֖yţiy ma֣yim zári֑ym wĕ⁠ʼaẖĕrib֙ bĕ̇⁠kap-pĕ̇ʻáma֔⁠y kò֖̇l yĕʼòré֥y máẕֽwòr׃"],[19,25,"הֲ⁠לֹֽא־שָׁמַ֤עְתָּ לְ⁠מֵֽ⁠רָחוֹק֙ אֹתָ֣⁠הּ עָשִׂ֔יתִי לְ⁠מִ֥⁠ימֵי קֶ֖דֶם וִֽ⁠יצַרְתִּ֑י⁠הָ עַתָּ֣ה הֲבֵיאתִ֗י⁠הָ וּ⁠תְהִ֗י לַ⁠הְשׁ֛וֹת גַּלִּ֥ים נִצִּ֖ים עָרִ֥ים בְּצֻרֽוֹת׃","hà⁠lòֽʼ-şá̌ma֤ʻĕţá̇ lĕ⁠méֽ⁠ráẖwòq֙ ʼòţá֣⁠ḣ ʻáşî֔yţiy lĕ⁠mi֥⁠yméy qe֖dem wiֽ⁠yẕarĕţi֑̇y⁠há ʻaţá֣̇h hàbéyʼţi֗y⁠há ẇ⁠ţĕhi֗y la⁠hĕş֛̌wòţ gȧli֥̇ym niẕi֖̇ym ʻári֥ym bĕ̇ẕurֽwòţ׃"],[19,26,"וְ⁠יֹֽשְׁבֵי⁠הֶן֙ קִצְרֵי־יָ֔ד חַ֖תּוּ וַ⁠יֵּבֹ֑שׁוּ הָי֞וּ עֵ֤שֶׂב שָׂדֶה֙ וִ֣⁠ירַק דֶּ֔שֶׁא חֲצִ֣יר גַּגּ֔וֹת וּ⁠שְׁדֵפָ֖ה לִ⁠פְנֵ֥י קָמָֽה׃","wĕ⁠yòֽşĕ̌béy⁠hen֙ qiẕĕréy-yá֔d ẖa֖ţ̇ẇ wa⁠yé̇bò֑ş̌ẇ háy֞ẇ ʻé֤şêb şá̂deh֙ wi֣⁠yraq dė֔şěʼ ẖàẕi֣yr gȧġ֔wòţ ẇ⁠şĕ̌dépá֖h li⁠pĕné֥y qámáֽh׃"],[19,27,"וְ⁠שִׁבְתְּ⁠ךָ֛ וְ⁠צֵאתְ⁠ךָ֥ וּ⁠בֹאֲ⁠ךָ֖ יָדָ֑עְתִּי וְ⁠אֵ֖ת הִֽתְרַגֶּזְ⁠ךָ֥ אֵלָֽ⁠י׃","wĕ⁠şǐbĕţĕ̇⁠ká֛ wĕ⁠ẕéʼţĕ⁠ká֥ ẇ⁠bòʼà⁠ká֖ yádá֑ʻĕţi̇y wĕ⁠ʼé֖ţ hiֽţĕragėzĕ⁠ká֥ ʼéláֽ⁠y׃"],[19,28,"יַ֚עַן הִתְרַגֶּזְ⁠ךָ֣ אֵלַ֔⁠י וְ⁠שַׁאֲנַנְ⁠ךָ֖ עָלָ֣ה בְ⁠אָזְנָ֑⁠י וְ⁠שַׂמְתִּ֨י חַחִ֜⁠י בְּ⁠אַפֶּ֗⁠ךָ וּ⁠מִתְגִּ⁠י֙ בִּ⁠שְׂפָתֶ֔י⁠ךָ וַ⁠הֲשִׁ֣בֹתִ֔י⁠ךָ בַּ⁠דֶּ֖רֶךְ אֲשֶׁר־בָּ֥אתָ בָּֽ⁠הּ׃","ya֚ʻan hiţĕragėzĕ⁠ká֣ ʼéla֔⁠y wĕ⁠şǎʼànanĕ⁠ká֖ ʻálá֣h bĕ⁠ʼázĕná֑⁠y wĕ⁠şâmĕţi̇֨y ẖaẖi֜⁠y bĕ̇⁠ʼapė֗⁠ká ẇ⁠miţĕgi̇⁠y֙ bi̇⁠şĕ̂páţe֔y⁠ká wa⁠hàşǐ֣bòţi֔y⁠ká bȧ⁠dė֖rekĕ ʼàşěr-bá֥̇ʼţá báֽ̇⁠ḣ׃"],[19,29,"וְ⁠זֶה־לְּ⁠ךָ֣ הָ⁠א֔וֹת אָכ֤וֹל הַ⁠שָּׁנָה֙ סָפִ֔יחַ וּ⁠בַ⁠שָּׁנָ֥ה הַ⁠שֵּׁנִ֖ית סָחִ֑ישׁ וּ⁠בַ⁠שָּׁנָ֣ה הַ⁠שְּׁלִישִׁ֗ית זִרְע֧וּ וְ⁠קִצְר֛וּ וְ⁠נִטְע֥וּ כְרָמִ֖ים וְ⁠אִכְל֥וּ פִרְיָֽ⁠ם׃","wĕ⁠zeh-lĕ̇⁠ká֣ há⁠ʼ֔wòţ ʼák֤wòl ha⁠şá̇̌náh֙ sápi֔yẖa ẇ⁠ba⁠şá̇̌ná֥h ha⁠şé̇̌ni֖yţ sáẖi֑yş̌ ẇ⁠ba⁠şá̇̌ná֣h ha⁠şĕ̇̌liyşǐ֗yţ zirĕʻ֧ẇ wĕ⁠qiẕĕr֛ẇ wĕ⁠nitĕʻ֥ẇ kĕrámi֖ym wĕ⁠ʼikĕl֥ẇ pirĕyáֽ⁠m׃"],[19,30,"וְ⁠יָ֨סְפָ֜ה פְּלֵיטַ֧ת בֵּית־יְהוּדָ֛ה הַ⁠נִּשְׁאָרָ֖ה שֹׁ֣רֶשׁ לְ⁠מָ֑טָּה וְ⁠עָשָׂ֥ה פְרִ֖י לְ⁠מָֽעְלָ⁠ה׃","wĕ⁠yá֨sĕpá֜h pĕ̇léyta֧ţ bé̇yţ-yĕhẇdá֛h ha⁠ni̇şĕ̌ʼárá֖h şò֣̌reş̌ lĕ⁠má֑tá̇h wĕ⁠ʻáşá֥̂h pĕri֖y lĕ⁠máֽʻĕlá⁠h׃"],[19,31,"כִּ֤י מִ⁠ירוּשָׁלִַ֨ם֙ תֵּצֵ֣א שְׁאֵרִ֔ית וּ⁠פְלֵיטָ֖ה מֵ⁠הַ֣ר צִיּ֑וֹן קִנְאַ֛ת יְהוָ֥ה תַּֽעֲשֶׂה־זֹּֽאת׃ס","ki֤̇y mi⁠yrẇşá̌lia֨m֙ ţé̇ẕé֣ʼ şĕ̌ʼéri֔yţ ẇ⁠pĕléytá֖h mé⁠ha֣r ẕiẏ֑wòn qinĕʼa֛ţ yĕhwá֥h ţȧֽʻàşêh-zòֽ̇ʼţ׃s"],[19,32,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֤ר יְהוָה֙ אֶל־מֶ֣לֶךְ אַשּׁ֔וּר לֹ֤א יָבֹא֙ אֶל־הָ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠לֹֽא־יוֹרֶ֥ה שָׁ֖ם חֵ֑ץ וְ⁠לֹֽא־יְקַדְּמֶ֣⁠נָּה מָגֵ֔ן וְ⁠לֹֽא־יִשְׁפֹּ֥ךְ עָלֶ֖י⁠הָ סֹלְלָֽה׃","lá⁠ké֗n kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼel-me֣lekĕ ʼaş̇̌֔ẇr lò֤ʼ yábòʼ֙ ʼel-há⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠lòֽʼ-ywòre֥h şá֖̌m ẖé֑ẕ wĕ⁠lòֽʼ-yĕqadĕ̇me֣⁠ná̇h mágé֔n wĕ⁠lòֽʼ-yişĕ̌pò֥̇kĕ ʻále֖y⁠há sòlĕláֽh׃"],[19,33,"בַּ⁠דֶּ֥רֶךְ אֲשֶׁר־יָבֹ֖א בָּ֣⁠הּ יָשׁ֑וּב וְ⁠אֶל־הָ⁠עִ֥יר הַ⁠זֹּ֛את לֹ֥א יָבֹ֖א נְאֻם־יְהוָֽה׃","bȧ⁠dė֥rekĕ ʼàşěr-yábò֖ʼ bá֣̇⁠ḣ yáş֑̌ẇb wĕ⁠ʼel-há⁠ʻi֥yr ha⁠zò֛̇ʼţ lò֥ʼ yábò֖ʼ nĕʼum-yĕhwáֽh׃"],[19,34,"וְ⁠גַנּוֹתִ֛י אֶל־הָ⁠עִ֥יר הַ⁠זֹּ֖את לְ⁠הֽוֹשִׁיעָ֑⁠הּ לְמַֽעֲנִ֔⁠י וּ⁠לְמַ֖עַן דָּוִ֥ד עַבְדִּֽ⁠י׃","wĕ⁠gaṅwòţi֛y ʼel-há⁠ʻi֥yr ha⁠zò֖̇ʼţ lĕ⁠hֽwòşǐyʻá֑⁠ḣ lĕmaֽʻàni֔⁠y ẇ⁠lĕma֖ʻan dá̇wi֥d ʻabĕdiֽ̇⁠y׃"],[19,35,"וַ⁠יְהִי֮ בַּ⁠לַּ֣יְלָה הַ⁠הוּא֒ וַ⁠יֵּצֵ֣א ׀ מַלְאַ֣ךְ יְהוָ֗ה וַ⁠יַּךְ֙ בְּ⁠מַחֲנֵ֣ה אַשּׁ֔וּר מֵאָ֛ה שְׁמוֹנִ֥ים וַ⁠חֲמִשָּׁ֖ה אָ֑לֶף וַ⁠יַּשְׁכִּ֣ימוּ בַ⁠בֹּ֔קֶר וְ⁠הִנֵּ֥ה כֻלָּ֖⁠ם פְּגָרִ֥ים מֵתִֽים׃","wa⁠yĕhiy֮ bȧ⁠lȧ֣yĕláh ha⁠hẇʼ֒ wa⁠yé̇ẕé֣ʼ ׀ malĕʼa֣kĕ yĕhwá֗h wa⁠yȧkĕ֙ bĕ̇⁠maẖàné֣h ʼaş̇̌֔ẇr méʼá֛h şĕ̌mwòni֥ym wa⁠ẖàmişá֖̇̌h ʼá֑lep wa⁠yȧşĕ̌ki֣̇ymẇ ba⁠bò̇֔qer wĕ⁠hiné֥̇h kulá֖̇⁠m pĕ̇gári֥ym méţiֽym׃"],[19,36,"וַ⁠יִּסַּ֣ע וַ⁠יֵּ֔לֶךְ וַ⁠יָּ֖שָׁב סַנְחֵרִ֣יב מֶֽלֶךְ־אַשּׁ֑וּר וַ⁠יֵּ֖שֶׁב בְּ⁠נִֽינְוֵֽה׃","wa⁠yi̇sȧ֣ʻ wa⁠yé̇֔lekĕ wa⁠yá֖̇şá̌b sanĕẖéri֣yb meֽlekĕ-ʼaş֑̇̌ẇr wa⁠yé֖̇şěb bĕ̇⁠niֽynĕwéֽh׃"],[19,37,"וַ⁠יְהִי֩ ה֨וּא מִֽשְׁתַּחֲוֶ֜ה בֵּ֣ית ׀ נִסְרֹ֣ךְ אֱלֹהָ֗י⁠ו וְֽ⁠אַדְרַמֶּ֨לֶךְ וְ⁠שַׂרְאֶ֤צֶר הִכֻּ֣⁠הוּ בַ⁠חֶ֔רֶב וְ⁠הֵ֥מָּה נִמְלְט֖וּ אֶ֣רֶץ אֲרָרָ֑ט וַ⁠יִּמְלֹ֛ךְ אֵֽסַר־חַדֹּ֥ן בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yĕhiy֩ h֨ẇʼ miֽşĕ̌ţȧẖàwe֜h bé֣̇yţ ׀ nisĕrò֣kĕ ʼèlòhá֗y⁠w wĕֽ⁠ʼadĕramė֨lekĕ wĕ⁠şârĕʼe֤ẕer hiku֣̇⁠hẇ ba⁠ẖe֔reb wĕ⁠hé֥má̇h nimĕlĕt֖ẇ ʼe֣reẕ ʼàrárá֑t wa⁠yi̇mĕlò֛kĕ ʼéֽsar-ẖadò֥̇n bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[20,1,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם חָלָ֥ה חִזְקִיָּ֖הוּ לָ⁠מ֑וּת וַ⁠יָּבֹ֣א אֵ֠לָי⁠ו יְשַׁעְיָ֨הוּ בֶן־אָמ֜וֹץ הַ⁠נָּבִ֗יא וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו כֹּֽה־אָמַ֤ר יְהוָה֙ צַ֣ו לְ⁠בֵיתֶ֔⁠ךָ כִּ֛י מֵ֥ת אַתָּ֖ה וְ⁠לֹ֥א תִֽחְיֶֽה׃","bȧ⁠yá̇mi֣ym há⁠hé֔m ẖálá֥h ẖizĕqiyá֖̇hẇ lá⁠m֑ẇţ wa⁠yá̇bò֣ʼ ʼé֠láy⁠w yĕşǎʻĕyá֨hẇ ben-ʼám֜wòẕ ha⁠ná̇bi֗yʼ wa⁠yò̇֨ʼmer ʼélá֜y⁠w kòֽ̇h-ʼáma֤r yĕhwáh֙ ẕa֣w lĕ⁠béyţe֔⁠ká ki֛̇y mé֥ţ ʼaţá֖̇h wĕ⁠lò֥ʼ ţiֽẖĕyeֽh׃"],[20,2,"וַ⁠יַּסֵּ֥ב אֶת־פָּנָ֖י⁠ו אֶל־הַ⁠קִּ֑יר וַ⁠יִּ֨תְפַּלֵּ֔ל אֶל־יְהוָ֖ה לֵ⁠אמֹֽר׃","wa⁠yȧsé֥̇b ʼeţ-pá̇ná֖y⁠w ʼel-ha⁠qi֑̇yr wa⁠yi̇֨ţĕpȧlé̇֔l ʼel-yĕhwá֖h lé⁠ʼmòֽr׃"],[20,3,"אָנָּ֣ה יְהוָ֗ה זְכָר־נָ֞א אֵ֣ת אֲשֶׁ֧ר הִתְהַלַּ֣כְתִּי לְ⁠פָנֶ֗י⁠ךָ בֶּֽ⁠אֱמֶת֙ וּ⁠בְ⁠לֵבָ֣ב שָׁלֵ֔ם וְ⁠הַ⁠טּ֥וֹב בְּ⁠עֵינֶ֖י⁠ךָ עָשִׂ֑יתִי וַ⁠יֵּ֥בְךְּ חִזְקִיָּ֖הוּ בְּכִ֥י גָדֽוֹל׃ס","ʼáná֣̇h yĕhwá֗h zĕkár-ná֞ʼ ʼé֣ţ ʼàşě֧r hiţĕhalȧ֣kĕţi̇y lĕ⁠páne֗y⁠ká bėֽ⁠ʼèmeţ֙ ẇ⁠bĕ⁠lébá֣b şá̌lé֔m wĕ⁠ha⁠ṫ֥wòb bĕ̇⁠ʻéyne֖y⁠ká ʻáşî֑yţiy wa⁠yé֥̇bĕkĕ̇ ẖizĕqiyá֖̇hẇ bĕ̇ki֥y gádֽwòl׃s"],[20,4,"וַ⁠יְהִ֣י יְשַׁעְיָ֔הוּ לֹ֣א יָצָ֔א ה⁠עיר הַ⁠תִּֽיכֹנָ֑ה וּ⁠דְבַר־יְהוָ֔ה הָיָ֥ה אֵלָ֖י⁠ו לֵ⁠אמֹֽר׃","wa⁠yĕhi֣y yĕşǎʻĕyá֔hẇ lò֣ʼ yáẕá֔ʼ h⁠ʻyr ha⁠ţiֽ̇ykòná֑h ẇ⁠dĕbar-yĕhwá֔h háyá֥h ʼélá֖y⁠w lé⁠ʼmòֽr׃"],[20,5,"שׁ֣וּב וְ⁠אָמַרְתָּ֞ אֶל־חִזְקִיָּ֣הוּ נְגִיד־עַמִּ֗⁠י כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵי֙ דָּוִ֣ד אָבִ֔י⁠ךָ שָׁמַ֨עְתִּי֙ אֶת־תְּפִלָּתֶ֔⁠ךָ רָאִ֖יתִי אֶת־דִּמְעָתֶ֑⁠ךָ הִנְ⁠נִי֙ רֹ֣פֶא לָ֔⁠ךְ בַּ⁠יּוֹם֙ הַ⁠שְּׁלִישִׁ֔י תַּעֲלֶ֖ה בֵּ֥ית יְהוָֽה׃","ş֣̌ẇb wĕ⁠ʼámarĕţá̇֞ ʼel-ẖizĕqiyá֣̇hẇ nĕgiyd-ʻami̇֗⁠y kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhéy֙ dá̇wi֣d ʼábi֔y⁠ká şá̌ma֨ʻĕţi̇y֙ ʼeţ-ţĕ̇pilá̇ţe֔⁠ká ráʼi֖yţiy ʼeţ-di̇mĕʻáţe֑⁠ká hinĕ⁠niy֙ rò֣peʼ lá֔⁠kĕ bȧ⁠ẏwòm֙ ha⁠şĕ̇̌liyşǐ֔y ţȧʻàle֖h bé֥̇yţ yĕhwáֽh׃"],[20,6,"וְ⁠הֹסַפְתִּ֣י עַל־יָמֶ֗י⁠ךָ חֲמֵ֤שׁ עֶשְׂרֵה֙ שָׁנָ֔ה וּ⁠מִ⁠כַּ֤ף מֶֽלֶךְ־אַשּׁוּר֙ אַצִּ֣ילְ⁠ךָ֔ וְ⁠אֵ֖ת הָ⁠עִ֣יר הַ⁠זֹּ֑את וְ⁠גַנּוֹתִי֙ עַל־הָ⁠עִ֣יר הַ⁠זֹּ֔את לְמַֽעֲנִ֔⁠י וּ⁠לְמַ֖עַן דָּוִ֥ד עַבְדִּֽ⁠י׃","wĕ⁠hòsapĕţi֣̇y ʻal-yáme֗y⁠ká ẖàmé֤ş̌ ʻeşĕ̂réh֙ şá̌ná֔h ẇ⁠mi⁠kȧ֤p meֽlekĕ-ʼaş̇̌ẇr֙ ʼaẕi֣̇ylĕ⁠ká֔ wĕ⁠ʼé֖ţ há⁠ʻi֣yr ha⁠zò֑̇ʼţ wĕ⁠gaṅwòţiy֙ ʻal-há⁠ʻi֣yr ha⁠zò̇֔ʼţ lĕmaֽʻàni֔⁠y ẇ⁠lĕma֖ʻan dá̇wi֥d ʻabĕdiֽ̇⁠y׃"],[20,7,"וַ⁠יֹּ֣אמֶר יְשַֽׁעְיָ֔הוּ קְח֖וּ דְּבֶ֣לֶת תְּאֵנִ֑ים וַ⁠יִּקְח֛וּ וַ⁠יָּשִׂ֥ימוּ עַֽל־הַ⁠שְּׁחִ֖ין וַ⁠יֶּֽחִי׃","wa⁠yò֣̇ʼmer yĕşǎֽʻĕyá֔hẇ qĕẖ֖ẇ dĕ̇be֣leţ ţĕ̇ʼéni֑ym wa⁠yi̇qĕẖ֛ẇ wa⁠yá̇şî֥ymẇ ʻaֽl-ha⁠şĕ̇̌ẖi֖yn wa⁠yėֽẖiy׃"],[20,8,"וַ⁠יֹּ֤אמֶר חִזְקִיָּ֨הוּ֙ אֶֽל־יְשַׁעְיָ֔הוּ מָ֣ה א֔וֹת כִּֽי־יִרְפָּ֥א יְהוָ֖ה לִ֑⁠י וְ⁠עָלִ֛יתִי בַּ⁠יּ֥וֹם הַ⁠שְּׁלִישִׁ֖י בֵּ֥ית יְהוָֽה׃","wa⁠yò֤̇ʼmer ẖizĕqiyá̇֨hẇ֙ ʼeֽl-yĕşǎʻĕyá֔hẇ má֣h ʼ֔wòţ kiֽ̇y-yirĕpá֥̇ʼ yĕhwá֖h li֑⁠y wĕ⁠ʻáli֛yţiy bȧ⁠ẏ֥wòm ha⁠şĕ̇̌liyşǐ֖y bé֥̇yţ yĕhwáֽh׃"],[20,9,"וַ⁠יֹּ֣אמֶר יְשַׁעְיָ֗הוּ זֶה־לְּ⁠ךָ֤ הָ⁠אוֹת֙ מֵ⁠אֵ֣ת יְהוָ֔ה כִּ֚י יַעֲשֶׂ֣ה יְהוָ֔ה אֶת־הַ⁠דָּבָ֖ר אֲשֶׁ֣ר דִּבֵּ֑ר הָלַ֤ךְ הַ⁠צֵּל֙ עֶ֣שֶׂר מַֽעֲל֔וֹת אִם־יָשׁ֖וּב עֶ֥שֶׂר מַעֲלֽוֹת׃","wa⁠yò֣̇ʼmer yĕşǎʻĕyá֗hẇ zeh-lĕ̇⁠ká֤ há⁠ʼwòţ֙ mé⁠ʼé֣ţ yĕhwá֔h ki֚̇y yaʻàşê֣h yĕhwá֔h ʼeţ-ha⁠dá̇bá֖r ʼàşě֣r di̇bé֑̇r hála֤kĕ ha⁠ẕé̇l֙ ʻe֣şêr maֽʻàl֔wòţ ʼim-yáş֖̌ẇb ʻe֥şêr maʻàlֽwòţ׃"],[20,10,"וַ⁠יֹּ֨אמֶר֙ יְחִזְקִיָּ֔הוּ נָקֵ֣ל לַ⁠צֵּ֔ל לִ⁠נְט֖וֹת עֶ֣שֶׂר מַעֲל֑וֹת לֹ֣א כִ֔י יָשׁ֥וּב הַ⁠צֵּ֛ל אֲחֹרַנִּ֖ית עֶ֥שֶׂר מַעֲלֽוֹת׃","wa⁠yò̇֨ʼmer֙ yĕẖizĕqiyá̇֔hẇ náqé֣l la⁠ẕé̇֔l li⁠nĕt֖wòţ ʻe֣şêr maʻàl֑wòţ lò֣ʼ ki֔y yáş֥̌ẇb ha⁠ẕé֛̇l ʼàẖòrani֖̇yţ ʻe֥şêr maʻàlֽwòţ׃"],[20,11,"וַ⁠יִּקְרָ֛א יְשַׁעְיָ֥הוּ הַ⁠נָּבִ֖יא אֶל־יְהוָ֑ה וַ⁠יָּ֣שֶׁב אֶת־הַ⁠צֵּ֗ל בַּֽ֠⁠מַּעֲלוֹת אֲשֶׁ֨ר יָרְדָ֜ה בְּ⁠מַעֲל֥וֹת אָחָ֛ז אֲחֹֽרַנִּ֖ית עֶ֥שֶׂר מַעֲלֽוֹת׃פ","wa⁠yi̇qĕrá֛ʼ yĕşǎʻĕyá֥hẇ ha⁠ná̇bi֖yʼ ʼel-yĕhwá֑h wa⁠yá֣̇şěb ʼeţ-ha⁠ẕé̇֗l bȧֽ֠⁠mȧʻàlwòţ ʼàşě֨r yárĕdá֜h bĕ̇⁠maʻàl֥wòţ ʼáẖá֛z ʼàẖòֽrani֖̇yţ ʻe֥şêr maʻàlֽwòţ׃p"],[20,12,"בָּ⁠עֵ֣ת הַ⁠הִ֡יא שָׁלַ֡ח בְּרֹאדַ֣ךְ בַּ֠לְאֲדָן בֶּֽן־בַּלְאֲדָ֧ן מֶֽלֶךְ־בָּבֶ֛ל סְפָרִ֥ים וּ⁠מִנְחָ֖ה אֶל־חִזְקִיָּ֑הוּ כִּ֣י שָׁמַ֔ע כִּ֥י חָלָ֖ה חִזְקִיָּֽהוּ׃","bá̇⁠ʻé֣ţ ha⁠hi֡yʼ şá̌la֡ẖ bĕ̇ròʼda֣kĕ bȧ֠lĕʼàdán bėֽn-bȧlĕʼàdá֧n meֽlekĕ-bá̇be֛l sĕpári֥ym ẇ⁠minĕẖá֖h ʼel-ẖizĕqiyá֑̇hẇ ki֣̇y şá̌ma֔ʻ ki֥̇y ẖálá֖h ẖizĕqiyáֽ̇hẇ׃"],[20,13,"וַ⁠יִּשְׁמַ֣ע עֲלֵי⁠הֶם֮ חִזְקִיָּהוּ֒ וַ⁠יַּרְאֵ֣⁠ם אֶת־כָּל־בֵּ֣ית נְכֹתֹ֡⁠ה אֶת־הַ⁠כֶּסֶף֩ וְ⁠אֶת־הַ⁠זָּהָ֨ב וְ⁠אֶת־הַ⁠בְּשָׂמִ֜ים וְ⁠אֵ֣ת ׀ שֶׁ֣מֶן הַ⁠טּ֗וֹב וְ⁠אֵת֙ בֵּ֣ית כֵּלָ֔י⁠ו וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר נִמְצָ֖א בְּ⁠אֽוֹצְרֹתָ֑י⁠ו לֹֽא־הָיָ֣ה דָבָ֗ר אֲ֠שֶׁר לֹֽא־הֶרְאָ֧⁠ם חִזְקִיָּ֛הוּ בְּ⁠בֵית֖⁠וֹ וּ⁠בְ⁠כָל־מֶמְשַׁלְתּֽ⁠וֹ׃","wa⁠yi̇şĕ̌ma֣ʻ ʻàléy⁠hem֮ ẖizĕqiyá̇hẇ֒ wa⁠yȧrĕʼé֣⁠m ʼeţ-ká̇l-bé֣̇yţ nĕkòţò֡⁠h ʼeţ-ha⁠kėsep֩ wĕ⁠ʼeţ-ha⁠zá̇há֨b wĕ⁠ʼeţ-ha⁠bĕ̇şá̂mi֜ym wĕ⁠ʼé֣ţ ׀ şě֣men ha⁠ṫ֗wòb wĕ⁠ʼéţ֙ bé֣̇yţ ké̇lá֔y⁠w wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r nimĕẕá֖ʼ bĕ̇⁠ʼֽwòẕĕròţá֑y⁠w lòֽʼ-háyá֣h dábá֗r ʼà֠şěr lòֽʼ-herĕʼá֧⁠m ẖizĕqiyá֛̇hẇ bĕ̇⁠béyţ֖⁠wò ẇ⁠bĕ⁠kál-memĕşǎlĕţֽ̇⁠wò׃"],[20,14,"וַ⁠יָּבֹא֙ יְשַֽׁעְיָ֣הוּ הַ⁠נָּבִ֔יא אֶל־הַ⁠מֶּ֖לֶךְ חִזְקִיָּ֑הוּ וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו מָ֥ה אָמְר֣וּ ׀ הָ⁠אֲנָשִׁ֣ים הָ⁠אֵ֗לֶּה וּ⁠מֵ⁠אַ֨יִן֙ יָבֹ֣אוּ אֵלֶ֔י⁠ךָ וַ⁠יֹּ֨אמֶר֙ חִזְקִיָּ֔הוּ מֵ⁠אֶ֧רֶץ רְחוֹקָ֛ה בָּ֖אוּ מִ⁠בָּבֶֽל׃","wa⁠yá̇bòʼ֙ yĕşǎֽʻĕyá֣hẇ ha⁠ná̇bi֔yʼ ʼel-ha⁠mė֖lekĕ ẖizĕqiyá֑̇hẇ wa⁠yò̇֨ʼmer ʼélá֜y⁠w má֥h ʼámĕr֣ẇ ׀ há⁠ʼànáşǐ֣ym há⁠ʼé֗lėh ẇ⁠mé⁠ʼa֨yin֙ yábò֣ʼẇ ʼéle֔y⁠ká wa⁠yò̇֨ʼmer֙ ẖizĕqiyá̇֔hẇ mé⁠ʼe֧reẕ rĕẖwòqá֛h bá֖̇ʼẇ mi⁠bá̇beֽl׃"],[20,15,"וַ⁠יֹּ֕אמֶר מָ֥ה רָא֖וּ בְּ⁠בֵיתֶ֑⁠ךָ וַ⁠יֹּ֣אמֶר חִזְקִיָּ֗הוּ אֵ֣ת כָּל־אֲשֶׁ֤ר בְּ⁠בֵיתִ⁠י֙ רָא֔וּ לֹא־הָיָ֥ה דָבָ֛ר אֲשֶׁ֥ר לֹֽא־הִרְאִיתִ֖⁠ם בְּ⁠אֹצְרֹתָֽ⁠י׃","wa⁠yò̇֕ʼmer má֥h ráʼ֖ẇ bĕ̇⁠béyţe֑⁠ká wa⁠yò֣̇ʼmer ẖizĕqiyá̇֗hẇ ʼé֣ţ ká̇l-ʼàşě֤r bĕ̇⁠béyţi⁠y֙ ráʼ֔ẇ lòʼ-háyá֥h dábá֛r ʼàşě֥r lòֽʼ-hirĕʼiyţi֖⁠m bĕ̇⁠ʼòẕĕròţáֽ⁠y׃"],[20,16,"וַ⁠יֹּ֥אמֶר יְשַׁעְיָ֖הוּ אֶל־חִזְקִיָּ֑הוּ שְׁמַ֖ע דְּבַר־יְהוָֽה׃","wa⁠yò֥̇ʼmer yĕşǎʻĕyá֖hẇ ʼel-ẖizĕqiyá֑̇hẇ şĕ̌ma֖ʻ dĕ̇bar-yĕhwáֽh׃"],[20,17,"הִנֵּה֮ יָמִ֣ים בָּאִים֒ וְ⁠נִשָּׂ֣א ׀ כָּל־אֲשֶׁ֣ר בְּ⁠בֵיתֶ֗⁠ךָ וַ⁠אֲשֶׁ֨ר אָצְר֧וּ אֲבֹתֶ֛י⁠ךָ עַד־הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה בָּבֶ֑לָ⁠ה לֹֽא־יִוָּתֵ֥ר דָּבָ֖ר אָמַ֥ר יְהוָֽה׃","hiné̇h֮ yámi֣ym bá̇ʼiym֒ wĕ⁠nişá֣̇̂ʼ ׀ ká̇l-ʼàşě֣r bĕ̇⁠béyţe֗⁠ká wa⁠ʼàşě֨r ʼáẕĕr֧ẇ ʼàbòţe֛y⁠ká ʻad-ha⁠ẏ֥wòm ha⁠zė֖h bá̇be֑lá⁠h lòֽʼ-yiwá̇ţé֥r dá̇bá֖r ʼáma֥r yĕhwáֽh׃"],[20,18,"וּ⁠מִ⁠בָּנֶ֜י⁠ךָ אֲשֶׁ֨ר יֵצְא֧וּ מִמְּ⁠ךָ֛ אֲשֶׁ֥ר תּוֹלִ֖יד יקח וְ⁠הָיוּ֙ סָֽרִיסִ֔ים בְּ⁠הֵיכַ֖ל מֶ֥לֶךְ בָּבֶֽל׃","ẇ⁠mi⁠bá̇ne֜y⁠ká ʼàşě֨r yéẕĕʼ֧ẇ mimĕ̇⁠ká֛ ʼàşě֥r ţ̇wòli֖yd yqẖ wĕ⁠háyẇ֙ sáֽriysi֔ym bĕ̇⁠héyka֖l me֥lekĕ bá̇beֽl׃"],[20,19,"וַ⁠יֹּ֤אמֶר חִזְקִיָּ֨הוּ֙ אֶֽל־יְשַֽׁעְיָ֔הוּ ט֥וֹב דְּבַר־יְהוָ֖ה אֲשֶׁ֣ר דִּבַּ֑רְתָּ וַ⁠יֹּ֕אמֶר הֲ⁠ל֛וֹא אִם־שָׁל֥וֹם וֶ⁠אֱמֶ֖ת יִהְיֶ֥ה בְ⁠יָמָֽ⁠י׃","wa⁠yò֤̇ʼmer ẖizĕqiyá̇֨hẇ֙ ʼeֽl-yĕşǎֽʻĕyá֔hẇ t֥wòb dĕ̇bar-yĕhwá֖h ʼàşě֣r di̇bȧ֑rĕţá̇ wa⁠yò̇֕ʼmer hà⁠l֛wòʼ ʼim-şá̌l֥wòm we⁠ʼème֖ţ yihĕye֥h bĕ⁠yámáֽ⁠y׃"],[20,20,"וְ⁠יֶ֨תֶר דִּבְרֵ֤י חִזְקִיָּ֨הוּ֙ וְ⁠כָל־גְּב֣וּרָת֔⁠וֹ וַ⁠אֲשֶׁ֣ר עָשָׂ֗ה אֶת־הַ⁠בְּרֵכָה֙ וְ⁠אֶת־הַ⁠תְּעָלָ֔ה וַ⁠יָּבֵ֥א אֶת־הַ⁠מַּ֖יִם הָ⁠עִ֑ירָ⁠ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֨ţer di̇bĕré֤y ẖizĕqiyá̇֨hẇ֙ wĕ⁠kál-gĕ̇b֣ẇráţ֔⁠wò wa⁠ʼàşě֣r ʻáşá̂֗h ʼeţ-ha⁠bĕ̇rékáh֙ wĕ⁠ʼeţ-ha⁠ţĕ̇ʻálá֔h wa⁠yá̇bé֥ʼ ʼeţ-ha⁠mȧ֖yim há⁠ʻi֑yrá⁠h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[20,21,"וַ⁠יִּשְׁכַּ֥ב חִזְקִיָּ֖הוּ עִם־אֲבֹתָ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ מְנַשֶּׁ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֥b ẖizĕqiyá֖̇hẇ ʻim-ʼàbòţá֑y⁠w wa⁠yi̇mĕlò֛kĕ mĕnaşė֥̌h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[21,1,"בֶּן־שְׁתֵּ֨ים עֶשְׂרֵ֤ה שָׁנָה֙ מְנַשֶּׁ֣ה בְ⁠מָלְכ֔⁠וֹ וַ⁠חֲמִשִּׁ֤ים וְ⁠חָמֵשׁ֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֥ם אִמּ֖⁠וֹ חֶפְצִי־בָֽהּ׃","bėn-şĕ̌ţé̇֨ym ʻeşĕ̂ré֤h şá̌náh֙ mĕnaşė֣̌h bĕ⁠málĕk֔⁠wò wa⁠ẖàmişi֤̇̌ym wĕ⁠ẖáméş̌֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֥̌m ʼiṁ֖⁠wò ẖepĕẕiy-báֽḣ׃"],[21,2,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠תֽוֹעֲבֹת֙ הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠ţֽwòʻàbòţ֙ ha⁠ġwòyi֔m ʼàşěr֙ hwòri֣yş̌ yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[21,3,"וַ⁠יָּ֗שָׁב וַ⁠יִּ֨בֶן֙ אֶת־הַ⁠בָּמ֔וֹת אֲשֶׁ֥ר אִבַּ֖ד חִזְקִיָּ֣הוּ אָבִ֑י⁠ו וַ⁠יָּ֨קֶם מִזְבְּחֹ֜ת לַ⁠בַּ֗עַל וַ⁠יַּ֤עַשׂ אֲשֵׁרָה֙ כַּ⁠אֲשֶׁ֣ר עָשָׂ֗ה אַחְאָב֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַ⁠יִּשְׁתַּ֨חוּ֙ לְ⁠כָל־צְבָ֣א הַ⁠שָּׁמַ֔יִם וַֽ⁠יַּעֲבֹ֖ד אֹתָֽ⁠ם׃","wa⁠yá̇֗şá̌b wa⁠yi̇֨ben֙ ʼeţ-ha⁠bá̇m֔wòţ ʼàşě֥r ʼibȧ֖d ẖizĕqiyá֣̇hẇ ʼábi֑y⁠w wa⁠yá̇֨qem mizĕbĕ̇ẖò֜ţ la⁠bȧ֗ʻal wa⁠yȧ֤ʻaş̂ ʼàşé̌ráh֙ kȧ⁠ʼàşě֣r ʻáşá̂֗h ʼaẖĕʼáb֙ me֣lekĕ yişĕ̂ráʼé֔l wa⁠yi̇şĕ̌ţȧ֨ẖẇ֙ lĕ⁠kál-ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim waֽ⁠yȧʻàbò֖d ʼòţáֽ⁠m׃"],[21,4,"וּ⁠בָנָ֥ה מִזְבְּחֹ֖ת בְּ⁠בֵ֣ית יְהוָ֑ה אֲשֶׁר֙ אָמַ֣ר יְהוָ֔ה בִּ⁠ירוּשָׁלִַ֖ם אָשִׂ֥ים אֶת־שְׁמִֽ⁠י׃","ẇ⁠báná֥h mizĕbĕ̇ẖò֖ţ bĕ̇⁠bé֣yţ yĕhwá֑h ʼàşěr֙ ʼáma֣r yĕhwá֔h bi̇⁠yrẇşá̌lia֖m ʼáşî֥ym ʼeţ-şĕ̌miֽ⁠y׃"],[21,5,"וַ⁠יִּ֥בֶן מִזְבְּח֖וֹת לְ⁠כָל־צְבָ֣א הַ⁠שָּׁמָ֑יִם בִּ⁠שְׁתֵּ֖י חַצְר֥וֹת בֵּית־יְהוָֽה׃","wa⁠yi֥̇ben mizĕbĕ̇ẖ֖wòţ lĕ⁠kál-ẕĕbá֣ʼ ha⁠şá̇̌má֑yim bi̇⁠şĕ̌ţé֖̇y ẖaẕĕr֥wòţ bé̇yţ-yĕhwáֽh׃"],[21,6,"וְ⁠הֶעֱבִ֤יר אֶת־בְּנ⁠וֹ֙ בָּ⁠אֵ֔שׁ וְ⁠עוֹנֵ֣ן וְ⁠נִחֵ֔שׁ וְ⁠עָ֥שָׂה א֖וֹב וְ⁠יִדְּעֹנִ֑ים הִרְבָּ֗ה לַ⁠עֲשׂ֥וֹת הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה לְ⁠הַכְעִֽיס׃","wĕ⁠heʻèbi֤yr ʼeţ-bĕ̇n⁠wò֙ bá̇⁠ʼé֔ş̌ wĕ⁠ʻwòné֣n wĕ⁠niẖé֔ş̌ wĕ⁠ʻá֥şá̂h ʼ֖wòb wĕ⁠yidĕ̇ʻòni֑ym hirĕbá̇֗h la⁠ʻàş֥̂wòţ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h lĕ⁠hakĕʻiֽys׃"],[21,7,"וַ⁠יָּ֕שֶׂם אֶת־פֶּ֥סֶל הָ⁠אֲשֵׁרָ֖ה אֲשֶׁ֣ר עָשָׂ֑ה בַּ⁠בַּ֗יִת אֲשֶׁ֨ר אָמַ֤ר יְהוָה֙ אֶל־דָּוִד֙ וְ⁠אֶל־שְׁלֹמֹ֣ה בְנ֔⁠וֹ בַּ⁠בַּ֨יִת הַ⁠זֶּ֜ה וּ⁠בִ⁠ירוּשָׁלִַ֗ם אֲשֶׁ֤ר בָּחַ֨רְתִּי֙ מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל אָשִׂ֥ים אֶת־שְׁמִ֖⁠י לְ⁠עוֹלָֽם׃","wa⁠yá̇֕şêm ʼeţ-pė֥sel há⁠ʼàşé̌rá֖h ʼàşě֣r ʻáşá֑̂h bȧ⁠bȧ֗yiţ ʼàşě֨r ʼáma֤r yĕhwáh֙ ʼel-dá̇wid֙ wĕ⁠ʼel-şĕ̌lòmò֣h bĕn֔⁠wò bȧ⁠bȧ֨yiţ ha⁠zė֜h ẇ⁠bi⁠yrẇşá̌lia֗m ʼàşě֤r bá̇ẖa֨rĕţi̇y֙ mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l ʼáşî֥ym ʼeţ-şĕ̌mi֖⁠y lĕ⁠ʻwòláֽm׃"],[21,8,"וְ⁠לֹ֣א אֹסִ֗יף לְ⁠הָנִיד֙ רֶ֣גֶל יִשְׂרָאֵ֔ל מִן־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֥ר נָתַ֖תִּי לַֽ⁠אֲבוֹתָ֑⁠ם רַ֣ק ׀ אִם־יִשְׁמְר֣וּ לַ⁠עֲשׂ֗וֹת כְּ⁠כֹל֙ אֲשֶׁ֣ר צִוִּיתִ֔י⁠ם וּ⁠לְ⁠כָל־הַ֨⁠תּוֹרָ֔ה אֲשֶׁר־צִוָּ֥ה אֹתָ֖⁠ם עַבְדִּ֥⁠י מֹשֶֽׁה׃","wĕ⁠lò֣ʼ ʼòsi֗yp lĕ⁠hániyd֙ re֣gel yişĕ̂ráʼé֔l min-há֣⁠ʼàdámá֔h ʼàşě֥r náţa֖ţi̇y laֽ⁠ʼàbwòţá֑⁠m ra֣q ׀ ʼim-yişĕ̌mĕr֣ẇ la⁠ʻàş̂֗wòţ kĕ̇⁠kòl֙ ʼàşě֣r ẕiwi̇yţi֔y⁠m ẇ⁠lĕ⁠kál-ha֨⁠ţ̇wòrá֔h ʼàşěr-ẕiwá֥̇h ʼòţá֖⁠m ʻabĕdi֥̇⁠y mòşěֽh׃"],[21,9,"וְ⁠לֹ֖א שָׁמֵ֑עוּ וַ⁠יַּתְעֵ֤⁠ם מְנַשֶּׁה֙ לַ⁠עֲשׂ֣וֹת אֶת־הָ⁠רָ֔ע מִן־הַ֨⁠גּוֹיִ֔ם אֲשֶׁר֙ הִשְׁמִ֣יד יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠lò֖ʼ şá̌mé֑ʻẇ wa⁠yȧţĕʻé֤⁠m mĕnaşė̌h֙ la⁠ʻàş֣̂wòţ ʼeţ-há⁠rá֔ʻ min-ha֨⁠ġwòyi֔m ʼàşěr֙ hişĕ̌mi֣yd yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[21,10,"וַ⁠יְדַבֵּ֧ר יְהוָ֛ה בְּ⁠יַד־עֲבָדָ֥י⁠ו הַ⁠נְּבִיאִ֖ים לֵ⁠אמֹֽר׃","wa⁠yĕdabé֧̇r yĕhwá֛h bĕ̇⁠yad-ʻàbádá֥y⁠w ha⁠nĕ̇biyʼi֖ym lé⁠ʼmòֽr׃"],[21,11,"יַעַן֩ אֲשֶׁ֨ר עָשָׂ֜ה מְנַשֶּׁ֤ה מֶֽלֶךְ־יְהוּדָה֙ הַ⁠תֹּעֵב֣וֹת הָ⁠אֵ֔לֶּה הֵרַ֕ע מִ⁠כֹּ֛ל אֲשֶׁר־עָשׂ֥וּ הָ⁠אֱמֹרִ֖י אֲשֶׁ֣ר לְ⁠פָנָ֑י⁠ו וַ⁠יַּחֲטִ֥א גַֽם־אֶת־יְהוּדָ֖ה בְּ⁠גִלּוּלָֽי⁠ו׃פ","yaʻan֩ ʼàşě֨r ʻáşá̂֜h mĕnaşė֤̌h meֽlekĕ-yĕhẇdáh֙ ha⁠ţò̇ʻéb֣wòţ há⁠ʼé֔lėh héra֕ʻ mi⁠kò֛̇l ʼàşěr-ʻáş֥̂ẇ há⁠ʼèmòri֖y ʼàşě֣r lĕ⁠páná֑y⁠w wa⁠yȧẖàti֥ʼ gaֽm-ʼeţ-yĕhẇdá֖h bĕ̇⁠gil̇ẇláֽy⁠w׃p"],[21,12,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הִנְ⁠נִי֙ מֵבִ֣יא רָעָ֔ה עַל־יְרוּשָׁלִַ֖ם וִֽ⁠יהוּדָ֑ה אֲשֶׁר֙ כָּל־שמעי⁠ו תִּצַּ֖לְנָה שְׁתֵּ֥י אָזְנָֽי⁠ו׃","lá⁠ké֗n kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hinĕ⁠niy֙ mébi֣yʼ ráʻá֔h ʻal-yĕrẇşá̌lia֖m wiֽ⁠yhẇdá֑h ʼàşěr֙ ká̇l-şmʻy⁠w ţi̇ẕȧ֖lĕnáh şĕ̌ţé֥̇y ʼázĕnáֽy⁠w׃"],[21,13,"וְ⁠נָטִ֣יתִי עַל־יְרוּשָׁלִַ֗ם אֵ֚ת קָ֣ו שֹֽׁמְר֔וֹן וְ⁠אֶת־מִשְׁקֹ֖לֶת בֵּ֣ית אַחְאָ֑ב וּ⁠מָחִ֨יתִי אֶת־יְרוּשָׁלִַ֜ם כַּֽ⁠אֲשֶׁר־יִמְחֶ֤ה אֶת־הַ⁠צַּלַּ֨חַת֙ מָחָ֔ה וְ⁠הָפַ֖ךְ עַל־פָּנֶֽי⁠הָ׃","wĕ⁠náti֣yţiy ʻal-yĕrẇşá̌lia֗m ʼé֚ţ qá֣w şòֽ̌mĕr֔wòn wĕ⁠ʼeţ-mişĕ̌qò֖leţ bé֣̇yţ ʼaẖĕʼá֑b ẇ⁠máẖi֨yţiy ʼeţ-yĕrẇşá̌lia֜m kȧֽ⁠ʼàşěr-yimĕẖe֤h ʼeţ-ha⁠ẕȧlȧ֨ẖaţ֙ máẖá֔h wĕ⁠hápa֖kĕ ʻal-pá̇neֽy⁠há׃"],[21,14,"וְ⁠נָטַשְׁתִּ֗י אֵ֚ת שְׁאֵרִ֣ית נַחֲלָתִ֔⁠י וּ⁠נְתַתִּ֖י⁠ם בְּ⁠יַ֣ד אֹֽיְבֵי⁠הֶ֑ם וְ⁠הָי֥וּ לְ⁠בַ֛ז וְ⁠לִ⁠מְשִׁסָּ֖ה לְ⁠כָל־אֹיְבֵי⁠הֶֽם׃","wĕ⁠nátaşĕ̌ţi̇֗y ʼé֚ţ şĕ̌ʼéri֣yţ naẖàláţi֔⁠y ẇ⁠nĕţaţi֖̇y⁠m bĕ̇⁠ya֣d ʼòֽyĕbéy⁠he֑m wĕ⁠háy֥ẇ lĕ⁠ba֛z wĕ⁠li⁠mĕşǐsá֖̇h lĕ⁠kál-ʼòyĕbéy⁠heֽm׃"],[21,15,"יַ֗עַן אֲשֶׁ֨ר עָשׂ֤וּ אֶת־הָ⁠רַע֙ בְּ⁠עֵינַ֔⁠י וַ⁠יִּהְי֥וּ מַכְעִסִ֖ים אֹתִ֑⁠י מִן־הַ⁠יּ֗וֹם אֲשֶׁ֨ר יָצְא֤וּ אֲבוֹתָ⁠ם֙ מִ⁠מִּצְרַ֔יִם וְ⁠עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ya֗ʻan ʼàşě֨r ʻáş֤̂ẇ ʼeţ-há⁠raʻ֙ bĕ̇⁠ʻéyna֔⁠y wa⁠yi̇hĕy֥ẇ makĕʻisi֖ym ʼòţi֑⁠y min-ha⁠ẏ֗wòm ʼàşě֨r yáẕĕʼ֤ẇ ʼàbwòţá⁠m֙ mi⁠mi̇ẕĕra֔yim wĕ⁠ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[21,16,"וְ⁠גַם֩ דָּ֨ם נָקִ֜י שָׁפַ֤ךְ מְנַשֶּׁה֙ הַרְבֵּ֣ה מְאֹ֔ד עַ֛ד אֲשֶׁר־מִלֵּ֥א אֶת־יְרוּשָׁלִַ֖ם פֶּ֣ה לָ⁠פֶ֑ה לְ⁠בַ֤ד מֵֽ⁠חַטָּאת⁠וֹ֙ אֲשֶׁ֣ר הֶחֱטִ֣יא אֶת־יְהוּדָ֔ה לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃","wĕ⁠gam֩ dá̇֨m náqi֜y şá̌pa֤kĕ mĕnaşė̌h֙ harĕbé֣̇h mĕʼò֔d ʻa֛d ʼàşěr-milé֥̇ʼ ʼeţ-yĕrẇşá̌lia֖m pė֣h lá⁠pe֑h lĕ⁠ba֤d méֽ⁠ẖatá̇ʼţ⁠wò֙ ʼàşě֣r heẖèti֣yʼ ʼeţ-yĕhẇdá֔h la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[21,17,"וְ⁠יֶ֨תֶר דִּבְרֵ֤י מְנַשֶּׁה֙ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֔ה וְ⁠חַטָּאת֖⁠וֹ אֲשֶׁ֣ר חָטָ֑א הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֨ţer di̇bĕré֤y mĕnaşė̌h֙ wĕ⁠kál-ʼàşě֣r ʻáşá̂֔h wĕ⁠ẖatá̇ʼţ֖⁠wò ʼàşě֣r ẖátá֑ʼ hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[21,18,"וַ⁠יִּשְׁכַּ֤ב מְנַשֶּׁה֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֥ר בְּ⁠גַן־בֵּית֖⁠וֹ בְּ⁠גַן־עֻזָּ֑א וַ⁠יִּמְלֹ֛ךְ אָמ֥וֹן בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b mĕnaşė̌h֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֥r bĕ̇⁠gan-bé̇yţ֖⁠wò bĕ̇⁠gan-ʻuzá֑̇ʼ wa⁠yi̇mĕlò֛kĕ ʼám֥wòn bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[21,19,"בֶּן־עֶשְׂרִ֨ים וּ⁠שְׁתַּ֤יִם שָׁנָה֙ אָמ֣וֹן בְּ⁠מָלְכ֔⁠וֹ וּ⁠שְׁתַּ֣יִם שָׁנִ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ מְשֻׁלֶּ֥מֶת בַּת־חָר֖וּץ מִן־יָטְבָֽה׃","bėn-ʻeşĕ̂ri֨ym ẇ⁠şĕ̌ţȧ֤yim şá̌náh֙ ʼám֣wòn bĕ̇⁠málĕk֔⁠wò ẇ⁠şĕ̌ţȧ֣yim şá̌ni֔ym mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò mĕşǔlė֥meţ bȧţ-ẖár֖ẇẕ min-yátĕbáֽh׃"],[21,20,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כַּ⁠אֲשֶׁ֥ר עָשָׂ֖ה מְנַשֶּׁ֥ה אָבִֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kȧ⁠ʼàşě֥r ʻáşá֖̂h mĕnaşė֥̌h ʼábiֽy⁠w׃"],[21,21,"וַ⁠יֵּ֕לֶךְ בְּ⁠כָל־הַ⁠דֶּ֖רֶךְ אֲשֶׁר־הָלַ֣ךְ אָבִ֑י⁠ו וַֽ⁠יַּעֲבֹ֗ד אֶת־הַ⁠גִּלֻּלִים֙ אֲשֶׁ֣ר עָבַ֣ד אָבִ֔י⁠ו וַ⁠יִּשְׁתַּ֖חוּ לָ⁠הֶֽם׃","wa⁠yé̇֕lekĕ bĕ̇⁠kál-ha⁠dė֖rekĕ ʼàşěr-hála֣kĕ ʼábi֑y⁠w waֽ⁠yȧʻàbò֗d ʼeţ-ha⁠gi̇lu̇liym֙ ʼàşě֣r ʻába֣d ʼábi֔y⁠w wa⁠yi̇şĕ̌ţȧ֖ẖẇ lá⁠heֽm׃"],[21,22,"וַ⁠יַּעֲזֹ֕ב אֶת־יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתָ֑י⁠ו וְ⁠לֹ֥א הָלַ֖ךְ בְּ⁠דֶ֥רֶךְ יְהוָֽה׃","wa⁠yȧʻàzò֕b ʼeţ-yĕhwá֖h ʼèlòhé֣y ʼàbòţá֑y⁠w wĕ⁠lò֥ʼ hála֖kĕ bĕ̇⁠de֥rekĕ yĕhwáֽh׃"],[21,23,"וַ⁠יִּקְשְׁר֥וּ עַבְדֵֽי־אָמ֖וֹן עָלָ֑י⁠ו וַ⁠יָּמִ֥יתוּ אֶת־הַ⁠מֶּ֖לֶךְ בְּ⁠בֵיתֽ⁠וֹ׃","wa⁠yi̇qĕşĕ̌r֥ẇ ʻabĕdéֽy-ʼám֖wòn ʻálá֑y⁠w wa⁠yá̇mi֥yţẇ ʼeţ-ha⁠mė֖lekĕ bĕ̇⁠béyţֽ⁠wò׃"],[21,24,"וַ⁠יַּךְ֙ עַם־הָ⁠אָ֔רֶץ אֵ֥ת כָּל־הַ⁠קֹּשְׁרִ֖ים עַל־הַ⁠מֶּ֣לֶךְ אָמ֑וֹן וַ⁠יַּמְלִ֧יכוּ עַם־הָ⁠אָ֛רֶץ אֶת־יֹאשִׁיָּ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yȧkĕ֙ ʻam-há⁠ʼá֔reẕ ʼé֥ţ ká̇l-ha⁠qò̇şĕ̌ri֖ym ʻal-ha⁠mė֣lekĕ ʼám֑wòn wa⁠yȧmĕli֧ykẇ ʻam-há⁠ʼá֛reẕ ʼeţ-yòʼşǐyá֥̇hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[21,25,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י אָמ֖וֹן אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y ʼám֖wòn ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[21,26,"וַ⁠יִּקְבְֹּ֥ר אֹת֛⁠וֹ בִּ⁠קְבֻרָת֖⁠וֹ בְּ⁠גַן־עֻזָּ֑א וַ⁠יִּמְלֹ֛ךְ יֹאשִׁיָּ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇qĕbĕò֥̇r ʼòţ֛⁠wò bi̇⁠qĕburáţ֖⁠wò bĕ̇⁠gan-ʻuzá֑̇ʼ wa⁠yi̇mĕlò֛kĕ yòʼşǐyá֥̇hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[22,1,"בֶּן־שְׁמֹנֶ֤ה שָׁנָה֙ יֹאשִׁיָּ֣הוּ בְ⁠מָלְכ֔⁠וֹ וּ⁠שְׁלֹשִׁ֤ים וְ⁠אַחַת֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יְדִידָ֥ה בַת־עֲדָ֖יָה מִ⁠בָּצְקַֽת׃","bėn-şĕ̌mòne֤h şá̌náh֙ yòʼşǐyá֣̇hẇ bĕ⁠málĕk֔⁠wò ẇ⁠şĕ̌lòşǐ֤ym wĕ⁠ʼaẖaţ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò yĕdiydá֥h baţ-ʻàdá֖yáh mi⁠bá̇ẕĕqaֽţ׃"],[22,2,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יֵּ֗לֶךְ בְּ⁠כָל־דֶּ֨רֶךְ֙ דָּוִ֣ד אָבִ֔י⁠ו וְ⁠לֹא־סָ֖ר יָמִ֥ין וּ⁠שְׂמֹֽאול׃פ","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yé̇֗lekĕ bĕ̇⁠kál-dė֨rekĕ֙ dá̇wi֣d ʼábi֔y⁠w wĕ⁠lòʼ-sá֖r yámi֥yn ẇ⁠şĕ̂mòֽʼwl׃p"],[22,3,"וַ⁠יְהִ֗י בִּ⁠שְׁמֹנֶ֤ה עֶשְׂרֵה֙ שָׁנָ֔ה לַ⁠מֶּ֖לֶךְ יֹאשִׁיָּ֑הוּ שָׁלַ֣ח הַ֠⁠מֶּלֶךְ אֶת־שָׁפָ֨ן בֶּן־אֲצַלְיָ֤הוּ בֶן־מְשֻׁלָּם֙ הַ⁠סֹּפֵ֔ר בֵּ֥ית יְהוָ֖ה לֵ⁠אמֹֽר׃","wa⁠yĕhi֗y bi̇⁠şĕ̌mòne֤h ʻeşĕ̂réh֙ şá̌ná֔h la⁠mė֖lekĕ yòʼşǐyá֑̇hẇ şá̌la֣ẖ ha֠⁠mėlekĕ ʼeţ-şá̌pá֨n bėn-ʼàẕalĕyá֤hẇ ben-mĕşǔlá̇m֙ ha⁠sò̇pé֔r bé֥̇yţ yĕhwá֖h lé⁠ʼmòֽr׃"],[22,4,"עֲלֵ֗ה אֶל־חִלְקִיָּ֨הוּ֙ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל וְ⁠יַתֵּ֣ם אֶת־הַ⁠כֶּ֔סֶף הַ⁠מּוּבָ֖א בֵּ֣ית יְהוָ֑ה אֲשֶׁ֥ר אָסְפ֛וּ שֹׁמְרֵ֥י הַ⁠סַּ֖ף מֵ⁠אֵ֥ת הָ⁠עָֽם׃","ʻàlé֗h ʼel-ẖilĕqiyá̇֨hẇ֙ ha⁠kò̇hé֣n ha⁠gá̇d֔wòl wĕ⁠yaţé֣̇m ʼeţ-ha⁠kė֔sep ha⁠ṁẇbá֖ʼ bé֣̇yţ yĕhwá֑h ʼàşě֥r ʼásĕp֛ẇ şò̌mĕré֥y ha⁠sȧ֖p mé⁠ʼé֥ţ há⁠ʻáֽm׃"],[22,5,"ו⁠יתנ⁠ה עַל־יַד֙ עֹשֵׂ֣י הַ⁠מְּלָאכָ֔ה הַ⁠מֻּפְקָדִ֖ים ב⁠בית יְהוָ֑ה וְ⁠יִתְּנ֣וּ אֹת֗⁠וֹ לְ⁠עֹשֵׂ֤י הַ⁠מְּלָאכָה֙ אֲשֶׁר֙ בְּ⁠בֵ֣ית יְהוָ֔ה לְ⁠חַזֵּ֖ק בֶּ֥דֶק הַ⁠בָּֽיִת׃","w⁠yţn⁠h ʻal-yad֙ ʻòşé֣̂y ha⁠mĕ̇láʼká֔h ha⁠mu̇pĕqádi֖ym b⁠byţ yĕhwá֑h wĕ⁠yiţĕ̇n֣ẇ ʼòţ֗⁠wò lĕ⁠ʻòşé֤̂y ha⁠mĕ̇láʼkáh֙ ʼàşěr֙ bĕ̇⁠bé֣yţ yĕhwá֔h lĕ⁠ẖazé֖̇q bė֥deq ha⁠báֽ̇yiţ׃"],[22,6,"לֶ⁠חָ֣רָשִׁ֔ים וְ⁠לַ⁠בֹּנִ֖ים וְ⁠לַ⁠גֹּֽדְרִ֑ים וְ⁠לִ⁠קְנ֤וֹת עֵצִים֙ וְ⁠אַבְנֵ֣י מַחְצֵ֔ב לְ⁠חַזֵּ֖ק אֶת־הַ⁠בָּֽיִת׃","le⁠ẖá֣ráşǐ֔ym wĕ⁠la⁠bò̇ni֖ym wĕ⁠la⁠gòֽ̇dĕri֑ym wĕ⁠li⁠qĕn֤wòţ ʻéẕiym֙ wĕ⁠ʼabĕné֣y maẖĕẕé֔b lĕ⁠ẖazé֖̇q ʼeţ-ha⁠báֽ̇yiţ׃"],[22,7,"אַ֚ךְ לֹא־יֵחָשֵׁ֣ב אִתָּ֔⁠ם הַ⁠כֶּ֖סֶף הַ⁠נִּתָּ֣ן עַל־יָדָ֑⁠ם כִּ֥י בֶ⁠אֱמוּנָ֖ה הֵ֥ם עֹשִֽׂים׃","ʼa֚kĕ lòʼ-yéẖáşé֣̌b ʼiţá̇֔⁠m ha⁠kė֖sep ha⁠ni̇ţá֣̇n ʻal-yádá֑⁠m ki֥̇y be⁠ʼèmẇná֖h hé֥m ʻòşîֽym׃"],[22,8,"וַ֠⁠יֹּאמֶר חִלְקִיָּ֜הוּ הַ⁠כֹּהֵ֤ן הַ⁠גָּדוֹל֙ עַל־שָׁפָ֣ן הַ⁠סֹּפֵ֔ר סֵ֧פֶר הַ⁠תּוֹרָ֛ה מָצָ֖אתִי בְּ⁠בֵ֣ית יְהוָ֑ה וַ⁠יִּתֵּ֨ן חִלְקִיָּ֧ה אֶת־הַ⁠סֵּ֛פֶר אֶל־שָׁפָ֖ן וַ⁠יִּקְרָאֵֽ⁠הוּ׃","wa֠⁠yò̇ʼmer ẖilĕqiyá̇֜hẇ ha⁠kò̇hé֤n ha⁠gá̇dwòl֙ ʻal-şá̌pá֣n ha⁠sò̇pé֔r sé֧per ha⁠ţ̇wòrá֛h máẕá֖ʼţiy bĕ̇⁠bé֣yţ yĕhwá֑h wa⁠yi̇ţé̇֨n ẖilĕqiyá֧̇h ʼeţ-ha⁠sé֛̇per ʼel-şá̌pá֖n wa⁠yi̇qĕráʼéֽ⁠hẇ׃"],[22,9,"וַ⁠יָּבֹ֞א שָׁפָ֤ן הַ⁠סֹּפֵר֙ אֶל־הַ⁠מֶּ֔לֶךְ וַ⁠יָּ֥שֶׁב אֶת־הַ⁠מֶּ֖לֶךְ דָּבָ֑ר וַ⁠יֹּ֗אמֶר הִתִּ֤יכוּ עֲבָדֶ֨י⁠ךָ֙ אֶת־הַ⁠כֶּ֨סֶף֙ הַ⁠נִּמְצָ֣א בַ⁠בַּ֔יִת וַֽ⁠יִּתְּנֻ֗⁠הוּ עַל־יַד֙ עֹשֵׂ֣י הַ⁠מְּלָאכָ֔ה הַ⁠מֻּפְקָדִ֖ים בֵּ֥ית יְהוָֽה׃","wa⁠yá̇bò֞ʼ şá̌pá֤n ha⁠sò̇pér֙ ʼel-ha⁠mė֔lekĕ wa⁠yá֥̇şěb ʼeţ-ha⁠mė֖lekĕ dá̇bá֑r wa⁠yò̇֗ʼmer hiţi֤̇ykẇ ʻàbáde֨y⁠ká֙ ʼeţ-ha⁠kė֨sep֙ ha⁠ni̇mĕẕá֣ʼ ba⁠bȧ֔yiţ waֽ⁠yi̇ţĕ̇nu֗⁠hẇ ʻal-yad֙ ʻòşé֣̂y ha⁠mĕ̇láʼká֔h ha⁠mu̇pĕqádi֖ym bé֥̇yţ yĕhwáֽh׃"],[22,10,"וַ⁠יַּגֵּ֞ד שָׁפָ֤ן הַ⁠סֹּפֵר֙ לַ⁠מֶּ֣לֶךְ לֵ⁠אמֹ֔ר סֵ֚פֶר נָ֣תַן לִ֔⁠י חִלְקִיָּ֖ה הַ⁠כֹּהֵ֑ן וַ⁠יִּקְרָאֵ֥⁠הוּ שָׁפָ֖ן לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yȧgé̇֞d şá̌pá֤n ha⁠sò̇pér֙ la⁠mė֣lekĕ lé⁠ʼmò֔r sé֚per ná֣ţan li֔⁠y ẖilĕqiyá֖̇h ha⁠kò̇hé֑n wa⁠yi̇qĕráʼé֥⁠hẇ şá̌pá֖n li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[22,11,"וַֽ⁠יְהִי֙ כִּ⁠שְׁמֹ֣עַ הַ⁠מֶּ֔לֶךְ אֶת־דִּבְרֵ֖י סֵ֣פֶר הַ⁠תּוֹרָ֑ה וַ⁠יִּקְרַ֖ע אֶת־בְּגָדָֽי⁠ו׃","waֽ⁠yĕhiy֙ ki̇⁠şĕ̌mò֣ʻa ha⁠mė֔lekĕ ʼeţ-di̇bĕré֖y sé֣per ha⁠ţ̇wòrá֑h wa⁠yi̇qĕra֖ʻ ʼeţ-bĕ̇gádáֽy⁠w׃"],[22,12,"וַ⁠יְצַ֣ו הַ⁠מֶּ֡לֶךְ אֶת־חִלְקִיָּ֣ה הַ⁠כֹּהֵ֡ן וְ⁠אֶת־אֲחִיקָ֣ם בֶּן־שָׁ֠פָן וְ⁠אֶת־עַכְבּ֨וֹר בֶּן־מִיכָיָ֜ה וְ⁠אֵ֣ת ׀ שָׁפָ֣ן הַ⁠סֹּפֵ֗ר וְ⁠אֵ֛ת עֲשָׂיָ֥ה עֶֽבֶד־הַ⁠מֶּ֖לֶךְ לֵ⁠אמֹֽר׃","wa⁠yĕẕa֣w ha⁠mė֡lekĕ ʼeţ-ẖilĕqiyá֣̇h ha⁠kò̇hé֡n wĕ⁠ʼeţ-ʼàẖiyqá֣m bėn-şá̌֠pán wĕ⁠ʼeţ-ʻakĕḃ֨wòr bėn-miykáyá֜h wĕ⁠ʼé֣ţ ׀ şá̌pá֣n ha⁠sò̇pé֗r wĕ⁠ʼé֛ţ ʻàşá̂yá֥h ʻeֽbed-ha⁠mė֖lekĕ lé⁠ʼmòֽr׃"],[22,13,"לְכוּ֩ דִרְשׁ֨וּ אֶת־יְהוָ֜ה בַּעֲדִ֣⁠י וּ⁠בְעַד־הָ⁠עָ֗ם וּ⁠בְעַד֙ כָּל־יְהוּדָ֔ה עַל־דִּבְרֵ֛י הַ⁠סֵּ֥פֶר הַ⁠נִּמְצָ֖א הַ⁠זֶּ֑ה כִּֽי־גְדוֹלָ֞ה חֲמַ֣ת יְהוָ֗ה אֲשֶׁר־הִיא֙ נִצְּתָ֣ה בָ֔⁠נוּ עַל֩ אֲשֶׁ֨ר לֹֽא־שָׁמְע֜וּ אֲבֹתֵ֗י⁠נוּ עַל־דִּבְרֵי֙ הַ⁠סֵּ֣פֶר הַ⁠זֶּ֔ה לַ⁠עֲשׂ֖וֹת כְּ⁠כָל־הַ⁠כָּת֥וּב עָלֵֽי⁠נוּ׃","lĕkẇ֩ dirĕş̌֨ẇ ʼeţ-yĕhwá֜h bȧʻàdi֣⁠y ẇ⁠bĕʻad-há⁠ʻá֗m ẇ⁠bĕʻad֙ ká̇l-yĕhẇdá֔h ʻal-di̇bĕré֛y ha⁠sé֥̇per ha⁠ni̇mĕẕá֖ʼ ha⁠zė֑h kiֽ̇y-gĕdwòlá֞h ẖàma֣ţ yĕhwá֗h ʼàşěr-hiyʼ֙ niẕĕ̇ţá֣h bá֔⁠nẇ ʻal֩ ʼàşě֨r lòֽʼ-şá̌mĕʻ֜ẇ ʼàbòţé֗y⁠nẇ ʻal-di̇bĕréy֙ ha⁠sé֣̇per ha⁠zė֔h la⁠ʻàş֖̂wòţ kĕ̇⁠kál-ha⁠ká̇ţ֥ẇb ʻáléֽy⁠nẇ׃"],[22,14,"וַ⁠יֵּ֣לֶךְ חִלְקִיָּ֣הוּ הַ֠⁠כֹּהֵן וַ⁠אֲחִיקָ֨ם וְ⁠עַכְבּ֜וֹר וְ⁠שָׁפָ֣ן וַ⁠עֲשָׂיָ֗ה אֶל־חֻלְדָּ֨ה הַ⁠נְּבִיאָ֜ה אֵ֣שֶׁת ׀ שַׁלֻּ֣ם בֶּן־תִּקְוָ֗ה בֶּן־חַרְחַס֙ שֹׁמֵ֣ר הַ⁠בְּגָדִ֔ים וְ⁠הִ֛יא יֹשֶׁ֥בֶת בִּ⁠ירוּשָׁלִַ֖ם בַּ⁠מִּשְׁנֶ֑ה וַֽ⁠יְדַבְּר֖וּ אֵלֶֽי⁠הָ׃","wa⁠yé֣̇lekĕ ẖilĕqiyá֣̇hẇ ha֠⁠kò̇hén wa⁠ʼàẖiyqá֨m wĕ⁠ʻakĕḃ֜wòr wĕ⁠şá̌pá֣n wa⁠ʻàşá̂yá֗h ʼel-ẖulĕdá̇֨h ha⁠nĕ̇biyʼá֜h ʼé֣şěţ ׀ şǎlu֣̇m bėn-ţi̇qĕwá֗h bėn-ẖarĕẖas֙ şò̌mé֣r ha⁠bĕ̇gádi֔ym wĕ⁠hi֛yʼ yòşě֥beţ bi̇⁠yrẇşá̌lia֖m bȧ⁠mi̇şĕ̌ne֑h waֽ⁠yĕdabĕ̇r֖ẇ ʼéleֽy⁠há׃"],[22,15,"וַ⁠תֹּ֣אמֶר אֲלֵי⁠הֶ֔ם כֹּֽה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אִמְר֣וּ לָ⁠אִ֔ישׁ אֲשֶׁר־שָׁלַ֥ח אֶתְ⁠כֶ֖ם אֵלָֽ⁠י׃","wa⁠ţò֣̇ʼmer ʼàléy⁠he֔m kòֽ̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʼimĕr֣ẇ lá⁠ʼi֔yş̌ ʼàşěr-şá̌la֥ẖ ʼeţĕ⁠ke֖m ʼéláֽ⁠y׃"],[22,16,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֨י מֵבִ֥יא רָעָ֛ה אֶל־הַ⁠מָּק֥וֹם הַ⁠זֶּ֖ה וְ⁠עַל־יֹֽשְׁבָ֑י⁠ו אֵ֚ת כָּל־דִּבְרֵ֣י הַ⁠סֵּ֔פֶר אֲשֶׁ֥ר קָרָ֖א מֶ֥לֶךְ יְהוּדָֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֨y mébi֥yʼ ráʻá֛h ʼel-ha⁠má̇q֥wòm ha⁠zė֖h wĕ⁠ʻal-yòֽşĕ̌bá֑y⁠w ʼé֚ţ ká̇l-di̇bĕré֣y ha⁠sé̇֔per ʼàşě֥r qárá֖ʼ me֥lekĕ yĕhẇdáֽh׃"],[22,17,"תַּ֣חַת ׀ אֲשֶׁ֣ר עֲזָב֗וּ⁠נִי וַֽ⁠יְקַטְּרוּ֙ לֵ⁠אלֹהִ֣ים אֲחֵרִ֔ים לְמַ֨עַן֙ הַכְעִיסֵ֔⁠נִי בְּ⁠כֹ֖ל מַעֲשֵׂ֣ה יְדֵי⁠הֶ֑ם וְ⁠נִצְּתָ֧ה חֲמָתִ֛⁠י בַּ⁠מָּק֥וֹם הַ⁠זֶּ֖ה וְ⁠לֹ֥א תִכְבֶּֽה׃","ţȧ֣ẖaţ ׀ ʼàşě֣r ʻàzáb֗ẇ⁠niy waֽ⁠yĕqatĕ̇rẇ֙ lé⁠ʼlòhi֣ym ʼàẖéri֔ym lĕma֨ʻan֙ hakĕʻiysé֔⁠niy bĕ̇⁠kò֖l maʻàşé֣̂h yĕdéy⁠he֑m wĕ⁠niẕĕ̇ţá֧h ẖàmáţi֛⁠y bȧ⁠má̇q֥wòm ha⁠zė֖h wĕ⁠lò֥ʼ ţikĕbėֽh׃"],[22,18,"וְ⁠אֶל־מֶ֣לֶךְ יְהוּדָ֗ה הַ⁠שֹּׁלֵ֤חַ אֶתְ⁠כֶם֙ לִ⁠דְרֹ֣שׁ אֶת־יְהוָ֔ה כֹּ֥ה תֹאמְר֖וּ אֵלָ֑י⁠ו כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הַ⁠דְּבָרִ֖ים אֲשֶׁ֥ר שָׁמָֽעְתָּ׃","wĕ⁠ʼel-me֣lekĕ yĕhẇdá֗h ha⁠şò̇̌lé֤ẖa ʼeţĕ⁠kem֙ li⁠dĕrò֣ş̌ ʼeţ-yĕhwá֔h kò֥̇h ţòʼmĕr֖ẇ ʼélá֑y⁠w kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ha⁠dĕ̇bári֖ym ʼàşě֥r şá̌máֽʻĕţá̇׃"],[22,19,"יַ֠עַן רַךְ־לְבָ֨בְ⁠ךָ֜ וַ⁠תִּכָּנַ֣ע ׀ מִ⁠פְּנֵ֣י יְהוָ֗ה בְּֽ⁠שָׁמְעֲ⁠ךָ֡ אֲשֶׁ֣ר דִּבַּרְתִּי֩ עַל־הַ⁠מָּק֨וֹם הַ⁠זֶּ֜ה וְ⁠עַל־יֹשְׁבָ֗י⁠ו לִ⁠הְי֤וֹת לְ⁠שַׁמָּה֙ וְ⁠לִ⁠קְלָלָ֔ה וַ⁠תִּקְרַע֙ אֶת־בְּגָדֶ֔י⁠ךָ וַ⁠תִּבְכֶּ֖ה לְ⁠פָנָ֑⁠י וְ⁠גַ֧ם אָנֹכִ֛י שָׁמַ֖עְתִּי נְאֻם־יְהוָֽה׃","ya֠ʻan rakĕ-lĕbá֨bĕ⁠ká֜ wa⁠ţi̇ká̇na֣ʻ ׀ mi⁠pĕ̇né֣y yĕhwá֗h bĕֽ̇⁠şá̌mĕʻà⁠ká֡ ʼàşě֣r di̇bȧrĕţi̇y֩ ʻal-ha⁠má̇q֨wòm ha⁠zė֜h wĕ⁠ʻal-yòşĕ̌bá֗y⁠w li⁠hĕy֤wòţ lĕ⁠şǎmá̇h֙ wĕ⁠li⁠qĕlálá֔h wa⁠ţi̇qĕraʻ֙ ʼeţ-bĕ̇gáde֔y⁠ká wa⁠ţi̇bĕkė֖h lĕ⁠páná֑⁠y wĕ⁠ga֧m ʼánòki֛y şá̌ma֖ʻĕţi̇y nĕʼum-yĕhwáֽh׃"],[22,20,"לָ⁠כֵן֩ הִנְ⁠נִ֨י אֹֽסִפְ⁠ךָ֜ עַל־אֲבֹתֶ֗י⁠ךָ וְ⁠נֶאֱסַפְתָּ֣ אֶל־קִבְרֹתֶי⁠ךָ֮ בְּ⁠שָׁלוֹם֒ וְ⁠לֹא־תִרְאֶ֣ינָה עֵינֶ֔י⁠ךָ בְּ⁠כֹל֙ הָֽ⁠רָעָ֔ה אֲשֶׁר־אֲנִ֥י מֵבִ֖יא עַל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וַ⁠יָּשִׁ֥יבוּ אֶת־הַ⁠מֶּ֖לֶךְ דָּבָֽר׃","lá⁠kén֩ hinĕ⁠ni֨y ʼòֽsipĕ⁠ká֜ ʻal-ʼàbòţe֗y⁠ká wĕ⁠neʼèsapĕţá֣̇ ʼel-qibĕròţey⁠ká֮ bĕ̇⁠şá̌lwòm֒ wĕ⁠lòʼ-ţirĕʼe֣ynáh ʻéyne֔y⁠ká bĕ̇⁠kòl֙ háֽ⁠ráʻá֔h ʼàşěr-ʼàni֥y mébi֖yʼ ʻal-ha⁠má̇q֣wòm ha⁠zė֑h wa⁠yá̇şǐ֥ybẇ ʼeţ-ha⁠mė֖lekĕ dá̇báֽr׃"],[23,1,"וַ⁠יִּשְׁלַ֖ח הַ⁠מֶּ֑לֶךְ וַ⁠יַּאַסְפ֣וּ אֵלָ֔י⁠ו כָּל־זִקְנֵ֥י יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃","wa⁠yi̇şĕ̌la֖ẖ ha⁠mė֑lekĕ wa⁠yȧʼasĕp֣ẇ ʼélá֔y⁠w ká̇l-ziqĕné֥y yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃"],[23,2,"וַ⁠יַּ֣עַל הַ⁠מֶּ֣לֶךְ בֵּית־יְהוָ֡ה וְ⁠כָל־אִ֣ישׁ יְהוּדָה֩ וְ⁠כָל־יֹשְׁבֵ֨י יְרוּשָׁלִַ֜ם אִתּ֗⁠וֹ וְ⁠הַ⁠כֹּֽהֲנִים֙ וְ⁠הַ⁠נְּבִיאִ֔ים וְ⁠כָל־הָ⁠עָ֖ם לְ⁠מִ⁠קָּטֹ֣ן וְ⁠עַד־גָּד֑וֹל וַ⁠יִּקְרָ֣א בְ⁠אָזְנֵי⁠הֶ֗ם אֶת־כָּל־דִּבְרֵי֙ סֵ֣פֶר הַ⁠בְּרִ֔ית הַ⁠נִּמְצָ֖א בְּ⁠בֵ֥ית יְהוָֽה׃","wa⁠yȧ֣ʻal ha⁠mė֣lekĕ bé̇yţ-yĕhwá֡h wĕ⁠kál-ʼi֣yş̌ yĕhẇdáh֩ wĕ⁠kál-yòşĕ̌bé֨y yĕrẇşá̌lia֜m ʼiţ̇֗⁠wò wĕ⁠ha⁠kòֽ̇hàniym֙ wĕ⁠ha⁠nĕ̇biyʼi֔ym wĕ⁠kál-há⁠ʻá֖m lĕ⁠mi⁠qá̇tò֣n wĕ⁠ʻad-gá̇d֑wòl wa⁠yi̇qĕrá֣ʼ bĕ⁠ʼázĕnéy⁠he֗m ʼeţ-ká̇l-di̇bĕréy֙ sé֣per ha⁠bĕ̇ri֔yţ ha⁠ni̇mĕẕá֖ʼ bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[23,3,"וַ⁠יַּעֲמֹ֣ד הַ֠⁠מֶּלֶךְ עַֽל־הָ֨⁠עַמּ֜וּד וַ⁠יִּכְרֹ֥ת אֶֽת־הַ⁠בְּרִ֣ית ׀ לִ⁠פְנֵ֣י יְהוָ֗ה לָ⁠לֶ֜כֶת אַחַ֤ר יְהוָה֙ וְ⁠לִ⁠שְׁמֹ֨ר מִצְוֺתָ֜י⁠ו וְ⁠אֶת־עֵדְוֺתָ֤י⁠ו וְ⁠אֶת־חֻקֹּתָי⁠ו֙ בְּ⁠כָל־לֵ֣ב וּ⁠בְ⁠כָל־נֶ֔פֶשׁ לְ⁠הָקִ֗ים אֶת־דִּבְרֵי֙ הַ⁠בְּרִ֣ית הַ⁠זֹּ֔את הַ⁠כְּתֻבִ֖ים עַל־הַ⁠סֵּ֣פֶר הַ⁠זֶּ֑ה וַ⁠יַּעֲמֹ֥ד כָּל־הָ⁠עָ֖ם בַּ⁠בְּרִֽית׃","wa⁠yȧʻàmò֣d ha֠⁠mėlekĕ ʻaֽl-há֨⁠ʻaṁ֜ẇd wa⁠yi̇kĕrò֥ţ ʼeֽţ-ha⁠bĕ̇ri֣yţ ׀ li⁠pĕné֣y yĕhwá֗h lá⁠le֜keţ ʼaẖa֤r yĕhwáh֙ wĕ⁠li⁠şĕ̌mò֨r miẕĕwֺţá֜y⁠w wĕ⁠ʼeţ-ʻédĕwֺţá֤y⁠w wĕ⁠ʼeţ-ẖuqò̇ţáy⁠w֙ bĕ̇⁠kál-lé֣b ẇ⁠bĕ⁠kál-ne֔peş̌ lĕ⁠háqi֗ym ʼeţ-di̇bĕréy֙ ha⁠bĕ̇ri֣yţ ha⁠zò̇֔ʼţ ha⁠kĕ̇ţubi֖ym ʻal-ha⁠sé֣̇per ha⁠zė֑h wa⁠yȧʻàmò֥d ká̇l-há⁠ʻá֖m bȧ⁠bĕ̇riֽyţ׃"],[23,4,"וַ⁠יְצַ֣ו הַ⁠מֶּ֡לֶךְ אֶת־חִלְקִיָּהוּ֩ הַ⁠כֹּהֵ֨ן הַ⁠גָּד֜וֹל וְ⁠אֶת־כֹּהֲנֵ֣י הַ⁠מִּשְׁנֶה֮ וְ⁠אֶת־שֹׁמְרֵ֣י הַ⁠סַּף֒ לְ⁠הוֹצִיא֙ מֵ⁠הֵיכַ֣ל יְהוָ֔ה אֵ֣ת כָּל־הַ⁠כֵּלִ֗ים הָֽ⁠עֲשׂוּיִם֙ לַ⁠בַּ֣עַל וְ⁠לָֽ⁠אֲשֵׁרָ֔ה וּ⁠לְ⁠כֹ֖ל צְבָ֣א הַ⁠שָּׁמָ֑יִם וַֽ⁠יִּשְׂרְפֵ֞⁠ם מִ⁠ח֤וּץ לִ⁠ירוּשָׁלִַ֨ם֙ בְּ⁠שַׁדְמ֣וֹת קִדְר֔וֹן וְ⁠נָשָׂ֥א אֶת־עֲפָרָ֖⁠ם בֵּֽית־אֵֽל׃","wa⁠yĕẕa֣w ha⁠mė֡lekĕ ʼeţ-ẖilĕqiyá̇hẇ֩ ha⁠kò̇hé֨n ha⁠gá̇d֜wòl wĕ⁠ʼeţ-kò̇hàné֣y ha⁠mi̇şĕ̌neh֮ wĕ⁠ʼeţ-şò̌mĕré֣y ha⁠sȧp֒ lĕ⁠hwòẕiyʼ֙ mé⁠héyka֣l yĕhwá֔h ʼé֣ţ ká̇l-ha⁠ké̇li֗ym háֽ⁠ʻàş̂ẇyim֙ la⁠bȧ֣ʻal wĕ⁠láֽ⁠ʼàşé̌rá֔h ẇ⁠lĕ⁠kò֖l ẕĕbá֣ʼ ha⁠şá̇̌má֑yim waֽ⁠yi̇şĕ̂rĕpé֞⁠m mi⁠ẖ֤ẇẕ li⁠yrẇşá̌lia֨m֙ bĕ̇⁠şǎdĕm֣wòţ qidĕr֔wòn wĕ⁠náşá֥̂ʼ ʼeţ-ʻàpárá֖⁠m béֽ̇yţ-ʼéֽl׃"],[23,5,"וְ⁠הִשְׁבִּ֣ית אֶת־הַ⁠כְּמָרִ֗ים אֲשֶׁ֤ר נָֽתְנוּ֙ מַלְכֵ֣י יְהוּדָ֔ה וַ⁠יְקַטֵּ֤ר בַּ⁠בָּמוֹת֙ בְּ⁠עָרֵ֣י יְהוּדָ֔ה וּ⁠מְסִבֵּ֖י יְרוּשָׁלִָ֑ם וְ⁠אֶת־הַֽ⁠מְקַטְּרִ֣ים לַ⁠בַּ֗עַל לַ⁠שֶּׁ֤מֶשׁ וְ⁠לַ⁠יָּרֵ֨חַ֙ וְ⁠לַ⁠מַּזָּל֔וֹת וּ⁠לְ⁠כֹ֖ל צְבָ֥א הַ⁠שָּׁמָֽיִם׃","wĕ⁠hişĕ̌bi֣̇yţ ʼeţ-ha⁠kĕ̇mári֗ym ʼàşě֤r náֽţĕnẇ֙ malĕké֣y yĕhẇdá֔h wa⁠yĕqaté֤̇r bȧ⁠bá̇mwòţ֙ bĕ̇⁠ʻáré֣y yĕhẇdá֔h ẇ⁠mĕsibé֖̇y yĕrẇşá̌liá֑m wĕ⁠ʼeţ-haֽ⁠mĕqatĕ̇ri֣ym la⁠bȧ֗ʻal la⁠şė֤̌meş̌ wĕ⁠la⁠yá̇ré֨ẖa֙ wĕ⁠la⁠mȧzá̇l֔wòţ ẇ⁠lĕ⁠kò֖l ẕĕbá֥ʼ ha⁠şá̇̌máֽyim׃"],[23,6,"וַ⁠יֹּצֵ֣א אֶת־הָ⁠אֲשֵׁרָה֩ מִ⁠בֵּ֨ית יְהוָ֜ה מִ⁠ח֤וּץ לִ⁠ירוּשָׁלִַ֨ם֙ אֶל־נַ֣חַל קִדְר֔וֹן וַ⁠יִּשְׂרֹ֥ף אֹתָ֛⁠הּ בְּ⁠נַ֥חַל קִדְר֖וֹן וַ⁠יָּ֣דֶק לְ⁠עָפָ֑ר וַ⁠יַּשְׁלֵךְ֙ אֶת־עֲפָרָ֔⁠הּ עַל־קֶ֖בֶר בְּנֵ֥י הָ⁠עָֽם׃","wa⁠yò̇ẕé֣ʼ ʼeţ-há⁠ʼàşé̌ráh֩ mi⁠bé̇֨yţ yĕhwá֜h mi⁠ẖ֤ẇẕ li⁠yrẇşá̌lia֨m֙ ʼel-na֣ẖal qidĕr֔wòn wa⁠yi̇şĕ̂rò֥p ʼòţá֛⁠ḣ bĕ̇⁠na֥ẖal qidĕr֖wòn wa⁠yá֣̇deq lĕ⁠ʻápá֑r wa⁠yȧşĕ̌lékĕ֙ ʼeţ-ʻàpárá֔⁠ḣ ʻal-qe֖ber bĕ̇né֥y há⁠ʻáֽm׃"],[23,7,"וַ⁠יִּתֹּץ֙ אֶת־בָּתֵּ֣י הַ⁠קְּדֵשִׁ֔ים אֲשֶׁ֖ר בְּ⁠בֵ֣ית יְהוָ֑ה אֲשֶׁ֣ר הַ⁠נָּשִׁ֗ים אֹרְג֥וֹת שָׁ֛ם בָּתִּ֖ים לָ⁠אֲשֵׁרָֽה׃","wa⁠yi̇ţò̇ẕ֙ ʼeţ-bá̇ţé֣̇y ha⁠qĕ̇déşǐ֔ym ʼàşě֖r bĕ̇⁠bé֣yţ yĕhwá֑h ʼàşě֣r ha⁠ná̇şǐ֗ym ʼòrĕg֥wòţ şá֛̌m bá̇ţi֖̇ym lá⁠ʼàşé̌ráֽh׃"],[23,8,"וַ⁠יָּבֵ֤א אֶת־כָּל־הַ⁠כֹּֽהֲנִים֙ מֵ⁠עָרֵ֣י יְהוּדָ֔ה וַ⁠יְטַמֵּ֣א אֶת־הַ⁠בָּמ֗וֹת אֲשֶׁ֤ר קִטְּרוּ־שָׁ֨מָּ⁠ה֙ הַ⁠כֹּ֣הֲנִ֔ים מִ⁠גֶּ֖בַע עַד־בְּאֵ֣ר שָׁ֑בַע וְ⁠נָתַ֞ץ אֶת־בָּמ֣וֹת הַ⁠שְּׁעָרִ֗ים אֲשֶׁר־פֶּ֜תַח שַׁ֤עַר יְהוֹשֻׁ֨עַ֙ שַׂר־הָ⁠עִ֔יר אֲשֶֽׁר־עַל־שְׂמֹ֥אול אִ֖ישׁ בְּ⁠שַׁ֥עַר הָ⁠עִֽיר׃","wa⁠yá̇bé֤ʼ ʼeţ-ká̇l-ha⁠kòֽ̇hàniym֙ mé⁠ʻáré֣y yĕhẇdá֔h wa⁠yĕtamé֣̇ʼ ʼeţ-ha⁠bá̇m֗wòţ ʼàşě֤r qitĕ̇rẇ-şá̌֨má̇⁠h֙ ha⁠kò֣̇hàni֔ym mi⁠gė֖baʻ ʻad-bĕ̇ʼé֣r şá֑̌baʻ wĕ⁠náţa֞ẕ ʼeţ-bá̇m֣wòţ ha⁠şĕ̇̌ʻári֗ym ʼàşěr-pė֜ţaẖ şǎ֤ʻar yĕhwòşǔ֨ʻa֙ şâr-há⁠ʻi֔yr ʼàşěֽr-ʻal-şĕ̂mò֥ʼwl ʼi֖yş̌ bĕ̇⁠şǎ֥ʻar há⁠ʻiֽyr׃"],[23,9,"אַ֗ךְ לֹ֤א יַֽעֲלוּ֙ כֹּהֲנֵ֣י הַ⁠בָּמ֔וֹת אֶל־מִזְבַּ֥ח יְהוָ֖ה בִּ⁠ירוּשָׁלִָ֑ם כִּ֛י אִם־אָכְל֥וּ מַצּ֖וֹת בְּ⁠ת֥וֹךְ אֲחֵי⁠הֶֽם׃","ʼa֗kĕ lò֤ʼ yaֽʻàlẇ֙ kò̇hàné֣y ha⁠bá̇m֔wòţ ʼel-mizĕbȧ֥ẖ yĕhwá֖h bi̇⁠yrẇşá̌liá֑m ki֛̇y ʼim-ʼákĕl֥ẇ maẕ֖̇wòţ bĕ̇⁠ţ֥wòkĕ ʼàẖéy⁠heֽm׃"],[23,10,"וְ⁠טִמֵּ֣א אֶת־הַ⁠תֹּ֔פֶת אֲשֶׁ֖ר בְּ⁠גֵ֣י בני־הִנֹּ֑ם לְ⁠בִלְתִּ֗י לְ⁠הַעֲבִ֨יר אִ֜ישׁ אֶת־בְּנ֧⁠וֹ וְ⁠אֶת־בִּתּ֛⁠וֹ בָּ⁠אֵ֖שׁ לַ⁠מֹּֽלֶךְ׃","wĕ⁠timé֣̇ʼ ʼeţ-ha⁠ţò̇֔peţ ʼàşě֖r bĕ̇⁠gé֣y bny-hinò֑̇m lĕ⁠bilĕţi̇֗y lĕ⁠haʻàbi֨yr ʼi֜yş̌ ʼeţ-bĕ̇n֧⁠wò wĕ⁠ʼeţ-bi̇ţ֛̇⁠wò bá̇⁠ʼé֖ş̌ la⁠mòֽ̇lekĕ׃"],[23,11,"וַ⁠יַּשְׁבֵּ֣ת אֶת־הַ⁠סּוּסִ֗ים אֲשֶׁ֣ר נָתְנוּ֩ מַלְכֵ֨י יְהוּדָ֤ה לַ⁠שֶּׁ֨מֶשׁ֙ מִ⁠בֹּ֣א בֵית־יְהוָ֔ה אֶל־לִשְׁכַּת֙ נְתַן־מֶ֣לֶךְ הַ⁠סָּרִ֔יס אֲשֶׁ֖ר בַּ⁠פַּרְוָרִ֑ים וְ⁠אֶת־מַרְכְּב֥וֹת הַ⁠שֶּׁ֖מֶשׁ שָׂרַ֥ף בָּ⁠אֵֽשׁ׃","wa⁠yȧşĕ̌bé֣̇ţ ʼeţ-ha⁠ṡẇsi֗ym ʼàşě֣r náţĕnẇ֩ malĕké֨y yĕhẇdá֤h la⁠şė̌֨meş̌֙ mi⁠bò֣̇ʼ béyţ-yĕhwá֔h ʼel-lişĕ̌kȧţ֙ nĕţan-me֣lekĕ ha⁠sá̇ri֔ys ʼàşě֖r bȧ⁠pȧrĕwári֑ym wĕ⁠ʼeţ-marĕkĕ̇b֥wòţ ha⁠şė֖̌meş̌ şá̂ra֥p bá̇⁠ʼéֽş̌׃"],[23,12,"וְ⁠אֶֽת־הַֽ⁠מִּזְבְּח֡וֹת אֲשֶׁ֣ר עַל־הַ⁠גָּג֩ עֲלִיַּ֨ת אָחָ֜ז אֲשֶׁר־עָשׂ֣וּ ׀ מַלְכֵ֣י יְהוּדָ֗ה וְ⁠אֶת־הַֽ⁠מִּזְבְּחוֹת֙ אֲשֶׁר־עָשָׂ֣ה מְנַשֶּׁ֔ה בִּ⁠שְׁתֵּ֛י חַצְר֥וֹת בֵּית־יְהוָ֖ה נָתַ֣ץ הַ⁠מֶּ֑לֶךְ וַ⁠יָּ֣רָץ מִ⁠שָּׁ֔ם וְ⁠הִשְׁלִ֥יךְ אֶת־עֲפָרָ֖⁠ם אֶל־נַ֥חַל קִדְרֽוֹן׃","wĕ⁠ʼeֽţ-haֽ⁠mi̇zĕbĕ̇ẖ֡wòţ ʼàşě֣r ʻal-ha⁠gá̇g֩ ʻàliyȧ֨ţ ʼáẖá֜z ʼàşěr-ʻáş֣̂ẇ ׀ malĕké֣y yĕhẇdá֗h wĕ⁠ʼeţ-haֽ⁠mi̇zĕbĕ̇ẖwòţ֙ ʼàşěr-ʻáşá֣̂h mĕnaşė̌֔h bi̇⁠şĕ̌ţé֛̇y ẖaẕĕr֥wòţ bé̇yţ-yĕhwá֖h náţa֣ẕ ha⁠mė֑lekĕ wa⁠yá֣̇ráẕ mi⁠şá̇̌֔m wĕ⁠hişĕ̌li֥ykĕ ʼeţ-ʻàpárá֖⁠m ʼel-na֥ẖal qidĕrֽwòn׃"],[23,13,"וְֽ⁠אֶת־הַ⁠בָּמ֞וֹת אֲשֶׁ֣ר ׀ עַל־פְּנֵ֣י יְרוּשָׁלִַ֗ם אֲשֶׁר֮ מִ⁠ימִ֣ין לְ⁠הַר־הַ⁠מַּשְׁחִית֒ אֲשֶׁ֣ר בָּ֠נָה שְׁלֹמֹ֨ה מֶֽלֶךְ־יִשְׂרָאֵ֜ל לְ⁠עַשְׁתֹּ֣רֶת ׀ שִׁקֻּ֣ץ צִידֹנִ֗ים וְ⁠לִ⁠כְמוֹשׁ֙ שִׁקֻּ֣ץ מוֹאָ֔ב וּ⁠לְ⁠מִלְכֹּ֖ם תּוֹעֲבַ֣ת בְּנֵֽי־עַמּ֑וֹן טִמֵּ֖א הַ⁠מֶּֽלֶךְ׃","wĕֽ⁠ʼeţ-ha⁠bá̇m֞wòţ ʼàşě֣r ׀ ʻal-pĕ̇né֣y yĕrẇşá̌lia֗m ʼàşěr֮ mi⁠ymi֣yn lĕ⁠har-ha⁠mȧşĕ̌ẖiyţ֒ ʼàşě֣r bá̇֠náh şĕ̌lòmò֨h meֽlekĕ-yişĕ̂ráʼé֜l lĕ⁠ʻaşĕ̌ţò֣̇reţ ׀ şǐqu֣̇ẕ ẕiydòni֗ym wĕ⁠li⁠kĕmwòş̌֙ şǐqu֣̇ẕ mwòʼá֔b ẇ⁠lĕ⁠milĕkò֖̇m ţ̇wòʻàba֣ţ bĕ̇néֽy-ʻaṁ֑wòn timé֖̇ʼ ha⁠mėֽlekĕ׃"],[23,14,"וְ⁠שִׁבַּר֙ אֶת־הַ⁠מַּצֵּב֔וֹת וַ⁠יִּכְרֹ֖ת אֶת־הָ⁠אֲשֵׁרִ֑ים וַ⁠יְמַלֵּ֥א אֶת־מְקוֹמָ֖⁠ם עַצְמ֥וֹת אָדָֽם׃","wĕ⁠şǐbȧr֙ ʼeţ-ha⁠mȧẕé̇b֔wòţ wa⁠yi̇kĕrò֖ţ ʼeţ-há⁠ʼàşé̌ri֑ym wa⁠yĕmalé֥̇ʼ ʼeţ-mĕqwòmá֖⁠m ʻaẕĕm֥wòţ ʼádáֽm׃"],[23,15,"וְ⁠גַ֨ם אֶת־הַ⁠מִּזְבֵּ֜חַ אֲשֶׁ֣ר בְּ⁠בֵֽית־אֵ֗ל הַ⁠בָּמָה֙ אֲשֶׁ֨ר עָשָׂ֜ה יָרָבְעָ֤ם בֶּן־נְבָט֙ אֲשֶׁ֣ר הֶחֱטִ֣יא אֶת־יִשְׂרָאֵ֔ל גַּ֣ם אֶת־הַ⁠מִּזְבֵּ֧חַ הַ⁠ה֛וּא וְ⁠אֶת־הַ⁠בָּמָ֖ה נָתָ֑ץ וַ⁠יִּשְׂרֹ֧ף אֶת־הַ⁠בָּמָ֛ה הֵדַ֥ק לְ⁠עָפָ֖ר וְ⁠שָׂרַ֥ף אֲשֵׁרָֽה׃","wĕ⁠ga֨m ʼeţ-ha⁠mi̇zĕbé̇֜ẖa ʼàşě֣r bĕ̇⁠béֽyţ-ʼé֗l ha⁠bá̇máh֙ ʼàşě֨r ʻáşá̂֜h yárábĕʻá֤m bėn-nĕbát֙ ʼàşě֣r heẖèti֣yʼ ʼeţ-yişĕ̂ráʼé֔l gȧ֣m ʼeţ-ha⁠mi̇zĕbé֧̇ẖa ha⁠h֛ẇʼ wĕ⁠ʼeţ-ha⁠bá̇má֖h náţá֑ẕ wa⁠yi̇şĕ̂rò֧p ʼeţ-ha⁠bá̇má֛h héda֥q lĕ⁠ʻápá֖r wĕ⁠şá̂ra֥p ʼàşé̌ráֽh׃"],[23,16,"וַ⁠יִּ֣פֶן יֹאשִׁיָּ֗הוּ וַ⁠יַּ֨רְא אֶת־הַ⁠קְּבָרִ֤ים אֲשֶׁר־שָׁם֙ בָּ⁠הָ֔ר וַ⁠יִּשְׁלַ֗ח וַ⁠יִּקַּ֤ח אֶת־הָֽ⁠עֲצָמוֹת֙ מִן־הַ⁠קְּבָרִ֔ים וַ⁠יִּשְׂרֹ֥ף עַל־הַ⁠מִּזְבֵּ֖חַ וַֽ⁠יְטַמְּאֵ֑⁠הוּ כִּ⁠דְבַ֣ר יְהוָ֗ה אֲשֶׁ֤ר קָרָא֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים אֲשֶׁ֣ר קָרָ֔א אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yi֣̇pen yòʼşǐyá̇֗hẇ wa⁠yȧ֨rĕʼ ʼeţ-ha⁠qĕ̇bári֤ym ʼàşěr-şá̌m֙ bá̇⁠há֔r wa⁠yi̇şĕ̌la֗ẖ wa⁠yi̇qȧ֤ẖ ʼeţ-háֽ⁠ʻàẕámwòţ֙ min-ha⁠qĕ̇bári֔ym wa⁠yi̇şĕ̂rò֥p ʻal-ha⁠mi̇zĕbé֖̇ẖa waֽ⁠yĕtamĕ̇ʼé֑⁠hẇ ki̇⁠dĕba֣r yĕhwá֗h ʼàşě֤r qáráʼ֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym ʼàşě֣r qárá֔ʼ ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[23,17,"וַ⁠יֹּ֕אמֶר מָ֚ה הַ⁠צִּיּ֣וּן הַלָּ֔ז אֲשֶׁ֖ר אֲנִ֣י רֹאֶ֑ה וַ⁠יֹּאמְר֨וּ אֵלָ֜י⁠ו אַנְשֵׁ֣י הָ⁠עִ֗יר הַ⁠קֶּ֤בֶר אִישׁ־הָֽ⁠אֱלֹהִים֙ אֲשֶׁר־בָּ֣א מִֽ⁠יהוּדָ֔ה וַ⁠יִּקְרָ֗א אֶת־הַ⁠דְּבָרִ֤ים הָ⁠אֵ֨לֶּה֙ אֲשֶׁ֣ר עָשִׂ֔יתָ עַ֖ל הַ⁠מִּזְבַּ֥ח בֵּֽית־אֵֽל׃","wa⁠yò̇֕ʼmer má֚h ha⁠ẕi̇ẏ֣ẇn halá̇֔z ʼàşě֖r ʼàni֣y ròʼe֑h wa⁠yò̇ʼmĕr֨ẇ ʼélá֜y⁠w ʼanĕşé֣̌y há⁠ʻi֗yr ha⁠qė֤ber ʼiyş̌-háֽ⁠ʼèlòhiym֙ ʼàşěr-bá֣̇ʼ miֽ⁠yhẇdá֔h wa⁠yi̇qĕrá֗ʼ ʼeţ-ha⁠dĕ̇bári֤ym há⁠ʼé֨lėh֙ ʼàşě֣r ʻáşî֔yţá ʻa֖l ha⁠mi̇zĕbȧ֥ẖ béֽ̇yţ-ʼéֽl׃"],[23,18,"וַ⁠יֹּ֨אמֶר֙ הַנִּ֣יחוּ ל֔⁠וֹ אִ֖ישׁ אַל־יָנַ֣ע עַצְמֹתָ֑י⁠ו וַֽ⁠יְמַלְּטוּ֙ עַצְמֹתָ֔י⁠ו אֵ֚ת עַצְמ֣וֹת הַ⁠נָּבִ֔יא אֲשֶׁר־בָּ֖א מִ⁠שֹּׁמְרֽוֹן׃","wa⁠yò̇֨ʼmer֙ hani֣̇yẖẇ l֔⁠wò ʼi֖yş̌ ʼal-yána֣ʻ ʻaẕĕmòţá֑y⁠w waֽ⁠yĕmalĕ̇tẇ֙ ʻaẕĕmòţá֔y⁠w ʼé֚ţ ʻaẕĕm֣wòţ ha⁠ná̇bi֔yʼ ʼàşěr-bá֖̇ʼ mi⁠şò̇̌mĕrֽwòn׃"],[23,19,"וְ⁠גַם֩ אֶת־כָּל־בָּתֵּ֨י הַ⁠בָּמ֜וֹת אֲשֶׁ֣ר ׀ בְּ⁠עָרֵ֣י שֹׁמְר֗וֹן אֲשֶׁ֨ר עָשׂ֜וּ מַלְכֵ֤י יִשְׂרָאֵל֙ לְ⁠הַכְעִ֔יס הֵסִ֖יר יֹֽאשִׁיָּ֑הוּ וַ⁠יַּ֣עַשׂ לָ⁠הֶ֔ם כְּ⁠כָל־הַֽ⁠מַּעֲשִׂ֔ים אֲשֶׁ֥ר עָשָׂ֖ה בְּ⁠בֵֽית־אֵֽל׃","wĕ⁠gam֩ ʼeţ-ká̇l-bá̇ţé̇֨y ha⁠bá̇m֜wòţ ʼàşě֣r ׀ bĕ̇⁠ʻáré֣y şò̌mĕr֗wòn ʼàşě֨r ʻáş̂֜ẇ malĕké֤y yişĕ̂ráʼél֙ lĕ⁠hakĕʻi֔ys hési֖yr yòֽʼşǐyá֑̇hẇ wa⁠yȧ֣ʻaş̂ lá⁠he֔m kĕ̇⁠kál-haֽ⁠mȧʻàşî֔ym ʼàşě֥r ʻáşá֖̂h bĕ̇⁠béֽyţ-ʼéֽl׃"],[23,20,"וַ֠⁠יִּזְבַּח אֶת־כָּל־כֹּהֲנֵ֨י הַ⁠בָּמ֤וֹת אֲשֶׁר־שָׁם֙ עַל־הַֽ⁠מִּזְבְּח֔וֹת וַ⁠יִּשְׂרֹ֛ף אֶת־עַצְמ֥וֹת אָדָ֖ם עֲלֵי⁠הֶ֑ם וַ⁠יָּ֖שָׁב יְרוּשָׁלִָֽם׃","wa֠⁠yi̇zĕbȧẖ ʼeţ-ká̇l-kò̇hàné֨y ha⁠bá̇m֤wòţ ʼàşěr-şá̌m֙ ʻal-haֽ⁠mi̇zĕbĕ̇ẖ֔wòţ wa⁠yi̇şĕ̂rò֛p ʼeţ-ʻaẕĕm֥wòţ ʼádá֖m ʻàléy⁠he֑m wa⁠yá֖̇şá̌b yĕrẇşá̌liáֽm׃"],[23,21,"וַ⁠יְצַ֤ו הַ⁠מֶּ֨לֶךְ֙ אֶת־כָּל־הָ⁠עָ֣ם לֵ⁠אמֹ֔ר עֲשׂ֣וּ פֶ֔סַח לַֽ⁠יהוָ֖ה אֱלֹֽהֵי⁠כֶ֑ם כַּ⁠כָּת֕וּב עַ֛ל סֵ֥פֶר הַ⁠בְּרִ֖ית הַ⁠זֶּֽה׃","wa⁠yĕẕa֤w ha⁠mė֨lekĕ֙ ʼeţ-ká̇l-há⁠ʻá֣m lé⁠ʼmò֔r ʻàş֣̂ẇ pe֔saẖ laֽ⁠yhwá֖h ʼèlòֽhéy⁠ke֑m kȧ⁠ká̇ţ֕ẇb ʻa֛l sé֥per ha⁠bĕ̇ri֖yţ ha⁠zėֽh׃"],[23,22,"כִּ֣י לֹ֤א נַֽעֲשָׂה֙ כַּ⁠פֶּ֣סַח הַ⁠זֶּ֔ה מִ⁠ימֵי֙ הַ⁠שֹּׁ֣פְטִ֔ים אֲשֶׁ֥ר שָׁפְט֖וּ אֶת־יִשְׂרָאֵ֑ל וְ⁠כֹ֗ל יְמֵ֛י מַלְכֵ֥י יִשְׂרָאֵ֖ל וּ⁠מַלְכֵ֥י יְהוּדָֽה׃","ki֣̇y lò֤ʼ naֽʻàşá̂h֙ kȧ⁠pė֣saẖ ha⁠zė֔h mi⁠yméy֙ ha⁠şò֣̇̌pĕti֔ym ʼàşě֥r şá̌pĕt֖ẇ ʼeţ-yişĕ̂ráʼé֑l wĕ⁠kò֗l yĕmé֛y malĕké֥y yişĕ̂ráʼé֖l ẇ⁠malĕké֥y yĕhẇdáֽh׃"],[23,23,"כִּ֗י אִם־בִּ⁠שְׁמֹנֶ֤ה עֶשְׂרֵה֙ שָׁנָ֔ה לַ⁠מֶּ֖לֶךְ יֹֽאשִׁיָּ֑הוּ נַעֲשָׂ֞ה הַ⁠פֶּ֧סַח הַ⁠זֶּ֛ה לַ⁠יהוָ֖ה בִּ⁠ירוּשָׁלִָֽם׃","ki̇֗y ʼim-bi̇⁠şĕ̌mòne֤h ʻeşĕ̂réh֙ şá̌ná֔h la⁠mė֖lekĕ yòֽʼşǐyá֑̇hẇ naʻàşá̂֞h ha⁠pė֧saẖ ha⁠zė֛h la⁠yhwá֖h bi̇⁠yrẇşá̌liáֽm׃"],[23,24,"וְ⁠גַ֣ם אֶת־הָ⁠אֹב֣וֹת וְ⁠אֶת־הַ֠⁠יִּדְּעֹנִים וְ⁠אֶת־הַ⁠תְּרָפִ֨ים וְ⁠אֶת־הַ⁠גִּלֻּלִ֜ים וְ⁠אֵ֣ת כָּל־הַ⁠שִּׁקֻּצִ֗ים אֲשֶׁ֤ר נִרְאוּ֙ בְּ⁠אֶ֤רֶץ יְהוּדָה֙ וּ⁠בִ⁠יר֣וּשָׁלִַ֔ם בִּעֵ֖ר יֹֽאשִׁיָּ֑הוּ לְ֠מַעַן הָקִ֞ים אֶת־דִּבְרֵ֤י הַ⁠תּוֹרָה֙ הַ⁠כְּתֻבִ֣ים עַל־הַ⁠סֵּ֔פֶר אֲשֶׁ֥ר מָצָ֛א חִלְקִיָּ֥הוּ הַ⁠כֹּהֵ֖ן בֵּ֥ית יְהוָֽה׃","wĕ⁠ga֣m ʼeţ-há⁠ʼòb֣wòţ wĕ⁠ʼeţ-ha֠⁠yi̇dĕ̇ʻòniym wĕ⁠ʼeţ-ha⁠ţĕ̇rápi֨ym wĕ⁠ʼeţ-ha⁠gi̇lu̇li֜ym wĕ⁠ʼé֣ţ ká̇l-ha⁠şi̇̌qu̇ẕi֗ym ʼàşě֤r nirĕʼẇ֙ bĕ̇⁠ʼe֤reẕ yĕhẇdáh֙ ẇ⁠bi⁠yr֣ẇşá̌lia֔m bi̇ʻé֖r yòֽʼşǐyá֑̇hẇ lĕ֠maʻan háqi֞ym ʼeţ-di̇bĕré֤y ha⁠ţ̇wòráh֙ ha⁠kĕ̇ţubi֣ym ʻal-ha⁠sé̇֔per ʼàşě֥r máẕá֛ʼ ẖilĕqiyá֥̇hẇ ha⁠kò̇hé֖n bé֥̇yţ yĕhwáֽh׃"],[23,25,"וְ⁠כָמֹ⁠הוּ֩ לֹֽא־הָיָ֨ה לְ⁠פָנָ֜י⁠ו מֶ֗לֶךְ אֲשֶׁר־שָׁ֤ב אֶל־יְהוָה֙ בְּ⁠כָל־לְבָב֤⁠וֹ וּ⁠בְ⁠כָל־נַפְשׁ⁠וֹ֙ וּ⁠בְ⁠כָל־מְאֹד֔⁠וֹ כְּ⁠כֹ֖ל תּוֹרַ֣ת מֹשֶׁ֑ה וְ⁠אַחֲרָ֖י⁠ו לֹֽא־קָ֥ם כָּמֹֽ⁠הוּ׃","wĕ⁠kámò⁠hẇ֩ lòֽʼ-háyá֨h lĕ⁠páná֜y⁠w me֗lekĕ ʼàşěr-şá֤̌b ʼel-yĕhwáh֙ bĕ̇⁠kál-lĕbáb֤⁠wò ẇ⁠bĕ⁠kál-napĕş̌⁠wò֙ ẇ⁠bĕ⁠kál-mĕʼòd֔⁠wò kĕ̇⁠kò֖l ţ̇wòra֣ţ mòşě֑h wĕ⁠ʼaẖàrá֖y⁠w lòֽʼ-qá֥m ká̇mòֽ⁠hẇ׃"],[23,26,"אַ֣ךְ ׀ לֹֽא־שָׁ֣ב יְהוָ֗ה מֵ⁠חֲר֤וֹן אַפּ⁠וֹ֙ הַ⁠גָּד֔וֹל אֲשֶׁר־חָרָ֥ה אַפּ֖⁠וֹ בִּֽ⁠יהוּדָ֑ה עַ֚ל כָּל־הַ⁠כְּעָסִ֔ים אֲשֶׁ֥ר הִכְעִיס֖⁠וֹ מְנַשֶּֽׁה׃","ʼa֣kĕ ׀ lòֽʼ-şá֣̌b yĕhwá֗h mé⁠ẖàr֤wòn ʼaṗ⁠wò֙ ha⁠gá̇d֔wòl ʼàşěr-ẖárá֥h ʼaṗ֖⁠wò biֽ̇⁠yhẇdá֑h ʻa֚l ká̇l-ha⁠kĕ̇ʻási֔ym ʼàşě֥r hikĕʻiys֖⁠wò mĕnaşėֽ̌h׃"],[23,27,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה גַּ֤ם אֶת־יְהוּדָה֙ אָסִיר֙ מֵ⁠עַ֣ל פָּנַ֔⁠י כַּ⁠אֲשֶׁ֥ר הֲסִרֹ֖תִי אֶת־יִשְׂרָאֵ֑ל וּ֠⁠מָאַסְתִּי אֶת־הָ⁠עִ֨יר הַ⁠זֹּ֤את אֲשֶׁר־בָּחַ֨רְתִּי֙ אֶת־יְר֣וּשָׁלִַ֔ם וְ⁠אֶת־הַ⁠בַּ֔יִת אֲשֶׁ֣ר אָמַ֔רְתִּי יִהְיֶ֥ה שְׁמִ֖⁠י שָֽׁם׃","wa⁠yò֣̇ʼmer yĕhwá֗h gȧ֤m ʼeţ-yĕhẇdáh֙ ʼásiyr֙ mé⁠ʻa֣l pá̇na֔⁠y kȧ⁠ʼàşě֥r hàsirò֖ţiy ʼeţ-yişĕ̂ráʼé֑l ẇ֠⁠máʼasĕţi̇y ʼeţ-há⁠ʻi֨yr ha⁠zò֤̇ʼţ ʼàşěr-bá̇ẖa֨rĕţi̇y֙ ʼeţ-yĕr֣ẇşá̌lia֔m wĕ⁠ʼeţ-ha⁠bȧ֔yiţ ʼàşě֣r ʼáma֔rĕţi̇y yihĕye֥h şĕ̌mi֖⁠y şáֽ̌m׃"],[23,28,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יֹאשִׁיָּ֖הוּ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y yòʼşǐyá֖̇hẇ wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[23,29,"בְּ⁠יָמָ֡י⁠ו עָלָה֩ פַרְעֹ֨ה נְכֹ֧ה מֶֽלֶךְ־מִצְרַ֛יִם עַל־מֶ֥לֶךְ אַשּׁ֖וּר עַל־נְהַר־פְּרָ֑ת וַ⁠יֵּ֨לֶךְ הַ⁠מֶּ֤לֶךְ יֹאשִׁיָּ֨הוּ֙ לִ⁠קְרָאת֔⁠וֹ וַ⁠יְמִיתֵ֨⁠הוּ֙ בִּ⁠מְגִדּ֔וֹ כִּ⁠רְאֹת֖⁠וֹ אֹתֽ⁠וֹ׃","bĕ̇⁠yámá֡y⁠w ʻáláh֩ parĕʻò֨h nĕkò֧h meֽlekĕ-miẕĕra֛yim ʻal-me֥lekĕ ʼaş֖̇̌ẇr ʻal-nĕhar-pĕ̇rá֑ţ wa⁠yé̇֨lekĕ ha⁠mė֤lekĕ yòʼşǐyá̇֨hẇ֙ li⁠qĕráʼţ֔⁠wò wa⁠yĕmiyţé֨⁠hẇ֙ bi̇⁠mĕgiḋ֔wò ki̇⁠rĕʼòţ֖⁠wò ʼòţֽ⁠wò׃"],[23,30,"וַ⁠יַּרְכִּבֻ֨⁠הוּ עֲבָדָ֥י⁠ו מֵת֙ מִ⁠מְּגִדּ֔וֹ וַ⁠יְבִאֻ֨⁠הוּ֙ יְר֣וּשָׁלִַ֔ם וַֽ⁠יִּקְבְּרֻ֖⁠הוּ בִּ⁠קְבֻֽרָת֑⁠וֹ וַ⁠יִּקַּ֣ח עַם־הָ⁠אָ֗רֶץ אֶת־יְהֽוֹאָחָז֙ בֶּן־יֹ֣אשִׁיָּ֔הוּ וַ⁠יִּמְשְׁח֥וּ אֹת֛⁠וֹ וַ⁠יַּמְלִ֥יכוּ אֹת֖⁠וֹ תַּ֥חַת אָבִֽי⁠ו׃פ","wa⁠yȧrĕki̇bu֨⁠hẇ ʻàbádá֥y⁠w méţ֙ mi⁠mĕ̇giḋ֔wò wa⁠yĕbiʼu֨⁠hẇ֙ yĕr֣ẇşá̌lia֔m waֽ⁠yi̇qĕbĕ̇ru֖⁠hẇ bi̇⁠qĕbuֽráţ֑⁠wò wa⁠yi̇qȧ֣ẖ ʻam-há⁠ʼá֗reẕ ʼeţ-yĕhֽwòʼáẖáz֙ bėn-yò֣ʼşǐyá̇֔hẇ wa⁠yi̇mĕşĕ̌ẖ֥ẇ ʼòţ֛⁠wò wa⁠yȧmĕli֥ykẇ ʼòţ֖⁠wò ţȧ֥ẖaţ ʼábiֽy⁠w׃p"],[23,31,"בֶּן־עֶשְׂרִ֨ים וְ⁠שָׁלֹ֤שׁ שָׁנָה֙ יְהוֹאָחָ֣ז בְּ⁠מָלְכ֔⁠וֹ וּ⁠שְׁלֹשָׁ֣ה חֳדָשִׁ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ חֲמוּטַ֥ל בַּֽת־יִרְמְיָ֖הוּ מִ⁠לִּבְנָֽה׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠şá̌lò֤ş̌ şá̌náh֙ yĕhwòʼáẖá֣z bĕ̇⁠málĕk֔⁠wò ẇ⁠şĕ̌lòşá֣̌h ẖodáşǐ֔ym mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ẖàmẇta֥l bȧֽţ-yirĕmĕyá֖hẇ mi⁠li̇bĕnáֽh׃"],[23,32,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשׂ֖וּ אֲבֹתָֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáş֖̂ẇ ʼàbòţáֽy⁠w׃"],[23,33,"וַ⁠יַּאַסְרֵ⁠הוּ֩ פַרְעֹ֨ה נְכֹ֤ה בְ⁠רִבְלָה֙ בְּ⁠אֶ֣רֶץ חֲמָ֔ת ב⁠מלך בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יִּתֶּן־עֹ֨נֶשׁ֙ עַל־הָ⁠אָ֔רֶץ מֵאָ֥ה כִכַּר־כֶּ֖סֶף וְ⁠כִכַּ֥ר זָהָֽב׃","wa⁠yȧʼasĕré⁠hẇ֩ parĕʻò֨h nĕkò֤h bĕ⁠ribĕláh֙ bĕ̇⁠ʼe֣reẕ ẖàmá֔ţ b⁠mlk bi̇⁠yrẇşá̌liá֑m wa⁠yi̇ţėn-ʻò֨neş̌֙ ʻal-há⁠ʼá֔reẕ méʼá֥h kikȧr-kė֖sep wĕ⁠kikȧ֥r záháֽb׃"],[23,34,"וַ⁠יַּמְלֵךְ֩ פַּרְעֹ֨ה נְכֹ֜ה אֶת־אֶלְיָקִ֣ים בֶּן־יֹאשִׁיָּ֗הוּ תַּ֚חַת יֹאשִׁיָּ֣הוּ אָבִ֔י⁠ו וַ⁠יַּסֵּ֥ב אֶת־שְׁמ֖⁠וֹ יְהוֹיָקִ֑ים וְ⁠אֶת־יְהוֹאָחָ֣ז לָקָ֔ח וַ⁠יָּבֹ֥א מִצְרַ֖יִם וַ⁠יָּ֥מָת שָֽׁם׃","wa⁠yȧmĕlékĕ֩ pȧrĕʻò֨h nĕkò֜h ʼeţ-ʼelĕyáqi֣ym bėn-yòʼşǐyá̇֗hẇ ţȧ֚ẖaţ yòʼşǐyá֣̇hẇ ʼábi֔y⁠w wa⁠yȧsé֥̇b ʼeţ-şĕ̌m֖⁠wò yĕhwòyáqi֑ym wĕ⁠ʼeţ-yĕhwòʼáẖá֣z láqá֔ẖ wa⁠yá̇bò֥ʼ miẕĕra֖yim wa⁠yá֥̇máţ şáֽ̌m׃"],[23,35,"וְ⁠הַ⁠כֶּ֣סֶף וְ⁠הַ⁠זָּהָ֗ב נָתַ֤ן יְהוֹיָקִים֙ לְ⁠פַרְעֹ֔ה אַ֚ךְ הֶעֱרִ֣יךְ אֶת־הָ⁠אָ֔רֶץ לָ⁠תֵ֥ת אֶת־הַ⁠כֶּ֖סֶף עַל־פִּ֣י פַרְעֹ֑ה אִ֣ישׁ כְּ⁠עֶרְכּ֗⁠וֹ נָגַ֞שׂ אֶת־הַ⁠כֶּ֤סֶף וְ⁠אֶת־הַ⁠זָּהָב֙ אֶת־עַ֣ם הָ⁠אָ֔רֶץ לָ⁠תֵ֖ת לְ⁠פַרְעֹ֥ה נְכֹֽה׃ס","wĕ⁠ha⁠kė֣sep wĕ⁠ha⁠zá̇há֗b náţa֤n yĕhwòyáqiym֙ lĕ⁠parĕʻò֔h ʼa֚kĕ heʻèri֣ykĕ ʼeţ-há⁠ʼá֔reẕ lá⁠ţé֥ţ ʼeţ-ha⁠kė֖sep ʻal-pi֣̇y parĕʻò֑h ʼi֣yş̌ kĕ̇⁠ʻerĕk̇֗⁠wò nága֞ş̂ ʼeţ-ha⁠kė֤sep wĕ⁠ʼeţ-ha⁠zá̇háb֙ ʼeţ-ʻa֣m há⁠ʼá֔reẕ lá⁠ţé֖ţ lĕ⁠parĕʻò֥h nĕkòֽh׃s"],[23,36,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָ֨ה יְהוֹיָקִ֣ים בְּ⁠מָלְכ֔⁠וֹ וְ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ זבידה בַת־פְּדָיָ֖ה מִן־רוּמָֽה׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌ná֨h yĕhwòyáqi֣ym bĕ̇⁠málĕk֔⁠wò wĕ⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò zbydh baţ-pĕ̇dáyá֖h min-rẇmáֽh׃"],[23,37,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשׂ֖וּ אֲבֹתָֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáş֖̂ẇ ʼàbòţáֽy⁠w׃"],[24,1,"בְּ⁠יָמָ֣י⁠ו עָלָ֔ה נְבֻכַדְנֶאצַּ֖ר מֶ֣לֶךְ בָּבֶ֑ל וַ⁠יְהִי־ל֨⁠וֹ יְהוֹיָקִ֥ים עֶ֨בֶד֙ שָׁלֹ֣שׁ שָׁנִ֔ים וַ⁠יָּ֖שָׁב וַ⁠יִּמְרָד־בּֽ⁠וֹ׃","bĕ̇⁠yámá֣y⁠w ʻálá֔h nĕbukadĕneʼẕȧ֖r me֣lekĕ bá̇be֑l wa⁠yĕhiy-l֨⁠wò yĕhwòyáqi֥ym ʻe֨bed֙ şá̌lò֣ş̌ şá̌ni֔ym wa⁠yá֖̇şá̌b wa⁠yi̇mĕrád-ḃֽ⁠wò׃"],[24,2,"וַ⁠יְשַׁלַּ֣ח יְהוָ֣ה ׀ בּ֡⁠וֹ אֶת־גְּדוּדֵ֣י כַשְׂדִּים֩ וְ⁠אֶת־גְּדוּדֵ֨י אֲרָ֜ם וְ⁠אֵ֣ת ׀ גְּדוּדֵ֣י מוֹאָ֗ב וְ⁠אֵת֙ גְּדוּדֵ֣י בְנֵֽי־עַמּ֔וֹן וַ⁠יְשַׁלְּחֵ֥⁠ם בִּֽ⁠יהוּדָ֖ה לְ⁠הַֽאֲבִיד֑⁠וֹ כִּ⁠דְבַ֣ר יְהוָ֔ה אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַ֖ד עֲבָדָ֥י⁠ו הַ⁠נְּבִיאִֽים׃","wa⁠yĕşǎlȧ֣ẖ yĕhwá֣h ׀ ḃ֡⁠wò ʼeţ-gĕ̇dẇdé֣y kaşĕ̂di̇ym֩ wĕ⁠ʼeţ-gĕ̇dẇdé֨y ʼàrá֜m wĕ⁠ʼé֣ţ ׀ gĕ̇dẇdé֣y mwòʼá֗b wĕ⁠ʼéţ֙ gĕ̇dẇdé֣y bĕnéֽy-ʻaṁ֔wòn wa⁠yĕşǎlĕ̇ẖé֥⁠m biֽ̇⁠yhẇdá֖h lĕ⁠haֽʼàbiyd֑⁠wò ki̇⁠dĕba֣r yĕhwá֔h ʼàşě֣r di̇bė֔r bĕ̇⁠ya֖d ʻàbádá֥y⁠w ha⁠nĕ̇biyʼiֽym׃"],[24,3,"אַ֣ךְ ׀ עַל־פִּ֣י יְהוָ֗ה הָֽיְתָה֙ בִּֽ⁠יהוּדָ֔ה לְ⁠הָסִ֖יר מֵ⁠עַ֣ל פָּנָ֑י⁠ו בְּ⁠חַטֹּ֣את מְנַשֶּׁ֔ה כְּ⁠כֹ֖ל אֲשֶׁ֥ר עָשָֽׂה׃","ʼa֣kĕ ׀ ʻal-pi֣̇y yĕhwá֗h háֽyĕţáh֙ biֽ̇⁠yhẇdá֔h lĕ⁠hási֖yr mé⁠ʻa֣l pá̇ná֑y⁠w bĕ̇⁠ẖatò֣̇ʼţ mĕnaşė̌֔h kĕ̇⁠kò֖l ʼàşě֥r ʻáşáֽ̂h׃"],[24,4,"וְ⁠גַ֤ם דַּֽם־הַ⁠נָּקִי֙ אֲשֶׁ֣ר שָׁפָ֔ךְ וַ⁠יְמַלֵּ֥א אֶת־יְרוּשָׁלִַ֖ם דָּ֣ם נָקִ֑י וְ⁠לֹֽא־אָבָ֥ה יְהוָ֖ה לִ⁠סְלֹֽחַ׃","wĕ⁠ga֤m dȧֽm-ha⁠ná̇qiy֙ ʼàşě֣r şá̌pá֔kĕ wa⁠yĕmalé֥̇ʼ ʼeţ-yĕrẇşá̌lia֖m dá֣̇m náqi֑y wĕ⁠lòֽʼ-ʼábá֥h yĕhwá֖h li⁠sĕlòֽẖa׃"],[24,5,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יְהוֹיָקִ֖ים וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y yĕhwòyáqi֖ym wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[24,6,"וַ⁠יִּשְׁכַּ֥ב יְהוֹיָקִ֖ים עִם־אֲבֹתָ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ יְהוֹיָכִ֥ין בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yi̇şĕ̌kȧ֥b yĕhwòyáqi֖ym ʻim-ʼàbòţá֑y⁠w wa⁠yi̇mĕlò֛kĕ yĕhwòyáki֥yn bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[24,7,"וְ⁠לֹֽא־הֹסִ֥יף עוֹד֙ מֶ֣לֶךְ מִצְרַ֔יִם לָ⁠צֵ֖את מֵֽ⁠אַרְצ֑⁠וֹ כִּֽי־לָקַ֞ח מֶ֣לֶךְ בָּבֶ֗ל מִ⁠נַּ֤חַל מִצְרַ֨יִם֙ עַד־נְהַר־פְּרָ֔ת כֹּ֛ל אֲשֶׁ֥ר הָיְתָ֖ה לְ⁠מֶ֥לֶךְ מִצְרָֽיִם׃פ","wĕ⁠lòֽʼ-hòsi֥yp ʻwòd֙ me֣lekĕ miẕĕra֔yim lá⁠ẕé֖ʼţ méֽ⁠ʼarĕẕ֑⁠wò kiֽ̇y-láqa֞ẖ me֣lekĕ bá̇be֗l mi⁠nȧ֤ẖal miẕĕra֨yim֙ ʻad-nĕhar-pĕ̇rá֔ţ kò֛̇l ʼàşě֥r háyĕţá֖h lĕ⁠me֥lekĕ miẕĕráֽyim׃p"],[24,8,"בֶּן־שְׁמֹנֶ֨ה עֶשְׂרֵ֤ה שָׁנָה֙ יְהוֹיָכִ֣ין בְּ⁠מָלְכ֔⁠וֹ וּ⁠שְׁלֹשָׁ֣ה חֳדָשִׁ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ נְחֻשְׁתָּ֥א בַת־אֶלְנָתָ֖ן מִ⁠ירוּשָׁלִָֽם׃","bėn-şĕ̌mòne֨h ʻeşĕ̂ré֤h şá̌náh֙ yĕhwòyáki֣yn bĕ̇⁠málĕk֔⁠wò ẇ⁠şĕ̌lòşá֣̌h ẖodáşǐ֔ym mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò nĕẖuşĕ̌ţá֥̇ʼ baţ-ʼelĕnáţá֖n mi⁠yrẇşá̌liáֽm׃"],[24,9,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה אָבִֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h ʼábiֽy⁠w׃"],[24,10,"בָּ⁠עֵ֣ת הַ⁠הִ֔יא עלה עַבְדֵ֛י נְבֻכַדְנֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל יְרוּשָׁלִָ֑ם וַ⁠תָּבֹ֥א הָ⁠עִ֖יר בַּ⁠מָּצֽוֹר׃","bá̇⁠ʻé֣ţ ha⁠hi֔yʼ ʻlh ʻabĕdé֛y nĕbukadĕneʼẕȧ֥r meֽlekĕ-bá̇be֖l yĕrẇşá̌liá֑m wa⁠ţá̇bò֥ʼ há⁠ʻi֖yr bȧ⁠má̇ẕֽwòr׃"],[24,11,"וַ⁠יָּבֹ֛א נְבוּכַדְנֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל עַל־הָ⁠עִ֑יר וַ⁠עֲבָדָ֖י⁠ו צָרִ֥ים עָלֶֽי⁠הָ׃","wa⁠yá̇bò֛ʼ nĕbẇkadĕneʼẕȧ֥r meֽlekĕ-bá̇be֖l ʻal-há⁠ʻi֑yr wa⁠ʻàbádá֖y⁠w ẕári֥ym ʻáleֽy⁠há׃"],[24,12,"וַ⁠יֵּצֵ֞א יְהוֹיָכִ֤ין מֶֽלֶךְ־יְהוּדָה֙ עַל־מֶ֣לֶךְ בָּבֶ֔ל ה֣וּא וְ⁠אִמּ֔⁠וֹ וַ⁠עֲבָדָ֖י⁠ו וְ⁠שָׂרָ֣י⁠ו וְ⁠סָֽרִיסָ֑י⁠ו וַ⁠יִּקַּ֤ח אֹת⁠וֹ֙ מֶ֣לֶךְ בָּבֶ֔ל בִּ⁠שְׁנַ֥ת שְׁמֹנֶ֖ה לְ⁠מָלְכֽ⁠וֹ׃","wa⁠yé̇ẕé֞ʼ yĕhwòyáki֤yn meֽlekĕ-yĕhẇdáh֙ ʻal-me֣lekĕ bá̇be֔l h֣ẇʼ wĕ⁠ʼiṁ֔⁠wò wa⁠ʻàbádá֖y⁠w wĕ⁠şá̂rá֣y⁠w wĕ⁠sáֽriysá֑y⁠w wa⁠yi̇qȧ֤ẖ ʼòţ⁠wò֙ me֣lekĕ bá̇be֔l bi̇⁠şĕ̌na֥ţ şĕ̌mòne֖h lĕ⁠málĕkֽ⁠wò׃"],[24,13,"וַ⁠יּוֹצֵ֣א מִ⁠שָּׁ֗ם אֶת־כָּל־אוֹצְרוֹת֙ בֵּ֣ית יְהוָ֔ה וְ⁠אֽוֹצְר֖וֹת בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יְקַצֵּ֞ץ אֶת־כָּל־כְּלֵ֣י הַ⁠זָּהָ֗ב אֲשֶׁ֨ר עָשָׂ֜ה שְׁלֹמֹ֤ה מֶֽלֶךְ־יִשְׂרָאֵל֙ בְּ⁠הֵיכַ֣ל יְהוָ֔ה כַּֽ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃","wa⁠ẏwòẕé֣ʼ mi⁠şá̇̌֗m ʼeţ-ká̇l-ʼwòẕĕrwòţ֙ bé֣̇yţ yĕhwá֔h wĕ⁠ʼֽwòẕĕr֖wòţ bé֣̇yţ ha⁠mė֑lekĕ wa⁠yĕqaẕé̇֞ẕ ʼeţ-ká̇l-kĕ̇lé֣y ha⁠zá̇há֗b ʼàşě֨r ʻáşá̂֜h şĕ̌lòmò֤h meֽlekĕ-yişĕ̂ráʼél֙ bĕ̇⁠héyka֣l yĕhwá֔h kȧֽ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃"],[24,14,"וְ⁠הִגְלָ֣ה אֶת־כָּל־יְ֠רוּשָׁלִַם וְֽ⁠אֶת־כָּל־הַ⁠שָּׂרִ֞ים וְ⁠אֵ֣ת ׀ כָּל־גִּבּוֹרֵ֣י הַ⁠חַ֗יִל עשרה אֲלָפִים֙ גּוֹלֶ֔ה וְ⁠כָל־הֶ⁠חָרָ֖שׁ וְ⁠הַ⁠מַּסְגֵּ֑ר לֹ֣א נִשְׁאַ֔ר זוּלַ֖ת דַּלַּ֥ת עַם־הָ⁠אָֽרֶץ׃","wĕ⁠higĕlá֣h ʼeţ-ká̇l-yĕ֠rẇşá̌liam wĕֽ⁠ʼeţ-ká̇l-ha⁠şá̇̂ri֞ym wĕ⁠ʼé֣ţ ׀ ká̇l-gi̇ḃwòré֣y ha⁠ẖa֗yil ʻşrh ʼàlápiym֙ ġwòle֔h wĕ⁠kál-he⁠ẖárá֖ş̌ wĕ⁠ha⁠mȧsĕgé֑̇r lò֣ʼ nişĕ̌ʼa֔r zẇla֖ţ dȧlȧ֥ţ ʻam-há⁠ʼáֽreẕ׃"],[24,15,"וַ⁠יֶּ֥גֶל אֶת־יְהוֹיָכִ֖ין בָּבֶ֑לָ⁠ה וְ⁠אֶת־אֵ֣ם הַ֠⁠מֶּלֶךְ וְ⁠אֶת־נְשֵׁ֨י הַ⁠מֶּ֜לֶךְ וְ⁠אֶת־סָרִיסָ֗י⁠ו וְ⁠אֵת֙ אולי הָ⁠אָ֔רֶץ הוֹלִ֛יךְ גּוֹלָ֥ה מִ⁠ירוּשָׁלִַ֖ם בָּבֶֽלָ⁠ה׃","wa⁠yė֥gel ʼeţ-yĕhwòyáki֖yn bá̇be֑lá⁠h wĕ⁠ʼeţ-ʼé֣m ha֠⁠mėlekĕ wĕ⁠ʼeţ-nĕşé̌֨y ha⁠mė֜lekĕ wĕ⁠ʼeţ-sáriysá֗y⁠w wĕ⁠ʼéţ֙ ʼwly há⁠ʼá֔reẕ hwòli֛ykĕ ġwòlá֥h mi⁠yrẇşá̌lia֖m bá̇beֽlá⁠h׃"],[24,16,"וְ⁠אֵת֩ כָּל־אַנְשֵׁ֨י הַ⁠חַ֜יִל שִׁבְעַ֣ת אֲלָפִ֗ים וְ⁠הֶ⁠חָרָ֤שׁ וְ⁠הַ⁠מַּסְגֵּר֙ אֶ֔לֶף הַ⁠כֹּ֕ל גִּבּוֹרִ֖ים עֹשֵׂ֣י מִלְחָמָ֑ה וַ⁠יְבִיאֵ֧⁠ם מֶֽלֶךְ־בָּבֶ֛ל גּוֹלָ֖ה בָּבֶֽלָ⁠ה׃","wĕ⁠ʼéţ֩ ká̇l-ʼanĕşé̌֨y ha⁠ẖa֜yil şǐbĕʻa֣ţ ʼàlápi֗ym wĕ⁠he⁠ẖárá֤ş̌ wĕ⁠ha⁠mȧsĕgé̇r֙ ʼe֔lep ha⁠kò̇֕l gi̇ḃwòri֖ym ʻòşé֣̂y milĕẖámá֑h wa⁠yĕbiyʼé֧⁠m meֽlekĕ-bá̇be֛l ġwòlá֖h bá̇beֽlá⁠h׃"],[24,17,"וַ⁠יַּמְלֵ֧ךְ מֶֽלֶךְ־בָּבֶ֛ל אֶת־מַתַּנְיָ֥ה דֹד֖⁠וֹ תַּחְתָּ֑י⁠ו וַ⁠יַּסֵּ֥ב אֶת־שְׁמ֖⁠וֹ צִדְקִיָּֽהוּ׃פ","wa⁠yȧmĕlé֧kĕ meֽlekĕ-bá̇be֛l ʼeţ-maţȧnĕyá֥h dòd֖⁠wò ţȧẖĕţá֑̇y⁠w wa⁠yȧsé֥̇b ʼeţ-şĕ̌m֖⁠wò ẕidĕqiyáֽ̇hẇ׃p"],[24,18,"בֶּן־עֶשְׂרִ֨ים וְ⁠אַחַ֤ת שָׁנָה֙ צִדְקִיָּ֣הוּ בְ⁠מָלְכ֔⁠וֹ וְ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ חמיטל בַּֽת־יִרְמְיָ֖הוּ מִ⁠לִּבְנָֽה׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ʼaẖa֤ţ şá̌náh֙ ẕidĕqiyá֣̇hẇ bĕ⁠málĕk֔⁠wò wĕ⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ẖmytl bȧֽţ-yirĕmĕyá֖hẇ mi⁠li̇bĕnáֽh׃"],[24,19,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה יְהוֹיָקִֽים׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h yĕhwòyáqiֽym׃"],[24,20,"כִּ֣י ׀ עַל־אַ֣ף יְהוָ֗ה הָיְתָ֤ה בִ⁠ירוּשָׁלִַ֨ם֙ וּ⁠בִ֣⁠יהוּדָ֔ה עַד־הִשְׁלִכ֥⁠וֹ אֹתָ֖⁠ם מֵ⁠עַ֣ל פָּנָ֑י⁠ו וַ⁠יִּמְרֹ֥ד צִדְקִיָּ֖הוּ בְּ⁠מֶ֥לֶךְ בָּבֶֽל׃ס","ki֣̇y ׀ ʻal-ʼa֣p yĕhwá֗h háyĕţá֤h bi⁠yrẇşá̌lia֨m֙ ẇ⁠bi֣⁠yhẇdá֔h ʻad-hişĕ̌lik֥⁠wò ʼòţá֖⁠m mé⁠ʻa֣l pá̇ná֑y⁠w wa⁠yi̇mĕrò֥d ẕidĕqiyá֖̇hẇ bĕ̇⁠me֥lekĕ bá̇beֽl׃s"],[25,1,"וַ⁠יְהִי֩ בִ⁠שְׁנַ֨ת הַ⁠תְּשִׁיעִ֜ית לְ⁠מָלְכ֗⁠וֹ בַּ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂירִי֮ בֶּ⁠עָשׂ֣וֹר לַ⁠חֹדֶשׁ֒ בָּ֠א נְבֻכַדְנֶאצַּ֨ר מֶֽלֶךְ־בָּבֶ֜ל ה֧וּא וְ⁠כָל־חֵיל֛⁠וֹ עַל־יְרוּשָׁלִַ֖ם וַ⁠יִּ֣חַן עָלֶ֑י⁠הָ וַ⁠יִּבְנ֥וּ עָלֶ֖י⁠הָ דָּיֵ֥ק סָבִֽיב׃","wa⁠yĕhiy֩ bi⁠şĕ̌na֨ţ ha⁠ţĕ̇şǐyʻi֜yţ lĕ⁠málĕk֗⁠wò bȧ⁠ẖò֣deş̌ há⁠ʻàşîyriy֮ bė⁠ʻáş֣̂wòr la⁠ẖòdeş̌֒ bá̇֠ʼ nĕbukadĕneʼẕȧ֨r meֽlekĕ-bá̇be֜l h֧ẇʼ wĕ⁠kál-ẖéyl֛⁠wò ʻal-yĕrẇşá̌lia֖m wa⁠yi֣̇ẖan ʻále֑y⁠há wa⁠yi̇bĕn֥ẇ ʻále֖y⁠há dá̇yé֥q sábiֽyb׃"],[25,2,"וַ⁠תָּבֹ֥א הָ⁠עִ֖יר בַּ⁠מָּצ֑וֹר עַ֚ד עַשְׁתֵּ֣י עֶשְׂרֵ֣ה שָׁנָ֔ה לַ⁠מֶּ֖לֶךְ צִדְקִיָּֽהוּ׃","wa⁠ţá̇bò֥ʼ há⁠ʻi֖yr bȧ⁠má̇ẕ֑wòr ʻa֚d ʻaşĕ̌ţé֣̇y ʻeşĕ̂ré֣h şá̌ná֔h la⁠mė֖lekĕ ẕidĕqiyáֽ̇hẇ׃"],[25,3,"בְּ⁠תִשְׁעָ֣ה לַ⁠חֹ֔דֶשׁ וַ⁠יֶּחֱזַ֥ק הָ⁠רָעָ֖ב בָּ⁠עִ֑יר וְ⁠לֹא־הָ֥יָה לֶ֖חֶם לְ⁠עַ֥ם הָ⁠אָֽרֶץ׃","bĕ̇⁠ţişĕ̌ʻá֣h la⁠ẖò֔deş̌ wa⁠yėẖèza֥q há⁠ráʻá֖b bá̇⁠ʻi֑yr wĕ⁠lòʼ-há֥yáh le֖ẖem lĕ⁠ʻa֥m há⁠ʼáֽreẕ׃"],[25,4,"וַ⁠תִּבָּקַ֣ע הָ⁠עִ֗יר וְ⁠כָל־אַנְשֵׁ֨י הַ⁠מִּלְחָמָ֤ה ׀ הַ⁠לַּ֨יְלָה֙ דֶּ֜רֶךְ שַׁ֣עַר ׀ בֵּ֣ין הַ⁠חֹמֹתַ֗יִם אֲשֶׁר֙ עַל־גַּ֣ן הַ⁠מֶּ֔לֶךְ וְ⁠כַשְׂדִּ֥ים עַל־הָ⁠עִ֖יר סָבִ֑יב וַ⁠יֵּ֖לֶךְ דֶּ֥רֶךְ הָ⁠עֲרָבָֽה׃","wa⁠ţi̇bá̇qa֣ʻ há⁠ʻi֗yr wĕ⁠kál-ʼanĕşé̌֨y ha⁠mi̇lĕẖámá֤h ׀ ha⁠lȧ֨yĕláh֙ dė֜rekĕ şǎ֣ʻar ׀ bé֣̇yn ha⁠ẖòmòţa֗yim ʼàşěr֙ ʻal-gȧ֣n ha⁠mė֔lekĕ wĕ⁠kaşĕ̂di֥̇ym ʻal-há⁠ʻi֖yr sábi֑yb wa⁠yé֖̇lekĕ dė֥rekĕ há⁠ʻàrábáֽh׃"],[25,5,"וַ⁠יִּרְדְּפ֤וּ חֵיל־כַּשְׂדִּים֙ אַחַ֣ר הַ⁠מֶּ֔לֶךְ וַ⁠יַּשִּׂ֥גוּ אֹת֖⁠וֹ בְּ⁠עַרְב֣וֹת יְרֵח֑וֹ וְ⁠כָל־חֵיל֔⁠וֹ נָפֹ֖צוּ מֵ⁠עָלָֽי⁠ו׃","wa⁠yi̇rĕdĕ̇p֤ẇ ẖéyl-kȧşĕ̂di̇ym֙ ʼaẖa֣r ha⁠mė֔lekĕ wa⁠yȧşi֥̇̂gẇ ʼòţ֖⁠wò bĕ̇⁠ʻarĕb֣wòţ yĕréẖ֑wò wĕ⁠kál-ẖéyl֔⁠wò nápò֖ẕẇ mé⁠ʻáláֽy⁠w׃"],[25,6,"וַֽ⁠יִּתְפְּשׂוּ֙ אֶת־הַ⁠מֶּ֔לֶךְ וַ⁠יַּעֲל֥וּ אֹת֛⁠וֹ אֶל־מֶ֥לֶךְ בָּבֶ֖ל רִבְלָ֑תָ⁠ה וַ⁠יְדַבְּר֥וּ אִתּ֖⁠וֹ מִשְׁפָּֽט׃","waֽ⁠yi̇ţĕpĕ̇ş̂ẇ֙ ʼeţ-ha⁠mė֔lekĕ wa⁠yȧʻàl֥ẇ ʼòţ֛⁠wò ʼel-me֥lekĕ bá̇be֖l ribĕlá֑ţá⁠h wa⁠yĕdabĕ̇r֥ẇ ʼiţ֖̇⁠wò mişĕ̌páֽ̇t׃"],[25,7,"וְ⁠אֶת־בְּנֵי֙ צִדְקִיָּ֔הוּ שָׁחֲט֖וּ לְ⁠עֵינָ֑י⁠ו וְ⁠אֶת־עֵינֵ֤י צִדְקִיָּ֨הוּ֙ עִוֵּ֔ר וַ⁠יַּאַסְרֵ֨⁠הוּ֙ בַֽ⁠נְחֻשְׁתַּ֔יִם וַ⁠יְבִאֵ֖⁠הוּ בָּבֶֽל׃ס","wĕ⁠ʼeţ-bĕ̇néy֙ ẕidĕqiyá̇֔hẇ şá̌ẖàt֖ẇ lĕ⁠ʻéyná֑y⁠w wĕ⁠ʼeţ-ʻéyné֤y ẕidĕqiyá̇֨hẇ֙ ʻiwé̇֔r wa⁠yȧʼasĕré֨⁠hẇ֙ baֽ⁠nĕẖuşĕ̌ţȧ֔yim wa⁠yĕbiʼé֖⁠hẇ bá̇beֽl׃s"],[25,8,"וּ⁠בַ⁠חֹ֤דֶשׁ הַֽ⁠חֲמִישִׁי֙ בְּ⁠שִׁבְעָ֣ה לַ⁠חֹ֔דֶשׁ הִ֗יא שְׁנַת֙ תְּשַֽׁע־עֶשְׂרֵ֣ה שָׁנָ֔ה לַ⁠מֶּ֖לֶךְ נְבֻכַדְנֶאצַּ֣ר מֶֽלֶךְ־בָּבֶ֑ל בָּ֞א נְבוּזַרְאֲדָ֧ן רַב־טַבָּחִ֛ים עֶ֥בֶד מֶֽלֶךְ־בָּבֶ֖ל יְרוּשָׁלִָֽם׃","ẇ⁠ba⁠ẖò֤deş̌ hֽa⁠ẖàmiyşǐy֙ bĕ̇⁠şǐbĕʻá֣h la⁠ẖò֔deş̌ hi֗yʼ şĕ̌naţ֙ ţĕ̇şǎֽʻ-ʻeşĕ̂ré֣h şá̌ná֔h la⁠mė֖lekĕ nĕbukadĕneʼẕȧ֣r meֽlekĕ-bá̇be֑l bá̇֞ʼ nĕbẇzarĕʼàdá֧n rab-tabá̇ẖi֛ym ʻe֥bed meֽlekĕ-bá̇be֖l yĕrẇşá̌liáֽm׃"],[25,9,"וַ⁠יִּשְׂרֹ֥ף אֶת־בֵּית־יְהוָ֖ה וְ⁠אֶת־בֵּ֣ית הַ⁠מֶּ֑לֶךְ וְ⁠אֵ֨ת כָּל־בָּתֵּ֧י יְרוּשָׁלִַ֛ם וְ⁠אֶת־כָּל־בֵּ֥ית גָּד֖וֹל שָׂרַ֥ף בָּ⁠אֵֽשׁ׃","wa⁠yi̇şĕ̂rò֥p ʼeţ-bé̇yţ-yĕhwá֖h wĕ⁠ʼeţ-bé֣̇yţ ha⁠mė֑lekĕ wĕ⁠ʼé֨ţ ká̇l-bá̇ţé֧̇y yĕrẇşá̌lia֛m wĕ⁠ʼeţ-ká̇l-bé֥̇yţ gá̇d֖wòl şá̂ra֥p bá̇⁠ʼéֽş̌׃"],[25,10,"וְ⁠אֶת־חוֹמֹ֥ת יְרוּשָׁלִַ֖ם סָבִ֑יב נָֽתְצוּ֙ כָּל־חֵ֣יל כַּשְׂדִּ֔ים אֲשֶׁ֖ר רַב־טַבָּחִֽים׃","wĕ⁠ʼeţ-ẖwòmò֥ţ yĕrẇşá̌lia֖m sábi֑yb náֽţĕẕẇ֙ ká̇l-ẖé֣yl kȧşĕ̂di̇֔ym ʼàşě֖r rab-tabá̇ẖiֽym׃"],[25,11,"וְ⁠אֵת֩ יֶ֨תֶר הָ⁠עָ֜ם הַ⁠נִּשְׁאָרִ֣ים בָּ⁠עִ֗יר וְ⁠אֶת־הַ⁠נֹּֽפְלִים֙ אֲשֶׁ֤ר נָפְלוּ֙ עַל־הַ⁠מֶּ֣לֶךְ בָּבֶ֔ל וְ⁠אֵ֖ת יֶ֣תֶר הֶ⁠הָמ֑וֹן הֶגְלָ֕ה נְבוּזַרְאֲדָ֖ן רַב־טַבָּחִֽים׃","wĕ⁠ʼéţ֩ ye֨ţer há⁠ʻá֜m ha⁠ni̇şĕ̌ʼári֣ym bá̇⁠ʻi֗yr wĕ⁠ʼeţ-ha⁠nòֽ̇pĕliym֙ ʼàşě֤r nápĕlẇ֙ ʻal-ha⁠mė֣lekĕ bá̇be֔l wĕ⁠ʼé֖ţ ye֣ţer he⁠hám֑wòn hegĕlá֕h nĕbẇzarĕʼàdá֖n rab-tabá̇ẖiֽym׃"],[25,12,"וּ⁠מִ⁠דַּלַּ֣ת הָ⁠אָ֔רֶץ הִשְׁאִ֖יר רַב־טַבָּחִ֑ים לְ⁠כֹֽרְמִ֖ים וּ⁠לְ⁠יֹגְבִֽים׃","ẇ⁠mi⁠dȧlȧ֣ţ há⁠ʼá֔reẕ hişĕ̌ʼi֖yr rab-tabá̇ẖi֑ym lĕ⁠kòֽrĕmi֖ym ẇ⁠lĕ⁠yògĕbiֽym׃"],[25,13,"וְ⁠אֶת־עַמּוּדֵ֨י הַ⁠נְּחֹ֜שֶׁת אֲשֶׁ֣ר בֵּית־יְהוָ֗ה וְֽ⁠אֶת־הַ⁠מְּכֹנ֞וֹת וְ⁠אֶת־יָ֧ם הַ⁠נְּחֹ֛שֶׁת אֲשֶׁ֥ר בְּ⁠בֵית־יְהוָ֖ה שִׁבְּר֣וּ כַשְׂדִּ֑ים וַ⁠יִּשְׂא֥וּ אֶת־נְחֻשְׁתָּ֖⁠ם בָּבֶֽלָ⁠ה׃","wĕ⁠ʼeţ-ʻaṁẇdé֨y ha⁠nĕ̇ẖò֜şěţ ʼàşě֣r bé̇yţ-yĕhwá֗h wĕֽ⁠ʼeţ-ha⁠mĕ̇kòn֞wòţ wĕ⁠ʼeţ-yá֧m ha⁠nĕ̇ẖò֛şěţ ʼàşě֥r bĕ̇⁠béyţ-yĕhwá֖h şǐbĕ̇r֣ẇ kaşĕ̂di֑̇ym wa⁠yi̇şĕ̂ʼ֥ẇ ʼeţ-nĕẖuşĕ̌ţá֖̇⁠m bá̇beֽlá⁠h׃"],[25,14,"וְ⁠אֶת־הַ⁠סִּירֹ֨ת וְ⁠אֶת־הַ⁠יָּעִ֜ים וְ⁠אֶת־הַֽ⁠מְזַמְּר֣וֹת וְ⁠אֶת־הַ⁠כַּפּ֗וֹת וְ⁠אֵ֨ת כָּל־כְּלֵ֧י הַ⁠נְּחֹ֛שֶׁת אֲשֶׁ֥ר יְשָֽׁרְתוּ־בָ֖⁠ם לָקָֽחוּ׃","wĕ⁠ʼeţ-ha⁠si̇yrò֨ţ wĕ⁠ʼeţ-ha⁠yá̇ʻi֜ym wĕ⁠ʼeţ-haֽ⁠mĕzamĕ̇r֣wòţ wĕ⁠ʼeţ-ha⁠kȧṗ֗wòţ wĕ⁠ʼé֨ţ ká̇l-kĕ̇lé֧y ha⁠nĕ̇ẖò֛şěţ ʼàşě֥r yĕşáֽ̌rĕţẇ-bá֖⁠m láqáֽẖẇ׃"],[25,15,"וְ⁠אֶת־הַ⁠מַּחְתּוֹת֙ וְ⁠אֶת־הַ⁠מִּזְרָק֗וֹת אֲשֶׁ֤ר זָהָב֙ זָהָ֔ב וַ⁠אֲשֶׁר־כֶּ֖סֶף כָּ֑סֶף לָקַ֖ח רַב־טַבָּחִֽים׃","wĕ⁠ʼeţ-ha⁠mȧẖĕţ̇wòţ֙ wĕ⁠ʼeţ-ha⁠mi̇zĕráq֗wòţ ʼàşě֤r záháb֙ záhá֔b wa⁠ʼàşěr-kė֖sep ká֑̇sep láqa֖ẖ rab-tabá̇ẖiֽym׃"],[25,16,"הָ⁠עַמּוּדִ֣ים ׀ שְׁנַ֗יִם הַ⁠יָּ֤ם הָֽ⁠אֶחָד֙ וְ⁠הַ⁠מְּכֹנ֔וֹת אֲשֶׁר־עָשָׂ֥ה שְׁלֹמֹ֖ה לְ⁠בֵ֣ית יְהוָ֑ה לֹא־הָיָ֣ה מִשְׁקָ֔ל לִ⁠נְחֹ֖שֶׁת כָּל־הַ⁠כֵּלִ֥ים הָ⁠אֵֽלֶּה׃","há⁠ʻaṁẇdi֣ym ׀ şĕ̌na֗yim ha⁠yá֤̇m háֽ⁠ʼeẖád֙ wĕ⁠ha⁠mĕ̇kòn֔wòţ ʼàşěr-ʻáşá֥̂h şĕ̌lòmò֖h lĕ⁠bé֣yţ yĕhwá֑h lòʼ-háyá֣h mişĕ̌qá֔l li⁠nĕẖò֖şěţ ká̇l-ha⁠ké̇li֥ym há⁠ʼéֽlėh׃"],[25,17,"שְׁמֹנֶה֩ עֶשְׂרֵ֨ה אַמָּ֜ה קוֹמַ֣ת ׀ הָ⁠עַמּ֣וּד הָ⁠אֶחָ֗ד וְ⁠כֹתֶ֨רֶת עָלָ֥י⁠ו ׀ נְחֹשֶׁת֮ וְ⁠קוֹמַ֣ת הַ⁠כֹּתֶרֶת֮ שָׁלֹ֣שׁ אמה וּ⁠שְׂבָכָ֨ה וְ⁠רִמֹּנִ֧ים עַֽל־הַ⁠כֹּתֶ֛רֶת סָבִ֖יב הַ⁠כֹּ֣ל נְחֹ֑שֶׁת וְ⁠כָ⁠אֵ֛לֶּה לַֽ⁠עַמּ֥וּד הַ⁠שֵּׁנִ֖י עַל־הַ⁠שְּׂבָכָֽה׃","şĕ̌mòneh֩ ʻeşĕ̂ré֨h ʼamá̇֜h qwòma֣ţ ׀ há⁠ʻaṁ֣ẇd há⁠ʼeẖá֗d wĕ⁠kòţe֨reţ ʻálá֥y⁠w ׀ nĕẖòşěţ֮ wĕ⁠qwòma֣ţ ha⁠kò̇ţereţ֮ şá̌lò֣ş̌ ʼmh ẇ⁠şĕ̂báká֨h wĕ⁠rimò̇ni֧ym ʻaֽl-ha⁠kò̇ţe֛reţ sábi֖yb ha⁠kò֣̇l nĕẖò֑şěţ wĕ⁠ká⁠ʼé֛lėh laֽ⁠ʻaṁ֥ẇd ha⁠şé̇̌ni֖y ʻal-ha⁠şĕ̇̂bákáֽh׃"],[25,18,"וַ⁠יִּקַּ֣ח רַב־טַבָּחִ֗ים אֶת־שְׂרָיָה֙ כֹּהֵ֣ן הָ⁠רֹ֔אשׁ וְ⁠אֶת־צְפַנְיָ֖הוּ כֹּהֵ֣ן מִשְׁנֶ֑ה וְ⁠אֶת־שְׁלֹ֖שֶׁת שֹׁמְרֵ֥י הַ⁠סַּֽף׃","wa⁠yi̇qȧ֣ẖ rab-tabá̇ẖi֗ym ʼeţ-şĕ̂ráyáh֙ kò̇hé֣n há⁠rò֔ʼş̌ wĕ⁠ʼeţ-ẕĕpanĕyá֖hẇ kò̇hé֣n mişĕ̌ne֑h wĕ⁠ʼeţ-şĕ̌lò֖şěţ şò̌mĕré֥y ha⁠sȧֽp׃"],[25,19,"וּ⁠מִן־הָ⁠עִ֡יר לָקַח֩ סָרִ֨יס אֶחָ֜ד אֲֽשֶׁר־ה֥וּא פָקִ֣יד ׀ עַל־אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֗ה וַ⁠חֲמִשָּׁ֨ה אֲנָשִׁ֜ים מֵ⁠רֹאֵ֤י פְנֵֽי־הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר נִמְצְא֣וּ בָ⁠עִ֔יר וְ⁠אֵ֗ת הַ⁠סֹּפֵר֙ שַׂ֣ר הַ⁠צָּבָ֔א הַ⁠מַּצְבִּ֖א אֶת־עַ֣ם הָ⁠אָ֑רֶץ וְ⁠שִׁשִּׁ֥ים אִישׁ֙ מֵ⁠עַ֣ם הָ⁠אָ֔רֶץ הַֽ⁠נִּמְצְאִ֖ים בָּ⁠עִֽיר׃","ẇ⁠min-há⁠ʻi֡yr láqaẖ֩ sári֨ys ʼeẖá֜d ʼàֽşěr-h֥ẇʼ páqi֣yd ׀ ʻal-ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֗h wa⁠ẖàmişá̇̌֨h ʼànáşǐ֜ym mé⁠ròʼé֤y pĕnéֽy-ha⁠mė֨lekĕ֙ ʼàşě֣r nimĕẕĕʼ֣ẇ bá⁠ʻi֔yr wĕ⁠ʼé֗ţ ha⁠sò̇pér֙ şâ֣r ha⁠ẕá̇bá֔ʼ ha⁠mȧẕĕbi֖̇ʼ ʼeţ-ʻa֣m há⁠ʼá֑reẕ wĕ⁠şǐşi֥̇̌ym ʼiyş̌֙ mé⁠ʻa֣m há⁠ʼá֔reẕ haֽ⁠ni̇mĕẕĕʼi֖ym bá̇⁠ʻiֽyr׃"],[25,20,"וַ⁠יִּקַּ֣ח אֹתָ֔⁠ם נְבוּזַרְאֲדָ֖ן רַב־טַבָּחִ֑ים וַ⁠יֹּ֧לֶךְ אֹתָ֛⁠ם עַל־מֶ֥לֶךְ בָּבֶ֖ל רִבְלָֽתָ⁠ה׃","wa⁠yi̇qȧ֣ẖ ʼòţá֔⁠m nĕbẇzarĕʼàdá֖n rab-tabá̇ẖi֑ym wa⁠yò֧̇lekĕ ʼòţá֛⁠m ʻal-me֥lekĕ bá̇be֖l ribĕláֽţá⁠h׃"],[25,21,"וַ⁠יַּ֣ךְ אֹתָ⁠ם֩ מֶ֨לֶךְ בָּבֶ֧ל וַ⁠יְמִיתֵ֛⁠ם בְּ⁠רִבְלָ֖ה בְּ⁠אֶ֣רֶץ חֲמָ֑ת וַ⁠יִּ֥גֶל יְהוּדָ֖ה מֵ⁠עַ֥ל אַדְמָתֽ⁠וֹ׃","wa⁠yȧ֣kĕ ʼòţá⁠m֩ me֨lekĕ bá̇be֧l wa⁠yĕmiyţé֛⁠m bĕ̇⁠ribĕlá֖h bĕ̇⁠ʼe֣reẕ ẖàmá֑ţ wa⁠yi֥̇gel yĕhẇdá֖h mé⁠ʻa֥l ʼadĕmáţֽ⁠wò׃"],[25,22,"וְ⁠הָ⁠עָ֗ם הַ⁠נִּשְׁאָר֙ בְּ⁠אֶ֣רֶץ יְהוּדָ֔ה אֲשֶׁ֣ר הִשְׁאִ֔יר נְבֽוּכַדְנֶאצַּ֖ר מֶ֣לֶךְ בָּבֶ֑ל וַ⁠יַּפְקֵ֣ד עֲלֵי⁠הֶ֔ם אֶת־גְּדַלְיָ֖הוּ בֶּן־אֲחִיקָ֥ם בֶּן־שָׁפָֽן׃פ","wĕ⁠há⁠ʻá֗m ha⁠ni̇şĕ̌ʼár֙ bĕ̇⁠ʼe֣reẕ yĕhẇdá֔h ʼàşě֣r hişĕ̌ʼi֔yr nĕbֽẇkadĕneʼẕȧ֖r me֣lekĕ bá̇be֑l wa⁠yȧpĕqé֣d ʻàléy⁠he֔m ʼeţ-gĕ̇dalĕyá֖hẇ bėn-ʼàẖiyqá֥m bėn-şá̌páֽn׃p"],[25,23,"וַ⁠יִּשְׁמְעוּ֩ כָל־שָׂרֵ֨י הַ⁠חֲיָלִ֜ים הֵ֣מָּה וְ⁠הָ⁠אֲנָשִׁ֗ים כִּֽי־הִפְקִ֤יד מֶֽלֶךְ־בָּבֶל֙ אֶת־גְּדַלְיָ֔הוּ וַ⁠יָּבֹ֥אוּ אֶל־גְּדַלְיָ֖הוּ הַ⁠מִּצְפָּ֑ה וְ⁠יִשְׁמָעֵ֣אל בֶּן־נְתַנְיָ֡ה וְ⁠יוֹחָנָ֣ן בֶּן־קָ֠רֵחַ וּ⁠שְׂרָיָ֨ה בֶן־תַּנְחֻ֜מֶת הַ⁠נְּטֹפָתִ֗י וְ⁠יַֽאֲזַנְיָ֨הוּ֙ בֶּן־הַ⁠מַּ֣עֲכָתִ֔י הֵ֖מָּה וְ⁠אַנְשֵׁי⁠הֶֽם׃","wa⁠yi̇şĕ̌mĕʻẇ֩ kál-şá̂ré֨y ha⁠ẖàyáli֜ym hé֣má̇h wĕ⁠há⁠ʼànáşǐ֗ym kiֽ̇y-hipĕqi֤yd meֽlekĕ-bá̇bel֙ ʼeţ-gĕ̇dalĕyá֔hẇ wa⁠yá̇bò֥ʼẇ ʼel-gĕ̇dalĕyá֖hẇ ha⁠mi̇ẕĕpá֑̇h wĕ⁠yişĕ̌máʻé֣ʼl bėn-nĕţanĕyá֡h wĕ⁠ywòẖáná֣n bėn-qá֠réẖa ẇ⁠şĕ̂ráyá֨h ben-ţȧnĕẖu֜meţ ha⁠nĕ̇tòpáţi֗y wĕ⁠yaֽʼàzanĕyá֨hẇ֙ bėn-ha⁠mȧ֣ʻàkáţi֔y hé֖má̇h wĕ⁠ʼanĕşé̌y⁠heֽm׃"],[25,24,"וַ⁠יִּשָּׁבַ֨ע לָ⁠הֶ֤ם גְּדַלְיָ֨הוּ֙ וּ⁠לְ⁠אַנְשֵׁי⁠הֶ֔ם וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם אַל־תִּֽירְא֖וּ מֵ⁠עַבְדֵ֣י הַ⁠כַּשְׂדִּ֑ים שְׁב֣וּ בָ⁠אָ֗רֶץ וְ⁠עִבְד֛וּ אֶת־מֶ֥לֶךְ בָּבֶ֖ל וְ⁠יִטַ֥ב לָ⁠כֶֽם׃ס","wa⁠yi̇şá̇̌ba֨ʻ lá⁠he֤m gĕ̇dalĕyá֨hẇ֙ ẇ⁠lĕ⁠ʼanĕşé̌y⁠he֔m wa⁠yò֣̇ʼmer lá⁠he֔m ʼal-ţiֽ̇yrĕʼ֖ẇ mé⁠ʻabĕdé֣y ha⁠kȧşĕ̂di֑̇ym şĕ̌b֣ẇ bá⁠ʼá֗reẕ wĕ⁠ʻibĕd֛ẇ ʼeţ-me֥lekĕ bá̇be֖l wĕ⁠yita֥b lá⁠keֽm׃s"],[25,25,"וַ⁠יְהִ֣י ׀ בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֗י בָּ֣א יִשְׁמָעֵ֣אל בֶּן־נְ֠תַנְיָה בֶּן־אֱלִ֨ישָׁמָ֜ע מִ⁠זֶּ֣רַע הַ⁠מְּלוּכָ֗ה וַ⁠עֲשָׂרָ֤ה אֲנָשִׁים֙ אִתּ֔⁠וֹ וַ⁠יַּכּ֥וּ אֶת־גְּדַלְיָ֖הוּ וַ⁠יָּמֹ֑ת וְ⁠אֶת־הַ⁠יְּהוּדִים֙ וְ⁠אֶת־הַ⁠כַּשְׂדִּ֔ים אֲשֶׁר־הָי֥וּ אִתּ֖⁠וֹ בַּ⁠מִּצְפָּֽה׃","wa⁠yĕhi֣y ׀ bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֗y bá֣̇ʼ yişĕ̌máʻé֣ʼl bėn-nĕ֠ţanĕyáh bėn-ʼèli֨yşá̌má֜ʻ mi⁠zė֣raʻ ha⁠mĕ̇lẇká֗h wa⁠ʻàşá̂rá֤h ʼànáşǐym֙ ʼiţ̇֔⁠wò wa⁠yȧk֥̇ẇ ʼeţ-gĕ̇dalĕyá֖hẇ wa⁠yá̇mò֑ţ wĕ⁠ʼeţ-ha⁠yĕ̇hẇdiym֙ wĕ⁠ʼeţ-ha⁠kȧşĕ̂di̇֔ym ʼàşěr-háy֥ẇ ʼiţ֖̇⁠wò bȧ⁠mi̇ẕĕpáֽ̇h׃"],[25,26,"וַ⁠יָּקֻ֨מוּ כָל־הָ⁠עָ֜ם מִ⁠קָּטֹ֤ן וְ⁠עַד־גָּדוֹל֙ וְ⁠שָׂרֵ֣י הַ⁠חֲיָלִ֔ים וַ⁠יָּבֹ֖אוּ מִצְרָ֑יִם כִּ֥י יָרְא֖וּ מִ⁠פְּנֵ֥י כַשְׂדִּֽים׃פ","wa⁠yá̇qu֨mẇ kál-há⁠ʻá֜m mi⁠qá̇tò֤n wĕ⁠ʻad-gá̇dwòl֙ wĕ⁠şá̂ré֣y ha⁠ẖàyáli֔ym wa⁠yá̇bò֖ʼẇ miẕĕrá֑yim ki֥̇y yárĕʼ֖ẇ mi⁠pĕ̇né֥y kaşĕ̂diֽ̇ym׃p"],[25,27,"וַ⁠יְהִי֩ בִ⁠שְׁלֹשִׁ֨ים וָ⁠שֶׁ֜בַע שָׁנָ֗ה לְ⁠גָלוּת֙ יְהוֹיָכִ֣ין מֶֽלֶךְ־יְהוּדָ֔ה בִּ⁠שְׁנֵ֤ים עָשָׂר֙ חֹ֔דֶשׁ בְּ⁠עֶשְׂרִ֥ים וְ⁠שִׁבְעָ֖ה לַ⁠חֹ֑דֶשׁ נָשָׂ֡א אֱוִ֣יל מְרֹדַךְ֩ מֶ֨לֶךְ בָּבֶ֜ל בִּ⁠שְׁנַ֣ת מָלְכ֗⁠וֹ אֶת־רֹ֛אשׁ יְהוֹיָכִ֥ין מֶֽלֶךְ־יְהוּדָ֖ה מִ⁠בֵּ֥ית כֶּֽלֶא׃","wa⁠yĕhiy֩ bi⁠şĕ̌lòşǐ֨ym wá⁠şě֜baʻ şá̌ná֗h lĕ⁠gálẇţ֙ yĕhwòyáki֣yn meֽlekĕ-yĕhẇdá֔h bi̇⁠şĕ̌né֤ym ʻáşá̂r֙ ẖò֔deş̌ bĕ̇⁠ʻeşĕ̂ri֥ym wĕ⁠şǐbĕʻá֖h la⁠ẖò֑deş̌ náşá̂֡ʼ ʼèwi֣yl mĕròdakĕ֩ me֨lekĕ bá̇be֜l bi̇⁠şĕ̌na֣ţ málĕk֗⁠wò ʼeţ-rò֛ʼş̌ yĕhwòyáki֥yn meֽlekĕ-yĕhẇdá֖h mi⁠bé֥̇yţ kėֽleʼ׃"],[25,28,"וַ⁠יְדַבֵּ֥ר אִתּ֖⁠וֹ טֹב֑וֹת וַ⁠יִּתֵּן֙ אֶת־כִּסְא֔⁠וֹ מֵ⁠עַ֗ל כִּסֵּ֧א הַ⁠מְּלָכִ֛ים אֲשֶׁ֥ר אִתּ֖⁠וֹ בְּ⁠בָבֶֽל׃","wa⁠yĕdabé֥̇r ʼiţ֖̇⁠wò tòb֑wòţ wa⁠yi̇ţé̇n֙ ʼeţ-ki̇sĕʼ֔⁠wò mé⁠ʻa֗l ki̇sé֧̇ʼ ha⁠mĕ̇láki֛ym ʼàşě֥r ʼiţ֖̇⁠wò bĕ̇⁠bábeֽl׃"],[25,29,"וְ⁠שִׁנָּ֕א אֵ֖ת בִּגְדֵ֣י כִלְא֑⁠וֹ וְ⁠אָכַ֨ל לֶ֧חֶם תָּמִ֛יד לְ⁠פָנָ֖י⁠ו כָּל־יְמֵ֥י חַיָּֽי⁠ו׃","wĕ⁠şǐná̇֕ʼ ʼé֖ţ bi̇gĕdé֣y kilĕʼ֑⁠wò wĕ⁠ʼáka֨l le֧ẖem ţá̇mi֛yd lĕ⁠páná֖y⁠w ká̇l-yĕmé֥y ẖayáֽ̇y⁠w׃"],[25,30,"וַ⁠אֲרֻחָת֗⁠וֹ אֲרֻחַ֨ת תָּמִ֧יד נִתְּנָה־לּ֛⁠וֹ מֵ⁠אֵ֥ת הַ⁠מֶּ֖לֶךְ דְּבַר־י֣וֹם בְּ⁠יוֹמ֑⁠וֹ כֹּ֖ל יְמֵ֥י חַיָּֽ⁠ו׃","wa⁠ʼàruẖáţ֗⁠wò ʼàruẖa֨ţ ţá̇mi֧yd niţĕ̇náh-l֛̇⁠wò mé⁠ʼé֥ţ ha⁠mė֖lekĕ dĕ̇bar-y֣wòm bĕ̇⁠ywòm֑⁠wò kò֖̇l yĕmé֥y ẖayáֽ̇⁠w׃"]]}};